terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources for static provider metadata
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

variable "sftp_users" {
  description = "Map of SFTP users with UID, GID, SSH public key, and home directory"
  type = map(object({
    uid            = number
    gid            = number
    ssh_public_key = string
    home_directory = string
  }))
  default = {
    "alice" = {
      uid            = 1001
      gid            = 1001
      ssh_public_key = "ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABAQDA... alice@example.com"
      home_directory = "/alice"
    }
  }
}

locals {
  environment = "dev"
  name_prefix = "sftp"
  az_count    = length(data.aws_availability_zones.available.names)
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${local.name_prefix}-vpc"
    Environment = local.environment
  }
}

# Public subnets (one per AZ)
resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.name_prefix}-subnet-${count.index + 1}"
    Environment = local.environment
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-igw"
    Environment = local.environment
  }
}

# Route table for public subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${local.name_prefix}-public-rt"
    Environment = local.environment
  }
}

# Associate public subnets with route table
resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Elastic IPs for Transfer Server endpoints
resource "aws_eip" "sftp" {
  count  = local.az_count
  domain = "vpc"

  tags = {
    Name        = "${local.name_prefix}-eip-${count.index + 1}"
    Environment = local.environment
  }
}

# Security group for EFS mount targets
resource "aws_security_group" "efs" {
  name        = "${local.name_prefix}-efs-sg"
  description = "Allow NFS access from SFTP server"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "NFS from SFTP SG"
    from_port       = 2049
    to_port         = 2049
    protocol        = "tcp"
    security_groups = [aws_security_group.sftp.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "${local.name_prefix}-efs-sg"
    Environment = local.environment
  }
}

# Security group for SFTP server
resource "aws_security_group" "sftp" {
  name        = "${local.name_prefix}-sftp-sg"
  description = "Allow SSH access to SFTP server"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from anywhere (0.0.0.0/1)"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/1"]
  }

  ingress {
    description = "SSH from anywhere (128.0.0.0/1)"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["128.0.0.0/1"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "${local.name_prefix}-sftp-sg"
    Environment = local.environment
  }
}

# KMS key for EFS encryption
resource "aws_kms_key" "efs" {
  description             = "KMS key for EFS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EFS service"
        Effect = "Allow"
        Principal = {
          Service = "elasticfilesystem.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "elasticfilesystem.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = {
    Name        = "${local.name_prefix}-efs-kms"
    Environment = local.environment
  }
}

# EFS file system
resource "aws_efs_file_system" "main" {
  creation_token   = "${local.name_prefix}-efs"
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = {
    Name        = "${local.name_prefix}-efs"
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# EFS mount targets in each public subnet
resource "aws_efs_mount_target" "main" {
  count           = local.az_count
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.public[count.index].id
  security_groups = [aws_security_group.efs.id]
}

# EFS access points for each user
resource "aws_efs_access_point" "user" {
  for_each       = var.sftp_users
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }

  root_directory {
    path = each.value.home_directory
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }

  tags = {
    Name        = "${local.name_prefix}-accesspoint-${each.key}"
    Environment = local.environment
  }
}

# CloudWatch log group for Transfer server
resource "aws_cloudwatch_log_group" "transfer" {
  name              = "/aws/transfer/${local.name_prefix}"
  retention_in_days = 30

  tags = {
    Name        = "${local.name_prefix}-cloudwatch"
    Environment = local.environment
  }
}

# IAM role for CloudWatch logging
resource "aws_iam_role" "transfer_logging" {
  name = "${local.name_prefix}-transfer-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "${local.name_prefix}-logging-role"
    Environment = local.environment
  }
}

# IAM policy for CloudWatch logging (least privilege)
resource "aws_iam_policy" "transfer_logging" {
  name = "${local.name_prefix}-transfer-logging-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.transfer.arn,
          "${aws_cloudwatch_log_group.transfer.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  role       = aws_iam_role.transfer_logging.name
  policy_arn = aws_iam_policy.transfer_logging.arn
}

# IAM role for EFS access for SFTP users
resource "aws_iam_role" "sftp_efs" {
  name = "${local.name_prefix}-sftp-efs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "${local.name_prefix}-efs-role"
    Environment = local.environment
  }
}

# IAM policy for EFS access (least privilege)
resource "aws_iam_policy" "sftp_efs" {
  name = "${local.name_prefix}-sftp-efs-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = concat(
          [aws_efs_file_system.main.arn],
          [for ap in aws_efs_access_point.user : ap.arn]
        )
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sftp_efs" {
  role       = aws_iam_role.sftp_efs.name
  policy_arn = aws_iam_policy.sftp_efs.arn
}

# Transfer Family SFTP Server
resource "aws_transfer_server" "sftp" {
  protocols              = ["SFTP"]
  identity_provider_type = "SERVICE_MANAGED"
  endpoint_type          = "VPC"
  logging_role           = aws_iam_role.transfer_logging.arn

  endpoint_details {
    address_allocation_ids = aws_eip.sftp[*].id
    subnet_ids             = aws_subnet.public[*].id
    security_group_ids     = [aws_security_group.sftp.id]
  }

  tags = {
    Name        = "${local.name_prefix}-server"
    Environment = local.environment
  }
}

# Transfer users (service-managed)
resource "aws_transfer_user" "user" {
  for_each            = var.sftp_users
  server_id           = aws_transfer_server.sftp.id
  user_name           = each.key
  role                = aws_iam_role.sftp_efs.arn
  home_directory      = "/${aws_efs_access_point.user[each.key].id}"
  home_directory_type = "PATH"

  posix_profile {
    uid = each.value.uid
    gid = each.value.gid
  }

  tags = {
    Name        = "${local.name_prefix}-user-${each.key}"
    Environment = local.environment
  }
}

# SSH public key for each user
resource "aws_transfer_ssh_key" "user" {
  for_each   = var.sftp_users
  server_id  = aws_transfer_server.sftp.id
  user_name  = each.key
  body       = each.value.ssh_public_key
  depends_on = [aws_transfer_user.user]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.5"
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.common_tags, {
    Name = "${var.environment}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name = "${var.environment}-public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name = "${var.environment}-private-${count.index}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name = "${var.environment}-igw"
  })
}

resource "aws_eip" "nat" {
  count  = 2
  domain = "vpc"

  tags = merge(var.common_tags, {
    Name = "${var.environment}-nat-eip-${count.index}"
  })
}

resource "aws_nat_gateway" "main" {
  count = 2

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.common_tags, {
    Name = "${var.environment}-nat-gw-${count.index}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.common_tags, {
    Name = "${var.environment}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(var.common_tags, {
    Name = "${var.environment}-private-rt-${count.index}"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

output "region_description" {
  description = "The AWS region where resources are deployed"
  value       = var.region
}

output "aws_account_id" {
  description = "The AWS account ID"
  value       = data.aws_caller_identity.current.account_id
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "The IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC"
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_cidr_blocks" {
  description = "The CIDR blocks of the public subnets"
  value       = aws_subnet.public[*].cidr_block
}

output "private_subnet_cidr_blocks" {
  description = "The CIDR blocks of the private subnets"
  value       = aws_subnet.private[*].cidr_block
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "domain_name" {
  description = "Custom domain name for the hosted zone"
  type        = string
  default     = "example.com"
}

variable "subdomain" {
  description = "Subdomain for code-server access"
  type        = string
  default     = "code"
}

variable "hashed_password" {
  description = "Hashed password for code-server (use mkpasswd -m sha-256 or similar)"
  type        = string
  default     = "changeme"
  sensitive   = true
}

variable "timezone" {
  description = "Timezone for the container"
  type        = string
  default     = "America/New_York"
}

variable "puid" {
  description = "User ID for code-server process"
  type        = number
  default     = 1000
}

variable "pgid" {
  description = "Group ID for code-server process"
  type        = number
  default     = 1000
}

variable "workspace_path" {
  description = "Default workspace path inside container"
  type        = string
  default     = "/home/coder/workspace"
}

variable "container_port" {
  description = "Port code-server listens on inside container"
  type        = number
  default     = 8080
}

variable "cpu" {
  description = "CPU units for Fargate task (512 = 0.5 vCPU)"
  type        = number
  default     = 512
}

variable "memory" {
  description = "Memory in MiB for Fargate task (1024 = 1 GB)"
  type        = number
  default     = 1024
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "code-server-vpc"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "code-server-public-${count.index + 1}"
    Tier = "public"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "code-server-private-${count.index + 1}"
    Tier = "private"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "code-server-igw"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "code-server-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"
  tags = {
    Name = "code-server-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  tags = {
    Name = "code-server-nat"
  }
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
  tags = {
    Name = "code-server-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Secrets Manager for hashed password
resource "aws_secretsmanager_secret" "hashed_password" {
  name                    = "code-server-hashed-password"
  recovery_window_in_days = 0
  lifecycle {
    prevent_destroy = true
  }
  tags = {
    Name = "code-server-hashed-password"
  }
}

resource "aws_secretsmanager_secret_version" "hashed_password" {
  secret_id     = aws_secretsmanager_secret.hashed_password.id
  secret_string = var.hashed_password
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "code_server" {
  name              = "/ecs/code-server"
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
}

# IAM roles and policies
# Execution role
resource "aws_iam_role" "ecs_execution" {
  name = "ecsTaskExecutionRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_managed" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_policy" "ecs_execution_custom" {
  name        = "ecs-execution-custom"
  description = "Custom policy for ECS task execution"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.code_server.arn}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = aws_secretsmanager_secret.hashed_password.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_custom" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = aws_iam_policy.ecs_execution_custom.arn
}

# Task role
resource "aws_iam_role" "ecs_task" {
  name = "ecsTaskRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "ecs_task_custom" {
  name        = "ecs-task-custom"
  description = "Custom policy for ECS task"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.code_server.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_custom" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = aws_iam_policy.ecs_task_custom.arn
}

# ECS Cluster
resource "aws_ecs_cluster" "code_server" {
  name = "code-server-cluster"
}

# ECS Task Definition
resource "aws_ecs_task_definition" "code_server" {
  family                   = "code-server-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = var.cpu
  memory                   = var.memory
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name  = "code-server"
      image = "codercom/code-server:latest"
      essential = true
      environment = [
        { name = "PUID", value = tostring(var.puid) },
        { name = "PGID", value = tostring(var.pgid) },
        { name = "TZ", value = var.timezone },
        { name = "DEFAULT_WORKSPACE", value = var.workspace_path }
      ]
      secrets = [
        {
          name      = "HASHED_PASSWORD"
          valueFrom = aws_secretsmanager_secret.hashed_password.arn
        }
      ]
      portMappings = [
        {
          containerPort = var.container_port
          protocol      = "tcp"
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.code_server.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = "code-server"
        }
      }
      healthCheck = {
        command     = ["CMD-SHELL", "curl -f http://localhost:${var.container_port}/healthz || exit 1"]
        interval    = 30
        timeout     = 5
        retries     = 3
        startPeriod = 60
      }
    }
  ])
}

# Security Groups
# ALB security group - only allow HTTPS from CloudFront (any IP)
resource "aws_security_group" "alb" {
  name        = "code-server-alb-sg"
  description = "Security group for Application Load Balancer"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = {
    Name = "code-server-alb-sg"
  }
}

# ECS tasks security group
resource "aws_security_group" "ecs_tasks" {
  name        = "code-server-ecs-tasks-sg"
  description = "Security group for ECS tasks"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port       = var.container_port
    to_port         = var.container_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = {
    Name = "code-server-ecs-tasks-sg"
  }
}

# VPC Endpoints Security Group
resource "aws_security_group" "vpc_endpoints" {
  name        = "code-server-vpc-endpoints-sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_tasks.id]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = {
    Name = "code-server-vpc-endpoints-sg"
  }
}

# VPC Endpoints
# S3 Gateway Endpoint
resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.us-east-1.s3"
  route_table_ids = [aws_route_table.private.id]
  tags = {
    Name = "code-server-s3-endpoint"
  }
}

# ECR API Interface Endpoint
resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "code-server-ecr-api-endpoint"
  }
}

# ECR DKR Interface Endpoint
resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "code-server-ecr-dkr-endpoint"
  }
}

# CloudWatch Logs Interface Endpoint
resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "code-server-logs-endpoint"
  }
}

# Application Load Balancer (internal)
resource "aws_lb" "code_server" {
  name                       = "code-server-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.private[*].id
  idle_timeout               = 60
  drop_invalid_header_fields = true
  tags = {
    Name = "code-server-alb"
  }
}

# Target Group
resource "aws_lb_target_group" "code_server" {
  name        = "code-server-tg"
  port        = var.container_port
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"
  health_check {
    enabled             = true
    path                = "/healthz"
    protocol            = "HTTP"
    port                = "traffic-port"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 5
    interval            = 30
    matcher             = "200"
  }
  tags = {
    Name = "code-server-tg"
  }
}

# ACM Certificate
resource "aws_acm_certificate" "wildcard" {
  domain_name       = "*.${var.domain_name}"
  validation_method = "DNS"
  lifecycle {
    prevent_destroy = true
  }
  tags = {
    Name = "code-server-wildcard"
  }
}

# DNS validation records for ACM
resource "aws_route53_record" "cert_validation" {
  for_each = {
    for dvo in aws_acm_certificate.wildcard.domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  }
  zone_id = aws_route53_zone.main.zone_id
  name    = each.value.name
  type    = each.value.type
  records = [each.value.record]
  ttl     = 60
}

# ACM certificate validation
resource "aws_acm_certificate_validation" "wildcard" {
  certificate_arn         = aws_acm_certificate.wildcard.arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

# HTTPS listener for ALB (only HTTPS, no HTTP)
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.code_server.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate_validation.wildcard.certificate_arn
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.code_server.arn
  }
}

# WAFv2 Web ACL for CloudFront
resource "aws_wafv2_web_acl" "code_server" {
  name        = "code-server-waf"
  description = "WAF for code-server CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 0

    override_action {
      count {}
    }

    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesCommonRuleSet"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "code-server-waf"
    sampled_requests_enabled   = true
  }

  tags = {
    Name = "code-server-waf"
  }
}

# CloudFront distribution
resource "aws_cloudfront_distribution" "code_server" {
  enabled             = true
  aliases             = ["${var.subdomain}.${var.domain_name}"]
  default_root_object = ""
  price_class         = "PriceClass_100"
  web_acl_id          = aws_wafv2_web_acl.code_server.arn
  depends_on = [aws_lb_listener.https]

  origin {
    domain_name = aws_lb.code_server.dns_name
    origin_id   = "code-server-alb-origin"
    custom_origin_config {
      http_port                = 443
      https_port               = 443
      origin_protocol_policy   = "https-only"
      origin_ssl_protocols     = ["TLSv1.2"]
    }
  }

  default_cache_behavior {
    target_origin_id       = "code-server-alb-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  viewer_certificate {
    acm_certificate_arn      = aws_acm_certificate.wildcard.arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  tags = {
    Name = "code-server-cloudfront"
  }
}

# ECS Service
resource "aws_ecs_service" "code_server" {
  name            = "code-server-service"
  cluster         = aws_ecs_cluster.code_server.id
  task_definition = aws_ecs_task_definition.code_server.arn
  launch_type     = "FARGATE"
  desired_count   = 1

  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs_tasks.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.code_server.arn
    container_name   = "code-server"
    container_port   = var.container_port
  }

  depends_on = [aws_lb_listener.https]
}

# Route53 Hosted Zone
resource "aws_route53_zone" "main" {
  name = var.domain_name
  lifecycle {
    prevent_destroy = true
  }
  tags = {
    Name = "code-server-hosted-zone"
  }
}

# Route53 A record for subdomain (alias to CloudFront)
resource "aws_route53_record" "code_server" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "${var.subdomain}.${var.domain_name}"
  type    = "A"
  alias {
    name                   = aws_cloudfront_distribution.code_server.domain_name
    zone_id                = aws_cloudfront_distribution.code_server.hosted_zone_id
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "az_count" {
  description = "Number of availability zones to use"
  type        = number
  default     = 2
}

variable "enable_public_subnets" {
  description = "Enable creation of public subnets"
  type        = bool
  default     = true
}

variable "enable_nat_subnets" {
  description = "Enable creation of NAT subnets"
  type        = bool
  default     = false
}

variable "enable_private_subnets" {
  description = "Enable creation of private subnets"
  type        = bool
  default     = false
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "main"
}

variable "egress_cidr_blocks" {
  description = "CIDR blocks allowed for outbound traffic from the public security group"
  type        = list(string)
  default     = ["10.0.0.0/8"]
}

variable "map_public_ip_on_launch" {
  description = "Whether to auto-assign public IP addresses to instances launched in public subnets"
  type        = bool
  default     = false
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = var.environment
  }
}

resource "aws_subnet" "public" {
  count                   = var.enable_public_subnets ? var.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = var.map_public_ip_on_launch
  tags = {
    Name = "${var.environment}-public-${count.index + 1}"
  }
}

resource "aws_subnet" "nat" {
  count             = var.enable_nat_subnets ? var.az_count : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, (var.enable_public_subnets ? var.az_count : 0) + count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "${var.environment}-nat-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = var.enable_private_subnets ? var.az_count : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, (var.enable_public_subnets ? var.az_count : 0) + (var.enable_nat_subnets ? var.az_count : 0) + count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "${var.environment}-private-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.environment}-igw"
  }
}

resource "aws_route_table" "public" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw[0].id
  }

  tags = {
    Name = "${var.environment}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = var.enable_public_subnets ? var.az_count : 0
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_security_group" "public" {
  count       = var.enable_public_subnets ? 1 : 0
  name        = "${var.environment}-public-sg"
  description = "Security group for public subnets with outbound traffic restricted to configured CIDR blocks"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = var.egress_cidr_blocks
  }

  tags = {
    Name = "${var.environment}-public-sg"
  }
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "security_group_id" {
  description = "ID of the public security group"
  value       = one(aws_security_group.public[*].id)
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.1.0"
    }
  }
}

# ----------------------------------------------------------------------
# Variables: all configurable with defaults
# ----------------------------------------------------------------------
variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "zedcloud-vm-images"
}

variable "iam_user_name" {
  description = "Base name for the IAM user"
  type        = string
  default     = "zedcloud-readonly-user"
}

variable "iam_policy_name" {
  description = "Base name for the IAM policy"
  type        = string
  default     = "zedcloud-readonly-policy"
}

variable "create_random_suffix" {
  description = "Whether to append a random hex suffix to resource names"
  type        = bool
  default     = true
}

variable "folder_enabled" {
  description = "Whether to create a marker folder in the bucket"
  type        = bool
  default     = false
}

variable "folder_name" {
  description = "Name of the folder (prefix) inside the bucket"
  type        = string
  default     = "images/"
}

variable "image_file_path" {
  description = "Local path to a VM image file to upload (requires folder_enabled = true)"
  type        = string
  default     = ""
}

# ----------------------------------------------------------------------
# Random suffix (optional)
# ----------------------------------------------------------------------
resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  # Conditionally append the suffix to base names
  bucket_name   = var.create_random_suffix ? "${var.bucket_name}-${random_id.suffix.hex}" : var.bucket_name
  iam_user_name = var.create_random_suffix ? "${var.iam_user_name}-${random_id.suffix.hex}" : var.iam_user_name
  policy_name   = var.create_random_suffix ? "${var.iam_policy_name}-${random_id.suffix.hex}" : var.iam_policy_name

  # Full ARN of the bucket (derived from the bucket resource itself)
  bucket_arn = aws_s3_bucket.main.arn

  # Object key for the uploaded image (if applicable)
  image_object_key = var.folder_enabled && var.image_file_path != "" ? "${var.folder_name}${basename(var.image_file_path)}" : null

  # Folder object key (always folder_name if enabled)
  folder_object_key = var.folder_enabled ? var.folder_name : null
}

# ----------------------------------------------------------------------
# Customer managed KMS key for S3 encryption (CMK)
# ----------------------------------------------------------------------
resource "aws_kms_key" "main" {
  description             = "CMK for S3 bucket ${local.bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# S3 bucket (stateful – prevent_destroy)
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket        = local.bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# S3 bucket public access block (all block_* true)
# ----------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ----------------------------------------------------------------------
# S3 bucket encryption (SSE-KMS with CMK)
# ----------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

# ----------------------------------------------------------------------
# S3 bucket versioning (enabled)
# ----------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ----------------------------------------------------------------------
# IAM user (for Zedcloud integration)
# ----------------------------------------------------------------------
resource "aws_iam_user" "main" {
  name = local.iam_user_name
}

# ----------------------------------------------------------------------
# IAM policy document (read-only access to the bucket)
# ----------------------------------------------------------------------
data "aws_iam_policy_document" "readonly" {
  statement {
    sid    = "ListBucket"
    effect = "Allow"

    actions   = ["s3:ListBucket"]
    resources = [local.bucket_arn]
  }

  statement {
    sid    = "GetObject"
    effect = "Allow"

    actions   = ["s3:GetObject"]
    resources = ["${local.bucket_arn}/*"]
  }
}

# ----------------------------------------------------------------------
# IAM policy (create_before_destroy to avoid name conflicts)
# ----------------------------------------------------------------------
resource "aws_iam_policy" "main" {
  name        = local.policy_name
  description = "Read-only policy for Zedcloud to access VM images in bucket ${local.bucket_name}"
  policy      = data.aws_iam_policy_document.readonly.json

  lifecycle {
    create_before_destroy = true
  }
}

# ----------------------------------------------------------------------
# Attach policy to user
# ----------------------------------------------------------------------
resource "aws_iam_user_policy_attachment" "main" {
  user       = aws_iam_user.main.name
  policy_arn = aws_iam_policy.main.arn
}

# ----------------------------------------------------------------------
# IAM access key (sensitive)
# ----------------------------------------------------------------------
resource "aws_iam_access_key" "main" {
  user = aws_iam_user.main.name
}

# ----------------------------------------------------------------------
# Optional: folder marker object (zero-byte)
# ----------------------------------------------------------------------
resource "aws_s3_object" "folder" {
  count = var.folder_enabled ? 1 : 0

  bucket  = aws_s3_bucket.main.id
  key     = local.folder_object_key
  content = "" # empty content to create a zero-byte marker
}

# ----------------------------------------------------------------------
# Optional: upload VM image file
# ----------------------------------------------------------------------
resource "aws_s3_object" "image" {
  count = var.folder_enabled && var.image_file_path != "" ? 1 : 0

  bucket = aws_s3_bucket.main.id
  key    = local.image_object_key
  source = var.image_file_path
  etag   = filemd5(var.image_file_path)
}

# ----------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------
output "access_key_id" {
  description = "Access key ID for the IAM user"
  value       = aws_iam_access_key.main.id
  sensitive   = true
}

output "secret_access_key" {
  description = "Secret access key for the IAM user"
  value       = aws_iam_access_key.main.secret
  sensitive   = true
}

output "zcli_register_datastore" {
  description = "zCLI command to register the S3 bucket as a datastore in Zedcloud"
  value = format(
    "zcli datastore create %s s3://%s --access-key %s --secret-key %s",
    local.bucket_name,
    local.bucket_name,
    aws_iam_access_key.main.id,
    aws_iam_access_key.main.secret
  )
  sensitive = true
}

output "zcli_create_image" {
  description = "zCLI command to create an image entry in Zedcloud (if an image was uploaded)"
  value = (
    var.folder_enabled && var.image_file_path != ""
    ? format(
        "zcli image create --datastore %s --path %s --image-format raw",
        local.bucket_name,
        local.image_object_key
      )
    : "No image uploaded – skipping image creation command"
  )
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "tfstate_key" {
  description             = "KMS key for encrypting Terraform state and logs"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags = {
    Environment = "security"
  }
}

resource "aws_kms_alias" "tfstate_key" {
  name          = "alias/tfstate-key"
  target_key_id = aws_kms_key.tfstate_key.id
}

resource "aws_s3_bucket" "state" {
  bucket        = "fugue-ci-cd-example-tfstate-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
  force_destroy = false
  tags = {
    Environment = "security"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "logs" {
  bucket        = "fugue-ci-cd-example-logs-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
  force_destroy = false
  tags = {
    Environment = "security"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.tfstate_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.tfstate_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "state" {
  bucket = aws_s3_bucket.state.id

  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "log/"
}

resource "aws_s3_object" "tfstate_folder" {
  bucket       = aws_s3_bucket.state.id
  key          = "tfstate-aws/"
  content_type = "application/x-directory"
  content      = ""
}

resource "aws_dynamodb_table" "tflock" {
  name         = "tfstate-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.tfstate_key.arn
  }

  tags = {
    Environment = "security"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.0"
}

# -----------------------------------------------------------------------
# Variables controlling ELB creation and naming
# -----------------------------------------------------------------------
variable "create_elb" {
  description = "Whether to create the Classic ELB. Set to false to suppress all ELB and policy resources."
  type        = bool
  default     = true
}

variable "name_prefix" {
  description = "Prefix for naming resources (ELB and policies)"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment identifier used in resource names"
  type        = string
  default     = "STAGE"
}

# -----------------------------------------------------------------------
# Standard ELB configuration variables
# -----------------------------------------------------------------------
variable "listeners" {
  description = "List of listener configurations for the ELB. Default is a single HTTP listener on port 80. At least one listener is required when create_elb is true. Override with HTTPS listeners by providing ssl_certificate_id."
  type = list(object({
    instance_port      = number
    instance_protocol  = string
    lb_port            = number
    lb_protocol        = string
    ssl_certificate_id = optional(string)
  }))
  default = [{
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }]
}

variable "health_check" {
  description = "Health check configuration for the ELB"
  type = object({
    target             = string
    interval           = number
    timeout            = number
    healthy_threshold  = number
    unhealthy_threshold = number
  })
  default = null
}

variable "access_logs" {
  description = "Access logs configuration for the ELB"
  type = object({
    bucket        = string
    bucket_prefix = optional(string)
    enabled       = optional(bool, true)
  })
  default = null
}

variable "subnets" {
  description = "List of subnet IDs for the ELB"
  type        = list(string)
  default     = []
}

variable "security_groups" {
  description = "List of security group IDs for the ELB"
  type        = list(string)
  default     = []
}

variable "cross_zone_load_balancing" {
  description = "Enable cross-zone load balancing"
  type        = bool
  default     = false
}

variable "idle_timeout" {
  description = "Idle timeout for connections"
  type        = number
  default     = 60
}

variable "connection_draining" {
  description = "Enable connection draining"
  type        = bool
  default     = false
}

variable "connection_draining_timeout" {
  description = "Timeout for connection draining"
  type        = number
  default     = 300
}

variable "internal" {
  description = "Whether the ELB is internal (private). Defaults to true for security; set to false to create an internet-facing ELB."
  type        = bool
  default     = true
}

# -----------------------------------------------------------------------
# Instance attachment variables
# -----------------------------------------------------------------------
variable "instance_attachments" {
  description = "List of instance IDs to attach to the ELB"
  type        = list(string)
  default     = []
}

variable "enable_instance_attachment" {
  description = "Enable attachment of instances to the ELB"
  type        = bool
  default     = false
}

# -----------------------------------------------------------------------
# Policy enable flags and parameter variables
# -----------------------------------------------------------------------
variable "enable_app_cookie_stickiness" {
  description = "Enable AppCookieStickinessPolicyType"
  type        = bool
  default     = false
}

variable "enable_lb_cookie_stickiness" {
  description = "Enable LBCookieStickinessPolicyType"
  type        = bool
  default     = false
}

variable "enable_ssl_negotiation" {
  description = "Enable SSLNegotiationPolicyType"
  type        = bool
  default     = false
}

variable "enable_proxy_protocol" {
  description = "Enable ProxyProtocolPolicyType"
  type        = bool
  default     = false
}

variable "enable_backend_server_policy" {
  description = "Enable backend server policy attachments"
  type        = bool
  default     = false
}

variable "enable_listener_policy" {
  description = "Enable listener policy attachments"
  type        = bool
  default     = false
}

# Policy naming and parameters
variable "app_cookie_policy_name" {
  description = "Name for the App Cookie Stickiness policy"
  type        = string
  default     = ""
}

variable "cookie_name" {
  description = "Cookie name for App Cookie Stickiness"
  type        = string
  default     = "AppCookie"
}

variable "lb_cookie_policy_name" {
  description = "Name for the LB Cookie Stickiness policy"
  type        = string
  default     = ""
}

variable "lb_cookie_expiration_period" {
  description = "Expiration period (seconds) for LB Cookie Stickiness"
  type        = number
  default     = 86400
}

variable "ssl_negotiation_policy_name" {
  description = "Name for the SSL Negotiation policy"
  type        = string
  default     = ""
}

variable "ssl_security_policy" {
  description = "Security policy for SSL Negotiation"
  type        = string
  default     = "ELBSecurityPolicy-2016-08"
}

variable "proxy_protocol_policy_name" {
  description = "Name for the Proxy Protocol policy"
  type        = string
  default     = ""
}

variable "proxy_protocol_version" {
  description = "Proxy protocol version"
  type        = string
  default     = "1"
}

variable "backend_policy_names_map" {
  description = "Map of instance port (as string) to list of policy names for backend server policy"
  type        = map(list(string))
  default     = {}
}

variable "listener_policy_names_map" {
  description = "Map of ELB listener port (as string) to list of policy names for listener policy"
  type        = map(list(string))
  default     = {}
}

# -----------------------------------------------------------------------
# Locals to derive default policy names from prefix/environment
# -----------------------------------------------------------------------
locals {
  elb_name = "${var.name_prefix}-${var.environment}-elb"

  app_cookie_policy_name    = var.app_cookie_policy_name != "" ? var.app_cookie_policy_name : "${var.name_prefix}-${var.environment}-app-cookie"
  lb_cookie_policy_name     = var.lb_cookie_policy_name != "" ? var.lb_cookie_policy_name : "${var.name_prefix}-${var.environment}-lb-cookie"
  ssl_negotiation_policy_name = var.ssl_negotiation_policy_name != "" ? var.ssl_negotiation_policy_name : "${var.name_prefix}-${var.environment}-ssl-negotiation"
  proxy_protocol_policy_name = var.proxy_protocol_policy_name != "" ? var.proxy_protocol_policy_name : "${var.name_prefix}-${var.environment}-proxy-protocol"
}

# -----------------------------------------------------------------------
# Classic ELB
# -----------------------------------------------------------------------
resource "aws_elb" "main" {
  count = var.create_elb ? 1 : 0

  name                        = local.elb_name
  subnets                     = var.subnets
  security_groups             = var.security_groups
  internal                    = var.internal
  cross_zone_load_balancing   = var.cross_zone_load_balancing
  idle_timeout                = var.idle_timeout
  connection_draining         = var.connection_draining
  connection_draining_timeout = var.connection_draining_timeout

  dynamic "listener" {
    for_each = var.listeners
    content {
      instance_port      = listener.value.instance_port
      instance_protocol  = listener.value.instance_protocol
      lb_port            = listener.value.lb_port
      lb_protocol        = listener.value.lb_protocol
      ssl_certificate_id = listener.value.ssl_certificate_id
    }
  }

  dynamic "health_check" {
    for_each = var.health_check != null ? [1] : []
    content {
      target             = var.health_check.target
      interval           = var.health_check.interval
      timeout            = var.health_check.timeout
      healthy_threshold  = var.health_check.healthy_threshold
      unhealthy_threshold = var.health_check.unhealthy_threshold
    }
  }

  dynamic "access_logs" {
    for_each = var.access_logs != null ? [var.access_logs] : []
    content {
      bucket        = access_logs.value.bucket
      bucket_prefix = access_logs.value.bucket_prefix
      enabled       = access_logs.value.enabled
    }
  }
}

# -----------------------------------------------------------------------
# Instance attachments
# -----------------------------------------------------------------------
resource "aws_elb_attachment" "main" {
  count = var.create_elb && var.enable_instance_attachment ? length(var.instance_attachments) : 0

  elb      = aws_elb.main[0].id
  instance = var.instance_attachments[count.index]
}

# -----------------------------------------------------------------------
# Load Balancer Policies
# Each policy is created only when both create_elb and its enable flag are true.
# -----------------------------------------------------------------------
resource "aws_load_balancer_policy" "app_cookie" {
  count = var.create_elb && var.enable_app_cookie_stickiness ? 1 : 0

  load_balancer_name = aws_elb.main[0].name
  policy_name        = local.app_cookie_policy_name
  policy_type_name   = "AppCookieStickinessPolicyType"

  policy_attribute {
    name  = "CookieName"
    value = var.cookie_name
  }
}

resource "aws_load_balancer_policy" "lb_cookie" {
  count = var.create_elb && var.enable_lb_cookie_stickiness ? 1 : 0

  load_balancer_name = aws_elb.main[0].name
  policy_name        = local.lb_cookie_policy_name
  policy_type_name   = "LBCookieStickinessPolicyType"

  policy_attribute {
    name  = "CookieExpirationPeriod"
    value = var.lb_cookie_expiration_period
  }
}

resource "aws_load_balancer_policy" "ssl_negotiation" {
  count = var.create_elb && var.enable_ssl_negotiation ? 1 : 0

  load_balancer_name = aws_elb.main[0].name
  policy_name        = local.ssl_negotiation_policy_name
  policy_type_name   = "SSLNegotiationPolicyType"

  policy_attribute {
    name  = "Reference-Security-Policy"
    value = var.ssl_security_policy
  }
}

resource "aws_load_balancer_policy" "proxy_protocol" {
  count = var.create_elb && var.enable_proxy_protocol ? 1 : 0

  load_balancer_name = aws_elb.main[0].name
  policy_name        = local.proxy_protocol_policy_name
  policy_type_name   = "ProxyProtocolPolicyType"

  policy_attribute {
    name  = "ProxyProtocol"
    value = var.proxy_protocol_version
  }
}

# -----------------------------------------------------------------------
# Backend Server Policy (attaches policies to instance ports)
# -----------------------------------------------------------------------
resource "aws_load_balancer_backend_server_policy" "main" {
  for_each = var.create_elb && var.enable_backend_server_policy ? var.backend_policy_names_map : {}

  load_balancer_name = aws_elb.main[0].name
  instance_port      = tonumber(each.key)
  policy_names       = each.value
}

# -----------------------------------------------------------------------
# Listener Policy (attaches policies to ELB listeners)
# -----------------------------------------------------------------------
resource "aws_load_balancer_listener_policy" "main" {
  for_each = var.create_elb && var.enable_listener_policy ? var.listener_policy_names_map : {}

  load_balancer_name = aws_elb.main[0].name
  load_balancer_port = tonumber(each.key)
  policy_names       = each.value
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.0"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "repo_name" {
  description = "Name of the ECR repository"
  type        = string
  default     = "my-ecr-repo"
}

variable "visibility" {
  description = "Visibility of the repository (private or public)"
  type        = string
  default     = "private"

  validation {
    condition     = contains(["private", "public"], var.visibility)
    error_message = "The visibility must be either 'private' or 'public'."
  }
}

variable "untagged_image_count" {
  description = "Number of untagged images to retain before expiry (0 means keep all)"
  type        = number
  default     = 1
}

variable "max_tagged_images" {
  description = "Maximum number of tagged images to retain"
  type        = number
  default     = 10
}

variable "read_principals" {
  description = "List of AWS principal ARNs (accounts/roles) granted read-only access"
  type        = list(string)
  default     = []
}

variable "write_principals" {
  description = "List of AWS principal ARNs (accounts/roles) granted read/write access"
  type        = list(string)
  default     = []
}

# -----------------------------------------------------------------------------
# Repository resources
# -----------------------------------------------------------------------------
# Private repository
resource "aws_ecr_repository" "private" {
  count = var.visibility == "private" ? 1 : 0

  name                 = var.repo_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Public repository
resource "aws_ecrpublic_repository" "public" {
  count = var.visibility == "public" ? 1 : 0

  repository_name = var.repo_name

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Lifecycle policy (private only)
# -----------------------------------------------------------------------------
resource "aws_ecr_lifecycle_policy" "private" {
  count = var.visibility == "private" ? 1 : 0

  repository = aws_ecr_repository.private[0].name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images beyond count"
        selection = {
          tagStatus   = "untagged"
          countType   = "imageCountMoreThan"
          countNumber = var.untagged_image_count
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Keep only latest tagged images up to max count"
        selection = {
          tagStatus   = "tagged"
          countType   = "imageCountMoreThan"
          countNumber = var.max_tagged_images
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Repository policy (cross-account access)
# -----------------------------------------------------------------------------
locals {
  repo_arn = try(aws_ecr_repository.private[0].arn, aws_ecrpublic_repository.public[0].arn, "")

  policy_json = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      length(var.read_principals) > 0 ? [
        {
          Sid       = "CrossAccountReadOnly"
          Effect    = "Allow"
          Principal = {
            AWS = var.read_principals
          }
          Action = [
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
            "ecr:BatchCheckLayerAvailability",
            "ecr:DescribeRepositories",
            "ecr:ListImages",
            "ecr:DescribeImages"
          ]
          Resource = local.repo_arn
        }
      ] : [],
      length(var.write_principals) > 0 ? [
        {
          Sid       = "CrossAccountReadWrite"
          Effect    = "Allow"
          Principal = {
            AWS = var.write_principals
          }
          Action = [
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
            "ecr:BatchCheckLayerAvailability",
            "ecr:DescribeRepositories",
            "ecr:ListImages",
            "ecr:DescribeImages",
            "ecr:PutImage",
            "ecr:BatchDeleteImage",
            "ecr:CompleteLayerUpload",
            "ecr:InitiateLayerUpload",
            "ecr:UploadLayerPart"
          ]
          Resource = local.repo_arn
        }
      ] : []
    )
  })
}

# Attach policy to private repository (if any principals are provided)
resource "aws_ecr_repository_policy" "private" {
  count = var.visibility == "private" && (length(var.read_principals) + length(var.write_principals)) > 0 ? 1 : 0

  repository = aws_ecr_repository.private[0].name
  policy     = local.policy_json
}

# Attach policy to public repository (if any principals are provided)
resource "aws_ecrpublic_repository_policy" "public" {
  count = var.visibility == "public" && (length(var.read_principals) + length(var.write_principals)) > 0 ? 1 : 0

  repository_name = aws_ecrpublic_repository.public[0].repository_name
  policy          = local.policy_json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "registry_id" {
  description = "Registry ID (AWS account ID) of the repository"
  value       = try(aws_ecr_repository.private[0].registry_id, aws_ecrpublic_repository.public[0].registry_id, null)
}

output "repository_url" {
  description = "Repository URL"
  value       = try(aws_ecr_repository.private[0].repository_url, aws_ecrpublic_repository.public[0].repository_uri, null)
}

output "repository_name" {
  description = "Repository name"
  value       = try(aws_ecr_repository.private[0].name, aws_ecrpublic_repository.public[0].repository_name, null)
}

output "repository_arn" {
  description = "Repository ARN"
  value       = try(aws_ecr_repository.private[0].arn, aws_ecrpublic_repository.public[0].arn, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_region" "current" {}

# Random pet name prefix
resource "random_pet" "prefix" {
  length    = 2
  separator = "-"
}

locals {
  name_prefix = random_pet.prefix.id
}

# WebSocket API Gateway
resource "aws_apigatewayv2_api" "websocket" {
  name                       = "${local.name_prefix}-ws-api"
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# IAM role for API Gateway
data "aws_iam_policy_document" "assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
    effect = "Allow"
  }
}

resource "aws_iam_role" "api_gateway_sqs" {
  name               = "${local.name_prefix}-api-gateway-sqs-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

# SQS queue
resource "aws_sqs_queue" "main" {
  name                    = "${local.name_prefix}-queue"
  sqs_managed_sse_enabled = true
}

# IAM policy: full SQS access on the queue
data "aws_iam_policy_document" "sqs_access" {
  statement {
    actions   = ["sqs:*"]
    resources = [aws_sqs_queue.main.arn]
    effect    = "Allow"
  }
}

resource "aws_iam_policy" "sqs" {
  name        = "${local.name_prefix}-sqs-policy"
  description = "Full SQS access for the queue"
  policy      = data.aws_iam_policy_document.sqs_access.json
}

resource "aws_iam_role_policy_attachment" "sqs" {
  role       = aws_iam_role.api_gateway_sqs.name
  policy_arn = aws_iam_policy.sqs.arn
}

# IAM policy: CloudWatch logs permissions
data "aws_iam_policy_document" "logs_access" {
  statement {
    actions   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["arn:aws:logs:*:*:log-group:/aws/apigateway/${local.name_prefix}*"]
    effect    = "Allow"
  }
}

resource "aws_iam_policy" "logs" {
  name        = "${local.name_prefix}-logs-policy"
  description = "CloudWatch logs permissions for API Gateway"
  policy      = data.aws_iam_policy_document.logs_access.json
}

resource "aws_iam_role_policy_attachment" "logs" {
  role       = aws_iam_role.api_gateway_sqs.name
  policy_arn = aws_iam_policy.logs.arn
}

# CloudWatch log group
resource "aws_cloudwatch_log_group" "access_logs" {
  name              = "/aws/apigateway/${local.name_prefix}-access-logs"
  retention_in_days = 1
}

# Integrations
# $connect: mock integration (unchanged)
resource "aws_apigatewayv2_integration" "connect_mock" {
  api_id             = aws_apigatewayv2_api.websocket.id
  integration_type   = "MOCK"
  integration_method = "ANY"
  request_templates = {
    "application/json" = jsonencode({
      statusCode = 200
    })
  }
  template_selection_expression = "\\$default"
}

# $default: SQS integration using integration_uri and request_templates
resource "aws_apigatewayv2_integration" "default_sqs" {
  api_id           = aws_apigatewayv2_api.websocket.id
  integration_type = "AWS"
  integration_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${aws_sqs_queue.main.name}"
  credentials_arn  = aws_iam_role.api_gateway_sqs.arn

  request_templates = {
    "application/json" = <<EOF
{
  "QueueUrl":"${aws_sqs_queue.main.url}",
  "MessageBody":"$input.body"
}
EOF
  }
}

# $disconnect: SQS integration using integration_uri and request_templates
resource "aws_apigatewayv2_integration" "disconnect_sqs" {
  api_id           = aws_apigatewayv2_api.websocket.id
  integration_type = "AWS"
  integration_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${aws_sqs_queue.main.name}"
  credentials_arn  = aws_iam_role.api_gateway_sqs.arn

  request_templates = {
    "application/json" = <<EOF
{
  "QueueUrl":"${aws_sqs_queue.main.url}",
  "MessageBody":"Client disconnected"
}
EOF
  }
}

# Routes
resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect_mock.id}"
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default_sqs.id}"
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect_sqs.id}"
}

# Deployment (depends on all routes and integrations)
resource "aws_apigatewayv2_deployment" "main" {
  api_id      = aws_apigatewayv2_api.websocket.id
  description = "Deployment for WebSocket API"

  triggers = {
    api_id                = aws_apigatewayv2_api.websocket.id
    connect_integration   = aws_apigatewayv2_integration.connect_mock.id
    default_integration   = aws_apigatewayv2_integration.default_sqs.id
    disconnect_integration = aws_apigatewayv2_integration.disconnect_sqs.id
    connect_route         = aws_apigatewayv2_route.connect.id
    default_route         = aws_apigatewayv2_route.default.id
    disconnect_route      = aws_apigatewayv2_route.disconnect.id
  }

  lifecycle {
    create_before_destroy = true
  }
}

# Stage
resource "aws_apigatewayv2_stage" "dev" {
  api_id        = aws_apigatewayv2_api.websocket.id
  name          = "dev"
  auto_deploy   = true
  deployment_id = aws_apigatewayv2_deployment.main.id

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.access_logs.arn
    format          = "{\"requestId\":\"$context.requestId\",\"ip\":\"$context.identity.sourceIp\",\"routeKey\":\"$context.routeKey\",\"status\":$context.status,\"responseLatency\":$context.responseLatency,\"requestTime\":\"$context.requestTime\"}"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# DynamoDB table
resource "aws_dynamodb_table" "pets" {
  name         = "Pets"
  billing_mode = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }
  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name               = "PetType-index"
    hash_key           = "PetType"
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
    read_capacity      = 5
    write_capacity     = 5
  }

  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for API Gateway to DynamoDB
resource "aws_iam_role" "dynamodb_api_role" {
  name = "ApiGatewayDynamoDBRole"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "apigateway.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy" "dynamodb_api_policy" {
  name = "ApiGatewayDynamoDBPolicy"
  role = aws_iam_role.dynamodb_api_role.id

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "dynamodb:PutItem",
      "Resource": "${aws_dynamodb_table.pets.arn}"
    },
    {
      "Effect": "Allow",
      "Action": "dynamodb:Query",
      "Resource": [
        "${aws_dynamodb_table.pets.arn}",
        "${aws_dynamodb_table.pets.arn}/index/PetType-index"
      ]
    }
  ]
}
EOF
}

# Local OpenAPI specification
locals {
  openapi_spec = <<-JSON
{
  "swagger": "2.0",
  "info": {
    "title": "Pets API",
    "version": "1.0"
  },
  "basePath": "/v1",
  "x-amazon-apigateway-api-key-source": "HEADER",
  "paths": {
    "/pets": {
      "post": {
        "consumes": ["application/json"],
        "produces": ["application/json"],
        "parameters": [
          {
            "in": "body",
            "name": "requestBody",
            "required": true,
            "schema": {
              "type": "object",
              "properties": {
                "PetType": { "type": "string" },
                "PetName": { "type": "string" },
                "PetPrice": { "type": "string" }
              }
            }
          }
        ],
        "responses": {
          "200": {
            "description": "OK",
            "schema": { "type": "object" }
          }
        },
        "x-amazon-apigateway-integration": {
          "type": "aws",
          "httpMethod": "POST",
          "credentials": "${aws_iam_role.dynamodb_api_role.arn}",
          "requestTemplates": {
            "application/json": "{\n  \"TableName\": \"Pets\",\n  \"Item\": {\n    \"id\": { \"S\": \"$context.requestId\" },\n    \"PetType\": { \"S\": \"$input.path('$.PetType')\" },\n    \"PetName\": { \"S\": \"$input.path('$.PetName')\" },\n    \"PetPrice\": { \"S\": \"$input.path('$.PetPrice')\" }\n  }\n}"
          },
          "responses": {
            "200": {
              "responseTemplates": {
                "application/json": "#set($inputRoot = $input.path('$'))\n{ \"message\": \"Pet created\" }"
              }
            }
          }
        },
        "security": [{"api_key": []}]
      }
    },
    "/pets/{PetType}": {
      "get": {
        "produces": ["application/json"],
        "parameters": [
          {
            "name": "PetType",
            "in": "path",
            "required": true,
            "type": "string"
          }
        ],
        "responses": {
          "200": {
            "description": "OK",
            "schema": {
              "type": "array",
              "items": { "type": "object" }
            }
          }
        },
        "x-amazon-apigateway-integration": {
          "type": "aws",
          "httpMethod": "POST",
          "credentials": "${aws_iam_role.dynamodb_api_role.arn}",
          "requestTemplates": {
            "application/json": "{\n  \"TableName\": \"Pets\",\n  \"IndexName\": \"PetType-index\",\n  \"KeyConditionExpression\": \"PetType = :PetType\",\n  \"ExpressionAttributeValues\": {\n    \":PetType\": { \"S\": \"$input.params('PetType')\" }\n  }\n}"
          },
          "responses": {
            "200": {
              "responseTemplates": {
                "application/json": "#set($inputRoot = $input.path('$'))\n{\n  \"pets\": $input.json('$.Items')\n}"
              }
            }
          }
        },
        "security": [{"api_key": []}]
      }
    }
  },
  "securityDefinitions": {
    "api_key": {
      "type": "apiKey",
      "name": "x-api-key",
      "in": "header"
    }
  }
}
JSON
}

# API Gateway REST API
resource "aws_api_gateway_rest_api" "pets" {
  name        = "Pets API"
  body        = local.openapi_spec

  lifecycle {
    create_before_destroy = true
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "api_gw" {
  name              = "/aws/APIGW/terraform"
  retention_in_days = 7
}

# CloudWatch Log Resource Policy
resource "aws_cloudwatch_log_resource_policy" "api_gw" {
  policy_name = "ApiGatewayLogPolicy"

  policy_document = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "apigateway.amazonaws.com"
      },
      "Action": [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ],
      "Resource": "${aws_cloudwatch_log_group.api_gw.arn}:*"
    }
  ]
}
EOF
}

# IAM role for API Gateway to write logs to CloudWatch
resource "aws_iam_role" "cloudwatch_log_role" {
  name = "ApiGatewayCloudWatchLogRole"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "apigateway.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy" "cloudwatch_log_policy" {
  name = "ApiGatewayCloudWatchLogPolicy"
  role = aws_iam_role.cloudwatch_log_role.id

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ],
      "Resource": "${aws_cloudwatch_log_group.api_gw.arn}:*"
    }
  ]
}
EOF
}

# API Gateway Account Settings
resource "aws_api_gateway_account" "main" {
  cloudwatch_role_arn = aws_iam_role.cloudwatch_log_role.arn
}

# API Gateway Deployment
resource "aws_api_gateway_deployment" "v1" {
  rest_api_id = aws_api_gateway_rest_api.pets.id

  triggers = {
    redeployment = sha256(local.openapi_spec)
  }

  depends_on = [
    aws_api_gateway_rest_api.pets,
    aws_iam_role.dynamodb_api_role,
    aws_dynamodb_table.pets,
    aws_cloudwatch_log_group.api_gw,
    aws_cloudwatch_log_resource_policy.api_gw,
    aws_iam_role.cloudwatch_log_role,
    aws_iam_role_policy.cloudwatch_log_policy,
    aws_api_gateway_account.main
  ]
}

# API Gateway Stage
resource "aws_api_gateway_stage" "v1" {
  stage_name    = "v1"
  rest_api_id   = aws_api_gateway_rest_api.pets.id
  deployment_id = aws_api_gateway_deployment.v1.id

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_gw.arn
    format = jsonencode({
      requestId       = "$context.requestId"
      httpMethod      = "$context.httpMethod"
      path            = "$context.path"
      status          = "$context.status"
      responseLatency = "$context.responseLatency"
    })
  }
}

# Method settings for all methods
resource "aws_api_gateway_method_settings" "all" {
  rest_api_id = aws_api_gateway_rest_api.pets.id
  stage_name  = aws_api_gateway_stage.v1.stage_name
  method_path = "*/*"
  settings {
    logging_level      = "INFO"
    metrics_enabled    = true
    data_trace_enabled = false
  }
}

# Usage Plan
resource "aws_api_gateway_usage_plan" "pets" {
  name = "pets-api-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.pets.id
    stage  = aws_api_gateway_stage.v1.stage_name
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }
}

# API Key
resource "aws_api_gateway_api_key" "pets" {
  name    = "pets-api-key"
  enabled = true
}

# Usage Plan Key Association
resource "aws_api_gateway_usage_plan_key" "pets" {
  key_id        = aws_api_gateway_api_key.pets.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.pets.id
}

# Outputs
output "api_invoke_url" {
  value = "${aws_api_gateway_stage.v1.invoke_url}/v1/pets"
}

output "api_key_value" {
  value     = aws_api_gateway_api_key.pets.value
  sensitive = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "secondary_cidr_blocks" {
  type    = list(string)
  default = []
}

variable "az_count" {
  type    = number
  default = 2
}

variable "tags" {
  type    = map(string)
  default = {
    Environment = "dev"
    Project     = "vpc-template"
  }
}

variable "dhcp_domain_name" {
  type    = string
  default = "example.com"
}

variable "dhcp_domain_name_servers" {
  type    = list(string)
  default = ["AmazonProvidedDNS"]
}

locals {
  azs = data.aws_availability_zones.available.names
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "main-vpc"
  })
}

resource "aws_vpc_ipv4_cidr_block_association" "secondary" {
  count      = length(var.secondary_cidr_blocks)
  vpc_id     = aws_vpc.main.id
  cidr_block = var.secondary_cidr_blocks[count.index]
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.dhcp_domain_name
  domain_name_servers = var.dhcp_domain_name_servers

  tags = merge(var.tags, {
    Name = "main-dhcp-options"
  })
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "main-igw"
  })
}

resource "aws_eip" "nat" {
  count  = var.az_count
  domain = "vpc"

  tags = merge(var.tags, {
    Name = "nat-eip-${count.index}"
  })
}

resource "aws_nat_gateway" "main" {
  count         = var.az_count
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(var.tags, {
    Name = "nat-gateway-${count.index}"
  })
}

resource "aws_subnet" "public" {
  count                   = var.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "public-subnet-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count                   = var.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "private-subnet-${count.index}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "public-route-table"
  })
}

resource "aws_route" "public_internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = var.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = var.az_count
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "private-route-table-${count.index}"
  })
}

resource "aws_route" "private_nat_gateway" {
  count                  = var.az_count
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route_table_association" "private" {
  count          = var.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress = []
  egress  = []

  tags = merge(var.tags, {
    Name = "default-security-group"
  })
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.main.cidr_block
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.main.cidr_block
    from_port  = 1024
    to_port    = 65535
  }

  tags = merge(var.tags, {
    Name = "default-network-acl"
  })
}

resource "aws_default_route_table" "default" {
  default_route_table_id = aws_vpc.main.default_route_table_id

  tags = merge(var.tags, {
    Name = "default-route-table"
  })
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name = "/aws/vpc/flow-log/main"

  tags = merge(var.tags, {
    Name = "vpc-flow-log-group"
  })
}

data "aws_iam_policy_document" "flow_log" {
  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      aws_cloudwatch_log_group.flow_log.arn,
      "${aws_cloudwatch_log_group.flow_log.arn}:*",
    ]
  }
}

resource "aws_iam_role" "flow_log" {
  name = "vpc-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "flow_log" {
  name   = "vpc-flow-log-policy"
  role   = aws_iam_role.flow_log.id
  policy = data.aws_iam_policy_document.flow_log.json
}

resource "aws_flow_log" "vpc_flow_log" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_group_name       = aws_cloudwatch_log_group.flow_log.name
  iam_role_arn         = aws_iam_role.flow_log.arn

  tags = merge(var.tags, {
    Name = "vpc-flow-log"
  })
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "vpc_arn" {
  value = aws_vpc.main.arn
}

output "vpc_cidr_block" {
  value = aws_vpc.main.cidr_block
}

# Required providers
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Data sources for region
data "aws_region" "current" {}

# Variables
variable "state_bucket_name" {
  description = "Name of the S3 bucket for Terraform state storage"
  type        = string
  default     = "terraform-state-bucket"
}

variable "state_table_name" {
  description = "Name of the DynamoDB table for Terraform state locking"
  type        = string
  default     = "terraform-state-lock-table"
}

variable "logs_bucket_name" {
  description = "Name of the S3 bucket for CodeBuild logs"
  type        = string
  default     = "codebuild-logs-bucket"
}

variable "repo_name" {
  description = "Name of the CodeCommit repository"
  type        = string
  default     = "vpc-deployment-repo"
}

variable "codecommit_username" {
  description = "IAM username for CodeCommit access"
  type        = string
  default     = "codecommit-user"
}

variable "terraform_version" {
  description = "Terraform version to use in CodeBuild"
  type        = string
  default     = "1.2.3"
}

variable "state_key" {
  description = "Terraform state file key"
  type        = string
  default     = "vpc/terraform.tfstate"
}

variable "default_branch" {
  description = "Default branch for the CodeCommit repository and pipeline source"
  type        = string
  default     = "main"
}

# ----- KMS Keys -----
resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform state S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_key" "logs" {
  description             = "KMS key for CodeBuild logs S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ----- S3 Bucket for Terraform State -----
resource "aws_s3_bucket" "state" {
  bucket        = var.state_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket                  = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

# ----- DynamoDB Table for State Locking -----
resource "aws_dynamodb_table" "state_lock" {
  name           = var.state_table_name
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ----- S3 Bucket for CodeBuild Logs -----
resource "aws_s3_bucket" "logs" {
  bucket        = var.logs_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.logs.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

# ----- IAM User for CodeCommit -----
data "aws_iam_policy" "codecommit_poweruser" {
  arn = "arn:aws:iam::aws:policy/AWSCodeCommitPowerUser"
}

resource "aws_iam_user" "codecommit_user" {
  name = var.codecommit_username
}

resource "aws_iam_user_policy_attachment" "codecommit_user" {
  user       = aws_iam_user.codecommit_user.name
  policy_arn = data.aws_iam_policy.codecommit_poweruser.arn
}

# ----- CodeCommit Repository -----
resource "aws_codecommit_repository" "vpc_repo" {
  repository_name = var.repo_name
  description     = "Repository for VPC Terraform deployment code"
}

# ----- IAM Roles and Policies for CodeBuild and CodePipeline -----
# CodeBuild Role
resource "aws_iam_role" "codebuild" {
  name = "codebuild-role-vpc-pipeline"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "codebuild" {
  name        = "codebuild-policy-vpc-pipeline"
  description = "Policy for CodeBuild to manage Terraform state and logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*",
          aws_s3_bucket.logs.arn,
          "${aws_s3_bucket.logs.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:GetItem",
          "dynamodb:DeleteItem",
          "dynamodb:DescribeTable"
        ]
        Resource = aws_dynamodb_table.state_lock.arn
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:log-group:/aws/codebuild/*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.state.arn,
          aws_kms_key.logs.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild" {
  role       = aws_iam_role.codebuild.name
  policy_arn = aws_iam_policy.codebuild.arn
}

# CodePipeline Role
resource "aws_iam_role" "codepipeline" {
  name = "codepipeline-role-vpc-pipeline"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "codepipeline" {
  name        = "codepipeline-policy-vpc-pipeline"
  description = "Policy for CodePipeline to access CodeCommit and CodeBuild"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:UploadArchive",
          "codecommit:GetUploadArchiveStatus",
          "codecommit:CancelUploadArchive"
        ]
        Resource = aws_codecommit_repository.vpc_repo.arn
      },
      {
        Effect = "Allow"
        Action = [
          "codebuild:StartBuild",
          "codebuild:BatchGetBuilds"
        ]
        Resource = aws_codebuild_project.vpc.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.logs.arn,
          "${aws_s3_bucket.logs.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.logs.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codepipeline" {
  role       = aws_iam_role.codepipeline.name
  policy_arn = aws_iam_policy.codepipeline.arn
}

# ----- CodeBuild Project -----
resource "aws_codebuild_project" "vpc" {
  name         = "vpc-terraform-build"
  description  = "CodeBuild project for VPC Terraform deployment"
  service_role = aws_iam_role.codebuild.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:5.0"
    type         = "LINUX_CONTAINER"

    environment_variable {
      name  = "TF_ACTION"
      value = "plan" # overridden by pipeline
    }

    environment_variable {
      name  = "TF_VERSION"
      value = var.terraform_version
    }

    environment_variable {
      name  = "TF_BACKEND_BUCKET"
      value = aws_s3_bucket.state.id
    }

    environment_variable {
      name  = "TF_BACKEND_KEY"
      value = var.state_key
    }

    environment_variable {
      name  = "TF_BACKEND_REGION"
      value = data.aws_region.current.name
    }

    environment_variable {
      name  = "TF_BACKEND_DYNAMODB_TABLE"
      value = aws_dynamodb_table.state_lock.name
    }
  }

  logs_config {
    s3_logs {
      status   = "ENABLED"
      location = "${aws_s3_bucket.logs.id}/build-logs"
    }
  }

  source {
    type            = "CODECOMMIT"
    location        = aws_codecommit_repository.vpc_repo.clone_url_http
    git_clone_depth = 1

    buildspec = <<-EOT
version: 0.2

phases:
  install:
    runtime-versions:
      python: 3.11
    commands:
      - echo "Installing Terraform version $${TF_VERSION}"
      - curl -O "https://releases.hashicorp.com/terraform/$${TF_VERSION}/terraform_$${TF_VERSION}_linux_amd64.zip"
      - unzip terraform_$${TF_VERSION}_linux_amd64.zip -d /usr/local/bin/
      - rm terraform_$${TF_VERSION}_linux_amd64.zip
      - terraform --version
  pre_build:
    commands:
      - echo "Initializing Terraform"
      - terraform init -input=false -backend-config="bucket=$${TF_BACKEND_BUCKET}" -backend-config="key=$${TF_BACKEND_KEY}" -backend-config="region=$${TF_BACKEND_REGION}" -backend-config="dynamodb_table=$${TF_BACKEND_DYNAMODB_TABLE}"
  build:
    commands:
      - |
        if [ "$TF_ACTION" = "plan" ]; then
          terraform plan -out=tfplan
        elif [ "$TF_ACTION" = "apply" ]; then
          terraform apply -auto-approve tfplan
        else
          echo "Unknown TF_ACTION: $TF_ACTION"
          exit 1
        fi
    EOT
  }
}

# ----- CodePipeline -----
resource "aws_codepipeline" "vpc" {
  name     = "vpc-terraform-pipeline"
  role_arn = aws_iam_role.codepipeline.arn

  artifact_store {
    type     = "S3"
    location = aws_s3_bucket.logs.id
  }

  stage {
    name = "Source"

    action {
      name             = "Source"
      category         = "Source"
      owner            = "AWS"
      provider         = "CodeCommit"
      version          = "1"
      output_artifacts = ["source_output"]

      configuration = {
        RepositoryName = aws_codecommit_repository.vpc_repo.repository_name
        BranchName     = var.default_branch
      }
    }
  }

  stage {
    name = "Development"

    action {
      name            = "Terraform-Plan"
      category        = "Build"
      owner           = "AWS"
      provider        = "CodeBuild"
      version         = "1"
      input_artifacts = ["source_output"]

      configuration = {
        ProjectName = aws_codebuild_project.vpc.name
        EnvironmentVariables = jsonencode([
          {
            name  = "TF_ACTION"
            value = "plan"
            type  = "PLAINTEXT"
          }
        ])
      }
    }

    action {
      name            = "Terraform-Apply"
      category        = "Build"
      owner           = "AWS"
      provider        = "CodeBuild"
      version         = "1"
      input_artifacts = ["source_output"]
      run_order       = 2

      configuration = {
        ProjectName = aws_codebuild_project.vpc.name
        EnvironmentVariables = jsonencode([
          {
            name  = "TF_ACTION"
            value = "apply"
            type  = "PLAINTEXT"
          }
        ])
      }
    }
  }

  # Commented-out UAT stage
  # stage {
  #   name = "UAT"
  #   action {
  #     name            = "Terraform-Plan"
  #     category        = "Build"
  #     owner           = "AWS"
  #     provider        = "CodeBuild"
  #     version         = "1"
  #     input_artifacts = ["source_output"]
  #     configuration = {
  #       ProjectName = aws_codebuild_project.vpc.name
  #       EnvironmentVariables = jsonencode([
  #         { name = "TF_ACTION", value = "plan", type = "PLAINTEXT" }
  #       ])
  #     }
  #   }
  #   action {
  #     name            = "Terraform-Apply"
  #     category        = "Build"
  #     owner           = "AWS"
  #     provider        = "CodeBuild"
  #     version         = "1"
  #     input_artifacts = ["source_output"]
  #     run_order       = 2
  #     configuration = {
  #       ProjectName = aws_codebuild_project.vpc.name
  #       EnvironmentVariables = jsonencode([
  #         { name = "TF_ACTION", value = "apply", type = "PLAINTEXT" }
  #       ])
  #     }
  #   }
  # }

  # Commented-out Production stage with approval gate
  # stage {
  #   name = "Production"
  #   action {
  #     name     = "Approval"
  #     category = "Approval"
  #     owner    = "AWS"
  #     provider = "Manual"
  #     version  = "1"
  #     configuration = {
  #       CustomData = "Approve VPC deployment to production?"
  #     }
  #   }
  #   action {
  #     name            = "Terraform-Plan"
  #     category        = "Build"
  #     owner           = "AWS"
  #     provider        = "CodeBuild"
  #     version         = "1"
  #     input_artifacts = ["source_output"]
  #     run_order       = 2
  #     configuration = {
  #       ProjectName = aws_codebuild_project.vpc.name
  #       EnvironmentVariables = jsonencode([
  #         { name = "TF_ACTION", value = "plan", type = "PLAINTEXT" }
  #       ])
  #     }
  #   }
  #   action {
  #     name            = "Terraform-Apply"
  #     category        = "Build"
  #     owner           = "AWS"
  #     provider        = "CodeBuild"
  #     version         = "1"
  #     input_artifacts = ["source_output"]
  #     run_order       = 3
  #     configuration = {
  #       ProjectName = aws_codebuild_project.vpc.name
  #       EnvironmentVariables = jsonencode([
  #         { name = "TF_ACTION", value = "apply", type = "PLAINTEXT" }
  #       ])
  #     }
  #   }
  # }
}

terraform {
  required_version = "~> 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region                      = "us-east-1"
  access_key                  = "test"
  secret_key                  = "test"
  shared_config_files         = []
  shared_credentials_files    = []
  skip_credentials_validation = true
  skip_requesting_account_id  = true
  skip_metadata_api_check     = true
  s3_use_path_style           = true

  endpoints {
    codeartifact = "http://localhost:4566"
  }
}

variable "enable_domain" {
  type    = bool
  default = true
}

variable "enable_repository" {
  type    = bool
  default = true
}

variable "enable_domain_policy" {
  type    = bool
  default = false
}

variable "enable_repository_policy" {
  type    = bool
  default = false
}

variable "base_name" {
  type    = string
  default = "myapp"
}

variable "environment" {
  type    = string
  default = "dev"
}

variable "domain_kms_key_arn" {
  type    = string
  default = ""
}

variable "upstream_repositories" {
  type    = list(string)
  default = []
}

variable "external_connections" {
  type    = list(string)
  default = []
}

variable "domain_policy_document" {
  type    = string
  default = ""
}

variable "repository_policy_document" {
  type    = string
  default = ""
}

variable "tags" {
  type    = map(string)
  default = {}
}

locals {
  name_prefix = lower(var.base_name)
  domain_name = lower("${local.name_prefix}-codeartifact-domain-${var.environment}")
  repo_name   = lower("${local.name_prefix}-codeartifact-repository-${var.environment}")
}

# Domain resource – conditionally created
resource "aws_codeartifact_domain" "main" {
  count = var.enable_domain ? 1 : 0

  domain = local.domain_name
  encryption_key = var.domain_kms_key_arn != "" ? var.domain_kms_key_arn : null
  tags = merge(var.tags, { Name = local.domain_name })

  lifecycle {
    prevent_destroy = true
  }
}

# Repository resource – conditionally created
resource "aws_codeartifact_repository" "main" {
  count = var.enable_repository ? 1 : 0

  repository = local.repo_name

  domain = try(aws_codeartifact_domain.main[0].domain, local.domain_name)

  dynamic "upstream" {
    for_each = var.upstream_repositories
    content {
      repository_name = upstream.value
    }
  }

  dynamic "external_connections" {
    for_each = var.external_connections
    content {
      external_connection_name = external_connections.value
    }
  }

  tags = merge(var.tags, { Name = local.repo_name })
}

# Domain permissions policy – conditionally created (tags not supported)
resource "aws_codeartifact_domain_permissions_policy" "main" {
  count = var.enable_domain_policy ? 1 : 0

  domain = local.domain_name
  policy_document = var.domain_policy_document
}

# Repository permissions policy – conditionally created (tags not supported)
resource "aws_codeartifact_repository_permissions_policy" "main" {
  count = var.enable_repository_policy ? 1 : 0

  domain = local.domain_name
  repository = local.repo_name
  policy_document = var.repository_policy_document
}

# Outputs
output "domain_id" {
  value = try(aws_codeartifact_domain.main[0].id, null)
}

output "domain_arn" {
  value = try(aws_codeartifact_domain.main[0].arn, null)
}

output "domain_owner" {
  value = try(aws_codeartifact_domain.main[0].owner, null)
}

output "domain_created_time" {
  value = try(aws_codeartifact_domain.main[0].created_time, null)
}

output "domain_repository_count" {
  value = try(aws_codeartifact_domain.main[0].repository_count, null)
}

output "domain_asset_size_bytes" {
  value = try(aws_codeartifact_domain.main[0].asset_size_bytes, null)
}

output "repository_id" {
  value = try(aws_codeartifact_repository.main[0].id, null)
}

output "repository_arn" {
  value = try(aws_codeartifact_repository.main[0].arn, null)
}

output "repository_domain_owner" {
  value = try(aws_codeartifact_repository.main[0].domain_owner, null)
}

output "domain_policy_arn" {
  value = try(aws_codeartifact_domain_permissions_policy.main[0].resource_arn, null)
}

output "repository_policy_arn" {
  value = try(aws_codeartifact_repository_permissions_policy.main[0].id, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name          = "internal"
  domain_name_servers  = ["10.0.0.2", "8.8.8.8"]

  tags = {
    Name = "main-dhcp-options"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_route53_zone" "internal" {
  name = "internal"
  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = "internal-zone"
  }
}

# ----------------------------------------------------------------------
# Reserved subnet (10.0.0.0/24)
# ----------------------------------------------------------------------
resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "reserved-subnet"
  }
}

resource "aws_route_table" "reserved" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "reserved-rt"
  }
}

resource "aws_route_table_association" "reserved" {
  subnet_id      = aws_subnet.reserved.id
  route_table_id = aws_route_table.reserved.id
}

resource "aws_network_acl" "reserved" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "reserved-acl"
  }
}

resource "aws_network_acl_rule" "reserved_ingress_tcp" {
  network_acl_id = aws_network_acl.reserved.id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "reserved_ingress_udp" {
  network_acl_id = aws_network_acl.reserved.id
  rule_number    = 110
  egress         = false
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "reserved_egress_tcp" {
  network_acl_id = aws_network_acl.reserved.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "reserved_egress_udp" {
  network_acl_id = aws_network_acl.reserved.id
  rule_number    = 110
  egress         = true
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_association" "reserved" {
  subnet_id      = aws_subnet.reserved.id
  network_acl_id = aws_network_acl.reserved.id
}

