# ----------------------------------------------------------------------
# Security Groups
# ----------------------------------------------------------------------
variable "ssh_allowed_cidrs" {
  type    = list(string)
  default = ["10.0.0.0/8"]
}

resource "aws_security_group" "ssh_access" {
  name        = "ssh-access"
  description = "Allow SSH from specified CIDRs"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.ssh_allowed_cidrs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = {
    Name = "ssh-access"
  }
}

resource "aws_security_group" "packer_builds" {
  name        = "packer-builds"
  description = "Allow SSH from specific CIDRs for Packer builds"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = {
    Name = "packer-builds"
  }
}

