output "internal_zone_id" {
  value = aws_route53_zone.internal.zone_id
}

output "ssh_security_group_id" {
  value = aws_security_group.ssh_access.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
  required_version = ">= 1.3.0"
}

# Variables
variable "create_bucket" {
  description = "Whether to create the S3 bucket"
  type        = bool
  default     = true
}

variable "enable_features" {
  description = "Master switch for all optional features"
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "Fixed bucket name (used if bucket_prefix is empty)"
  type        = string
  default     = "my-test-bucket"
}

variable "bucket_prefix" {
  description = "Prefix for bucket name (takes precedence over bucket_name); a random suffix is appended"
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Allow bucket deletion even if not empty"
  type        = bool
  default     = false
}

variable "enable_website" {
  description = "Enable static website hosting"
  type        = bool
  default     = false
}

variable "index_document" {
  description = "Index document for website"
  type        = string
  default     = "index.html"
}

variable "error_document" {
  description = "Error document for website"
  type        = string
  default     = "error.html"
}

variable "cors_rules" {
  description = "List of CORS rules; each rule is an object with allowed_headers, allowed_methods, allowed_origins, expose_headers, max_age_seconds"
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules; each rule is an object with id, status, filter (prefix, tags), transitions, expiration, noncurrent_version_expiration"
  type = list(object({
    id     = string
    status = string
    filter = object({
      prefix = optional(string)
      tags   = optional(map(string))
    })
    transitions = optional(list(object({
      days          = number
      storage_class = string
    })), [])
    expiration = optional(object({
      days = number
    }))
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
  }))
  default = []
}

variable "sse_algorithm" {
  description = "Server-side encryption algorithm: AES256 or aws:kms"
  type        = string
  default     = "AES256"
}

variable "enable_versioning" {
  description = "Enable bucket versioning"
  type        = bool
  default     = false
}

variable "logging_target_bucket_prefix" {
  description = "Prefix for the logging target bucket; if non-empty, a separate logging bucket is created and logging is enabled"
  type        = string
  default     = ""
}

variable "enable_replication" {
  description = "Enable replication configuration"
  type        = bool
  default     = false
}

variable "replication_destination_bucket_prefix" {
  description = "Prefix for the replication destination bucket"
  type        = string
  default     = "replication-destination"
}

variable "enable_object_lock" {
  description = "Enable object lock (requires versioning)"
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Object lock default retention mode: GOVERNANCE or COMPLIANCE"
  type        = string
  default     = "GOVERNANCE"
}

variable "object_lock_days" {
  description = "Default retention period in days (mutually exclusive with years)"
  type        = number
  default     = null
}

variable "object_lock_years" {
  description = "Default retention period in years (mutually exclusive with days)"
  type        = number
  default     = null
}

variable "intelligent_tiering_tiers" {
  description = "List of intelligent tiering tiers; each tier is an object with access_tier and days"
  type = list(object({
    access_tier = string
    days        = number
  }))
  default = []
}

variable "request_payer" {
  description = "Request payer configuration: BucketOwner or Requester"
  type        = string
  default     = null
}

variable "enable_acceleration" {
  description = "Enable transfer acceleration"
  type        = bool
  default     = false
}

variable "acl" {
  description = "Canned ACL to apply (e.g., private, public-read); leave null if not using ACL"
  type        = string
  default     = null
}

variable "enable_deny_insecure_transport" {
  description = "Add bucket policy to deny non-SSL transport and require TLS 1.2+"
  type        = bool
  default     = false
}

variable "log_delivery_services" {
  description = "List of AWS services for which to grant log delivery permissions (e.g., elasticloadbalancing.amazonaws.com)"
  type        = list(string)
  default     = []
}

variable "block_public_acls" {
  description = "Block public ACLs"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets"
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership control: BucketOwnerPreferred, ObjectWriter, or BucketOwnerEnforced"
  type        = string
  default     = null
}

# Random suffix for bucket naming
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# Locals
locals {
  create_bucket = var.create_bucket && var.enable_features
  bucket_name   = var.bucket_prefix != "" ? "${var.bucket_prefix}-${random_id.bucket_suffix.hex}" : var.bucket_name

  # Logging bucket
  logging_bucket_name = var.logging_target_bucket_prefix != "" ? "${var.logging_target_bucket_prefix}-${random_id.bucket_suffix.hex}" : null
}

# Main S3 bucket
resource "aws_s3_bucket" "this" {
  count         = local.create_bucket ? 1 : 0
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  request_payer = var.request_payer != null ? var.request_payer : null
}

# Website configuration
resource "aws_s3_bucket_website_configuration" "this" {
  count  = local.create_bucket && var.enable_website ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket

  index_document {
    suffix = var.index_document
  }
  error_document {
    key = var.error_document
  }
}

# CORS configuration
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = local.create_bucket && length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Lifecycle configuration
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = local.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      filter {
        prefix = try(rule.value.filter.prefix, null)
        dynamic "tag" {
          for_each = try(rule.value.filter.tags, {})
          content {
            key   = tag.key
            value = tag.value
          }
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      expiration {
        days = try(rule.value.expiration.days, null)
      }

      noncurrent_version_expiration {
        noncurrent_days = try(rule.value.noncurrent_version_expiration.noncurrent_days, null)
      }
    }
  }
}

# Server-side encryption configuration
resource "aws_kms_key" "sse" {
  count = local.create_bucket && var.sse_algorithm == "aws:kms" ? 1 : 0
  description             = "KMS key for S3 SSE"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = local.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = var.sse_algorithm == "aws:kms" ? aws_kms_key.sse[0].arn : null
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  count  = local.create_bucket && var.enable_versioning ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket
  versioning_configuration {
    status = "Enabled"
  }
}

# Logging bucket and configuration
resource "aws_s3_bucket" "logging" {
  count  = local.create_bucket && var.logging_target_bucket_prefix != "" ? 1 : 0
  bucket = local.logging_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count                   = local.create_bucket && var.logging_target_bucket_prefix != "" ? 1 : 0
  bucket                  = aws_s3_bucket.logging[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = local.create_bucket && var.logging_target_bucket_prefix != "" ? 1 : 0
  bucket = aws_s3_bucket.logging[0].bucket

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_logging" "this" {
  count         = local.create_bucket && var.logging_target_bucket_prefix != "" ? 1 : 0
  bucket        = aws_s3_bucket.this[0].bucket
  target_bucket = aws_s3_bucket.logging[0].bucket
  target_prefix = "s3-access-logs/"
}

# Replication
resource "aws_iam_role" "replication" {
  count = local.create_bucket && var.enable_replication ? 1 : 0
  name  = "s3-replication-role-${random_id.bucket_suffix.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  count = local.create_bucket && var.enable_replication ? 1 : 0
  name  = "s3-replication-policy-${random_id.bucket_suffix.hex}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = aws_s3_bucket.this[0].arn
      },
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.this[0].arn}/*"
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.replication_destination[0].arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = local.create_bucket && var.enable_replication ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket" "replication_destination" {
  count  = local.create_bucket && var.enable_replication ? 1 : 0
  bucket = "${var.replication_destination_bucket_prefix}-${random_id.bucket_suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  count  = local.create_bucket && var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.replication_destination[0].bucket
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = local.create_bucket && var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket

  role = aws_iam_role.replication[0].arn

  rule {
    id     = "replication-rule"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replication_destination[0].arn
      storage_class = "STANDARD"
    }

    delete_marker_replication {
      status = "Disabled"
    }
  }
}

# Object lock (requires versioning)
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = local.create_bucket && var.enable_object_lock && var.enable_versioning ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket

  rule {
    default_retention {
      mode = var.object_lock_mode
      days  = var.object_lock_days
      years = var.object_lock_years
    }
  }
}

# Intelligent tiering
resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  count  = local.create_bucket && length(var.intelligent_tiering_tiers) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket
  name   = "Intelligent-Tiering"

  dynamic "tiering" {
    for_each = var.intelligent_tiering_tiers
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

# Accelerate
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = local.create_bucket && var.enable_acceleration ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket
  status = "Enabled"
}

# ACL
resource "aws_s3_bucket_acl" "this" {
  count  = local.create_bucket && var.acl != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket
  acl    = var.acl
}

# Bucket policy - deny non-SSL and require TLS 1.2
data "aws_iam_policy_document" "deny_insecure_transport" {
  count = local.create_bucket && var.enable_deny_insecure_transport ? 1 : 0
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
  statement {
    sid    = "RequireTLS12"
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*"
    ]
    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }
}

resource "aws_s3_bucket_policy" "deny_insecure_transport" {
  count  = local.create_bucket && var.enable_deny_insecure_transport ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket
  policy = data.aws_iam_policy_document.deny_insecure_transport[0].json
}

# Bucket policies for log delivery (ELB, ALB, NLB)
data "aws_iam_policy_document" "log_delivery" {
  count = local.create_bucket && length(var.log_delivery_services) > 0 ? 1 : 0

  dynamic "statement" {
    for_each = var.log_delivery_services
    content {
      sid    = "LogDelivery${replace(statement.value, ".", "")}"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = [statement.value]
      }
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/*"]
      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "log_delivery" {
  count  = local.create_bucket && length(var.log_delivery_services) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket
  policy = data.aws_iam_policy_document.log_delivery[0].json
}

# Public access block
resource "aws_s3_bucket_public_access_block" "this" {
  count  = local.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# Ownership controls
resource "aws_s3_bucket_ownership_controls" "this" {
  count  = local.create_bucket && var.object_ownership != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].bucket

  rule {
    object_ownership = var.object_ownership
  }
}

# Requirements: Terraform ~> 1.3
terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "name_prefix" {
  description = "Prefix for all resource names"
  type        = string
  default     = "backup-test"
}

variable "environment_tag" {
  description = "Value for the Environment tag"
  type        = string
  default     = "test"
}

variable "enable_backup_plan" {
  description = "Create the backup plan resource"
  type        = bool
  default     = false
}

variable "enable_backup_selection" {
  description = "Create the backup selection resource"
  type        = bool
  default     = false
}

variable "backup_plan_rules" {
  description = "List of backup plan rules with optional lifecycle parameters"
  type = list(object({
    schedule           = string
    start_window       = optional(number, null)
    completion_window  = optional(number, null)
    lifecycle = optional(object({
      cold_storage_after = optional(number, null)
      delete_after       = optional(number, null)
    }), {})
  }))
  default = []
}

variable "sns_topic_arn" {
  description = "ARN of an existing SNS topic for vault notifications"
  type        = string
  default     = ""
}

variable "vault_policy_json" {
  description = "JSON policy document for the backup vault. Leave empty to skip creating the vault policy."
  type        = string
  default     = ""
}

variable "iam_role_arn" {
  description = "ARN of the IAM role assumed by AWS Backup for the backup selection"
  type        = string
  default     = null
}

variable "backup_selection_resources" {
  description = "List of ARNs of resources to include in the backup selection"
  type        = list(string)
  default     = []
}

variable "backup_selection_tags" {
  description = "Map of tag conditions for the backup selection"
  type        = map(string)
  default     = {}
}

variable "cross_account_backup_enabled" {
  description = "Enable cross-account backup in global settings"
  type        = bool
  default     = true
}

variable "enable_backup_global_settings" {
  description = "Enable creation of aws_backup_global_settings (set to false for LocalStack)"
  type        = bool
  default     = false
}

variable "enable_backup_region_settings" {
  description = "Enable creation of aws_backup_region_settings (set to false for LocalStack)"
  type        = bool
  default     = false
}

variable "region_settings_opt_ins" {
  description = "Map of service resource type opt-in preferences for the region"
  type        = map(bool)
  default = {
    DynamoDB          = true
    Aurora            = true
    EBS               = true
    EC2               = true
    EFS               = true
    FSx               = true
    RDS               = true
    "Storage Gateway" = true
  }
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  name_prefix = var.name_prefix
  env_tag     = var.environment_tag

  common_tags = {
    Environment = local.env_tag
  }
}

# ------------------------------------------------------------------------------
# Backup Vault
# ------------------------------------------------------------------------------

resource "aws_backup_vault" "this" {
  name = "${local.name_prefix}-vault"
  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Backup Vault Notifications (conditional on SNS topic ARN)
# ------------------------------------------------------------------------------

resource "aws_backup_vault_notifications" "this" {
  count = length(var.sns_topic_arn) > 0 ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  sns_topic_arn     = var.sns_topic_arn
  backup_vault_events = [
    "BACKUP_JOB_STARTED",
    "RESTORE_JOB_COMPLETED",
  ]
}

# ------------------------------------------------------------------------------
# Backup Vault Policy (conditional on non-empty policy JSON)
# ------------------------------------------------------------------------------

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy_json != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy_json
}

# ------------------------------------------------------------------------------
# Backup Plan (conditional)
# ------------------------------------------------------------------------------

resource "aws_backup_plan" "this" {
  count = var.enable_backup_plan ? 1 : 0

  name = "${local.name_prefix}-plan"

  dynamic "rule" {
    for_each = var.backup_plan_rules
    content {
      rule_name         = "rule-${rule.key}"
      schedule          = rule.value.schedule
      start_window      = rule.value.start_window
      completion_window = rule.value.completion_window
      target_vault_name = aws_backup_vault.this.name

      dynamic "lifecycle" {
        for_each = rule.value.lifecycle != null ? [rule.value.lifecycle] : []
        content {
          cold_storage_after = lifecycle.value.cold_storage_after
          delete_after       = lifecycle.value.delete_after
        }
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-plan"
  })
}

# ------------------------------------------------------------------------------
# Backup Selection (conditional on enable_backup_selection and iam_role_arn)
# ------------------------------------------------------------------------------

resource "aws_backup_selection" "this" {
  count = var.enable_backup_selection && var.iam_role_arn != null ? 1 : 0

  name         = "${local.name_prefix}-selection"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = var.iam_role_arn

  resources = var.backup_selection_resources

  dynamic "selection_tag" {
    for_each = var.backup_selection_tags
    content {
      type  = "STRINGEQUALS"
      key   = selection_tag.key
      value = selection_tag.value
    }
  }
}

# ------------------------------------------------------------------------------
# Global Settings (conditional, default: disabled for LocalStack compat)
# ------------------------------------------------------------------------------

resource "aws_backup_global_settings" "this" {
  count = var.enable_backup_global_settings ? 1 : 0

  global_settings = {
    is_cross_account_backup_enabled = tostring(var.cross_account_backup_enabled)
  }
}

# ------------------------------------------------------------------------------
# Region Settings (conditional, default: disabled for LocalStack compat)
# ------------------------------------------------------------------------------

resource "aws_backup_region_settings" "this" {
  count = var.enable_backup_region_settings ? 1 : 0

  resource_type_opt_in_preference = var.region_settings_opt_ins
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  user_names = toset([
    "DevUser-rwwise.dev",
    "TestUser-rwwise.dev",
    "ProdUser-rwwise.dev"
  ])
}

data "aws_iam_policy_document" "read_only" {
  statement {
    sid    = "ReadOnlyAccess"
    effect = "Allow"
    actions = [
      "codebuild:List*",
      "codebuild:Get*",
      "codebuild:BatchGet*",
      "codebuild:Describe*",
      "codecommit:List*",
      "codecommit:Get*",
      "codecommit:BatchGet*",
      "codecommit:Describe*",
      "cloudwatch:List*",
      "cloudwatch:Get*",
      "cloudwatch:Describe*",
      "events:List*",
      "events:Describe*",
      "events:Get*",
      "logs:List*",
      "logs:Get*",
      "logs:Describe*",
      "logs:FilterLogEvents",
      "codestar-connections:List*",
      "codestar-connections:Get*",
      "codestar-notifications:List*",
      "codestar-notifications:Get*",
      "codestar-notifications:Describe*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "RestrictedDescribeNotificationRule"
    effect = "Allow"
    actions = [
      "codestar-notifications:DescribeNotificationRule"
    ]
    resources = ["*"]
    condition {
      test     = "StringLike"
      variable = "codestar-notifications:Resource"
      values   = ["arn:aws:codebuild:*"]
    }
  }
}

resource "aws_iam_user" "this" {
  for_each = local.user_names
  name     = each.key
  path     = "/system/"
  tags = {
    Name       = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
  }
}

resource "aws_iam_access_key" "this" {
  for_each = aws_iam_user.this
  user     = each.value.name
}

resource "aws_iam_user_policy" "this" {
  for_each = aws_iam_user.this
  name     = "read-only-policy"
  user     = each.value.name
  policy   = data.aws_iam_policy_document.read_only.json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Environment = "production"
    Project     = "multi-tier-network"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "public-subnet-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "app" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 3)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "app-subnet-${count.index + 1}"
    Tier = "app"
  })
}

resource "aws_subnet" "db" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 6)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "db-subnet-${count.index + 1}"
    Tier = "db"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = 3

  tags = merge(local.common_tags, {
    Name = "nat-eip-${count.index + 1}"
  })
}

resource "aws_nat_gateway" "nat" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "nat-gateway-${count.index + 1}"
    AZ   = data.aws_availability_zones.available.names[count.index]
  })
}

resource "aws_route_table" "app" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = merge(local.common_tags, {
    Name = "app-rt-${count.index + 1}"
    AZ   = data.aws_availability_zones.available.names[count.index]
  })
}

resource "aws_route_table_association" "app" {
  count          = 3
  subnet_id      = aws_subnet.app[count.index].id
  route_table_id = aws_route_table.app[count.index].id
}

resource "aws_route_table" "db" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "db-rt"
  })
}

resource "aws_route_table_association" "db" {
  count          = 3
  subnet_id      = aws_subnet.db[count.index].id
  route_table_id = aws_route_table.db.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "queue_name" {
  description = "Name of the main SQS queue"
  type        = string
  default     = "my-app-queue"
}

variable "dlq_name" {
  description = "Name of the dead letter queue"
  type        = string
  default     = "my-app-queue-dlq"
}

variable "delay_seconds" {
  description = "Delay in seconds for the main queue"
  type        = number
  default     = 0
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds"
  type        = number
  default     = 345600
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout in seconds"
  type        = number
  default     = 30
}

variable "receive_wait_time_seconds" {
  description = "Receive wait time in seconds"
  type        = number
  default     = 0
}

variable "max_receive_count" {
  description = "Maximum receive count before moving to DLQ"
  type        = number
  default     = 5
}

variable "main_queue_policy" {
  description = "JSON policy for the main queue"
  type        = string
  default     = <<EOF
{
  "Version": "2012-10-17",
  "Statement": []
}
EOF
}

variable "dlq_queue_policy" {
  description = "JSON policy for the DLQ"
  type        = string
  default     = <<EOF
{
  "Version": "2012-10-17",
  "Statement": []
}
EOF
}

resource "aws_sqs_queue" "main_queue" {
  name                       = var.queue_name
  fifo_queue                 = false
  sqs_managed_sse_enabled    = true
  delay_seconds              = var.delay_seconds
  message_retention_seconds  = var.message_retention_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
}

resource "aws_sqs_queue" "dlq_queue" {
  name                    = var.dlq_name
  fifo_queue              = false
  sqs_managed_sse_enabled = true
}

resource "aws_sqs_queue_redrive_policy" "main_queue_redrive" {
  queue_url = aws_sqs_queue.main_queue.id
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq_queue.arn
    maxReceiveCount     = var.max_receive_count
  })
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq_redrive_allow" {
  queue_url = aws_sqs_queue.dlq_queue.id
  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.main_queue.arn]
  })
}

resource "aws_sqs_queue_policy" "main_queue_policy" {
  queue_url = aws_sqs_queue.main_queue.id
  policy    = var.main_queue_policy
}

resource "aws_sqs_queue_policy" "dlq_queue_policy" {
  queue_url = aws_sqs_queue.dlq_queue.id
  policy    = var.dlq_queue_policy
}

output "main_queue_url" {
  value = aws_sqs_queue.main_queue.id
}

output "main_queue_arn" {
  value = aws_sqs_queue.main_queue.arn
}

output "dlq_queue_url" {
  value = aws_sqs_queue.dlq_queue.id
}

output "dlq_queue_arn" {
  value = aws_sqs_queue.dlq_queue.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# Data sources for account and region info
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# Variable for naming prefix
variable "prefix" {
  description = "Prefix for all IAM role and instance profile names"
  type        = string
  default     = "drs"
}

# Local values for convenience
locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  caller_arn = data.aws_caller_identity.current.arn

  # ARNs for the five AWS-managed DRS policies (now local resources)
  drs_service_role_arn   = aws_iam_policy.drs_service_role.arn
  drs_conversion_arn     = aws_iam_policy.drs_conversion.arn
  drs_recovery_arn       = aws_iam_policy.drs_recovery.arn
  drs_replication_arn    = aws_iam_policy.drs_replication.arn
  ssm_core_arn           = aws_iam_policy.ssm_core.arn
}

# ----- IAM POLICIES (replicate AWS managed policies for local creation) -----

resource "aws_iam_policy" "drs_service_role" {
  name        = "AWSElasticDisasterRecoveryServiceRolePolicy"
  path        = "/service-role/"
  description = "Policy for DRS service role to manage EC2 resources on behalf of DRS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateTags",
          "ec2:CreateSnapshot",
          "ec2:CreateVolume",
          "ec2:DeleteSnapshot",
          "ec2:DeleteVolume",
          "ec2:AttachVolume",
          "ec2:DetachVolume",
          "ec2:ModifyVolume",
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:RunInstances",
          "ec2:DescribeLaunchTemplateVersions",
          "ec2:CreateLaunchTemplate",
          "ec2:CreateLaunchTemplateVersion",
          "ec2:DescribeVpcEndpoints",
          "ec2:DescribeVpcEndpointServices",
          "ec2:CreateVpcEndpoint",
          "ec2:DeleteVpcEndpoint",
          "ec2:ModifyVpcEndpoint",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeVpcs",
          "ec2:DescribeRouteTables",
          "ec2:DescribeNetworkInterfaces",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses",
          "ec2:DescribeIamInstanceProfileAssociations",
          "ec2:AssociateIamInstanceProfile",
          "ec2:DisassociateIamInstanceProfile",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeKeyPairs",
          "ec2:DescribePlacementGroups",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeAccountAttributes"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RetireGrant",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "sns:Publish",
          "sns:ListTopics",
          "sns:GetTopicAttributes",
          "sns:CreateTopic",
          "sns:Subscribe",
          "sns:Unsubscribe"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DeleteAlarms"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = "*"
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "ec2.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "drs_conversion" {
  name        = "AWSElasticDisasterRecoveryConversionServerPolicy"
  path        = "/service-role/"
  description = "Policy for DRS conversion server to perform server conversion tasks"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "drs:DescribeJobLogItems",
          "drs:DescribeJobs",
          "drs:DescribeRecoveryInstances",
          "drs:DescribeSourceServers",
          "drs:GetLaunchConfiguration",
          "drs:DescribeReplicationConfigurationTemplates",
          "drs:ListTagsForResource"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:DescribeImages",
          "ec2:DescribeTags"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "drs_recovery" {
  name        = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
  path        = "/service-role/"
  description = "Policy for DRS recovery instance to communicate with DRS service"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "drs:DescribeRecoveryInstances",
          "drs:DescribeJobs",
          "drs:GetFailbackReplicationConfiguration",
          "drs:UpdateFailbackReplicationConfiguration",
          "drs:GetReplicationConfiguration",
          "drs:DescribeSourceServers",
          "drs:ListTagsForResource",
          "drs:DescribeReplicationConfigurationTemplates"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:DescribeTags"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "drs_replication" {
  name        = "AWSElasticDisasterRecoveryReplicationServerPolicy"
  path        = "/service-role/"
  description = "Policy for DRS replication server to perform data replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "drs:DescribeSourceServers",
          "drs:DescribeJobs",
          "drs:DescribeReplicationConfigurationTemplates",
          "drs:GetReplicationConfiguration",
          "drs:UpdateReplicationConfiguration",
          "drs:DescribeRecoveryInstances",
          "drs:ListTagsForResource"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:DescribeTags",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "ssm_core" {
  name        = "AmazonSSMManagedInstanceCore"
  path        = "/"
  description = "Policy for SSM managed instance core functionality"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:DescribeAssociation",
          "ssm:GetDeployablePatchSnapshotForInstance",
          "ssm:GetDocument",
          "ssm:DescribeDocument",
          "ssm:GetManifest",
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:ListAssociations",
          "ssm:ListInstanceAssociations",
          "ssm:PutInventory",
          "ssm:PutComplianceItems",
          "ssm:PutConfigurePackageResult",
          "ssm:UpdateAssociationStatus",
          "ssm:UpdateInstanceAssociationStatus",
          "ssm:UpdateInstanceInformation"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2messages:AcknowledgeMessage",
          "ec2messages:DeleteMessage",
          "ec2messages:FailMessage",
          "ec2messages:GetEndpoint",
          "ec2messages:GetMessages",
          "ec2messages:SendReply"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricData"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstanceStatus"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ds:CreateComputer",
          "ds:DescribeDirectories"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:PutObject",
          "s3:GetObject",
          "s3:GetEncryptionConfiguration",
          "s3:AbortMultipartUpload",
          "s3:ListBucketMultipartUploads",
          "s3:ListMultipartUploadParts",
          "s3:ListBucket"
        ]
        Resource = "*"
      }
    ]
  })
}

# ----- IAM ROLES -----

# DRS Service Role
resource "aws_iam_role" "drs_service" {
  name = "${var.prefix}-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "aws:SourceIdentity" = "drs-*"
          }
        }
      }
    ]
  })
}

# EC2 Roles
resource "aws_iam_role" "conversion_server" {
  name = "${var.prefix}-conversion-server-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "recovery_server" {
  name = "${var.prefix}-recovery-server-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "replication_server" {
  name = "${var.prefix}-replication-server-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Initialization Role (trusted by current caller)
resource "aws_iam_role" "initialization" {
  name = "${var.prefix}-initialization-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = local.caller_arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# ----- POLICY ATTACHMENTS (local policies) -----

resource "aws_iam_role_policy_attachment" "drs_service" {
  role       = aws_iam_role.drs_service.name
  policy_arn = local.drs_service_role_arn
}

resource "aws_iam_role_policy_attachment" "conversion_server" {
  role       = aws_iam_role.conversion_server.name
  policy_arn = local.drs_conversion_arn
}

resource "aws_iam_role_policy_attachment" "recovery_server_drs" {
  role       = aws_iam_role.recovery_server.name
  policy_arn = local.drs_recovery_arn
}

resource "aws_iam_role_policy_attachment" "recovery_server_ssm" {
  role       = aws_iam_role.recovery_server.name
  policy_arn = local.ssm_core_arn
}

resource "aws_iam_role_policy_attachment" "replication_server" {
  role       = aws_iam_role.replication_server.name
  policy_arn = local.drs_replication_arn
}

# ----- INLINE POLICY FOR INITIALIZATION ROLE -----

resource "aws_iam_role_policy" "initialization_policy" {
  name = "${var.prefix}-initialization-policy"
  role = aws_iam_role.initialization.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "AttachDRSPoliciesToAnyRole"
        Effect = "Allow"
        Action = "iam:AttachRolePolicy"
        Resource = [
          local.drs_service_role_arn,
          local.drs_conversion_arn,
          local.drs_recovery_arn,
          local.drs_replication_arn,
          local.ssm_core_arn
        ]
      },
      {
        Sid = "PassRolesToEC2AndDRS"
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = [
          aws_iam_role.drs_service.arn,
          aws_iam_role.conversion_server.arn,
          aws_iam_role.recovery_server.arn,
          aws_iam_role.replication_server.arn,
          aws_iam_role.initialization.arn
        ]
      },
      {
        Sid = "CreateDRSServiceLinkedRole"
        Effect = "Allow"
        Action = "iam:CreateServiceLinkedRole"
        Resource = "*"
        Condition = {
          StringEquals = {
            "iam:AWSServiceName" = "drs.amazonaws.com"
          }
        }
      },
      {
        Sid = "ManageDRSInstanceProfiles"
        Effect = "Allow"
        Action = [
          "iam:CreateInstanceProfile",
          "iam:DeleteInstanceProfile",
          "iam:AddRoleToInstanceProfile",
          "iam:RemoveRoleFromInstanceProfile"
        ]
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:instance-profile/${var.prefix}-conversion-server-profile",
          "arn:${local.partition}:iam::${local.account_id}:instance-profile/${var.prefix}-recovery-server-profile",
          "arn:${local.partition}:iam::${local.account_id}:instance-profile/${var.prefix}-replication-server-profile"
        ]
      }
    ]
  })
}

# ----- INSTANCE PROFILES -----

resource "aws_iam_instance_profile" "conversion_server" {
  name = "${var.prefix}-conversion-server-profile"
  role = aws_iam_role.conversion_server.name
}

resource "aws_iam_instance_profile" "recovery_server" {
  name = "${var.prefix}-recovery-server-profile"
  role = aws_iam_role.recovery_server.name
}

resource "aws_iam_instance_profile" "replication_server" {
  name = "${var.prefix}-replication-server-profile"
  role = aws_iam_role.replication_server.name
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~>5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~>3.0"
    }
  }
}

# Variables
variable "service_name" {
  description = "Name of the service, used in resource naming and host header"
  type        = string
  default     = "myservice"
}

variable "container_image" {
  description = "Container image to deploy"
  type        = string
  default     = "nginx:latest"
}

variable "container_port" {
  description = "Port exposed by the container"
  type        = number
  default     = 80
}

variable "task_cpu" {
  description = "CPU units for the Fargate task (e.g., 256, 512)"
  type        = string
  default     = "256"
}

variable "task_memory" {
  description = "Memory for the Fargate task (e.g., 512, 1024)"
  type        = string
  default     = "512"
}

variable "log_retention_days" {
  description = "Number of days to retain CloudWatch logs"
  type        = number
  default     = 30
}

variable "container_environment" {
  description = "Plaintext environment variables for the container (map of string)"
  type        = map(string)
  default     = {}
}

variable "secrets" {
  description = "Map of secret names to their plaintext values to be stored in SSM Parameter Store"
  type        = map(string)
  default     = {}
}

variable "create_lb" {
  description = "Whether to create an Application Load Balancer"
  type        = bool
  default     = true
}

variable "alb_port" {
  description = "Port for the ALB listener"
  type        = number
  default     = 80
}

variable "alb_allowed_cidrs" {
  description = "List of CIDR blocks allowed to access the ALB (empty means 0.0.0.0/0)"
  type        = list(string)
  default     = []
}

variable "alb_host_header_suffix" {
  description = "Additional host header suffix appended to service name and random ID"
  type        = string
  default     = ".example.com"
}

variable "target_group_stickiness_cookie_duration" {
  description = "Cookie duration for stickiness in seconds (0 disables stickiness)"
  type        = number
  default     = 0
}

variable "create_autoscaling" {
  description = "Whether to enable auto scaling for the ECS service"
  type        = bool
  default     = false
}

variable "autoscaling_min_capacity" {
  description = "Minimum desired count for auto scaling"
  type        = number
  default     = 1
}

variable "autoscaling_max_capacity" {
  description = "Maximum desired count for auto scaling"
  type        = number
  default     = 5
}

variable "autoscaling_target_cpu" {
  description = "Target CPU utilization percentage for auto scaling"
  type        = number
  default     = 70
}

variable "autoscaling_scale_in_cooldown" {
  description = "Cooldown seconds for scale-in"
  type        = number
  default     = 300
}

variable "autoscaling_scale_out_cooldown" {
  description = "Cooldown seconds for scale-out"
  type        = number
  default     = 300
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

# Data Sources
data "aws_availability_zones" "available" {
  state = "available"
}

# Random ID for unique naming
resource "random_id" "this" {
  byte_length = 4
}

# Locals
locals {
  resource_id = "${var.service_name}-${random_id.this.hex}"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = local.resource_id
    type = "vega"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = local.resource_id
  }
}

# Default route via Internet Gateway
resource "aws_route" "default" {
  route_table_id         = aws_vpc.main.main_route_table_id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# Subnets
resource "aws_subnet" "private" {
  count = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = local.resource_id
    type = "vega-private"
  }
}

# Security Group for ECS Tasks
resource "aws_security_group" "ecs_tasks" {
  name        = "${local.resource_id}-ecs-tasks"
  description = "Security group for ECS Fargate tasks"
  vpc_id      = aws_vpc.main.id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }
  tags = {
    Name = local.resource_id
    type = "vega"
  }
}

# Security Group for ALB (if LB enabled)
resource "aws_security_group" "alb" {
  count = var.create_lb ? 1 : 0
  name        = "${local.resource_id}-alb"
  description = "Security group for the Application Load Balancer"
  vpc_id      = aws_vpc.main.id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }
  tags = {
    Name = local.resource_id
    type = "vega"
  }
}

# ALB Security Group Ingress Rules
resource "aws_security_group_rule" "alb_ingress" {
  count = var.create_lb ? (length(var.alb_allowed_cidrs) > 0 ? 1 : 0) : 0
  type              = "ingress"
  from_port         = var.alb_port
  to_port           = var.alb_port
  protocol          = "tcp"
  cidr_blocks       = var.alb_allowed_cidrs
  security_group_id = aws_security_group.alb[0].id
}

resource "aws_security_group_rule" "alb_ingress_all" {
  count = var.create_lb ? (length(var.alb_allowed_cidrs) == 0 ? 1 : 0) : 0
  type              = "ingress"
  from_port         = var.alb_port
  to_port           = var.alb_port
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.alb[0].id
}

# Allow traffic from ALB to ECS tasks (if LB enabled)
resource "aws_security_group_rule" "ecs_ingress_from_alb" {
  count                    = var.create_lb ? 1 : 0
  type                     = "ingress"
  from_port                = var.container_port
  to_port                  = var.container_port
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.alb[0].id
  security_group_id        = aws_security_group.ecs_tasks.id
}

# IAM Role for ECS Task Execution
resource "aws_iam_role" "ecs_execution" {
  name = "${local.resource_id}-ecs-execution"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Name = local.resource_id
  }
}

resource "aws_iam_role_policy_attachment" "ecs_execution_policy" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# IAM Role for ECS Task (custom policy)
resource "aws_iam_role" "ecs_task" {
  name = "${local.resource_id}-ecs-task"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Name = local.resource_id
  }
}

resource "aws_iam_policy" "ecs_task" {
  name        = "${local.resource_id}-ecs-task-policy"
  description = "Custom policy for ECS task role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:SendCommand",
          "ssm:GetParameter*",
          "ssm:DescribeParameters"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:BatchCheckLayerAvailability"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ses:SendEmail",
          "ses:SendRawEmail",
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:DeleteObject",
          "lambda:InvokeFunction",
          "textract:AnalyzeDocument",
          "textract:DetectDocumentText"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_policy" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = aws_iam_policy.ecs_task.arn
}

# KMS Key for SSM parameters
resource "aws_kms_key" "ssm" {
  description             = "KMS key for encrypting SSM parameters used by ECS tasks"
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.ecs_task.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = local.resource_id
  }
}

data "aws_caller_identity" "current" {}

# SSM Parameters for secrets
resource "aws_ssm_parameter" "secret" {
  for_each = var.secrets
  name        = "/ecs/${local.resource_id}/secrets/${each.key}"
  type        = "SecureString"
  value       = each.value
  key_id      = aws_kms_key.ssm.key_id
  tags = {
    Name = local.resource_id
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/${local.resource_id}"
  retention_in_days = var.log_retention_days
  tags = {
    Name = local.resource_id
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = local.resource_id
  setting {
    name  = "containerInsights"
    value = "enabled"
  }
  tags = {
    Name = local.resource_id
  }
}

# Task Definition
resource "aws_ecs_task_definition" "app" {
  family                   = local.resource_id
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = var.task_cpu
  memory                   = var.task_memory
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn
  container_definitions = jsonencode([
    {
      name  = var.service_name
      image = var.container_image
      portMappings = [
        {
          containerPort = var.container_port
          protocol      = "tcp"
        }
      ]
      environment = [
        for key, value in var.container_environment : {
          name  = key
          value = value
        }
      ]
      secrets = [
        for key, ssm_param in aws_ssm_parameter.secret : {
          name      = key
          valueFrom = ssm_param.arn
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])
  tags = {
    Name = local.resource_id
  }
}

data "aws_region" "current" {}

# ECS Service
resource "aws_ecs_service" "app" {
  name            = local.resource_id
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 1
  launch_type     = "FARGATE"
  platform_version = "LATEST"
  enable_execute_command = true
  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs_tasks.id]
    assign_public_ip = true
  }
  dynamic "load_balancer" {
    for_each = var.create_lb ? [1] : []
    content {
      target_group_arn = aws_lb_target_group.app[0].arn
      container_name   = var.service_name
      container_port   = var.container_port
    }
  }
  depends_on = [aws_lb_listener_rule.app]
  tags = {
    Name = local.resource_id
  }
}

# ALB Resources (if LB enabled)
resource "aws_lb" "app" {
  count              = var.create_lb ? 1 : 0
  name               = local.resource_id
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb[0].id]
  subnets            = aws_subnet.private[*].id
  drop_invalid_header_fields = true
  tags = {
    Name = local.resource_id
    type = "vega"
  }
}

resource "aws_lb_target_group" "app" {
  count = var.create_lb ? 1 : 0
  name     = local.resource_id
  port     = var.container_port
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id
  target_type = "ip"
  health_check {
    enabled             = true
    interval            = 30
    path                = "/"
    protocol            = "HTTP"
    healthy_threshold   = 3
    unhealthy_threshold = 3
    timeout             = 5
  }
  dynamic "stickiness" {
    for_each = var.target_group_stickiness_cookie_duration > 0 ? [1] : []
    content {
      type            = "lb_cookie"
      cookie_duration = var.target_group_stickiness_cookie_duration
      enabled         = true
    }
  }
  tags = {
    Name = local.resource_id
  }
}

resource "aws_lb_listener" "app" {
  count             = var.create_lb ? 1 : 0
  load_balancer_arn = aws_lb.app[0].arn
  port              = var.alb_port
  protocol          = "HTTP"
  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_lb_listener_rule" "app" {
  count        = var.create_lb ? 1 : 0
  listener_arn = aws_lb_listener.app[0].arn
  priority     = 100
  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app[0].arn
  }
  condition {
    host_header {
      values = ["${local.resource_id}${var.alb_host_header_suffix}"]
    }
  }
}

# Auto Scaling (if enabled)
resource "aws_appautoscaling_target" "ecs" {
  count              = var.create_autoscaling ? 1 : 0
  max_capacity       = var.autoscaling_max_capacity
  min_capacity       = var.autoscaling_min_capacity
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.app.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

resource "aws_appautoscaling_policy" "cpu" {
  count              = var.create_autoscaling ? 1 : 0
  name               = "${local.resource_id}-cpu-target"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs[0].resource_id
  scalable_dimension = aws_appautoscaling_target.ecs[0].scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs[0].service_namespace
  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
    target_value       = var.autoscaling_target_cpu
    scale_in_cooldown  = var.autoscaling_scale_in_cooldown
    scale_out_cooldown = var.autoscaling_scale_out_cooldown
  }
}

# Outputs
output "resource_id" {
  description = "The unique resource identifier generated for this deployment"
  value       = local.resource_id
}

# Variables
variable "cluster_name" {
  description = "Name of the ECS cluster"
  type        = string
  default     = "my-ecs-cluster"
}

variable "instance_count" {
  description = "Number of EC2 instances in the autoscaling group"
  type        = number
  default     = 2
}

variable "service_desired_count" {
  description = "Desired number of ECS service tasks"
  type        = number
  default     = 2
}

# Terraform metadata
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Local values
locals {
  name_prefix = "ecs-demo"
  common_tags = {
    Environment = "dev"
    Project     = "ecs-demo"
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ecs_optimized" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-ecs-hvm-*-x86_64-ebs"]
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# Public subnets (for ALB only)
resource "aws_subnet" "public" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet-${count.index + 1}"
  })
}

# Private subnets (for EC2 instances)
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 4)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-gw"
  })
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

# Route table associations
resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security group (shared between ALB and instances)
resource "aws_security_group" "ecs_sg" {
  name_prefix = "${local.name_prefix}-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

# Self-signed certificate for ALB HTTPS
resource "tls_private_key" "main" {
  algorithm = "RSA"
}

resource "tls_self_signed_cert" "main" {
  private_key_pem = tls_private_key.main.private_key_pem

  subject {
    common_name = "ecs-demo.local"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
  ]
}

resource "aws_acm_certificate" "main" {
  private_key      = tls_private_key.main.private_key_pem
  certificate_body = tls_self_signed_cert.main.cert_pem
}

# Application Load Balancer (internal)
resource "aws_lb" "main" {
  name                       = "${local.name_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.ecs_sg.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb"
  })
}

# Target group (backend HTTP on port 80)
resource "aws_lb_target_group" "main" {
  name_prefix = "ecs-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    path = "/"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tg"
  })
}

# Listener (HTTPS on port 443)
resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.main.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-listener"
  })
}

# IAM role for EC2 (ECS agent)
resource "aws_iam_role" "ec2_instance_role" {
  name_prefix = "${local.name_prefix}-ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ec2_ecs_policy" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_instance_profile" "ecs_instance_profile" {
  name_prefix = "${local.name_prefix}-instance-profile"
  role        = aws_iam_role.ec2_instance_role.name

  tags = local.common_tags
}

# IAM role for ECS task execution
resource "aws_iam_role" "ecs_task_execution_role" {
  name_prefix = "${local.name_prefix}-task-exec-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_policy" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# Launch configuration
resource "aws_launch_configuration" "ecs" {
  name_prefix                 = "${local.name_prefix}-lc-"
  image_id                    = data.aws_ami.ecs_optimized.id
  instance_type               = "t2.small"
  associate_public_ip_address = false
  security_groups             = [aws_security_group.ecs_sg.id]
  iam_instance_profile        = aws_iam_instance_profile.ecs_instance_profile.name

  root_block_device {
    encrypted   = true
    volume_size = 30
  }

  metadata_options {
    http_tokens = "required"
  }

  user_data = base64encode(<<-EOF
    #!/bin/bash
    echo ECS_CLUSTER=${var.cluster_name} >> /etc/ecs/ecs.config
  EOF
  )

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [aws_iam_role_policy_attachment.ec2_ecs_policy]
}

# Auto Scaling group
resource "aws_autoscaling_group" "ecs" {
  name_prefix          = "${local.name_prefix}-asg-"
  launch_configuration = aws_launch_configuration.ecs.name
  vpc_zone_identifier  = aws_subnet.private[*].id

  min_size         = var.instance_count
  max_size         = var.instance_count
  desired_capacity = var.instance_count

  target_group_arns = [aws_lb_target_group.main.arn]

  tag {
    key                 = "Name"
    value               = "${local.name_prefix}-ecs-instance"
    propagate_at_launch = true
  }

  tag {
    key                 = "AmazonECSManaged"
    value               = true
    propagate_at_launch = true
  }

  lifecycle {
    create_before_destroy = true
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = var.cluster_name

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = merge(local.common_tags, {
    Name = var.cluster_name
  })
}

# CloudWatch log group
resource "aws_cloudwatch_log_group" "nginx" {
  name              = "/ecs/nginx-task"
  retention_in_days = 7

  tags = merge(local.common_tags, {
    Name = "/ecs/nginx-task"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ECS Task Definition
resource "aws_ecs_task_definition" "nginx" {
  family             = "nginx"
  execution_role_arn = aws_iam_role.ecs_task_execution_role.arn
  network_mode       = "bridge"

  container_definitions = jsonencode([
    {
      name      = "nginx"
      image     = "nginx:latest"
      essential = true
      memory    = 512
      cpu       = 512
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.nginx.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = "nginx"
        }
      }
    }
  ])

  tags = local.common_tags
}

# ECS Service
resource "aws_ecs_service" "nginx" {
  name            = "nginx-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = var.service_desired_count
  launch_type     = "EC2"

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = "nginx"
    container_port   = 80
  }

  depends_on = [
    aws_autoscaling_group.ecs,
    aws_lb_listener.main
  ]

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# Variables

variable "vpcs" {
  description = "List of VPC configurations. Each object must have a unique 'key'."
  type = list(object({
    key                  = string
    cidr_block           = string
    name                 = string
    enable_dns_support   = bool
    enable_dns_hostnames = bool
    tags                 = map(string)
  }))
  default = [
    {
      key                  = "main"
      cidr_block           = "10.0.0.0/16"
      name                 = "main"
      enable_dns_support   = true
      enable_dns_hostnames = true
      tags                 = {}
    }
  ]
}

variable "subnets" {
  description = "List of subnet configurations. Each object must have a unique 'key'. vpc_key references VPC key. az_index is an index into availability zones."
  type = list(object({
    key       = string
    vpc_key   = string
    cidr_block = string
    az_index  = number
    type      = string # "public" or "private"
    tags      = map(string)
  }))
  default = [
    {
      key       = "public-main-0"
      vpc_key   = "main"
      cidr_block = "10.0.1.0/24"
      az_index  = 0
      type      = "public"
      tags      = {}
    }
  ]
}

variable "internet_gateways" {
  description = "List of Internet Gateway configurations. Each object must have a unique 'key'. vpc_key references VPC key."
  type = list(object({
    key     = string
    vpc_key = string
    tags    = map(string)
  }))
  default = [
    {
      key     = "main"
      vpc_key = "main"
      tags    = {}
    }
  ]
}

variable "nat_gateways" {
  description = "List of NAT Gateway configurations. Each object must have a unique 'key'. vpc_key references VPC key. subnet_key references subnet key. connectivity_type: 'public' or 'private'."
  type = list(object({
    key               = string
    vpc_key           = string
    subnet_key        = string
    connectivity_type = string
    tags              = map(string)
  }))
  default = []
}

variable "route_tables" {
  description = "List of Route Table configurations. Each object must have a unique 'key'. vpc_key references VPC key. routes is a list of route objects."
  type = list(object({
    key     = string
    vpc_key = string
    name    = string
    routes = list(object({
      destination_cidr = string
      gateway_type    = string # "igw", "nat", "local", "egress_only_internet_gateway"
    }))
    tags = map(string)
  }))
  default = [
    {
      key     = "public-main"
      vpc_key = "main"
      name    = "public-main"
      routes = [
        {
          destination_cidr = "0.0.0.0/0"
          gateway_type    = "igw"
        }
      ]
      tags = {}
    }
  ]
}

variable "route_table_associations" {
  description = "List of Route Table Association configurations. Each object must have a unique 'key'. subnet_key and route_table_key reference subnet and route table keys."
  type = list(object({
    key            = string
    subnet_key     = string
    route_table_key = string
  }))
  default = [
    {
      key             = "public-main-0"
      subnet_key      = "public-main-0"
      route_table_key = "public-main"
    }
  ]
}

variable "security_groups" {
  description = "List of Security Group configurations (excluding default SGs). Each object must have a unique 'key'. vpc_key references VPC key."
  type = list(object({
    key         = string
    vpc_key     = string
    name        = string
    description = string
    tags        = map(string)
  }))
  default = []
}

variable "security_group_rules" {
  description = "List of Security Group Rule configurations. Each object must have a unique 'key'. sg_key references the SG key. type: 'ingress' or 'egress'. cidr_blocks, source_security_group_key, self are optional."
  type = list(object({
    key                      = string
    sg_key                   = string
    type                     = string
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string))
    source_security_group_key = optional(string)
    self                     = optional(bool)
    description              = string
  }))
  default = []
}

# Locals

locals {
  vpcs_map     = { for v in var.vpcs : v.key => v }
  subnets_map  = { for s in var.subnets : s.key => s }
  igws_map     = { for igw in var.internet_gateways : igw.key => igw }
  natgws_map   = { for nat in var.nat_gateways : nat.key => nat }
  rtbs_map     = { for rtb in var.route_tables : rtb.key => rtb }
  rtb_assocs_map = { for assoc in var.route_table_associations : assoc.key => assoc }
  sgs_map      = { for sg in var.security_groups : sg.key => sg }
  sg_rules_map = { for rule in var.security_group_rules : rule.key => rule }

  igw_for_vpc   = { for igw in var.internet_gateways : igw.vpc_key => igw.key }
  natgw_for_vpc = { for nat in var.nat_gateways : nat.vpc_key => nat.key }

  route_entries = flatten([
    for rtb in var.route_tables : [
      for route in rtb.routes : {
        key              = "${rtb.key}-${route.destination_cidr}"
        rtb_key          = rtb.key
        destination_cidr = route.destination_cidr
        gateway_type     = route.gateway_type
      }
    ]
  ])
}

# VPC

resource "aws_vpc" "main" {
  for_each = local.vpcs_map

  cidr_block           = each.value.cidr_block
  enable_dns_support   = each.value.enable_dns_support
  enable_dns_hostnames = each.value.enable_dns_hostnames
  tags = merge(
    { Name = each.value.name },
    each.value.tags
  )
}

# Subnets

resource "aws_subnet" "main" {
  for_each = local.subnets_map

  vpc_id            = aws_vpc.main[each.value.vpc_key].id
  cidr_block        = each.value.cidr_block
  availability_zone = data.aws_availability_zones.available.names[each.value.az_index]
  tags = merge(
    { Name = each.value.key },
    { Type = each.value.type },
    each.value.tags
  )
}

# Internet Gateways

resource "aws_internet_gateway" "main" {
  for_each = local.igws_map

  vpc_id = aws_vpc.main[each.value.vpc_key].id
  tags = merge(
    { Name = each.value.key },
    each.value.tags
  )
}

# Elastic IPs for NAT Gateways

resource "aws_eip" "nat" {
  for_each = local.natgws_map

  domain = "vpc"
  tags = merge(
    { Name = "${each.value.key}-eip" },
    each.value.tags
  )
}

# NAT Gateways

resource "aws_nat_gateway" "main" {
  for_each = local.natgws_map

  allocation_id     = aws_eip.nat[each.value.key].id
  subnet_id         = aws_subnet.main[each.value.subnet_key].id
  connectivity_type = each.value.connectivity_type
  tags = merge(
    { Name = each.value.key },
    each.value.tags
  )
}

# Route Tables (without inline routes – routes are created as separate resources)

resource "aws_route_table" "main" {
  for_each = local.rtbs_map

  vpc_id = aws_vpc.main[each.value.vpc_key].id
  tags = merge(
    { Name = each.value.name },
    each.value.tags
  )
}

# Route entries (one per route in the variable)

resource "aws_route" "main" {
  for_each = { for entry in local.route_entries : entry.key => entry }

  route_table_id = aws_route_table.main[each.value.rtb_key].id
  destination_cidr_block = each.value.destination_cidr

  gateway_id             = each.value.gateway_type == "igw" ? aws_internet_gateway.main[local.igw_for_vpc[local.rtbs_map[each.value.rtb_key].vpc_key]].id : null
  nat_gateway_id         = each.value.gateway_type == "nat" ? aws_nat_gateway.main[local.natgw_for_vpc[local.rtbs_map[each.value.rtb_key].vpc_key]].id : null
  egress_only_gateway_id = each.value.gateway_type == "egress_only_internet_gateway" ? null : null
}

# Route Table Associations

resource "aws_route_table_association" "main" {
  for_each = local.rtb_assocs_map

  subnet_id      = aws_subnet.main[each.value.subnet_key].id
  route_table_id = aws_route_table.main[each.value.route_table_key].id
}

# Default Security Group for each VPC:
# Allows all intra-VPC traffic (ingress from self) and egress to VPC CIDR only.

resource "aws_security_group" "default" {
  for_each = local.vpcs_map

  name        = "default-${each.value.key}"
  description = "Default security group for VPC ${each.value.key}"
  vpc_id      = aws_vpc.main[each.value.key].id

  ingress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    self      = true
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main[each.value.key].cidr_block]
  }

  tags = merge(
    { Name = "default-${each.value.key}" },
    each.value.tags
  )
}

# Additional Security Groups

resource "aws_security_group" "main" {
  for_each = local.sgs_map

  name        = each.value.name
  description = each.value.description
  vpc_id      = aws_vpc.main[each.value.vpc_key].id
  tags = merge(
    { Name = each.value.name },
    each.value.tags
  )
}

# Combined lookup for all security groups (default + additional)

locals {
  default_sgs = { for vpc_key, sg in aws_security_group.default : "default_${vpc_key}" => sg }
  added_sgs   = { for k, sg in aws_security_group.main : k => sg }
  sgs_all     = merge(local.default_sgs, local.added_sgs)
}

# Security Group Rules

resource "aws_security_group_rule" "main" {
  for_each = local.sg_rules_map

  type              = each.value.type
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description

  security_group_id = local.sgs_all[each.value.sg_key].id

  cidr_blocks              = each.value.cidr_blocks
  source_security_group_id = each.value.source_security_group_key != null ? local.sgs_all[each.value.source_security_group_key].id : null
  self                     = each.value.self != null ? each.value.self : null
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "bucket_name" {
  description = "Name of the S3 bucket. If null, a name will be generated using bucket_prefix and a random suffix."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Prefix for generated bucket name. Ignored if bucket_name is provided."
  type        = string
  default     = ""
}

variable "versioning_enabled" {
  description = "Enable S3 versioning on the bucket."
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "ARN of the KMS key for server-side encryption. If null, AES256 is used."
  type        = string
  default     = null
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule objects. Each object should contain fields as per aws_s3_bucket_lifecycle_configuration rule."
  type = list(object({
    id     = string
    status = string
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    transition = optional(list(object({
      days          = optional(number)
      storage_class = string
    })))
    expiration = optional(object({
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_transition = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })))
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

variable "cors_rules" {
  description = "List of CORS rule objects for the bucket."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "acl" {
  description = "Canned ACL to apply to the bucket. If null, no canned ACL is set (use grants instead)."
  type        = string
  default     = null
}

variable "grants" {
  description = "List of grant objects for access control policy."
  type = list(object({
    type       = string
    permission = string
    uri        = optional(string)
    id         = optional(string)
  }))
  default = []
}

variable "bucket_policy" {
  description = "JSON bucket policy document. If null, no policy is attached."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even if non-empty."
  type        = bool
  default     = false
}

variable "acceleration_enabled" {
  description = "Enable transfer acceleration for the bucket."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Sets the request payer configuration. Valid values: BucketOwner, Requester."
  type        = string
  default     = "BucketOwner"
}

variable "logging" {
  description = "Logging configuration object. If null, logging is not enabled."
  type = object({
    target_bucket = string
    target_prefix = string
  })
  default = null
}

variable "website" {
  description = "Website configuration object. If null, no website hosting is configured."
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
    routing_rules            = optional(string)
  })
  default = null
}

variable "object_lock" {
  description = "Object lock configuration. Requires versioning to be enabled. If null, object lock is not enabled."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "replication_rules" {
  description = "List of replication rule objects. If non-empty, cross-region replication is enabled."
  type = list(object({
    id       = string
    status   = string
    priority = number
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    destination = object({
      bucket        = string
      storage_class = optional(string)
      replica_kms_key_id = optional(string)
      access_control_translation = optional(object({
        owner = string
      }))
      account_id = optional(string)
      metrics = optional(object({
        status  = string
        minutes = optional(number)
      }))
      replication_time = optional(object({
        status  = string
        minutes = number
      }))
    })
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(object({
        status = string
      }))
    }))
    delete_marker_replication = optional(string)
  }))
  default = []
}

variable "replication_role_arn" {
  description = "ARN of IAM role for replication. If null and replication_rules is non-empty, an IAM role and policy will be created automatically."
  type        = string
  default     = null
}

resource "random_id" "suffix" {
  count       = var.bucket_name == null ? 1 : 0
  byte_length = 4
}

locals {
  bucket_name = var.bucket_name != null ? var.bucket_name : "${var.bucket_prefix}${random_id.suffix[0].hex}"
}

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy
  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_key_arn != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_key_arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status
      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = try(filter.value.prefix, null)
          # Single tag
          dynamic "tag" {
            for_each = length(try(filter.value.tags, {})) == 1 ? filter.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
          # Multiple tags wrapped in "and"
          dynamic "and" {
            for_each = length(try(filter.value.tags, {})) > 1 ? [filter.value.tags] : []
            content {
              tags = and.value
            }
          }
        }
      }
      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }
      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }
      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }
      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_acl" "canned" {
  count  = var.acl != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = var.acl
}

resource "aws_s3_bucket_acl" "grants" {
  count  = length(var.grants) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  access_control_policy {
    dynamic "grant" {
      for_each = var.grants
      content {
        grantee {
          type       = grant.value.type
          uri        = grant.value.uri
          id         = grant.value.id
        }
        permission = grant.value.permission
      }
    }
    owner {
      id = data.aws_caller_identity.current.account_id
    }
  }
}

data "aws_caller_identity" "current" {}

resource "aws_s3_bucket_policy" "this" {
  count  = var.bucket_policy != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = var.bucket_policy
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  status = var.acceleration_enabled ? "Enabled" : "Suspended"
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

resource "aws_s3_bucket_logging" "this" {
  count         = var.logging != null ? 1 : 0
  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.website != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  index_document {
    suffix = var.website.index_document
  }
  error_document {
    key = var.website.error_document
  }
  redirect_all_requests_to {
    host_name = var.website.redirect_all_requests_to
  }
  routing_rules = var.website.routing_rules
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  rule {
    default_retention {
      mode  = var.object_lock.mode
      days  = var.object_lock.days
      years = var.object_lock.years
    }
  }
}

# Cross-region replication resources
resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role_arn == null ? 1 : 0
  name  = "${local.bucket_name}-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role_arn == null ? 1 : 0
  name  = "${local.bucket_name}-replication-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:ListBucket",
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:PutBucketReplication"
        ]
        Resource = aws_s3_bucket.this.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = var.kms_key_arn != null ? var.kms_key_arn : "*"
        Condition = var.kms_key_arn != null ? {
          StringLike = {
            "kms:ViaService" = "s3.*.amazonaws.com"
          }
        } : {}
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = length(var.replication_rules) > 0 && var.replication_role_arn == null ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = var.replication_role_arn != null ? var.replication_role_arn : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = rule.value.priority
      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = try(filter.value.prefix, null)
          # Single tag
          dynamic "tag" {
            for_each = length(try(filter.value.tags, {})) == 1 ? filter.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
          # Multiple tags wrapped in "and"
          dynamic "and" {
            for_each = length(try(filter.value.tags, {})) > 1 ? [filter.value.tags] : []
            content {
              tags = and.value
            }
          }
        }
      }
      destination {
        bucket        = rule.value.destination.bucket
        storage_class = rule.value.destination.storage_class
        dynamic "encryption_configuration" {
          for_each = rule.value.destination.replica_kms_key_id != null ? [rule.value.destination.replica_kms_key_id] : []
          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }
        dynamic "access_control_translation" {
          for_each = rule.value.destination.access_control_translation != null ? [rule.value.destination.access_control_translation] : []
          content {
            owner = access_control_translation.value.owner
          }
        }
        dynamic "metrics" {
          for_each = rule.value.destination.metrics != null ? [rule.value.destination.metrics] : []
          content {
            status = metrics.value.status
            dynamic "event_threshold" {
              for_each = metrics.value.minutes != null ? [metrics.value.minutes] : []
              content {
                minutes = event_threshold.value
              }
            }
          }
        }
        dynamic "replication_time" {
          for_each = rule.value.destination.replication_time != null ? [rule.value.destination.replication_time] : []
          content {
            status = replication_time.value.status
            time {
              minutes = replication_time.value.minutes
            }
          }
        }
      }
      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          sse_kms_encrypted_objects {
            status = try(source_selection_criteria.value.sse_kms_encrypted_objects.status, null)
          }
        }
      }
      delete_marker_replication {
        status = try(rule.value.delete_marker_replication, "Disabled")
      }
    }
  }
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_region" {
  value = aws_s3_bucket.this.region
}

output "bucket_domain_name" {
  value = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  value = aws_s3_bucket.this.bucket_regional_domain_name
}

output "hosted_zone_id" {
  value = aws_s3_bucket.this.hosted_zone_id
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "allowed_ssh_cidr" {
  description = "CIDR block allowed for SSH access to bastion host. Defaults to VPC CIDR for security; replace with your specific admin IP(s) in production."
  type        = string
  default     = "10.255.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    application = "dosomething-quasar"
    environment = "production"
    stack       = "data"
  }
}

resource "aws_vpc" "quasar" {
  cidr_block           = "10.255.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "quasar-vpc"
  })
}

resource "aws_subnet" "rds_subnet_1" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "rds-subnet-1"
  })
}

resource "aws_subnet" "rds_subnet_2" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "rds-subnet-2"
  })
}

resource "aws_security_group" "bastion" {
  name        = "bastion-sg"
  description = "Security group for bastion host"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ssh_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block] # Restrict to VPC internal traffic; extend only if explicit external destinations required.
  }

  tags = merge(local.common_tags, {
    Name = "bastion-sg"
  })
}

resource "aws_security_group" "jenkins" {
  name        = "jenkins-sg"
  description = "Security group for Jenkins"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.load_balancer.id]
  }

  ingress {
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block] # Restrict to VPC internal traffic; extend only if explicit external destinations required.
  }

  tags = merge(local.common_tags, {
    Name = "jenkins-sg"
  })
}

resource "aws_security_group" "load_balancer" {
  name        = "lb-sg"
  description = "Security group for load balancer"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block] # Restrict to VPC internal traffic; extend only if explicit external destinations required.
  }

  tags = merge(local.common_tags, {
    Name = "lb-sg"
  })
}

resource "aws_security_group" "etl" {
  name        = "etl-sg"
  description = "Security group for ETL compute nodes"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  # Allow all internal traffic from VPC CIDR (internal communication)
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block] # Restrict to VPC internal traffic; extend only if explicit external destinations required.
  }

  tags = merge(local.common_tags, {
    Name = "etl-sg"
  })
}

resource "aws_security_group" "rds" {
  name        = "rds-postgresql-sg"
  description = "Security group for RDS PostgreSQL"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [
      aws_security_group.etl.id,
      aws_security_group.jenkins.id,
      aws_security_group.bastion.id
    ]
  }

  tags = merge(local.common_tags, {
    Name = "rds-postgresql-sg"
  })
}

# main.tf

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "my-cluster-vpc"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name = "my-cluster-private-${count.index}"
  }
}

# EKS Cluster IAM Role
resource "aws_iam_role" "eks_cluster" {
  name = "my-cluster-eks-cluster-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = { Service = "eks.amazonaws.com" }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = { Name = "my-cluster-eks-cluster-role" }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

# KMS Key for EKS secret encryption (no rotation to avoid LocalStack overhead)
resource "aws_kms_key" "eks" {
  description = "KMS key for EKS cluster secret encryption"
  tags = { Name = "my-cluster-eks-kms-key" }
}

# EKS Cluster
resource "aws_eks_cluster" "main" {
  name     = "my-cluster"
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids             = aws_subnet.private[*].id
    endpoint_public_access = true
    public_access_cidrs    = ["0.0.0.0/0"]
  }

  kubernetes_network_config {
    ip_family = "ipv4"
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  tags = {
    Name = "my-cluster"
  }
}

# OIDC Provider for EKS
resource "aws_iam_openid_connect_provider" "main" {
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["9e99a48a9960b14926bb7f3b02e22da2b0ab7280"]
  url             = aws_eks_cluster.main.identity[0].oidc[0].issuer
}

# Karpenter Controller IAM Role
resource "aws_iam_role" "karpenter_controller" {
  name = "my-cluster-karpenter-controller"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.main.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(aws_eks_cluster.main.identity[0].oidc[0].issuer, "https://", "")}:sub" = "system:serviceaccount:karpenter:karpenter"
            "${replace(aws_eks_cluster.main.identity[0].oidc[0].issuer, "https://", "")}:aud" = "sts.amazonaws.com"
          }
        }
      }
    ]
  })
  tags = { Name = "my-cluster-karpenter-controller" }
}

# Karpenter Controller Policy
data "aws_iam_policy_document" "karpenter_controller" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeLaunchTemplateVersions",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeInstanceTypeOfferings",
      "ec2:DescribeSpotPriceHistory",
      "ec2:DescribeImages",
      "ec2:DescribeTags",
      "ec2:DescribeFleets",
      "ec2:DescribeFleetHistory",
      "ec2:DescribeFleetInstances",
      "ec2:DescribeLaunchTemplates",
      "ec2:DescribeVpcs",
      "ec2:DescribeKeyPairs",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeInstanceCreditSpecifications",
      "ec2:DescribeInstanceEventWindows",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeInstanceTopology",
      "ec2:CreateLaunchTemplate",
      "ec2:CreateFleet",
      "ec2:RunInstances",
      "ec2:CreateTags",
    ]
    resources = ["*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "ec2:TerminateInstances",
      "ec2:DeleteLaunchTemplate"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "ec2:ResourceTag/karpenter.sh/discovery"
      values   = ["my-cluster"]
    }
  }
}

resource "aws_iam_policy" "karpenter_controller" {
  name   = "my-cluster-karpenter-controller-policy"
  policy = data.aws_iam_policy_document.karpenter_controller.json
}

resource "aws_iam_role_policy_attachment" "karpenter_controller" {
  role       = aws_iam_role.karpenter_controller.name
  policy_arn = aws_iam_policy.karpenter_controller.arn
}

# SQS Queue (stateful)
resource "aws_sqs_queue" "karpenter" {
  name                    = "Karpenter-my-cluster"
  sqs_managed_sse_enabled = true

  lifecycle {
    prevent_destroy = true
  }
}

# SQS Queue Policy to allow CloudWatch Events
data "aws_iam_policy_document" "sqs_policy" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.karpenter.arn]
  }
}

resource "aws_sqs_queue_policy" "karpenter" {
  queue_url = aws_sqs_queue.karpenter.id
  policy    = data.aws_iam_policy_document.sqs_policy.json
}

# CloudWatch Event Rules
resource "aws_cloudwatch_event_rule" "health" {
  name        = "Karpenter-my-cluster-health"
  description = "Capture AWS Health events"
  event_pattern = jsonencode({
    source = ["aws.health"]
  })
}

resource "aws_cloudwatch_event_rule" "spot_interruption" {
  name        = "Karpenter-my-cluster-spot-interruption"
  description = "Capture EC2 Spot Instance Interruption Warnings"
  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Spot Instance Interruption Warning"]
  })
}

resource "aws_cloudwatch_event_rule" "rebalance" {
  name        = "Karpenter-my-cluster-rebalance"
  description = "Capture EC2 Instance Rebalance Recommendations"
  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Instance Rebalance Recommendation"]
  })
}

resource "aws_cloudwatch_event_rule" "state_change" {
  name        = "Karpenter-my-cluster-state-change"
  description = "Capture EC2 Instance State-change Notifications"
  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Instance State-change Notification"]
  })
}

# CloudWatch Event Targets -> SQS
resource "aws_cloudwatch_event_target" "health" {
  rule      = aws_cloudwatch_event_rule.health.name
  target_id = "KarpenterSQS"
  arn       = aws_sqs_queue.karpenter.arn
}

resource "aws_cloudwatch_event_target" "spot_interruption" {
  rule      = aws_cloudwatch_event_rule.spot_interruption.name
  target_id = "KarpenterSQS"
  arn       = aws_sqs_queue.karpenter.arn
}

resource "aws_cloudwatch_event_target" "rebalance" {
  rule      = aws_cloudwatch_event_rule.rebalance.name
  target_id = "KarpenterSQS"
  arn       = aws_sqs_queue.karpenter.arn
}

resource "aws_cloudwatch_event_target" "state_change" {
  rule      = aws_cloudwatch_event_rule.state_change.name
  target_id = "KarpenterSQS"
  arn       = aws_sqs_queue.karpenter.arn
}

# Karpenter Node IAM Role
resource "aws_iam_role" "karpenter_node" {
  name = "Karpenter-my-cluster-node"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = { Name = "Karpenter-my-cluster-node" }
}

# Attach managed policies to node role
resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.karpenter_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_ecr_read" {
  role       = aws_iam_role.karpenter_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.karpenter_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy" # IPv4
}

# IAM Instance Profile for node
resource "aws_iam_instance_profile" "karpenter_node" {
  name = "Karpenter-my-cluster-node"
  role = aws_iam_role.karpenter_node.name
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  common_tags = {
    Name        = var.name
    Environment = var.environment
    Prefix      = var.prefix
  }
}

variable "enable_mount_targets" {
  description = "Whether to create mount targets"
  type        = bool
  default     = false
}

variable "enable_file_system_policy" {
  description = "Whether to create a file system policy"
  type        = bool
  default     = false
}

variable "enable_access_point" {
  description = "Whether to create an access point"
  type        = bool
  default     = false
}

variable "encrypted" {
  description = "Whether to encrypt the file system"
  type        = bool
  default     = true
}

variable "kms_key_id" {
  description = "ARN of the KMS key to use for encryption"
  type        = string
  default     = null
}

variable "performance_mode" {
  description = "Performance mode of the file system"
  type        = string
  default     = "generalPurpose"
}

variable "throughput_mode" {
  description = "Throughput mode (bursting, provisioned, or elastic)"
  type        = string
  default     = null
}

variable "provisioned_throughput_in_mibps" {
  description = "Provisioned throughput in MiB/s"
  type        = number
  default     = null
}

variable "lifecycle_policy" {
  description = "List of lifecycle policy transitions to IA"
  type = list(object({
    transition_to_ia = string
  }))
  default = []
}

variable "name" {
  description = "Name tag for the file system"
  type        = string
  default     = "efs-filesystem"
}

variable "prefix" {
  description = "Prefix for tags"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment tag"
  type        = string
  default     = "STAGE"
}

variable "subnet_ids" {
  description = "List of subnet IDs for mount targets"
  type        = list(string)
  default     = []
}

variable "mount_target_security_groups" {
  description = "Map of subnet ID to list of security group IDs for mount targets"
  type        = map(list(string))
  default     = {}
}

variable "mount_target_ip_addresses" {
  description = "Map of subnet ID to IP address for mount targets"
  type        = map(string)
  default     = {}
}

variable "file_system_policy_document" {
  description = "JSON policy document for the file system"
  type        = string
  default     = ""
}

variable "access_point_config" {
  description = "Configuration for the access point"
  type = object({
    posix_user = optional(object({
      uid            = number
      gid            = number
      secondary_gids = optional(list(number))
    }))
    root_directory = optional(object({
      path = string
      creation_info = optional(object({
        owner_uid   = number
        owner_gid   = number
        permissions = string
      }))
    }))
  })
  default = null
}

resource "aws_efs_file_system" "this" {
  creation_token   = var.name
  encrypted        = var.encrypted
  kms_key_id       = var.kms_key_id
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode
  provisioned_throughput_in_mibps = var.provisioned_throughput_in_mibps

  dynamic "lifecycle_policy" {
    for_each = length(var.lifecycle_policy) > 0 ? var.lifecycle_policy : []
    content {
      transition_to_ia = lifecycle_policy.value.transition_to_ia
    }
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_mount_target" "this" {
  count = var.enable_mount_targets ? length(var.subnet_ids) : 0

  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = var.subnet_ids[count.index]
  security_groups = lookup(var.mount_target_security_groups, var.subnet_ids[count.index], [])
  ip_address      = lookup(var.mount_target_ip_addresses, var.subnet_ids[count.index], null)
}

resource "aws_efs_file_system_policy" "this" {
  count = var.enable_file_system_policy && var.file_system_policy_document != "" ? 1 : 0

  file_system_id = aws_efs_file_system.this.id
  policy         = var.file_system_policy_document
}

resource "aws_efs_access_point" "this" {
  count = var.enable_access_point ? 1 : 0

  file_system_id = aws_efs_file_system.this.id

  dynamic "posix_user" {
    for_each = var.access_point_config != null && var.access_point_config.posix_user != null ? [var.access_point_config.posix_user] : []
    content {
      uid            = posix_user.value.uid
      gid            = posix_user.value.gid
      secondary_gids = posix_user.value.secondary_gids
    }
  }

  dynamic "root_directory" {
    for_each = var.access_point_config != null && var.access_point_config.root_directory != null ? [var.access_point_config.root_directory] : []
    content {
      path = root_directory.value.path
      dynamic "creation_info" {
        for_each = root_directory.value.creation_info != null ? [root_directory.value.creation_info] : []
        content {
          owner_uid   = creation_info.value.owner_uid
          owner_gid   = creation_info.value.owner_gid
          permissions = creation_info.value.permissions
        }
      }
    }
  }

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  environment = "dev"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "main-vpc"
    environment = local.environment
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "public-a"
    environment = local.environment
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name        = "public-b"
    environment = local.environment
  }
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "private-a"
    environment = local.environment
  }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.4.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name        = "private-b"
    environment = local.environment
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "main-igw"
    environment = local.environment
  }
}

resource "aws_eip" "nat_a" {
  domain = "vpc"

  tags = {
    Name        = "nat-a-eip"
    environment = local.environment
  }
}

resource "aws_eip" "nat_b" {
  domain = "vpc"

  tags = {
    Name        = "nat-b-eip"
    environment = local.environment
  }
}

resource "aws_nat_gateway" "nat_a" {
  allocation_id = aws_eip.nat_a.id
  subnet_id     = aws_subnet.public_a.id

  tags = {
    Name        = "nat-a"
    environment = local.environment
  }
}

resource "aws_nat_gateway" "nat_b" {
  allocation_id = aws_eip.nat_b.id
  subnet_id     = aws_subnet.public_b.id

  tags = {
    Name        = "nat-b"
    environment = local.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name        = "public-rt"
    environment = local.environment
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private_a" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_a.id
  }

  tags = {
    Name        = "private-a-rt"
    environment = local.environment
  }
}

resource "aws_route_table" "private_b" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_b.id
  }

  tags = {
    Name        = "private-b-rt"
    environment = local.environment
  }
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private_a.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private_b.id
}

resource "aws_security_group" "public_sg" {
  name        = "public-sg"
  description = "Security group for public resources"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "public-sg"
    environment = local.environment
  }
}

resource "aws_security_group" "private_sg" {
  name        = "private-sg"
  description = "Security group for private resources"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.public_sg.id]
  }

  ingress {
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.public_sg.id]
  }

  ingress {
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.public_sg.id]
  }

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.public_sg.id]
  }

  egress {
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.public_sg.id]
  }

  tags = {
    Name        = "private-sg"
    environment = local.environment
  }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------
variable "backup_enabled" {
  description = "Master flag to enable/disable all backup resources"
  type        = bool
  default     = true
}

variable "backup_vault_name" {
  description = "Name of the backup vault"
  type        = string
  default     = "production-backup-vault"
}

variable "kms_key_arn" {
  description = "ARN of an existing KMS key for vault encryption. If empty, a new KMS key will be created."
  type        = string
  default     = ""
}

variable "backup_plan_name" {
  description = "Name of the backup plan"
  type        = string
  default     = "production-backup-plan"
}

variable "backup_schedule" {
  description = "CRON schedule for the default backup rule"
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "start_window" {
  description = "Start window in minutes for the default rule"
  type        = number
  default     = 60
}

variable "completion_window" {
  description = "Completion window in minutes for the default rule"
  type        = number
  default     = 180
}

variable "enable_continuous_backup" {
  description = "Enable continuous backups for the default rule"
  type        = bool
  default     = false
}

variable "enable_windows_vss" {
  description = "Enable Windows VSS backup option for EC2 instances (default rule)"
  type        = bool
  default     = false
}

variable "additional_rules" {
  description = "List of additional backup rules. Each rule can have schedule, lifecycle, enable_continuous_backup, enable_windows_vss, optional target_vault_name, and optional copy_action with destination_vault_arn. If destination_vault_arn is empty, a new vault will be created."
  type = list(object({
    schedule                  = string
    target_vault_name         = optional(string)
    move_to_cold_storage_days = optional(number)
    delete_after_days         = number
    enable_continuous_backup  = optional(bool, false)
    enable_windows_vss        = optional(bool, false)
    copy_action = optional(object({
      destination_vault_arn = optional(string, "")
      lifecycle = optional(object({
        move_to_cold_storage_days = optional(number)
        delete_after_days         = optional(number)
      }), null)
    }), null)
  }))
  default = []
}

variable "selection_resources" {
  description = "List of ARN patterns to select resources for backup. If empty, tag-based selection will be used."
  type        = list(string)
  default     = []
}

variable "selection_tags" {
  description = "List of tag conditions for selecting resources. Each block: type (STRING_EQUALS, STRING_LIKE, STRING_NOT_EQUALS, STRING_NOT_LIKE), key, value."
  type = list(object({
    type  = string
    key   = string
    value = string
  }))
  default = []
}

variable "selection_tags_not" {
  description = "List of tag conditions to exclude resources. Same structure as selection_tags."
  type = list(object({
    type  = string
    key   = string
    value = string
  }))
  default = []
}

variable "existing_iam_role_arn" {
  description = "ARN of an existing IAM role to use for AWS Backup. If empty, a new role will be created."
  type        = string
  default     = ""
}

variable "sns_topic_name" {
  description = "Name of the SNS topic for backup vault notifications"
  type        = string
  default     = "backup-vault-notifications"
}

variable "enable_vault_notifications" {
  description = "Enable SNS notifications for backup vault events. Set to false for LocalStack compatibility."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Common tags to apply to all resources"
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------------------------------------------------
locals {
  create_kms_key = var.backup_enabled && var.kms_key_arn == "" ? true : false
  kms_key_arn    = var.kms_key_arn != "" ? var.kms_key_arn : (
    local.create_kms_key ? aws_kms_key.this[0].arn : ""
  )
  # Determine if any rule (default or additional) has Windows VSS enabled
  any_vss_enabled = var.backup_enabled && (
    var.enable_windows_vss || length(var.additional_rules) > 0
  )
}

# ---------------------------------------------------------------------------------------------------------------------
# KMS KEY (if not provided)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0
  description             = "KMS key for backup vault encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = var.tags
}

resource "aws_kms_alias" "this" {
  count         = local.create_kms_key ? 1 : 0
  name          = "alias/${var.backup_vault_name}-key"
  target_key_id = aws_kms_key.this[0].key_id
}

# ---------------------------------------------------------------------------------------------------------------------
# BACKUP VAULT
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_backup_vault" "this" {
  count = var.backup_enabled ? 1 : 0
  name        = var.backup_vault_name
  kms_key_arn = local.kms_key_arn
  tags        = var.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# BACKUP PLAN
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_backup_plan" "this" {
  count = var.backup_enabled ? 1 : 0
  name = var.backup_plan_name
  tags = var.tags

  rule {
    rule_name         = "default"
    target_vault_name = aws_backup_vault.this[0].name
    schedule          = var.backup_schedule
    start_window      = var.start_window
    completion_window = var.completion_window
    lifecycle {
      cold_storage_after = 30
      delete_after       = 180
    }
    enable_continuous_backup = var.enable_continuous_backup
  }

  dynamic "rule" {
    for_each = var.additional_rules
    content {
      rule_name         = "additional-${rule.key}"
      target_vault_name = try(rule.value.target_vault_name, var.backup_vault_name)
      schedule          = rule.value.schedule
      start_window      = try(rule.value.start_window, var.start_window)
      completion_window = try(rule.value.completion_window, var.completion_window)
      lifecycle {
        cold_storage_after = try(rule.value.move_to_cold_storage_days, null)
        delete_after       = rule.value.delete_after_days
      }
      enable_continuous_backup = rule.value.enable_continuous_backup

      dynamic "copy_action" {
        for_each = rule.value.copy_action != null ? [rule.value.copy_action] : []
        content {
          destination_vault_arn = try(
            copy_action.value.destination_vault_arn,
            aws_backup_vault.copy_dest[rule.key][0].arn
          )
          dynamic "lifecycle" {
            for_each = copy_action.value.lifecycle != null ? [copy_action.value.lifecycle] : []
            content {
              cold_storage_after = try(lifecycle.value.move_to_cold_storage_days, null)
              delete_after       = try(lifecycle.value.delete_after_days, null)
            }
          }
        }
      }
    }
  }

  dynamic "advanced_backup_setting" {
    for_each = local.any_vss_enabled ? [1] : []
    content {
      backup_options = {
        WindowsVSS = "enabled"
      }
      resource_type = "EC2"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DESTINATION VAULTS FOR COPY ACTIONS (if not provided)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_backup_vault" "copy_dest" {
  count = var.backup_enabled ? length(compact([
    for rule in var.additional_rules : (
      rule.copy_action != null && rule.copy_action.destination_vault_arn == "" ? "create" : ""
    )
  ])) : 0
  name        = "${var.backup_vault_name}-copy-dest-${count.index}"
  kms_key_arn = local.kms_key_arn
  tags        = var.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# BACKUP SELECTION
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_backup_selection" "this" {
  count        = var.backup_enabled ? 1 : 0
  name         = "${var.backup_plan_name}-selection"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = var.existing_iam_role_arn != "" ? var.existing_iam_role_arn : aws_iam_role.this[0].arn

  resources = length(var.selection_resources) > 0 ? var.selection_resources : null

  dynamic "selection_tag" {
    for_each = length(var.selection_resources) == 0 ? var.selection_tags : []
    content {
      type  = selection_tag.value.type
      key   = selection_tag.value.key
      value = selection_tag.value.value
    }
  }

  dynamic "selection_tag" {
    for_each = length(var.selection_resources) == 0 ? var.selection_tags_not : []
    content {
      type  = selection_tag.value.type
      key   = selection_tag.value.key
      value = selection_tag.value.value
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM ROLE (if not provided)
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "this" {
  count = var.backup_enabled && var.existing_iam_role_arn == "" ? 1 : 0
  name               = "${var.backup_plan_name}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = var.backup_enabled && var.existing_iam_role_arn == "" ? 1 : 0
  role       = aws_iam_role.this[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore" {
  count = var.backup_enabled && var.existing_iam_role_arn == "" ? 1 : 0
  role       = aws_iam_role.this[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# Custom S3 backup policy (replaces managed policy AWSBackupServiceRolePolicyForS3Backup)
data "aws_iam_policy_document" "s3_backup" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectTagging",
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:PutObject",
      "s3:PutObjectVersionTagging",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:GetBucketObjectLockConfiguration",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "s3_backup" {
  count = var.backup_enabled && var.existing_iam_role_arn == "" ? 1 : 0
  name   = "s3-backup-policy"
  role   = aws_iam_role.this[0].id
  policy = data.aws_iam_policy_document.s3_backup.json
}

# Custom S3 restore policy (replaces managed policy AWSBackupServiceRolePolicyForS3Restore)
data "aws_iam_policy_document" "s3_restore" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectTagging",
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:PutObject",
      "s3:PutObjectVersionTagging",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:GetBucketObjectLockConfiguration"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "s3_restore" {
  count = var.backup_enabled && var.existing_iam_role_arn == "" ? 1 : 0
  name   = "s3-restore-policy"
  role   = aws_iam_role.this[0].id
  policy = data.aws_iam_policy_document.s3_restore.json
}

data "aws_iam_policy_document" "tag_management" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:CreateTags",
      "ec2:DeleteTags",
      "ec2:DescribeTags"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "tag_management" {
  count = var.backup_enabled && var.existing_iam_role_arn == "" ? 1 : 0
  name   = "tag-management"
  role   = aws_iam_role.this[0].id
  policy = data.aws_iam_policy_document.tag_management.json
}

# ---------------------------------------------------------------------------------------------------------------------
# SNS TOPIC & NOTIFICATIONS
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_sns_topic" "this" {
  count = var.backup_enabled ? 1 : 0
  name   = var.sns_topic_name
  kms_master_key_id = local.kms_key_arn != "" ? local.kms_key_arn : null
  tags   = var.tags
}

data "aws_iam_policy_document" "sns_topic" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = ["SNS:Publish"]
    resources = [aws_sns_topic.this[0].arn]
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.backup_enabled ? 1 : 0
  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.sns_topic.json
}

resource "aws_backup_vault_notifications" "this" {
  count = var.backup_enabled && var.enable_vault_notifications ? 1 : 0
  backup_vault_name = aws_backup_vault.this[0].name
  sns_topic_arn     = aws_sns_topic.this[0].arn
  backup_vault_events = [
    "BACKUP_JOB_STARTED",
    "BACKUP_JOB_COMPLETED",
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_STARTED",
    "RESTORE_JOB_COMPLETED",
    "RESTORE_JOB_FAILED"
  ]
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------
output "backup_vault_id" {
  value = var.backup_enabled ? aws_backup_vault.this[0].id : null
}

output "backup_vault_arn" {
  value = var.backup_enabled ? aws_backup_vault.this[0].arn : null
}

output "backup_plan_id" {
  value = var.backup_enabled ? aws_backup_plan.this[0].id : null
}

output "backup_plan_arn" {
  value = var.backup_enabled ? aws_backup_plan.this[0].arn : null
}

output "backup_plan_version" {
  value = var.backup_enabled ? aws_backup_plan.this[0].version : null
}

output "backup_iam_role_arn" {
  value = var.backup_enabled ? (
    var.existing_iam_role_arn != "" ? var.existing_iam_role_arn : aws_iam_role.this[0].arn
  ) : null
}

output "backup_iam_role_name" {
  value = var.backup_enabled ? (
    var.existing_iam_role_arn != "" ? "provided externally" : aws_iam_role.this[0].name
  ) : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "prefix" {
  type    = string
  default = "quortex"
}

variable "bucket_list" {
  type = list(object({
    name         = string
    label        = string
    tags         = map(string)
    expiration = optional(object({
      enabled         = bool
      expiration_days = number
    }))
    role = optional(object({
      service_accounts = list(object({
        name      = string
        namespace = string
      }))
    }))
    force_destroy = optional(bool)
  }))
  default = [
    {
      name         = "data"
      label        = "Data Storage"
      tags         = { Environment = "dev" }
      expiration   = null
      role         = null
      force_destroy = false
    }
  ]
}

variable "enable_sse" {
  type    = bool
  default = true
}

variable "enable_user_access_key" {
  type    = bool
  default = true
}

variable "enable_irsa" {
  type    = bool
  default = false
}

variable "cluster_oidc_issuer_url" {
  type    = string
  default = ""
}

variable "enable_oai" {
  type    = bool
  default = false
}

locals {
  # Convert bucket_list to a map for for_each, using name as key
  buckets = {
    for b in var.bucket_list : b.name => b
  }
  # Default force_destroy to false if not provided
  bucket_force_destroy = {
    for k, b in local.buckets : k => try(b.force_destroy, false)
  }
  # Condition to create IAM user
  create_user = length(var.bucket_list) > 0 && var.enable_user_access_key
  # Condition to create IRSA resources
  create_irsa = var.enable_irsa && var.cluster_oidc_issuer_url != ""
}

# KMS key for S3 bucket encryption (only when SSE is enabled)
resource "aws_kms_key" "s3" {
  count = var.enable_sse ? 1 : 0

  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# S3 buckets
resource "aws_s3_bucket" "this" {
  for_each = local.buckets

  bucket        = "${var.prefix}-${each.value.name}"
  force_destroy = local.bucket_force_destroy[each.key]

  tags = merge(each.value.tags, { Name = each.value.label })

  lifecycle {
    prevent_destroy = true
  }
}

# Server-side encryption using CMK
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  for_each = var.enable_sse ? local.buckets : {}

  bucket = aws_s3_bucket.this[each.key].bucket

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3[0].arn
    }
  }
}

# Public access blocks
resource "aws_s3_bucket_public_access_block" "this" {
  for_each = local.buckets

  bucket = aws_s3_bucket.this[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM user and access key
resource "aws_iam_user" "storage" {
  count = local.create_user ? 1 : 0

  name = "${var.prefix}-user"
}

resource "aws_iam_access_key" "storage" {
  count = local.create_user ? 1 : 0

  user = aws_iam_user.storage[0].name
}

# IAM user policy with read/write access to all buckets
resource "aws_iam_user_policy" "storage" {
  count = local.create_user ? 1 : 0

  name = "${var.prefix}-policy"
  user = aws_iam_user.storage[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      for b in var.bucket_list : {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::${var.prefix}-${b.name}",
          "arn:aws:s3:::${var.prefix}-${b.name}/*"
        ]
      }
    ]
  })
}

# IRSA resources
data "tls_certificate" "oidc" {
  count = local.create_irsa ? 1 : 0

  url = var.cluster_oidc_issuer_url
}

resource "aws_iam_openid_connect_provider" "cluster" {
  count = local.create_irsa ? 1 : 0

  url             = var.cluster_oidc_issuer_url
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = data.tls_certificate.oidc[0].certificates[*].sha1_fingerprint
}

# Filter buckets that have a role defined
locals {
  irsa_buckets = {
    for k, b in local.buckets : k => b
    if b.role != null && length(b.role.service_accounts) > 0
  }
}

resource "aws_iam_role" "irsa" {
  for_each = local.create_irsa ? local.irsa_buckets : {}

  name               = "${var.prefix}-${each.key}-irsa"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.cluster[0].arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${var.cluster_oidc_issuer_url}:sub" = [
              for sa in each.value.role.service_accounts :
              "system:serviceaccount:${sa.namespace}:${sa.name}"
            ]
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "irsa" {
  for_each = local.create_irsa ? local.irsa_buckets : {}

  name        = "${var.prefix}-${each.key}-irsa-policy"
  description = "Policy for IRSA role for bucket ${var.prefix}-${each.key}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.this[each.key].arn,
          "${aws_s3_bucket.this[each.key].arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "irsa" {
  for_each = local.create_irsa ? local.irsa_buckets : {}

  role       = aws_iam_role.irsa[each.key].name
  policy_arn = aws_iam_policy.irsa[each.key].arn
}

# CloudFront OAI
resource "aws_cloudfront_origin_access_identity" "this" {
  for_each = var.enable_oai ? local.buckets : {}

  comment = each.value.label
}

# Bucket policy for OAI
resource "aws_s3_bucket_policy" "oai" {
  for_each = var.enable_oai ? local.buckets : {}

  bucket = aws_s3_bucket.this[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.this[each.key].iam_arn
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this[each.key].arn}/*"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# S3 bucket for static website frontend
resource "aws_s3_bucket" "frontend" {
  bucket = "dms-frontend-bucket"

  lifecycle {
    prevent_destroy = true
  }
}

# Enable versioning
resource "aws_s3_bucket_versioning" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Full public access blocking – bucket is private
resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Customer managed KMS key for SSE-KMS
resource "aws_kms_key" "s3_key" {
  description             = "CMK for S3 bucket encryption (dms-frontend-bucket)"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# Server-side encryption using KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_key.arn
    }
  }
}

# Bucket policy allowing CloudFront access via OAC
resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

data "aws_iam_policy_document" "bucket_policy" {
  statement {
    sid    = "AllowCloudFrontServicePrincipal"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.frontend.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.frontend.arn]
    }
  }
}

# CloudFront Origin Access Control (OAC)
resource "aws_cloudfront_origin_access_control" "frontend" {
  name                              = "oac-dms-frontend"
  description                       = "OAC for dms-frontend-bucket"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

# Custom CloudFront response headers policy for strict security headers
resource "aws_cloudfront_response_headers_policy" "strict_security" {
  name    = "strict-security-headers"
  comment = "Custom policy for strict security headers"

  security_headers_config {
    strict_transport_security {
      access_control_max_age_sec = 31536000
      include_subdomains        = true
      override                  = true
      preload                   = true
    }

    content_type_options {
      override = true
    }

    frame_options {
      frame_option = "DENY"
      override     = true
    }

    referrer_policy {
      referrer_policy = "strict-origin-when-cross-origin"
      override        = true
    }

    xss_protection {
      mode_block = true
      protection = true
      override   = true
    }

    content_security_policy {
      content_security_policy = "default-src 'none'; connect-src 'self' https://*.execute-api.us-east-1.amazonaws.com; font-src 'self'; img-src 'self'; script-src 'self'; style-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'"
      override               = true
    }
  }
}

# WAF Web ACL with AWS Managed Rules Common Rule Set
resource "aws_wafv2_web_acl" "frontend" {
  name        = "dms-frontend-waf"
  description = "WAF for dms-frontend CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWS-AWSManagedRulesCommonRuleSet"
    priority = 0

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesCommonRuleSet"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = false
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = false
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "dms-frontend-waf"
    sampled_requests_enabled   = false
  }
}

# CloudFront distribution fronting the private S3 bucket
resource "aws_cloudfront_distribution" "frontend" {
  origin {
    domain_name              = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id                = "S3-${aws_s3_bucket.frontend.id}"
    origin_access_control_id = aws_cloudfront_origin_access_control.frontend.id
  }

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id       = "S3-${aws_s3_bucket.frontend.id}"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    response_headers_policy_id = aws_cloudfront_response_headers_policy.strict_security.id
    min_ttl                    = 0
    default_ttl                = 3600
    max_ttl                    = 86400
  }

  price_class = "PriceClass_100"

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  web_acl_id = aws_wafv2_web_acl.frontend.arn

  tags = {
    Name = "dms-frontend-distribution"
  }
}

# Provider and Required Providers
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Data Sources
data "aws_caller_identity" "current" {}
data "aws_availability_zones" "available" {
  state = "available"
}

# Variables
variable "assume_role_arn" {
  description = "Optional ARN of an IAM entity to allow assume the permissive trust role"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Map of tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Locals
locals {
  common_tags = merge({
    Environment = "testing"
    Project     = "iam-privilege-escalation-test"
  }, var.tags)

  # Permissive trust role policy statements
  permissive_trust_statements = concat(
    [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ],
    var.assume_role_arn != "" ? [
      {
        Effect = "Allow"
        Principal = {
          AWS = var.assume_role_arn
        }
        Action = "sts:AssumeRole"
      }
    ] : []
  )
  permissive_trust_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.permissive_trust_statements
  })
}

