resource "aws_iam_user" "ex1" {
  name = "ex1-user"
  tags = local.common_tags
}

resource "aws_iam_role" "ex1" {
  name = "ex1-role"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_user.ex1.arn
        }
        Action = "sts:AssumeRole"
