    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_user.fn3.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_policy" "fn3" {
  name        = "fn3-create-policy-version-dategreaterthan"
  description = "Allow iam:CreatePolicyVersion with DateGreaterThan condition"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "iam:CreatePolicyVersion"
        Resource = "*"
