# -----------------------------------------------------------
# Test Case 7: do7 – Deny-only policy for all IAM actions
# -----------------------------------------------------------
resource "aws_iam_user" "do7" {
  name = "do7-user"
  tags = local.common_tags
}

resource "aws_iam_role" "do7" {
  name = "do7-role"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_user.do7.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_policy" "do7" {
  name        = "do7-deny-only-iam"
  description = "Deny all IAM actions"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Action   = "iam:*"
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "do7" {
  user       = aws_iam_user.do7.name
  policy_arn = aws_iam_policy.do7.arn
}

resource "aws_iam_role_policy_attachment" "do7" {
  role       = aws_iam_role.do7.name
  policy_arn = aws_iam_policy.do7.arn
}

resource "aws_iam_access_key" "do7" {
  user = aws_iam_user.do7.name
}

# -----------------------------------------------------------
# Test Case 8: fp4 – iam:CreatePolicyVersion on AWS managed fp4-* policies
# -----------------------------------------------------------
resource "aws_iam_user" "fp4" {
  name = "fp4-user"
  tags = local.common_tags
}

resource "aws_iam_role" "fp4" {
  name = "fp4-role"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_user.fp4.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_policy" "fp4" {
  name        = "fp4-create-policy-version-aws"
  description = "Allow iam:CreatePolicyVersion on AWS managed fp4-* policies"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "iam:CreatePolicyVersion"
        Resource = "arn:aws:iam::aws:policy/fp4-*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "fp4" {
  user       = aws_iam_user.fp4.name
  policy_arn = aws_iam_policy.fp4.arn
}

resource "aws_iam_role_policy_attachment" "fp4" {
  role       = aws_iam_role.fp4.name
  policy_arn = aws_iam_policy.fp4.arn
}

resource "aws_iam_access_key" "fp4" {
  user = aws_iam_user.fp4.name
}

# -----------------------------------------------------------
# Test Case 9: dl9 – iam:CreatePolicyVersion with DateLessThan
# -----------------------------------------------------------
resource "aws_iam_user" "dl9" {
  name = "dl9-user"
  tags = local.common_tags
}

resource "aws_iam_role" "dl9" {
  name = "dl9-role"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_user.dl9.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_policy" "dl9" {
  name        = "dl9-create-policy-version-datelessthan"
  description = "Allow iam:CreatePolicyVersion with DateLessThan condition"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "iam:CreatePolicyVersion"
        Resource = "*"
        Condition = {
          DateLessThan = {
            "aws:CurrentTime" = "2020-01-01T00:00:01Z"
          }
        }
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "dl9" {
  user       = aws_iam_user.dl9.name
  policy_arn = aws_iam_policy.dl9.arn
}

resource "aws_iam_role_policy_attachment" "dl9" {
  role       = aws_iam_role.dl9.name
  policy_arn = aws_iam_policy.dl9.arn
}

resource "aws_iam_access_key" "dl9" {
  user = aws_iam_user.dl9.name
}

# -----------------------------------------------------------
# Permissive Trust Role
# -----------------------------------------------------------
resource "aws_iam_role" "permissive_trust" {
  name               = "permissive-trust-role"
  assume_role_policy = local.permissive_trust_policy
  tags               = local.common_tags
}

