terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "namespace" {
  description = "Namespace for the ECR repository name"
  type        = string
  default     = ""
}

variable "name" {
  description = "Name for the ECR repository; if empty, a random suffix is generated"
  type        = string
  default     = ""
}

variable "image_tag_mutability" {
  description = "Image tag mutability setting: MUTABLE or IMMUTABLE"
  type        = string
  default     = "IMMUTABLE"

  validation {
    condition     = contains(["MUTABLE", "IMMUTABLE"], var.image_tag_mutability)
    error_message = "image_tag_mutability must be either 'MUTABLE' or 'IMMUTABLE'."
  }
}

variable "scan_on_push" {
  description = "Enable automatic image scanning on push"
  type        = bool
  default     = true
}

variable "custom_lifecycle_policy" {
  description = "Optional custom lifecycle policy JSON. If null, a default policy expires images when count per tag exceeds 2."
  type        = string
  default     = null
}

variable "trusted_account_ids" {
  description = "List of AWS account IDs allowed cross-account access to the repository"
  type        = list(string)
  default     = []
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "dev"
}

locals {
  # Compose repository name: namespace/name (or namespace/random, or just name, or just random)
  repo_name = (
    var.namespace != "" && var.name != "" ? "${var.namespace}/${var.name}" :
    var.namespace != "" && var.name == "" ? "${var.namespace}/${random_id.suffix.hex}" :
    var.namespace == "" && var.name != "" ? var.name :
    random_id.suffix.hex
  )

  common_tags = {
    Name        = local.repo_name
    Environment = var.environment
  }

  # Default lifecycle policy: expire images when count per tag > 2
  default_lifecycle_policy = jsonencode({
    rules = [{
      rulePriority = 1
      description  = "Expire images when count per tag exceeds 2"
      selection = {
        tagStatus   = "any"
        countType   = "imageCountMoreThan"
        countNumber = 2
      }
      action = {
        type = "expire"
      }
    }]
  })
}

resource "random_id" "suffix" {
  byte_length = 3
}

resource "aws_ecr_repository" "this" {
  name                 = local.repo_name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "this" {
  repository = aws_ecr_repository.this.name
  policy     = var.custom_lifecycle_policy != null ? var.custom_lifecycle_policy : local.default_lifecycle_policy
}

data "aws_iam_policy_document" "ecr_read" {
  statement {
    effect = "Allow"
    actions = [
      "ecr:DescribeRepositories",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:ListImages",
      "ecr:BatchCheckLayerAvailability",
      "ecr:DescribeImages",
      "ecr:GetRepositoryPolicy",
      "ecr:GetLifecyclePolicy",
    ]
    resources = [
      aws_ecr_repository.this.arn,
      "${aws_ecr_repository.this.arn}/*",
    ]
  }
}

resource "aws_iam_policy" "ecr_read" {
  name        = "${local.repo_name}-read-policy"
  description = "Read-only access policy for ECR repository ${local.repo_name}"
  policy      = data.aws_iam_policy_document.ecr_read.json
  tags        = local.common_tags
}

data "aws_iam_policy_document" "ecr_write" {
  statement {
    effect = "Allow"
    actions = [
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
      "ecr:PutImage",
      "ecr:BatchDeleteImage",
      "ecr:DeleteRepositoryPolicy",
      "ecr:PutLifecyclePolicy",
    ]
    resources = [
      aws_ecr_repository.this.arn,
      "${aws_ecr_repository.this.arn}/*",
    ]
  }
}

resource "aws_iam_policy" "ecr_write" {
  name        = "${local.repo_name}-write-policy"
  description = "Write access policy for ECR repository ${local.repo_name}"
  policy      = data.aws_iam_policy_document.ecr_write.json
  tags        = local.common_tags
}

data "aws_iam_policy_document" "repository_policy" {
  count = length(var.trusted_account_ids) > 0 ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:BatchCheckLayerAvailability",
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
    ]
    principals {
      type        = "AWS"
      identifiers = [for acct in var.trusted_account_ids : "arn:aws:iam::${acct}:root"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = var.trusted_account_ids
    }
  }

  statement {
    effect = "Allow"
    actions = [
      "ecr:DescribeRepositories",
      "ecr:ListImages",
      "ecr:DescribeImages",
      "ecr:GetRepositoryPolicy",
      "ecr:GetLifecyclePolicy",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:BatchCheckLayerAvailability",
    ]
    principals {
      type        = "AWS"
      identifiers = [for acct in var.trusted_account_ids : "arn:aws:iam::${acct}:root"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = var.trusted_account_ids
    }
  }
}

resource "aws_ecr_repository_policy" "this" {
  count = length(var.trusted_account_ids) > 0 ? 1 : 0

  repository = aws_ecr_repository.this.name
  policy     = data.aws_iam_policy_document.repository_policy[0].json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "base_name" {
  description = "Base name for resource naming"
  type        = string
  default     = "config"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "dev"
}

variable "iam_role_arn" {
  description = "IAM role ARN for the configuration recorder"
  type        = string
  default     = ""
}

variable "s3_bucket_name" {
  description = "S3 bucket name for delivery channel"
  type        = string
  default     = ""
}

variable "lambda_function_arn" {
  description = "Lambda function ARN for custom rules"
  type        = string
  default     = ""
}

variable "remediation_target_id" {
  description = "Target ID for remediation configuration"
  type        = string
  default     = ""
}

variable "remediation_target_type" {
  description = "Target type for remediation configuration (e.g., SSM_DOCUMENT)"
  type        = string
  default     = ""
}

variable "aggregate_authorization_account_id" {
  description = "Account ID for aggregate authorization"
  type        = string
  default     = ""
}

variable "aggregate_authorization_region" {
  description = "Region for aggregate authorization"
  type        = string
  default     = ""
}

variable "enable_recorder" {
  description = "Enable configuration recorder"
  type        = bool
  default     = true
}

variable "enable_delivery_channel" {
  description = "Enable delivery channel"
  type        = bool
  default     = true
}

variable "enable_aggregator" {
  description = "Enable configuration aggregator"
  type        = bool
  default     = false
}

variable "enable_org_managed_rule" {
  description = "Enable organization managed rule"
  type        = bool
  default     = false
}

variable "enable_org_custom_rule" {
  description = "Enable organization custom rule"
  type        = bool
  default     = false
}

variable "enable_account_rule" {
  description = "Enable account-level config rule"
  type        = bool
  default     = false
}

variable "enable_remediation" {
  description = "Enable remediation configuration"
  type        = bool
  default     = false
}

variable "enable_aggregate_authorization" {
  description = "Enable cross-account aggregate authorization"
  type        = bool
  default     = false
}

variable "organization_aggregator" {
  description = "If true, use organization aggregation source; otherwise use account IDs"
  type        = bool
  default     = false
}

variable "account_ids" {
  description = "List of account IDs for account aggregation source"
  type        = list(string)
  default     = []
}

variable "managed_rule_identifier" {
  description = "Identifier for the managed rule (e.g., IAM_PASSWORD_POLICY)"
  type        = string
  default     = "IAM_PASSWORD_POLICY"
}

variable "managed_rule_input_parameters" {
  description = "Input parameters for the managed rule as a JSON string"
  type        = string
  default     = "{}"
}

variable "managed_rule_scope_compliance_resource_types" {
  description = "List of resource types to scope the managed rule"
  type        = list(string)
  default     = []
}

variable "managed_rule_scope_tag_key" {
  description = "Tag key for scoping the managed rule"
  type        = string
  default     = ""
}

variable "managed_rule_scope_tag_value" {
  description = "Tag value for scoping the managed rule"
  type        = string
  default     = ""
}

variable "trigger_types" {
  description = "Trigger types for custom rules"
  type        = list(string)
  default     = ["ConfigurationItemChangeNotification"]
}

variable "custom_rule_scope_compliance_resource_types" {
  description = "List of resource types to scope the custom rule"
  type        = list(string)
  default     = []
}

variable "custom_rule_scope_tag_key" {
  description = "Tag key for scoping the custom rule"
  type        = string
  default     = ""
}

variable "custom_rule_scope_tag_value" {
  description = "Tag value for scoping the custom rule"
  type        = string
  default     = ""
}

variable "source_owner" {
  description = "Source owner for the account rule (CUSTOM_LAMBDA or AWS)"
  type        = string
  default     = "CUSTOM_LAMBDA"
}

variable "source_identifier" {
  description = "Source identifier for the account rule (Lambda ARN or managed rule identifier)"
  type        = string
  default     = ""
}

variable "account_rule_input_parameters" {
  description = "Input parameters for the account rule as a JSON string"
  type        = string
  default     = "{}"
}

variable "account_rule_scope_compliance_resource_types" {
  description = "List of resource types to scope the account rule"
  type        = list(string)
  default     = []
}

variable "account_rule_scope_tag_key" {
  description = "Tag key for scoping the account rule"
  type        = string
  default     = ""
}

variable "account_rule_scope_tag_value" {
  description = "Tag value for scoping the account rule"
  type        = string
  default     = ""
}

variable "remediation_automatic" {
  description = "Automatic remediation flag"
  type        = bool
  default     = true
}

variable "remediation_max_automatic_attempts" {
  description = "Maximum automatic attempts for remediation"
  type        = number
  default     = 3
}

variable "remediation_resource_type" {
  description = "Resource type for remediation (optional)"
  type        = string
  default     = ""
}

provider "aws" {
  region = var.aws_region
}

locals {
  name_prefix = "${var.base_name}-${var.environment}"
  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# Configuration Recorder
resource "aws_config_configuration_recorder" "main" {
  count    = var.enable_recorder ? 1 : 0
  name     = "${local.name_prefix}-recorder"
  role_arn = var.iam_role_arn != "" ? var.iam_role_arn : "arn:aws:iam::000000000000:role/placeholder-config-recorder"

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }

  lifecycle {
    create_before_destroy = true
  }
}

# Delivery Channel
resource "aws_config_delivery_channel" "main" {
  count          = var.enable_delivery_channel ? 1 : 0
  name           = "${local.name_prefix}-delivery"
  s3_bucket_name = var.s3_bucket_name != "" ? var.s3_bucket_name : "placeholder-config-bucket"
  s3_key_prefix  = "${local.name_prefix}/config"

  snapshot_delivery_properties {
    delivery_frequency = "One_Hour"
  }

  depends_on = [aws_config_configuration_recorder.main]

  lifecycle {
    create_before_destroy = true
  }
}

# Aggregator
resource "aws_config_configuration_aggregator" "main" {
  count = var.enable_aggregator ? 1 : 0
  name  = "${local.name_prefix}-aggregator"

  dynamic "organization_aggregation_source" {
    for_each = var.organization_aggregator ? [1] : []
    content {
      role_arn    = var.iam_role_arn != "" ? var.iam_role_arn : "arn:aws:iam::000000000000:role/placeholder-aggregator"
      all_regions = true
    }
  }

  dynamic "account_aggregation_source" {
    for_each = var.organization_aggregator ? [] : [1]
    content {
      account_ids = var.account_ids
      all_regions = true
    }
  }

  depends_on = [aws_config_configuration_recorder.main, aws_config_delivery_channel.main]

  tags = local.common_tags
}

# Organization Managed Rule
resource "aws_config_organization_managed_rule" "managed" {
  count            = var.enable_org_managed_rule ? 1 : 0
  name             = "${local.name_prefix}-org-managed-rule"
  rule_identifier  = var.managed_rule_identifier
  input_parameters = var.managed_rule_input_parameters

  resource_types_scope = length(var.managed_rule_scope_compliance_resource_types) > 0 ? toset(var.managed_rule_scope_compliance_resource_types) : null
  tag_key_scope        = var.managed_rule_scope_tag_key != "" ? var.managed_rule_scope_tag_key : null
  tag_value_scope      = var.managed_rule_scope_tag_key != "" ? var.managed_rule_scope_tag_value : null
}

# Organization Custom Rule
resource "aws_config_organization_custom_rule" "custom" {
  count              = var.enable_org_custom_rule ? 1 : 0
  name               = "${local.name_prefix}-org-custom-rule"
  lambda_function_arn = var.lambda_function_arn != "" ? var.lambda_function_arn : "arn:aws:lambda:us-east-1:000000000000:function:placeholder-custom-rule"
  trigger_types      = var.trigger_types
  input_parameters   = "{}"

  resource_types_scope = length(var.custom_rule_scope_compliance_resource_types) > 0 ? toset(var.custom_rule_scope_compliance_resource_types) : null
  tag_key_scope        = var.custom_rule_scope_tag_key != "" ? var.custom_rule_scope_tag_key : null
  tag_value_scope      = var.custom_rule_scope_tag_key != "" ? var.custom_rule_scope_tag_value : null
}

# Account-Level Config Rule (with remediation)
resource "aws_config_config_rule" "account_rule" {
  count            = var.enable_account_rule ? 1 : 0
  name             = "${local.name_prefix}-account-rule"
  input_parameters = var.account_rule_input_parameters

  source {
    owner             = var.source_owner
    source_identifier = var.source_identifier != "" ? var.source_identifier : var.lambda_function_arn != "" ? var.lambda_function_arn : "arn:aws:lambda:us-east-1:000000000000:function:placeholder-account-rule"
  }

  dynamic "scope" {
    for_each = length(var.account_rule_scope_compliance_resource_types) > 0 || var.account_rule_scope_tag_key != "" ? [1] : []
    content {
      compliance_resource_types = var.account_rule_scope_compliance_resource_types
      tag_key                     = var.account_rule_scope_tag_key != "" ? var.account_rule_scope_tag_key : null
      tag_value                   = var.account_rule_scope_tag_key != "" ? var.account_rule_scope_tag_value : null
    }
  }

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

# Remediation Configuration for Account Rule
resource "aws_config_remediation_configuration" "remediation" {
  count = var.enable_remediation && var.enable_account_rule ? 1 : 0

  config_rule_name                = aws_config_config_rule.account_rule[0].name
  target_id                       = var.remediation_target_id != "" ? var.remediation_target_id : "placeholder-target"
  target_type                     = var.remediation_target_type != "" ? var.remediation_target_type : "SSM_DOCUMENT"
  automatic                       = var.remediation_automatic
  maximum_automatic_attempts      = var.remediation_max_automatic_attempts
  resource_type                   = var.remediation_resource_type != "" ? var.remediation_resource_type : null

  depends_on = [aws_config_config_rule.account_rule]
}

# Aggregate Authorization
resource "aws_config_aggregate_authorization" "cross_account" {
  count      = var.enable_aggregate_authorization ? 1 : 0
  account_id = var.aggregate_authorization_account_id != "" ? var.aggregate_authorization_account_id : "000000000000"
  region     = var.aggregate_authorization_region != "" ? var.aggregate_authorization_region : var.aws_region
  tags       = local.common_tags
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "bucket_name" {
  description = "Name of the S3 bucket (max 63 characters)"
  type        = string
  default     = "my-terraform-bucket"
  validation {
    condition     = length(var.bucket_name) <= 63
    error_message = "Bucket name must be 63 characters or fewer."
  }
}

variable "enable_logging" {
  description = "Enable access logging to a target bucket"
  type        = bool
  default     = false
}

variable "logging_target_bucket_name" {
  description = "Name of the logging target bucket"
  type        = string
  default     = null
}

variable "logging_prefix" {
  description = "Prefix for log objects in the target bucket"
  type        = string
  default     = "logs/"
}

variable "enable_request_payment" {
  description = "Enable Requester Pays"
  type        = bool
  default     = false
}

variable "cors_rules" {
  description = "List of CORS rules. Each rule is a map with keys: allowed_headers, allowed_methods, allowed_origins, expose_headers, max_age_seconds"
  type        = list(any)
  default     = []
}

variable "intelligent_tiering_configurations" {
  description = "List of intelligent tiering configurations. Each configuration is a map with keys: name, status, tierings (list of maps with access_tier and days)"
  type        = list(any)
  default     = []
}

variable "enable_replication" {
  description = "Enable replication configuration"
  type        = bool
  default     = false
}

variable "replication_destination_bucket_name" {
  description = "Name of the destination bucket for replication"
  type        = string
  default     = null
}

variable "replication_iam_role_name" {
  description = "Name of the IAM role for replication"
  type        = string
  default     = null
}

variable "replication_rules" {
  description = "List of replication rules. Each rule is a map with keys: status, priority, filter (map), delete_marker_replication_status, destination (map with account, bucket, storage_class, encryption_configuration, access_control_translation, metrics, replication_time)"
  type        = list(any)
  default     = []
}

variable "enable_inventory" {
  description = "Enable inventory configuration"
  type        = bool
  default     = false
}

variable "inventory_destination_bucket_name" {
  description = "Name of the destination bucket for inventory reports"
  type        = string
  default     = null
}

variable "inventory_configurations" {
  description = "List of inventory configurations. Each is a map with keys: name, included_object_versions, optional_fields, schedule_frequency, filter (map with prefix), destination (map with bucket_arn, format, prefix)"
  type        = list(any)
  default     = []
}

variable "bucket_policy" {
  description = "Custom bucket policy statement (JSON). If not provided, defaults to deny non-SSL requests."
  type        = string
  default     = null
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules. Each rule is a map with keys: id, status, filter (map with prefix, tags, object_size_greater_than, object_size_less_than), expiration (map with days, date, expired_object_delete_marker), transitions (list of maps with days, storage_class), noncurrent_version_expiration (map with noncurrent_days), noncurrent_version_transitions (list of maps with noncurrent_days, storage_class), abort_incomplete_multipart_upload (map with days_after_initiation)"
  type        = list(any)
  default     = []
}

variable "enable_notifications" {
  description = "Enable bucket notifications"
  type        = bool
  default     = false
}

variable "notification_lambda_functions" {
  description = "List of Lambda function notification configurations. Each is a map with keys: lambda_function_arn, events, filter_prefix, filter_suffix"
  type        = list(any)
  default     = []
}

variable "notification_sns_topics" {
  description = "List of SNS topic notification configurations. Each is a map with keys: topic_arn, events, filter_prefix, filter_suffix"
  type        = list(any)
  default     = []
}

variable "notification_sqs_queues" {
  description = "List of SQS queue notification configurations. Each is a map with keys: queue_arn, events, filter_prefix, filter_suffix"
  type        = list(any)
  default     = []
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Local values
locals {
  enable_logging                = var.enable_logging
  logging_target_bucket_name    = var.enable_logging ? (var.logging_target_bucket_name != null ? var.logging_target_bucket_name : "${var.bucket_name}-logs") : null
  logging_prefix                = var.logging_prefix
  enable_request_payment        = var.enable_request_payment
  cors_rules                    = var.cors_rules
  intelligent_tiering_confs     = var.intelligent_tiering_configurations
  enable_replication            = var.enable_replication
  replication_dest_bucket_name  = var.enable_replication ? (var.replication_destination_bucket_name != null ? var.replication_destination_bucket_name : "${var.bucket_name}-replica") : null
  replication_iam_role_name     = var.enable_replication ? (var.replication_iam_role_name != null ? var.replication_iam_role_name : "${var.bucket_name}-replication-role") : null
  replication_rules             = var.replication_rules
  enable_inventory              = var.enable_inventory
  inventory_dest_bucket_name    = var.enable_inventory ? (var.inventory_destination_bucket_name != null ? var.inventory_destination_bucket_name : "${var.bucket_name}-inventory") : null
  inventory_configs             = var.inventory_configurations
  bucket_policy                 = var.bucket_policy
  lifecycle_rules               = var.lifecycle_rules
  enable_notifications          = var.enable_notifications
  lambda_notifications          = var.notification_lambda_functions
  sns_notifications             = var.notification_sns_topics
  sqs_notifications             = var.notification_sqs_queues

  # Default deny non-SSL policy if no custom policy provided
  default_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSSL"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          "arn:aws:s3:::${var.bucket_name}",
          "arn:aws:s3:::${var.bucket_name}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# KMS Key for main bucket encryption
resource "aws_kms_key" "main" {
  description             = "KMS key for S3 bucket ${var.bucket_name} encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "main" {
  name          = "alias/${var.bucket_name}-s3-key"
  target_key_id = aws_kms_key.main.key_id
}

# KMS Key for replication destination (if separate key needed)
resource "aws_kms_key" "replication_dest" {
  count                 = local.enable_replication ? 1 : 0
  description           = "KMS key for replication destination bucket ${local.replication_dest_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation   = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replication_dest" {
  count    = local.enable_replication ? 1 : 0
  name     = "alias/${local.replication_dest_bucket_name}-s3-key"
  target_key_id = aws_kms_key.replication_dest[0].key_id
}

# Main S3 bucket
resource "aws_s3_bucket" "main" {
  bucket        = var.bucket_name
  force_destroy = false
  tags = {
    Name = var.bucket_name
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Logging target bucket (conditional)
resource "aws_s3_bucket" "logging" {
  count         = local.enable_logging ? 1 : 0
  bucket        = local.logging_target_bucket_name
  force_destroy = false
  tags = {
    Name = local.logging_target_bucket_name
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logging" {
  count  = local.enable_logging ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = local.enable_logging ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count                  = local.enable_logging ? 1 : 0
  bucket                 = aws_s3_bucket.logging[0].id
  block_public_acls      = true
  block_public_policy    = true
  ignore_public_acls     = true
  restrict_public_buckets = true
}

# Replication destination bucket (conditional)
resource "aws_s3_bucket" "replication_dest" {
  count         = local.enable_replication ? 1 : 0
  bucket        = local.replication_dest_bucket_name
  force_destroy = false
  tags = {
    Name = local.replication_dest_bucket_name
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replication_dest" {
  count  = local.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.replication_dest[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replication_dest" {
  count                  = local.enable_replication ? 1 : 0
  bucket                 = aws_s3_bucket.replication_dest[0].id
  block_public_acls      = true
  block_public_policy    = true
  ignore_public_acls     = true
  restrict_public_buckets = true
}

# Inventory destination bucket (conditional)
resource "aws_s3_bucket" "inventory_dest" {
  count         = local.enable_inventory ? 1 : 0
  bucket        = local.inventory_dest_bucket_name
  force_destroy = false
  tags = {
    Name = local.inventory_dest_bucket_name
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "inventory_dest" {
  count                  = local.enable_inventory ? 1 : 0
  bucket                 = aws_s3_bucket.inventory_dest[0].id
  block_public_acls      = true
  block_public_policy    = true
  ignore_public_acls     = true
  restrict_public_buckets = true
}

# Versioning on main bucket
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Server-side encryption on main bucket
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# Public access block on main bucket
resource "aws_s3_bucket_public_access_block" "main" {
  bucket                 = aws_s3_bucket.main.id
  block_public_acls      = true
  block_public_policy    = true
  ignore_public_acls     = true
  restrict_public_buckets = true
}

# Ownership controls (default)
resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# Request payment configuration (optional)
resource "aws_s3_bucket_request_payment_configuration" "main" {
  count  = local.enable_request_payment ? 1 : 0
  bucket = aws_s3_bucket.main.id
  payer  = "Requester"
}

# Logging configuration (optional)
resource "aws_s3_bucket_logging" "main" {
  count  = local.enable_logging ? 1 : 0
  bucket = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = local.logging_prefix
}

# CORS configuration (optional)
resource "aws_s3_bucket_cors_configuration" "main" {
  count  = length(local.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id
  dynamic "cors_rule" {
    for_each = local.cors_rules
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Intelligent tiering configurations (optional)
resource "aws_s3_bucket_intelligent_tiering_configuration" "main" {
  for_each = { for idx, conf in local.intelligent_tiering_confs : idx => conf }
  bucket   = aws_s3_bucket.main.id
  name     = each.value.name
  status   = try(each.value.status, "Enabled")
  dynamic "tiering" {
    for_each = try(each.value.tierings, [])
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

# Replication IAM role
resource "aws_iam_role" "replication" {
  count = local.enable_replication ? 1 : 0
  name  = local.replication_iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  count = local.enable_replication ? 1 : 0
  name  = "${local.replication_iam_role_name}-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.main.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = "${aws_s3_bucket.replication_dest[0].arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.main.arn
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt"
        ]
        Resource = aws_kms_key.replication_dest[0].arn
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = local.enable_replication ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# Replication configuration (conditional)
resource "aws_s3_bucket_replication_configuration" "main" {
  count   = local.enable_replication ? 1 : 0
  bucket  = aws_s3_bucket.main.id
  role    = aws_iam_role.replication[0].arn
  dynamic "rule" {
    for_each = local.replication_rules
    content {
      id            = try(rule.value.id, null)
      status        = rule.value.status
      priority      = try(rule.value.priority, null)
      filter {
        prefix = try(rule.value.filter.prefix, null)
        dynamic "tag" {
          for_each = try(rule.value.filter.tags, {})
          content {
            key   = tag.key
            value = tag.value
          }
        }
      }
      delete_marker_replication {
        status = try(rule.value.delete_marker_replication_status, null)
      }
      destination {
        account  = try(rule.value.destination.account, null)
        bucket   = "arn:aws:s3:::${aws_s3_bucket.replication_dest[0].bucket}"
        storage_class = try(rule.value.destination.storage_class, null)
        encryption_configuration {
          replica_kms_key_id = aws_kms_key.replication_dest[0].arn
        }
        access_control_translation {
          owner = try(rule.value.destination.access_control_translation.owner, null)
        }
        metrics {
          status  = try(rule.value.destination.metrics.status, null)
          event_threshold {
            minutes = try(rule.value.destination.metrics.event_threshold.minutes, null)
          }
        }
        replication_time {
          status = try(rule.value.destination.replication_time.status, null)
          time {
            minutes = try(rule.value.destination.replication_time.time.minutes, null)
          }
        }
      }
    }
  }
}

# Inventory configuration (conditional)
resource "aws_s3_bucket_inventory" "main" {
  for_each = { for idx, conf in local.inventory_configs : idx => conf }
  bucket   = aws_s3_bucket.main.id
  name     = each.value.name
  included_object_versions = try(each.value.included_object_versions, "All")
  optional_fields          = try(each.value.optional_fields, null)
  schedule {
    frequency = each.value.schedule_frequency
  }
  filter {
    prefix = try(each.value.filter.prefix, null)
  }
  destination {
    bucket {
      format  = each.value.destination.format
      bucket_arn = "arn:aws:s3:::${aws_s3_bucket.inventory_dest[0].bucket}"
      prefix  = try(each.value.destination.prefix, null)
    }
  }
}

# Bucket policy (custom or default deny non-SSL)
resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = local.bucket_policy != null ? local.bucket_policy : local.default_policy
}

# Lifecycle rules (optional) - only created if at least one rule provided
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count  = length(local.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id
  dynamic "rule" {
    for_each = local.lifecycle_rules
    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.status, "Enabled")
      filter {
        prefix                   = try(rule.value.filter.prefix, null)
        object_size_greater_than = try(rule.value.filter.object_size_greater_than, null)
        object_size_less_than    = try(rule.value.filter.object_size_less_than, null)
        dynamic "tag" {
          for_each = try(rule.value.filter.tags, {})
          content {
            key   = tag.key
            value = tag.value
          }
        }
      }
      expiration {
        days                         = try(rule.value.expiration.days, null)
        date                         = try(rule.value.expiration.date, null)
        expired_object_delete_marker = try(rule.value.expiration.expired_object_delete_marker, null)
      }
      dynamic "transition" {
        for_each = try(rule.value.transitions, [])
        content {
          days          = try(transition.value.days, null)
          storage_class = try(transition.value.storage_class, null)
        }
      }
      noncurrent_version_expiration {
        noncurrent_days = try(rule.value.noncurrent_version_expiration.noncurrent_days, null)
      }
      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])
        content {
          noncurrent_days = try(noncurrent_version_transition.value.noncurrent_days, null)
          storage_class   = try(noncurrent_version_transition.value.storage_class, null)
        }
      }
      abort_incomplete_multipart_upload {
        days_after_initiation = try(rule.value.abort_incomplete_multipart_upload.days_after_initiation, null)
      }
    }
  }
}

# Notifications: Lambda functions, SNS topics, SQS queues (conditional)
resource "aws_s3_bucket_notification" "main" {
  count  = local.enable_notifications ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "lambda_function" {
    for_each = local.lambda_notifications
    content {
      lambda_function_arn = lambda_function.value.lambda_function_arn
      events              = lambda_function.value.events
      filter_prefix       = try(lambda_function.value.filter_prefix, null)
      filter_suffix       = try(lambda_function.value.filter_suffix, null)
    }
  }

  dynamic "topic" {
    for_each = local.sns_notifications
    content {
      topic_arn     = topic.value.topic_arn
      events        = topic.value.events
      filter_prefix = try(topic.value.filter_prefix, null)
      filter_suffix = try(topic.value.filter_suffix, null)
    }
  }

  dynamic "queue" {
    for_each = local.sqs_notifications
    content {
      queue_arn     = queue.value.queue_arn
      events        = queue.value.events
      filter_prefix = try(queue.value.filter_prefix, null)
      filter_suffix = try(queue.value.filter_suffix, null)
    }
  }
}

# Outputs
output "bucket" {
  description = "The main S3 bucket resource"
  value       = aws_s3_bucket.main
}

output "public_access_block" {
  description = "The public access block configuration for the main bucket"
  value       = aws_s3_bucket_public_access_block.main
}

output "notification" {
  description = "The S3 bucket notification configuration (if created)"
  value       = local.enable_notifications ? aws_s3_bucket_notification.main[0] : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ========== Provider configuration for LocalStack ==========
provider "aws" {
  region                      = "us-east-1"
  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_requesting_account_id  = true
  s3_use_path_style           = true

  endpoints {
    s3 = "http://localhost:4566"
  }
}

# ---------- Variables ----------
variable "bucket_prefix" {
  description = "Base name for all S3 buckets"
  type        = string
  default     = "sadcloud"
}

variable "disable_encryption" {
  description = "When true, disable SSE256 on the primary bucket"
  type        = bool
  default     = false
}

variable "disable_versioning" {
  description = "When true, suspend versioning on the primary bucket"
  type        = bool
  default     = false
}

variable "enable_logging" {
  description = "When true, create a log delivery bucket and enable S3 server access logging on the primary bucket"
  type        = bool
  default     = false
}

variable "enable_website" {
  description = "When true, enable static website hosting on the primary bucket"
  type        = bool
  default     = false
}

variable "allow_cleartext" {
  description = "When true, attach a bucket policy to the primary bucket that denies non‑TLS access"
  type        = bool
  default     = false
}

variable "create_publicly_readable_bucket" {
  description = "When true, create a bucket that allows public GetObject"
  type        = bool
  default     = false
}

variable "create_fully_public_bucket" {
  description = "When true, create a bucket that allows all S3 actions to any principal"
  type        = bool
  default     = false
}

# ---------- Local values ----------
locals {
  primary_bucket_name = var.bucket_prefix
  logging_bucket_name = "${var.bucket_prefix}-logs"
  public_read_name    = "${var.bucket_prefix}-public-read"
  public_full_name    = "${var.bucket_prefix}-public-full"
}

# ========== KMS key for S3 encryption ==========
resource "aws_kms_key" "s3_encryption_key" {
  description             = "S3 encryption key for primary bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

# ========== Primary bucket ==========
resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  count = var.disable_encryption ? 0 : 1

  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_encryption_key.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = var.disable_versioning ? "Suspended" : "Enabled"
  }
}

resource "aws_s3_bucket_website_configuration" "primary" {
  count = var.enable_website ? 1 : 0

  bucket = aws_s3_bucket.primary.id

  index_document {
    suffix = "index.html"
  }
  error_document {
    key = "error.html"
  }
}

# Logging – optional: creates a separate logging bucket with a bucket policy for log delivery
resource "aws_s3_bucket" "logging" {
  count = var.enable_logging ? 1 : 0

  bucket = local.logging_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.enable_logging ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "logging" {
  count = var.enable_logging ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3LogDeliveryWrite"
        Effect = "Allow"
        Principal = {
          AWS = "http://acs.amazonaws.com/groups/s3/LogDelivery"
        }
        Action = [
          "s3:PutObject"
        ]
        Resource = [
          "${aws_s3_bucket.logging[0].arn}/*",
          aws_s3_bucket.logging[0].arn
        ]
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "primary" {
  count = var.enable_logging ? 1 : 0

  bucket = aws_s3_bucket.primary.id

  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "log/"
}

# Cleartext policy – denies all actions when SecureTransport is false
resource "aws_s3_bucket_policy" "cleartext_deny" {
  count = var.allow_cleartext ? 1 : 0

  bucket = aws_s3_bucket.primary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonTLS"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# ========== Publicly readable bucket ==========
resource "aws_s3_bucket" "public_read" {
  count = var.create_publicly_readable_bucket ? 1 : 0

  bucket = local.public_read_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "public_read" {
  count = var.create_publicly_readable_bucket ? 1 : 0

  bucket = aws_s3_bucket.public_read[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "public_read" {
  count = var.create_publicly_readable_bucket ? 1 : 0

  bucket = aws_s3_bucket.public_read[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.public_read[0].arn}/*"
      }
    ]
  })
}

# ========== Fully public bucket ==========
resource "aws_s3_bucket" "public_full" {
  count = var.create_fully_public_bucket ? 1 : 0

  bucket = local.public_full_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "public_full" {
  count = var.create_fully_public_bucket ? 1 : 0

  bucket = aws_s3_bucket.public_full[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "public_full" {
  count = var.create_fully_public_bucket ? 1 : 0

  bucket = aws_s3_bucket.public_full[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicFullAccess"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public_full[0].arn,
          "${aws_s3_bucket.public_full[0].arn}/*"
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

data "aws_prefix_list" "s3" {
  name = "com.amazonaws.us-east-1.s3"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.10.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "web_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.10.100.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "web-a"
  }
}

resource "aws_subnet" "web_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.10.101.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "web-b"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route" "default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "web_a" {
  subnet_id      = aws_subnet.web_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "web_b" {
  subnet_id      = aws_subnet.web_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.us-east-1.s3"
  route_table_ids = [aws_route_table.public.id]
}

resource "aws_security_group" "web_sg" {
  name        = "web-sg"
  description = "Allow HTTP inbound, egress via S3 endpoint and VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    prefix_list_ids = [data.aws_prefix_list.s3.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "web-sg"
  }
}

resource "aws_instance" "web_server" {
  ami                         = data.aws_ami.amazon_linux.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.web_a.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.web_sg.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_size = 8
  }

  user_data = <<-EOF
              #!/bin/bash
              yum update -y
              yum install -y busybox
              mkdir -p /var/www/html
              cat > /var/www/html/index.html <<-EOHTML
              <html>
              <body>
              <h1>Test Web Server</h1>
              <p>Availability Zone ID: $(curl -s http://169.254.169.254/latest/meta-data/placement/availability-zone-id)</p>
              <p>Instance ID: $(curl -s http://169.254.169.254/latest/meta-data/instance-id)</p>
              <p>Private IP: $(curl -s http://169.254.169.254/latest/meta-data/local-ipv4)</p>
              </body>
              </html>
              EOHTML
              busybox httpd -p 80 -h /var/www/html
              EOF

  tags = {
    Name = "web-server"
  }
}

output "public_ip" {
  value = aws_instance.web_server.public_ip
}

terraform {
  required_version = "~> 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

variable "tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default = {
    Project     = "NLP Pipeline"
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ----------------------------------------------------------------------
# KMS Key for S3 Encryption
# ----------------------------------------------------------------------
resource "aws_kms_key" "s3_encryption" {
  description             = "CMK for S3 encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags
}

resource "aws_kms_alias" "s3_encryption_alias" {
  name          = "alias/nlp-pipeline-s3-encryption"
  target_key_id = aws_kms_key.s3_encryption.key_id
}

# ----------------------------------------------------------------------
# NLP Pipeline S3 Bucket
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "nlp_pipeline_bucket" {
  bucket        = "nlp-pipeline-bucket"
  force_destroy = false
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "nlp_pipeline_bucket_pab" {
  bucket                  = aws_s3_bucket.nlp_pipeline_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "nlp_pipeline_bucket_sse" {
  bucket = aws_s3_bucket.nlp_pipeline_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_encryption.arn
    }
  }

  depends_on = [aws_kms_key.s3_encryption]
}

resource "aws_s3_bucket_versioning" "nlp_pipeline_bucket_versioning" {
  bucket = aws_s3_bucket.nlp_pipeline_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ----------------------------------------------------------------------
# NLP Results DynamoDB Table
# ----------------------------------------------------------------------
resource "aws_dynamodb_table" "nlp_results" {
  name         = "NLPResults"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "ResultId"

  attribute {
    name = "ResultId"
    type = "S"
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# Terraform State S3 Bucket
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "terraform_state_bucket" {
  bucket        = "my-terraform-state-bucket"
  force_destroy = false
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state_bucket_pab" {
  bucket                  = aws_s3_bucket.terraform_state_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state_bucket_sse" {
  bucket = aws_s3_bucket.terraform_state_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_encryption.arn
    }
  }

  depends_on = [aws_kms_key.s3_encryption]
}

resource "aws_s3_bucket_versioning" "terraform_state_bucket_versioning" {
  bucket = aws_s3_bucket.terraform_state_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ----------------------------------------------------------------------
# Terraform State Lock DynamoDB Table
# ----------------------------------------------------------------------
resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# Lambda IAM Role and Policy
# ----------------------------------------------------------------------
resource "aws_iam_role" "lambda_exec_role" {
  name = "lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "lambda_policy" {
  name = "lambda-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "S3Access"
        Effect   = "Allow"
        Action   = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::nlp-pipeline-bucket",
          "arn:aws:s3:::nlp-pipeline-bucket/*"
        ]
      },
      {
        Sid      = "KMSAccess"
        Effect   = "Allow"
        Action   = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.s3_encryption.arn
      },
      {
        Sid      = "DynamoDBAccess"
        Effect   = "Allow"
        Action   = [
          "dynamodb:PutItem",
          "dynamodb:GetItem",
          "dynamodb:Query",
          "dynamodb:UpdateItem"
        ]
        Resource = "arn:aws:dynamodb:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:table/NLPResults"
      },
      {
        Sid      = "ComprehendAccess"
        Effect   = "Allow"
        Action   = [
          "comprehend:DetectEntities",
          "comprehend:DetectSentiment",
          "comprehend:DetectKeyPhrases"
        ]
        Resource = "*"
      },
      {
        Sid      = "CloudWatchLogsAccess"
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/nlp_processor:*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "lambda_attach" {
  role       = aws_iam_role.lambda_exec_role.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/nlp_processor"
  retention_in_days = 14
  tags              = var.tags
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/lambda_function.zip"

  source {
    content = <<PYTHON
import json

def lambda_handler(event, context):
    print("Processing event:", json.dumps(event))
    return {
        "statusCode": 200,
        "body": json.dumps("NLP processing completed")
    }
PYTHON
    filename = "index.py"
  }
}

resource "aws_lambda_function" "nlp_processor" {
  function_name    = "nlp_processor"
  role             = aws_iam_role.lambda_exec_role.arn
  handler          = "index.lambda_handler"
  runtime          = "python3.12"
  timeout          = 60
  memory_size      = 128
  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256

  depends_on = [
    aws_cloudwatch_log_group.lambda_logs
  ]

  tags = var.tags
}

# ----------------------------------------------------------------------
# Glue IAM Role and Policy
# ----------------------------------------------------------------------
resource "aws_iam_role" "glue_role" {
  name = "glue-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "glue_policy" {
  name = "glue-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "S3Access"
        Effect   = "Allow"
        Action   = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::nlp-pipeline-bucket",
          "arn:aws:s3:::nlp-pipeline-bucket/*"
        ]
      },
      {
        Sid      = "KMSAccess"
        Effect   = "Allow"
        Action   = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.s3_encryption.arn
      },
      {
        Sid      = "DynamoDBAccess"
        Effect   = "Allow"
        Action   = [
          "dynamodb:PutItem",
          "dynamodb:GetItem",
          "dynamodb:Query",
          "dynamodb:UpdateItem"
        ]
        Resource = "arn:aws:dynamodb:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:table/NLPResults"
      },
      {
        Sid      = "ComprehendAccess"
        Effect   = "Allow"
        Action   = [
          "comprehend:DetectEntities",
          "comprehend:DetectSentiment",
          "comprehend:DetectKeyPhrases"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "glue_attach" {
  role       = aws_iam_role.glue_role.name
  policy_arn = aws_iam_policy.glue_policy.arn
}

resource "aws_glue_job" "nlp_glue_job" {
  name     = "nlp_glue_job"
  role_arn = aws_iam_role.glue_role.arn

  command {
    script_location = "s3://nlp-pipeline-bucket/scripts/glue_job.py"
    python_version  = "3"
  }

  max_retries       = 0
  worker_type       = "Standard"
  number_of_workers = 2
  timeout           = 60
  tags              = var.tags
}

# ----------------------------------------------------------------------
# Step Functions IAM Role and Policy
# ----------------------------------------------------------------------
resource "aws_iam_role" "step_functions_role" {
  name = "step-functions-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "step_functions_policy" {
  name = "step-functions-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "InvokeLambda"
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:nlp_processor"
      },
      {
        Sid      = "StartGlueJob"
        Effect   = "Allow"
        Action   = "glue:StartJobRun"
        Resource = "arn:aws:glue:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:job/nlp_glue_job"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "step_functions_attach" {
  role       = aws_iam_role.step_functions_role.name
  policy_arn = aws_iam_policy.step_functions_policy.arn
}

resource "aws_sfn_state_machine" "nlp_pipeline" {
  name     = "nlp-pipeline"
  role_arn = aws_iam_role.step_functions_role.arn

  definition = jsonencode({
    Comment = "NLP Pipeline State Machine"
    StartAt = "ProcessNLP"
    States = {
      ProcessNLP = {
        Type     = "Task"
        Resource = "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:nlp_processor"
        Next     = "RunGlueJob"
        Catch = [
          {
            ErrorEquals = ["States.ALL"]
            Next        = "Fail"
          }
        ]
      },
      RunGlueJob = {
        Type       = "Task"
        Resource   = "arn:aws:states:::glue:startJobRun"
        Parameters = {
          JobName = "nlp_glue_job"
        }
        End = true
        Catch = [
          {
            ErrorEquals = ["States.ALL"]
            Next        = "Fail"
          }
        ]
      },
      Fail = {
        Type  = "Fail"
        Error = "NLPProcessingFailed"
        Cause = "NLP pipeline failed"
      }
    }
  })

  tags = var.tags
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Variables
variable "bucket_name" {
  type        = string
  default     = "my-secure-bucket"
  description = "Name of the S3 bucket"
}

variable "encryption_type" {
  type        = string
  default     = "AES256"
  description = "Either 'AES256' or a KMS key ARN for default encryption"
}

variable "cors_rules" {
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default     = []
  description = "CORS rules for the bucket"
}

variable "lifecycle_rules" {
  type = list(object({
    id     = string
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    status = string
    transition = optional(list(object({
      days          = number
      storage_class = string
    })))
    expiration = optional(object({
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
    noncurrent_version_transition = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default     = []
  description = "Lifecycle rules for the bucket"
}

variable "inventory_config" {
  type = object({
    destination_bucket       = string
    schedule                 = string
    optional_fields          = optional(list(string))
    included_object_versions = optional(string, "All")
  })
  default     = null
  description = "Inventory configuration for the bucket"
}

variable "object_lock_config" {
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default     = null
  description = "Object lock configuration (mode, days/years)"
}

variable "replication_config" {
  type = object({
    destination_bucket = string
    kms_key_arn        = optional(string)
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(bool)
      filter = optional(object({
        prefix = optional(string)
        tags   = optional(map(string))
      }))
    }))
  })
  default     = null
  description = "Replication configuration"
}

variable "logging_target_bucket" {
  type        = string
  default     = null
  description = "Target bucket for server access logs (name or ARN)"
}

variable "event_bridge_notifications_enabled" {
  type        = bool
  default     = false
  description = "Enable Amazon EventBridge notifications"
}

variable "custom_bucket_policy" {
  type        = string
  default     = null
  description = "Custom bucket policy (JSON string) to override default HTTPS enforcement"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags to apply to resources"
}

# Locals
locals {
  bucket_arn = "arn:aws:s3:::${var.bucket_name}"

  logging_target_is_name   = var.logging_target_bucket != null && !startswith(var.logging_target_bucket, "arn:")
  inventory_dest_is_name   = var.inventory_config != null && !startswith(var.inventory_config.destination_bucket, "arn:")
  replication_dest_is_name = var.replication_config != null && !startswith(var.replication_config.destination_bucket, "arn:")

  enable_versioning = (var.object_lock_config != null || var.replication_config != null)

  use_kms = startswith(var.encryption_type, "arn:aws:kms:")
}

# Source bucket
resource "aws_s3_bucket" "main" {
  bucket = var.bucket_name
  force_destroy = false
  object_lock_enabled = var.object_lock_config != null ? true : false
  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Versioning for source bucket (enabled only when needed)
resource "aws_s3_bucket_versioning" "main" {
  count  = local.enable_versioning ? 1 : 0
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Default encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.use_kms ? "aws:kms" : "AES256"
      kms_master_key_id = local.use_kms ? var.encryption_type : null
    }
  }
}

# Block public access
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Default bucket policy to enforce secure transport (unless custom policy provided)
resource "aws_s3_bucket_policy" "https_only" {
  count  = var.custom_bucket_policy == null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DenyInsecureTransport"
        Effect = "Deny"
        Principal = "*"
        Action = "s3:*"
        Resource = [
          local.bucket_arn,
          "${local.bucket_arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Optionally apply custom bucket policy (overrides default HTTPS policy)
resource "aws_s3_bucket_policy" "custom" {
  count  = var.custom_bucket_policy != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  policy = var.custom_bucket_policy
}

# CORS configuration
resource "aws_s3_bucket_cors_configuration" "main" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Lifecycle configuration
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status
      filter {
        prefix = try(rule.value.filter.prefix, null)
        dynamic "tag" {
          for_each = try(rule.value.filter.tags, {})
          content {
            key   = tag.key
            value = tag.value
          }
        }
      }
      dynamic "transition" {
        for_each = try(rule.value.transition, [])
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }
      expiration {
        days                         = try(rule.value.expiration.days, null)
        expired_object_delete_marker = try(rule.value.expiration.expired_object_delete_marker, null)
      }
      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, [])
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }
      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transition, [])
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, [])
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

# Object lock configuration
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count  = var.object_lock_config != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  rule {
    default_retention {
      mode  = var.object_lock_config.mode
      days  = var.object_lock_config.days
      years = var.object_lock_config.years
    }
  }
}

# Logging target bucket (if provided and not an ARN)
resource "aws_s3_bucket" "logging_target" {
  count = local.logging_target_is_name ? 1 : 0
  bucket = var.logging_target_bucket
  force_destroy = false
  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging_target" {
  count = local.logging_target_is_name ? 1 : 0
  bucket = aws_s3_bucket.logging_target[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logging_target" {
  count = local.logging_target_is_name ? 1 : 0
  bucket = aws_s3_bucket.logging_target[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Policy on logging target to allow source bucket to write logs
resource "aws_s3_bucket_policy" "logging_target" {
  count  = local.logging_target_is_name ? 1 : 0
  bucket = aws_s3_bucket.logging_target[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLogsWrite"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = "s3:PutObject"
        Resource = "arn:aws:s3:::${var.logging_target_bucket}/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = local.bucket_arn
          }
        }
      }
    ]
  })
}

# Logging configuration on source bucket
resource "aws_s3_bucket_logging" "main" {
  count  = var.logging_target_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.main.id

  target_bucket = local.logging_target_is_name ? aws_s3_bucket.logging_target[0].id : var.logging_target_bucket
  target_prefix = "logs/"
}

# Inventory destination bucket (if provided and not an ARN)
resource "aws_s3_bucket" "inventory_dest" {
  count = local.inventory_dest_is_name ? 1 : 0
  bucket = var.inventory_config.destination_bucket
  force_destroy = false
  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "inventory_dest" {
  count  = local.inventory_dest_is_name ? 1 : 0
  bucket = aws_s3_bucket.inventory_dest[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "inventory_dest" {
  count = local.inventory_dest_is_name ? 1 : 0
  bucket = aws_s3_bucket.inventory_dest[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "inventory_dest" {
  count = local.inventory_dest_is_name ? 1 : 0
  bucket = aws_s3_bucket.inventory_dest[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Policy on inventory destination to allow S3 to write inventory reports
resource "aws_s3_bucket_policy" "inventory_dest" {
  count  = local.inventory_dest_is_name ? 1 : 0
  bucket = aws_s3_bucket.inventory_dest[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "InventoryPermissions"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "s3:PutObject"
        Resource = "arn:aws:s3:::${var.inventory_config.destination_bucket}/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = local.bucket_arn
          }
        }
      }
    ]
  })
}

# Inventory configuration on source bucket
resource "aws_s3_bucket_inventory" "main" {
  count  = var.inventory_config != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  name   = "InventoryConfiguration"

  included_object_versions = var.inventory_config.included_object_versions
  optional_fields          = var.inventory_config.optional_fields

  schedule {
    frequency = var.inventory_config.schedule
  }

  destination {
    bucket {
      format    = "ORC"
      bucket_arn = local.inventory_dest_is_name ? aws_s3_bucket.inventory_dest[0].arn : var.inventory_config.destination_bucket
      prefix    = "inventory/"
    }
  }
}

# Replication destination bucket (if provided and not an ARN)
resource "aws_s3_bucket" "replication_dest" {
  count = local.replication_dest_is_name ? 1 : 0
  bucket = var.replication_config.destination_bucket
  force_destroy = false
  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replication_dest" {
  count  = local.replication_dest_is_name ? 1 : 0
  bucket = aws_s3_bucket.replication_dest[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replication_dest" {
  count = local.replication_dest_is_name ? 1 : 0
  bucket = aws_s3_bucket.replication_dest[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replication_dest" {
  count = local.replication_dest_is_name ? 1 : 0
  bucket = aws_s3_bucket.replication_dest[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Policy on replication destination bucket to allow replication from source
resource "aws_s3_bucket_policy" "replication_dest" {
  count  = local.replication_dest_is_name ? 1 : 0
  bucket = aws_s3_bucket.replication_dest[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReplicationPermissions"
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.account_id
        }
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = "arn:aws:s3:::${var.replication_config.destination_bucket}/*"
      }
    ]
  })
}

# IAM role for replication
resource "aws_iam_role" "replication" {
  count = var.replication_config != null ? 1 : 0
  name  = "${var.bucket_name}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ReplicationAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = local.bucket_arn
          }
        }
      }
    ]
  })
}

# IAM policy for replication permissions
resource "aws_iam_policy" "replication" {
  count = var.replication_config != null ? 1 : 0
  name  = "${var.bucket_name}-replication-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = local.bucket_arn
      },
      {
        Sid    = "SourceObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${local.bucket_arn}/*"
      },
      {
        Sid    = "DestinationBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = "arn:aws:s3:::${var.replication_config.destination_bucket}/*"
      }
    ]
  })
}

# Attach policy to role
resource "aws_iam_role_policy_attachment" "replication" {
  count = var.replication_config != null ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# Replication configuration on source bucket
resource "aws_s3_bucket_replication_configuration" "main" {
  count  = var.replication_config != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "ReplicationRule"
    status = "Enabled"

    destination {
      bucket        = local.replication_dest_is_name ? aws_s3_bucket.replication_dest[0].arn : var.replication_config.destination_bucket
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = var.replication_config.kms_key_arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = try(var.replication_config.source_selection_criteria.sse_kms_encrypted_objects, false) ? "Enabled" : "Disabled"
      }
    }

    filter {
      prefix = try(var.replication_config.source_selection_criteria.filter.prefix, "")
      dynamic "tag" {
        for_each = try(var.replication_config.source_selection_criteria.filter.tags, {})
        content {
          key   = tag.key
          value = tag.value
        }
      }
    }
  }
}

# EventBridge notifications
resource "aws_s3_bucket_notification" "eventbridge" {
  count  = var.event_bridge_notifications_enabled ? 1 : 0
  bucket = aws_s3_bucket.main.id

  eventbridge = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "admin_enabled" {
  description = "Toggle creation of the admin IAM role"
  type        = bool
  default     = true
}

variable "poweruser_enabled" {
  description = "Toggle creation of the poweruser IAM role"
  type        = bool
  default     = true
}

variable "readonly_enabled" {
  description = "Toggle creation of the readonly IAM role"
  type        = bool
  default     = true
}

variable "admin_mfa_enabled" {
  description = "Enforce MFA for the admin role assumption"
  type        = bool
  default     = false
}

variable "poweruser_mfa_enabled" {
  description = "Enforce MFA for the poweruser role assumption"
  type        = bool
  default     = false
}

variable "readonly_mfa_enabled" {
  description = "Enforce MFA for the readonly role assumption"
  type        = bool
  default     = false
}

variable "mfa_age_limit" {
  description = "Maximum age in seconds for an MFA token when MFA is required (default 24 hours)"
  type        = number
  default     = 86400
}

variable "allowed_principal_arns" {
  description = "List of AWS principal ARNs allowed to assume any created role"
  type        = list(string)
  default     = []
}

variable "allowed_service_principals" {
  description = "List of AWS service principals allowed to assume any created role"
  type        = list(string)
  default     = []
}

# ---------------------------------------------------------------------------
# Data sources - static provider metadata
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Locals – role definitions filtered by enabled toggle
# ---------------------------------------------------------------------------
locals {
  role_definitions = {
    admin = {
      enabled     = var.admin_enabled
      mfa_enabled = var.admin_mfa_enabled
      policy_arn  = "arn:aws:iam::aws:policy/AdministratorAccess"
    }
    poweruser = {
      enabled     = var.poweruser_enabled
      mfa_enabled = var.poweruser_mfa_enabled
      policy_arn  = "arn:aws:iam::aws:policy/PowerUserAccess"
    }
    readonly = {
      enabled     = var.readonly_enabled
      mfa_enabled = var.readonly_mfa_enabled
      policy_arn  = "arn:aws:iam::aws:policy/ReadOnlyAccess"
    }
  }

  # Only roles whose toggle is true will be created
  filtered_roles = {
    for k, v in local.role_definitions : k => v if v.enabled
  }

  # Build the assume-role policy for each enabled role
  role_assume_policy = {
    for k, v in local.filtered_roles : k => {
      Version = "2012-10-17"
      Statement = [
        merge(
          {
            Effect = "Allow"
            Principal = {
              AWS = concat(
                var.allowed_principal_arns,
                ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${k}"]
              )
              Service = var.allowed_service_principals
            }
            Action = "sts:AssumeRole"
          },
          v.mfa_enabled ? {
            Condition = {
              Bool = {
                "aws:MultiFactorAuthPresent" = "true"
              }
              NumericLessThanEquals = {
                "aws:MultiFactorAuthAge" = var.mfa_age_limit
              }
            }
          } : {}
        )
      ]
    }
  }
}

# ---------------------------------------------------------------------------
# IAM Role resources
# ---------------------------------------------------------------------------
resource "aws_iam_role" "this" {
  for_each           = local.filtered_roles
  name               = each.key
  path               = "/"
  assume_role_policy = jsonencode(local.role_assume_policy[each.key])
}

# ---------------------------------------------------------------------------
# Managed policy data sources
# ---------------------------------------------------------------------------
data "aws_iam_policy" "this" {
  for_each = local.filtered_roles
  arn      = each.value.policy_arn
}

# ---------------------------------------------------------------------------
# Policy attachements
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "this" {
  for_each   = local.filtered_roles
  role       = aws_iam_role.this[each.key].name
  policy_arn = data.aws_iam_policy.this[each.key].arn
}

# ---------------------------------------------------------------------------
# Outputs – map of created role details
# ---------------------------------------------------------------------------
output "roles" {
  description = "Details of each created IAM role"
  value = {
    for k, role in aws_iam_role.this : k => {
      arn          = role.arn
      name         = role.name
      path         = role.path
      unique_id    = role.unique_id
      mfa_required = local.role_definitions[k].mfa_enabled
    }
  }
}

# Terraform required providers
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Provider configurations
provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "uswest2"
  region = "us-west-2"
}

provider "aws" {
  alias  = "euw1"
  region = "eu-west-1"
}

provider "aws" {
  alias  = "apse1"
  region = "ap-southeast-1"
}

# Variables
variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "dev"
}

variable "bucket_name_prefix" {
  description = "Prefix for bucket names"
  type        = string
  default     = "test"
}

# Local values
locals {
  tags = {
    Environment = var.environment
  }
  # Source bucket names (all start with prefix)
  src1 = "${var.bucket_name_prefix}-src-1"
  src2 = "${var.bucket_name_prefix}-src-2"
  src3 = "${var.bucket_name_prefix}-src-3"
  src4 = "${var.bucket_name_prefix}-src-4"
  # Destination suffixes
  suffix_eu = "-replica-eu"
  suffix_ap = "-replica-ap"
}

# -------------------------------------------------------------------
# KMS keys per region (one per region hosting buckets)
# -------------------------------------------------------------------

# us-east-1 (source region)
resource "aws_kms_key" "key_use1" {
  description             = "KMS key for S3 SSE in us-east-1"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.tags
}

resource "aws_kms_alias" "alias_use1" {
  name          = "alias/s3-sse-key-use1"
  target_key_id = aws_kms_key.key_use1.key_id
}

# us-west-2 (source region)
resource "aws_kms_key" "key_usw2" {
  provider                = aws.uswest2
  description             = "KMS key for S3 SSE in us-west-2"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.tags
}

