# -------------------------------------------------------------------
# IAM Role and Policy for Replication
# -------------------------------------------------------------------

resource "aws_iam_role" "replication_role" {
  name               = "s3-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
  tags = local.tags
}

resource "aws_iam_role_policy" "replication_policy" {
  name   = "s3-replication-policy"
  role   = aws_iam_role.replication_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourcePermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = [
          aws_s3_bucket.src1.arn,
          aws_s3_bucket.src2.arn,
          aws_s3_bucket.src3.arn,
          aws_s3_bucket.src4.arn
        ]
      },
      {
        Sid    = "DestinationPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          aws_s3_bucket.src1_replica_eu.arn,
          aws_s3_bucket.src1_replica_ap.arn,
          aws_s3_bucket.src2_replica_eu.arn,
          aws_s3_bucket.src2_replica_ap.arn,
          aws_s3_bucket.src3_replica_eu.arn,
          aws_s3_bucket.src3_replica_ap.arn,
          aws_s3_bucket.src4_replica_eu.arn,
          aws_s3_bucket.src4_replica_ap.arn
        ]
      },
      {
        Sid    = "KMSDecryptSource"
        Effect = "Allow"
        Action = "kms:Decrypt"
        Resource = [
          aws_kms_key.key_use1.arn,
          aws_kms_key.key_usw2.arn
        ]
      },
      {
        Sid    = "KMSEncryptDestination"
        Effect = "Allow"
        Action = "kms:Encrypt"
        Resource = [
          aws_kms_key.key_euw1.arn,
          aws_kms_key.key_apse1.arn
        ]
      }
    ]
  })
}

# -------------------------------------------------------------------
# Replication Configuration for each source bucket
# -------------------------------------------------------------------

# src1 replication (us-east-1)
resource "aws_s3_bucket_replication_configuration" "src1_replication" {
  bucket   = aws_s3_bucket.src1.id
  role     = aws_iam_role.replication_role.arn
  # Rule: replicate to eu-west-1
  rule {
    id     = "replicate-to-eu-west-1"
    status = "Enabled"
    destination {
      bucket        = aws_s3_bucket.src1_replica_eu.arn
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.key_euw1.arn
      }
    }
    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
  # Rule: replicate to ap-southeast-1
  rule {
    id     = "replicate-to-ap-southeast-1"
    status = "Enabled"
    destination {
      bucket        = aws_s3_bucket.src1_replica_ap.arn
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.key_apse1.arn
      }
    }
    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0.0"
    }
  }
}

variable "aws_profile" {
  description = "AWS CLI profile to use"
  type        = string
  default     = "default"
}

variable "custom_bucket_name" {
  description = "Fully custom bucket name for the primary state bucket; if empty, a random name is generated"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Map of tags to apply to all resources"
  type        = map(string)
  default     = {}
}

provider "aws" {
  region  = "us-east-1"
  profile = var.aws_profile
}

locals {
  state_bucket_name   = var.custom_bucket_name != "" ? var.custom_bucket_name : "${random_pet.pet.id}-tf-backend"
  logging_bucket_name = "${random_pet.pet.id}-tf-backend-logs"
}

data "aws_caller_identity" "current" {}

resource "random_pet" "pet" {
  length = 2
}

resource "aws_kms_key" "main" {
  description             = "KMS key for Terraform state backend encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable Root Account Access"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
  tags = var.tags
}

# ----------------------------------------------------------------------
# Primary state S3 bucket
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket_name
  tags   = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket                  = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonTLSRequests"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "abort_incomplete_multipart_uploads"
    status = "Enabled"
    filter {}
    abort_incomplete_multipart_upload {
      days_after_initiation = 1
    }
  }

  rule {
    id     = "noncurrent_version_glacier"
    status = "Enabled"
    filter {}
    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "GLACIER"
    }
  }
}

# ----------------------------------------------------------------------
# Logging S3 bucket
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "logging" {
  bucket = local.logging_bucket_name
  tags   = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logging" {
  bucket = aws_s3_bucket.logging.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  bucket = aws_s3_bucket.logging.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  bucket                  = aws_s3_bucket.logging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "logging" {
  bucket = aws_s3_bucket.logging.id

  rule {
    id     = "noncurrent_version_glacier"
    status = "Enabled"
    filter {}
    noncurrent_version_transition {
      noncurrent_days = 90
      storage_class   = "GLACIER"
    }
  }
}

# ----------------------------------------------------------------------
# Configure server access logging on the state bucket
# ----------------------------------------------------------------------
resource "aws_s3_bucket_logging" "state" {
  bucket = aws_s3_bucket.state.id

  target_bucket = aws_s3_bucket.logging.id
  target_prefix = "log/"
}

# ----------------------------------------------------------------------
# DynamoDB table for state locking
# ----------------------------------------------------------------------
resource "aws_dynamodb_table" "lock" {
  name         = "tf_state_lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.main.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------
output "state_bucket_name" {
  description = "The name of the primary S3 bucket used for Terraform state"
  value       = aws_s3_bucket.state.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_kinesis_stream" "test_stream" {
  name             = "test-websocket-stream"
  shard_count      = 1
  encryption_type  = "KMS"
  kms_key_id       = "alias/aws/kinesis"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_apigatewayv2_api" "websocket_api" {
  name                       = "test-websocket-api"
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

resource "aws_apigatewayv2_integration" "kinesis_integration" {
  api_id                       = aws_apigatewayv2_api.websocket_api.id
  integration_type             = "AWS"
  integration_uri              = "arn:aws:apigateway:us-east-1:kinesis:action/PutRecord"
  integration_method           = "POST"
  template_selection_expression = "$request.body.action"
  credentials_arn              = aws_iam_role.api_gateway_kinesis_execution_role.arn

  request_templates = {
    "application/json" = <<EOF
{
  "StreamName": "${aws_kinesis_stream.test_stream.name}",
  "PartitionKey": "$context.connectionId",
  "Data": "$util.base64Encode($input.json('$'))"
}
EOF
  }
}

resource "aws_apigatewayv2_route" "default_route" {
  api_id    = aws_apigatewayv2_api.websocket_api.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.kinesis_integration.id}"
}

resource "aws_apigatewayv2_stage" "v1" {
  api_id      = aws_apigatewayv2_api.websocket_api.id
  name        = "v1"
  auto_deploy = true

  default_route_settings {
    data_trace_enabled       = true
    logging_level            = "INFO"
    throttling_burst_limit   = 100
    throttling_rate_limit    = 100
  }

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_gateway_logs.arn
    format          = "$context.identity.sourceIp - - [$context.requestTime] \"$context.routeKey\" $context.status"
  }
}

resource "aws_cloudwatch_log_group" "api_gateway_logs" {
  name              = "/aws/apigateway/websocket-test"
  retention_in_days = 1

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_stream" "api_gateway_log_stream" {
  name           = "api-gateway-log-stream"
  log_group_name = aws_cloudwatch_log_group.api_gateway_logs.name
}

resource "aws_iam_role" "api_gateway_kinesis_execution_role" {
  name = "api-gateway-kinesis-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_full_access" {
  role       = aws_iam_role.api_gateway_kinesis_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKinesisFullAccess"
}

