# Variables
variable "topic_name" {
  description = "Name of the SNS topic"
  type        = string
  default     = "my-topic"
}

variable "is_fifo" {
  description = "Whether the topic is FIFO"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "enable_kms" {
  description = "Enable server-side encryption with a customer-managed KMS key"
  type        = bool
  default     = false
}

variable "topic_policy_json" {
  description = "JSON policy document for the SNS topic"
  type        = string
  default     = ""
}

variable "delivery_policy_json" {
  description = "JSON delivery policy for the SNS topic"
  type        = string
  default     = ""
}

variable "feedback_roles" {
  description = "Map of feedback role configurations (protocol and sample_rate)"
  type        = map(object({
    protocol    = string
    sample_rate = number
  }))
  default = {}
}

variable "subscriptions" {
  description = "Map of subscriptions with endpoint, protocol, and optional redrive_policy and filter_policy"
  type = map(object({
    endpoint       = string
    protocol       = string
    redrive_policy = optional(string, "")
    filter_policy  = optional(string, "")
  }))
  default = {}
}

# Locals
locals {
  log_group_name = "/sns/${var.topic_name}"
}

# Data sources
data "aws_caller_identity" "current" {}

# SNS Topic
resource "aws_sns_topic" "main" {
  name                        = var.topic_name
  fifo_topic                  = var.is_fifo
  content_based_deduplication = var.content_based_deduplication
  kms_master_key_id           = var.enable_kms ? aws_kms_key.sns_key[0].arn : null
  delivery_policy             = var.delivery_policy_json != "" ? var.delivery_policy_json : null
  tags = {
    Name = var.topic_name
  }
}

# KMS Key (conditional)
resource "aws_kms_key" "sns_key" {
  count                  = var.enable_kms ? 1 : 0
  description            = "KMS key for SNS topic ${var.topic_name}"
  enable_key_rotation    = true
  deletion_window_in_days = 10
  policy                 = data.aws_iam_policy_document.kms_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

# KMS Key Policy Document
data "aws_iam_policy_document" "kms_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
    actions = [
      "kms:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryptDecrypt"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt"
    ]
    resources = ["*"]
  }
}

# KMS Alias (conditional)
resource "aws_kms_alias" "sns_alias" {
  count         = var.enable_kms ? 1 : 0
  name          = "alias/${replace(var.topic_name, ".fifo", "")}"
  target_key_id = aws_kms_key.sns_key[0].key_id
}

# Topic Policy (conditional)
resource "aws_sns_topic_policy" "main" {
  count  = var.topic_policy_json != "" ? 1 : 0
  arn    = aws_sns_topic.main.arn
  policy = var.topic_policy_json
}

# Subscriptions
resource "aws_sns_topic_subscription" "main" {
  for_each       = var.subscriptions
  topic_arn      = aws_sns_topic.main.arn
  protocol       = each.value.protocol
  endpoint       = each.value.endpoint
  filter_policy  = each.value.filter_policy != "" ? each.value.filter_policy : null
  redrive_policy = each.value.redrive_policy != "" ? each.value.redrive_policy : null
}

# CloudWatch Log Group for feedback logging
resource "aws_cloudwatch_log_group" "sns_logs" {
  name              = local.log_group_name
  retention_in_days = 7
  tags = {
    Name = local.log_group_name
  }
}

# Feedback IAM Roles
data "aws_iam_policy_document" "feedback_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "feedback_role" {
  for_each           = var.feedback_roles
  name               = "sns-feedback-${each.key}"
  assume_role_policy = data.aws_iam_policy_document.feedback_assume_role.json
  tags = {
    Name = "sns-feedback-${each.key}"
  }
}

# Feedback Logging Policies (one per role)
data "aws_iam_policy_document" "feedback_logging" {
  for_each = var.feedback_roles
  statement {
    sid    = "CreateLogGroup"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup"
    ]
    resources = [
      aws_cloudwatch_log_group.sns_logs.arn
    ]
  }

  statement {
    sid    = "PutLogEvents"
    effect = "Allow"
    actions = [
      "logs:PutLogEvents"
    ]
    resources = [
      "${aws_cloudwatch_log_group.sns_logs.arn}:*"
    ]
  }
}

resource "aws_iam_policy" "feedback_logging" {
  for_each = var.feedback_roles
  name     = "sns-feedback-logging-${each.key}"
  policy   = data.aws_iam_policy_document.feedback_logging[each.key].json
}

resource "aws_iam_role_policy_attachment" "feedback_attach" {
  for_each   = var.feedback_roles
  role       = aws_iam_role.feedback_role[each.key].name
  policy_arn = aws_iam_policy.feedback_logging[each.key].arn
}

# Outputs
output "topic_arn" {
  value = aws_sns_topic.main.arn
}

output "topic_owner" {
  value = data.aws_caller_identity.current.account_id
}

output "topic_tags" {
  value = aws_sns_topic.main.tags_all
}

output "subscription_arns" {
  value = { for k, v in aws_sns_topic_subscription.main : k => v.arn }
}

output "subscription_statuses" {
  value = {
    for k, v in aws_sns_topic_subscription.main : k => {
      confirmation_was_authenticated = v.confirmation_was_authenticated
      pending_confirmation           = v.pending_confirmation
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------
# Variables
# ------------------------------
variable "enable_basic_alarm" {
  description = "Enable basic CloudWatch metric alarm"
  type        = bool
  default     = true
}

variable "basic_alarm_metric_name" {
  description = "Metric name for basic alarm"
  type        = string
  default     = "CPUUtilization"
}

variable "basic_alarm_namespace" {
  description = "Namespace for basic alarm"
  type        = string
  default     = "AWS/EC2"
}

variable "basic_alarm_threshold" {
  description = "Threshold for basic alarm"
  type        = number
  default     = 80.0
}

variable "basic_alarm_period" {
  description = "Period (seconds) for basic alarm"
  type        = number
  default     = 300
}

variable "basic_alarm_evaluation_periods" {
  description = "Number of evaluation periods for basic alarm"
  type        = number
  default     = 2
}

variable "basic_alarm_statistic" {
  description = "Statistic for basic alarm"
  type        = string
  default     = "Average"
}

variable "basic_alarm_comparison_operator" {
  description = "Comparison operator for basic alarm"
  type        = string
  default     = "GreaterThanThreshold"
}

variable "enable_dynamic_alarms" {
  description = "Enable dynamic metric alarms defined in dynamic_alarms map"
  type        = bool
  default     = true
}

variable "dynamic_alarms" {
  description = "Map of dynamic alarms. Each key is alarm name, value is alarm config."
  type = map(object({
    metric_name         = string
    namespace           = string
    threshold           = number
    period              = number
    evaluation_periods  = number
    statistic           = string
    comparison_operator = string
  }))
  default = {
    "high-cpu" = {
      metric_name         = "CPUUtilization"
      namespace           = "AWS/EC2"
      threshold           = 90.0
      period              = 60
      evaluation_periods  = 1
      statistic           = "Maximum"
      comparison_operator = "GreaterThanThreshold"
    }
    "high-memory" = {
      metric_name         = "MemoryUtilization"
      namespace           = "CWAgent"
      threshold           = 85.0
      period              = 300
      evaluation_periods  = 2
      statistic           = "Average"
      comparison_operator = "GreaterThanThreshold"
    }
  }
}

variable "enable_expression_alarm" {
  description = "Enable expression alarm using anomaly detection"
  type        = bool
  default     = true
}

variable "expression_alarm_metric_name" {
  description = "Metric name for anomaly detection"
  type        = string
  default     = "CPUUtilization"
}

variable "expression_alarm_namespace" {
  description = "Namespace for anomaly detection"
  type        = string
  default     = "AWS/EC2"
}

variable "expression_alarm_statistic" {
  description = "Statistic for anomaly detection model"
  type        = string
  default     = "Average"
}

variable "expression_alarm_period" {
  description = "Period for anomaly detection model"
  type        = number
  default     = 300
}

variable "expression_alarm_deviation" {
  description = "Number of standard deviations for anomaly band (band width)"
  type        = number
  default     = 2.0
}

variable "enable_composite_alarm" {
  description = "Enable composite alarm that ORs all metric alarms"
  type        = bool
  default     = true
}

variable "enable_dashboard" {
  description = "Enable CloudWatch dashboard"
  type        = bool
  default     = true
}

# Set to true when deploying to AWS. Disabled by default for LocalStack
# compatibility, as the Synthetics service may not be fully supported.
variable "enable_canary" {
  description = "Enable Synthetics canary"
  type        = bool
  default     = false
}

variable "canary_uri" {
  description = "URI for canary heartbeat"
  type        = string
  default     = "https://example.com"
}

variable "canary_schedule_expression" {
  description = "Schedule expression for canary (rate or cron)"
  type        = string
  default     = "rate(5 minutes)"
}

variable "canary_retention_in_days" {
  description = "Retention period for canary artifacts in S3"
  type        = number
  default     = 30
}

variable "canary_startup_delay_seconds" {
  description = "Delay in seconds before canary creation"
  type        = number
  default     = 30
}

variable "canary_runtime_version" {
  description = "Runtime version for Synthetics canary"
  type        = string
  default     = "syn-nodejs-2.0"
}

variable "enable_log_group" {
  description = "Enable CloudWatch log group"
  type        = bool
  default     = true
}

variable "log_group_name" {
  description = "Name of CloudWatch log group"
  type        = string
  default     = "/aws/canary/my-canary"
}

variable "log_stream_name" {
  description = "Name of log stream inside log group"
  type        = string
  default     = "my-stream"
}

variable "log_group_retention_in_days" {
  description = "Retention in days for log group"
  type        = number
  default     = 30
}

# ------------------------------
# Data sources
# ------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# ------------------------------
# KMS key for SNS and S3 encryption
# ------------------------------
resource "aws_kms_key" "main" {
  description             = "CMK for SNS topic and S3 canary artifacts"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ------------------------------
# SNS topic for alarm actions
# ------------------------------
resource "aws_sns_topic" "alarm_notifications" {
  name              = "cloudwatch-alarm-notifications"
  kms_master_key_id = aws_kms_key.main.arn
}

# ------------------------------
# Basic metric alarm (conditional)
# ------------------------------
resource "aws_cloudwatch_metric_alarm" "basic" {
  count = var.enable_basic_alarm ? 1 : 0

  alarm_name          = "basic-alarm"
  comparison_operator = var.basic_alarm_comparison_operator
  evaluation_periods  = var.basic_alarm_evaluation_periods
  metric_name         = var.basic_alarm_metric_name
  namespace           = var.basic_alarm_namespace
  period              = var.basic_alarm_period
  statistic           = var.basic_alarm_statistic
  threshold           = var.basic_alarm_threshold
  alarm_actions       = [aws_sns_topic.alarm_notifications.arn]
}

# ------------------------------
# Dynamic metric alarms (conditional)
# ------------------------------
resource "aws_cloudwatch_metric_alarm" "dynamic" {
  for_each = var.enable_dynamic_alarms ? var.dynamic_alarms : {}

  alarm_name          = "dynamic-${each.key}"
  comparison_operator = each.value.comparison_operator
  evaluation_periods  = each.value.evaluation_periods
  metric_name         = each.value.metric_name
  namespace           = each.value.namespace
  period              = each.value.period
  statistic           = each.value.statistic
  threshold           = each.value.threshold
  alarm_actions       = [aws_sns_topic.alarm_notifications.arn]
}

# ------------------------------
# Expression alarm using anomaly detection (conditional)
# ------------------------------
resource "aws_cloudwatch_metric_alarm" "expression" {
  count = var.enable_expression_alarm ? 1 : 0

  alarm_name          = "expression-anomaly-alarm"
  comparison_operator = "GreaterThanUpperThreshold"
  evaluation_periods  = 2
  threshold_metric_id = "e1"
  alarm_actions       = [aws_sns_topic.alarm_notifications.arn]

  metric_query {
    id          = "m1"
    return_data = false
    metric {
      metric_name = var.expression_alarm_metric_name
      namespace   = var.expression_alarm_namespace
      period      = var.expression_alarm_period
      stat        = var.expression_alarm_statistic
    }
  }

  metric_query {
    id          = "e1"
    expression  = "ANOMALY_DETECTION_BAND(m1, ${var.expression_alarm_deviation})"
    label       = "CPUUtilization (Expected)"
    return_data = true
  }
}

# ------------------------------
# Local list of metric alarm ARNs for composite alarm
# ------------------------------
locals {
  metric_alarm_arns = compact(
    flatten([
      aws_cloudwatch_metric_alarm.basic[*].arn,
      [for a in aws_cloudwatch_metric_alarm.dynamic : a.arn],
      aws_cloudwatch_metric_alarm.expression[*].arn,
    ])
  )
}

# ------------------------------
# Composite alarm (conditional)
# ------------------------------
resource "aws_cloudwatch_composite_alarm" "main" {
  count = var.enable_composite_alarm ? 1 : 0

  alarm_name    = "composite-alarm-all"
  alarm_rule    = length(local.metric_alarm_arns) > 0 ? join(" OR ", [for arn in local.metric_alarm_arns : format("ALARM(%s)", arn)]) : "FALSE"
  alarm_actions = [aws_sns_topic.alarm_notifications.arn]
}

# ------------------------------
# CloudWatch Dashboard (conditional)
# ------------------------------
locals {
  dashboard_widgets = var.enable_dashboard ? [
    {
      type = "metric",
      x    = 0,
      y    = 0,
      width = 12,
      height = 6,
      properties = {
        metrics = [
          [var.basic_alarm_namespace, var.basic_alarm_metric_name, { stat = var.basic_alarm_statistic }],
          ["CWAgent", "MemoryUtilization", { stat = "Average" }],
          ["AWS/Lambda", "Invocations", { stat = "Sum" }]
        ],
        period = 300,
        stat   = "Average",
        region = "us-east-1",
        title  = "Key Metrics"
      }
    }
  ] : []
}

resource "aws_cloudwatch_dashboard" "main" {
  count          = var.enable_dashboard ? 1 : 0
  dashboard_name = "main-dashboard"
  dashboard_body = jsonencode({
    widgets = local.dashboard_widgets
  })
}

# ------------------------------
# S3 bucket for canary artifacts (conditional)
# ------------------------------
resource "aws_s3_bucket" "canary_artifacts" {
  count  = var.enable_canary ? 1 : 0
  bucket = "canary-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_availability_zones.available.id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "canary" {
  count  = var.enable_canary ? 1 : 0
  bucket = aws_s3_bucket.canary_artifacts[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "canary" {
  count  = var.enable_canary ? 1 : 0
  bucket = aws_s3_bucket.canary_artifacts[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "canary" {
  count  = var.enable_canary ? 1 : 0
  bucket = aws_s3_bucket.canary_artifacts[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------
# IAM role for Synthetics canary (conditional)
# ------------------------------
data "aws_iam_policy_document" "canary_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["synthetics.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "canary_inline_policy" {
  statement {
    actions   = ["s3:PutObject"]
    resources = [
      format("%s/*", var.enable_canary ? aws_s3_bucket.canary_artifacts[0].arn : "arn:aws:s3:::dummy")
    ]
  }
  statement {
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }
  statement {
    actions   = ["lambda:InvokeFunction", "lambda:GetFunctionConfiguration"]
    resources = ["*"]
  }
  dynamic "statement" {
    for_each = var.enable_log_group ? [1] : []
    content {
      actions   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
      resources = [
        aws_cloudwatch_log_group.main[0].arn,
        format("%s:*", aws_cloudwatch_log_group.main[0].arn)
      ]
    }
  }
}

resource "aws_iam_role" "canary" {
  count              = var.enable_canary ? 1 : 0
  name               = "canary-lambda-role"
  assume_role_policy = data.aws_iam_policy_document.canary_assume_role.json
}

resource "aws_iam_role_policy" "canary" {
  count  = var.enable_canary ? 1 : 0
  name   = "canary-inline-policy"
  role   = aws_iam_role.canary[0].name
  policy = data.aws_iam_policy_document.canary_inline_policy.json
}

# ------------------------------
# Time sleep for canary startup delay (conditional)
# ------------------------------
resource "time_sleep" "canary_delay" {
  count = var.enable_canary ? 1 : 0

  create_duration = format("%ds", var.canary_startup_delay_seconds)

  depends_on = [
    aws_s3_bucket.canary_artifacts,
    aws_iam_role.canary,
    aws_iam_role_policy.canary
  ]
}

# ------------------------------
# Synthetics canary (conditional)
# ------------------------------
resource "aws_synthetics_canary" "main" {
  count = var.enable_canary ? 1 : 0

  name                     = "heartbeat-canary"
  runtime_version          = var.canary_runtime_version
  artifact_s3_location     = "s3://${aws_s3_bucket.canary_artifacts[0].id}/"
  handler                  = "heartbeat.handler"
  start_canary             = false
  execution_role_arn       = aws_iam_role.canary[0].arn
  success_retention_period = var.canary_retention_in_days
  failure_retention_period = var.canary_retention_in_days

  schedule {
    expression          = var.canary_schedule_expression
    duration_in_seconds = 0
  }

  run_config {
    timeout_in_seconds = 120
    environment_variables = {
      URI = var.canary_uri
    }
  }

  depends_on = [time_sleep.canary_delay]
}

# ------------------------------
# CloudWatch log group (conditional)
# ------------------------------
resource "aws_cloudwatch_log_group" "main" {
  count = var.enable_log_group ? 1 : 0

  name              = var.log_group_name
  retention_in_days = var.log_group_retention_in_days

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_stream" "main" {
  count = var.enable_log_group ? 1 : 0

  name           = var.log_stream_name
  log_group_name = aws_cloudwatch_log_group.main[0].name
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name_prefix" {
  description = "Name prefix used for resource names"
  type        = string
  default     = "my"
}

variable "environment_suffix" {
  description = "Environment suffix used for resource names"
  type        = string
  default     = "dev"
}

variable "enable_cache_policy" {
  description = "Whether to create a CloudFront cache policy"
  type        = bool
  default     = true
}

variable "cache_policy_config" {
  description = "Configuration overrides for the cache policy"
  type        = map(string)
  default     = {}
}

variable "enable_origin_request_policy" {
  description = "Whether to create a CloudFront origin request policy"
  type        = bool
  default     = false
}

variable "origin_request_policy_config" {
  description = "Configuration overrides for the origin request policy"
  type        = map(string)
  default     = {}
}

variable "enable_origin_access_identity" {
  description = "Whether to create a CloudFront origin access identity"
  type        = bool
  default     = false
}

variable "origin_access_identity_config" {
  description = "Configuration overrides for the origin access identity"
  type        = map(string)
  default     = {}
}

variable "enable_public_key" {
  description = "Whether to create a CloudFront public key"
  type        = bool
  default     = false
}

variable "public_key_encoded" {
  description = "The encoded public key (required if enable_public_key is true)"
  type        = string
  sensitive   = true
  default     = ""
}

variable "public_key_config" {
  description = "Configuration overrides for the public key"
  type        = map(string)
  default     = {}
}

variable "enable_realtime_log_config" {
  description = "Whether to create a CloudFront real-time log configuration"
  type        = bool
  default     = false
}

variable "realtime_log_config_config" {
  description = "Configuration overrides for the real-time log configuration"
  type        = map(string)
  default     = {}
}

variable "enable_distribution" {
  description = "Whether to create a CloudFront distribution"
  type        = bool
  default     = false
}

variable "distribution_config" {
  description = "Configuration overrides for the distribution"
  type        = map(string)
  default     = {}
}

locals {
  default_name = "${var.name_prefix}-${var.environment_suffix}"
}

# Cache Policy
resource "aws_cloudfront_cache_policy" "this" {
  count = var.enable_cache_policy ? 1 : 0
  name  = try(var.cache_policy_config["name"], local.default_name)

  min_ttl     = try(var.cache_policy_config["min_ttl"], 0)
  max_ttl     = try(var.cache_policy_config["max_ttl"], 31536000)
  default_ttl = try(var.cache_policy_config["default_ttl"], 86400)

  parameters_in_cache_key_and_forwarded_to_origin {
    cookies_config {
      cookie_behavior = try(var.cache_policy_config["cookies_behavior"], "none")
    }
    headers_config {
      header_behavior = try(var.cache_policy_config["header_behavior"], "none")
    }
    query_strings_config {
      query_string_behavior = try(var.cache_policy_config["query_string_behavior"], "none")
    }
    enable_accept_encoding_gzip   = try(var.cache_policy_config["enable_gzip"], true)
    enable_accept_encoding_brotli = try(var.cache_policy_config["enable_brotli"], true)
  }
}

# Origin Request Policy
resource "aws_cloudfront_origin_request_policy" "this" {
  count = var.enable_origin_request_policy ? 1 : 0
  name  = try(var.origin_request_policy_config["name"], local.default_name)

  cookies_config {
    cookie_behavior = try(var.origin_request_policy_config["cookies_behavior"], "none")
  }
  headers_config {
    header_behavior = try(var.origin_request_policy_config["header_behavior"], "none")
  }
  query_strings_config {
    query_string_behavior = try(var.origin_request_policy_config["query_string_behavior"], "none")
  }
}

# Origin Access Identity
resource "aws_cloudfront_origin_access_identity" "this" {
  count   = var.enable_origin_access_identity ? 1 : 0
  comment = try(var.origin_access_identity_config["comment"], local.default_name)
}

# Public Key
resource "aws_cloudfront_public_key" "this" {
  count = var.enable_public_key ? 1 : 0
  name        = try(var.public_key_config["name"], local.default_name)
  encoded_key = var.public_key_encoded
}

# Real-time Log Configuration -> Kinesis Stream, IAM Role, Policy, Attachment
resource "aws_kinesis_stream" "realtime_log" {
  count             = var.enable_realtime_log_config ? 1 : 0
  name              = try(var.realtime_log_config_config["stream_name"], "${local.default_name}-stream")
  shard_count       = try(var.realtime_log_config_config["shard_count"], 1)
  retention_period  = try(var.realtime_log_config_config["retention_hours"], 24)
  encryption_type   = "KMS"
  kms_key_id        = "alias/aws/kinesis"
}

resource "aws_iam_role" "realtime_log" {
  count = var.enable_realtime_log_config ? 1 : 0
  name  = try(var.realtime_log_config_config["role_name"], "${local.default_name}-realtime-log-role")
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "realtime_log" {
  count = var.enable_realtime_log_config ? 1 : 0
  name  = try(var.realtime_log_config_config["policy_name"], "${local.default_name}-realtime-log-policy")
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:PutRecord",
          "kinesis:DescribeStream"
        ]
        Effect   = "Allow"
        Resource = try(aws_kinesis_stream.realtime_log[0].arn, null)
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "realtime_log" {
  count      = var.enable_realtime_log_config ? 1 : 0
  role       = aws_iam_role.realtime_log[0].name
  policy_arn = aws_iam_policy.realtime_log[0].arn
}

resource "aws_cloudfront_realtime_log_config" "this" {
  count          = var.enable_realtime_log_config ? 1 : 0
  name           = try(var.realtime_log_config_config["name"], "${local.default_name}-realtime-log")
  fields         = try(var.realtime_log_config_config["fields"], ["timestamp", "c-ip", "cs-uri-stem", "sc-status", "cs(user-agent)"])
  sampling_rate  = try(var.realtime_log_config_config["sampling_rate"], 100)

  endpoint {
    stream_type = "Kinesis"
    kinesis_stream_config {
      role_arn   = aws_iam_role.realtime_log[0].arn
      stream_arn = aws_kinesis_stream.realtime_log[0].arn
    }
  }
}

# Distribution - requires S3 bucket origin
resource "aws_s3_bucket" "distribution_origin" {
  count  = var.enable_distribution ? 1 : 0
  bucket = try(var.distribution_config["origin_bucket_name"], "${local.default_name}-origin")
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "distribution_origin" {
  count  = var.enable_distribution ? 1 : 0
  bucket = aws_s3_bucket.distribution_origin[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_cloudfront_distribution" "this" {
  count            = var.enable_distribution ? 1 : 0
  enabled          = true
  is_ipv6_enabled  = true
  comment          = try(var.distribution_config["comment"], local.default_name)
  default_root_object = try(var.distribution_config["default_root_object"], "index.html")
  price_class      = try(var.distribution_config["price_class"], "PriceClass_100")
  aliases          = try(var.distribution_config["aliases"], null)

  origin {
    domain_name = aws_s3_bucket.distribution_origin[0].bucket_regional_domain_name
    origin_id   = "S3-${local.default_name}"

    s3_origin_config {
      origin_access_identity = var.enable_origin_access_identity ? aws_cloudfront_origin_access_identity.this[0].cloudfront_access_identity_path : null
    }
  }

  default_cache_behavior {
    target_origin_id         = "S3-${local.default_name}"
    viewer_protocol_policy   = "redirect-to-https"
    allowed_methods          = try(split(",", try(var.distribution_config["allowed_methods"], "GET,HEAD")), ["GET", "HEAD"])
    cached_methods           = try(split(",", try(var.distribution_config["cached_methods"], "GET,HEAD")), ["GET", "HEAD"])
    compress                 = try(var.distribution_config["compress"], true)
    cache_policy_id          = try(aws_cloudfront_cache_policy.this[0].id, null)
    origin_request_policy_id = try(aws_cloudfront_origin_request_policy.this[0].id, null)
    realtime_log_config_arn  = try(aws_cloudfront_realtime_log_config.this[0].arn, null)
  }

  viewer_certificate {
    cloudfront_default_certificate = true
    minimum_protocol_version       = "TLSv1.2_2021"
  }

  restrictions {
    geo_restriction {
      restriction_type = try(var.distribution_config["geo_restriction_type"], "none")
      locations        = try(split(",", try(var.distribution_config["geo_restriction_locations"], "")), [])
    }
  }

  tags = try(var.distribution_config["tags"], {})
}

# Outputs
output "cache_policy_id" {
  value       = try(aws_cloudfront_cache_policy.this[0].id, null)
  description = "ID of the cache policy"
}

output "cache_policy_arn" {
  value       = try(aws_cloudfront_cache_policy.this[0].arn, null)
  description = "ARN of the cache policy"
}

output "origin_request_policy_id" {
  value       = try(aws_cloudfront_origin_request_policy.this[0].id, null)
  description = "ID of the origin request policy"
}

output "origin_request_policy_arn" {
  value       = try(aws_cloudfront_origin_request_policy.this[0].arn, null)
  description = "ARN of the origin request policy"
}

output "origin_access_identity_id" {
  value       = try(aws_cloudfront_origin_access_identity.this[0].id, null)
  description = "ID of the origin access identity"
}

output "origin_access_identity_iam_arn" {
  value       = try(aws_cloudfront_origin_access_identity.this[0].iam_arn, null)
  description = "IAM ARN of the origin access identity"
}

output "origin_access_identity_cloudfront_access_identity_path" {
  value       = try(aws_cloudfront_origin_access_identity.this[0].cloudfront_access_identity_path, null)
  description = "CloudFront access identity path of the origin access identity"
}

output "public_key_id" {
  value       = try(aws_cloudfront_public_key.this[0].id, null)
  description = "ID of the public key"
}

output "realtime_log_config_arn" {
  value       = try(aws_cloudfront_realtime_log_config.this[0].arn, null)
  description = "ARN of the real-time log configuration"
}

output "realtime_log_config_name" {
  value       = try(aws_cloudfront_realtime_log_config.this[0].name, null)
  description = "Name of the real-time log configuration"
}

output "distribution_id" {
  value       = try(aws_cloudfront_distribution.this[0].id, null)
  description = "ID of the CloudFront distribution"
}

output "distribution_arn" {
  value       = try(aws_cloudfront_distribution.this[0].arn, null)
  description = "ARN of the CloudFront distribution"
}

output "distribution_domain_name" {
  value       = try(aws_cloudfront_distribution.this[0].domain_name, null)
  description = "Domain name of the CloudFront distribution"
}

output "distribution_hosted_zone_id" {
  value       = try(aws_cloudfront_distribution.this[0].hosted_zone_id, null)
  description = "Hosted zone ID of the CloudFront distribution"
}

output "kinesis_stream_arn" {
  value       = try(aws_kinesis_stream.realtime_log[0].arn, null)
  description = "ARN of the Kinesis stream (only if real-time log config is enabled)"
}

output "kinesis_stream_name" {
  value       = try(aws_kinesis_stream.realtime_log[0].name, null)
  description = "Name of the Kinesis stream (only if real-time log config is enabled)"
}

output "iam_role_arn" {
  value       = try(aws_iam_role.realtime_log[0].arn, null)
  description = "ARN of the IAM role for real-time logs (only if real-time log config is enabled)"
}

output "iam_role_name" {
  value       = try(aws_iam_role.realtime_log[0].name, null)
  description = "Name of the IAM role for real-time logs (only if real-time log config is enabled)"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment identifier"
  type        = string
  default     = "STAGE"
}

variable "create_ipset" {
  description = "Create WAF Classic IP set"
  type        = bool
  default     = false
}

variable "create_rate_based_rule" {
  description = "Create WAF Classic rate-based rule"
  type        = bool
  default     = false
}

variable "create_rule" {
  description = "Create WAF Classic rule"
  type        = bool
  default     = false
}

variable "create_rule_group" {
  description = "Create WAF Classic rule group"
  type        = bool
  default     = false
}

variable "create_web_acl" {
  description = "Create WAF Classic web ACL"
  type        = bool
  default     = false
}

variable "create_byte_match_set" {
  description = "Create WAF Classic byte match set"
  type        = bool
  default     = false
}

variable "create_geo_match_set" {
  description = "Create WAF Classic geo match set"
  type        = bool
  default     = false
}

variable "create_regex_match_set" {
  description = "Create WAF Classic regex match set"
  type        = bool
  default     = false
}

variable "create_regex_pattern_set" {
  description = "Create WAF Classic regex pattern set"
  type        = bool
  default     = false
}

variable "create_size_constraint_set" {
  description = "Create WAF Classic size constraint set"
  type        = bool
  default     = false
}

variable "create_sql_injection_match_set" {
  description = "Create WAF Classic SQL injection match set"
  type        = bool
  default     = false
}

variable "create_xss_match_set" {
  description = "Create WAF Classic XSS match set"
  type        = bool
  default     = false
}

variable "web_acl_default_action" {
  description = "Default action for the WAF Classic web ACL (ALLOW or BLOCK)"
  type        = string
  default     = "ALLOW"
}

variable "web_acl_rules" {
  description = "List of rule objects to associate with the web ACL"
  type = list(object({
    action = object({
      type = string
    })
    priority = number
    rule_id  = string
  }))
  default = []
}

locals {
  sanitized_prefix = replace(lower("${var.name_prefix}${var.environment}"), "/[^a-z0-9]/", "")
  name_base        = lower("${var.name_prefix}-${var.environment}")
  metric_name_base = local.sanitized_prefix
}

# KMS Customer Managed Key for S3 bucket encryption
resource "aws_kms_key" "this" {
  description             = "CMK for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableFullAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

# Minimal S3 bucket for LocalStack deployability testing
resource "aws_s3_bucket" "test" {
  bucket        = lower("${var.name_prefix}-${var.environment}-test")
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "test" {
  bucket = aws_s3_bucket.test.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.test.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

# IP Set
resource "aws_waf_ipset" "main" {
  count = var.create_ipset ? 1 : 0
  name  = "${local.name_base}-ipset"
}

# Rate-based rule
resource "aws_waf_rate_based_rule" "main" {
  count       = var.create_rate_based_rule ? 1 : 0
  name        = "${local.name_base}-ratebasedrule"
  metric_name = "${local.metric_name_base}ratebasedrule"
  rate_key    = "IP"
  rate_limit  = 100
}

# Standard rule
resource "aws_waf_rule" "main" {
  count       = var.create_rule ? 1 : 0
  name        = "${local.name_base}-rule"
  metric_name = "${local.metric_name_base}rule"
}

# Rule group
resource "aws_waf_rule_group" "main" {
  count       = var.create_rule_group ? 1 : 0
  name        = "${local.name_base}-rulegroup"
  metric_name = "${local.metric_name_base}rulegroup"

  dynamic "activated_rule" {
    for_each = var.create_rule ? [1] : []
    content {
      action {
        type = "ALLOW"
      }
      priority = 1
      rule_id  = aws_waf_rule.main[0].id
    }
  }
}

# Web ACL
resource "aws_waf_web_acl" "main" {
  count       = var.create_web_acl ? 1 : 0
  name        = "${local.name_base}-webacl"
  metric_name = "${local.metric_name_base}webacl"

  default_action {
    type = var.web_acl_default_action
  }

  dynamic "rules" {
    for_each = var.web_acl_rules
    content {
      action {
        type = rules.value.action.type
      }
      priority = rules.value.priority
      rule_id  = rules.value.rule_id
    }
  }
}

# Byte match set
resource "aws_waf_byte_match_set" "main" {
  count = var.create_byte_match_set ? 1 : 0
  name  = "${local.name_base}-bytematchset"

  byte_match_tuples {
    text_transformation   = "NONE"
    target_string         = "bad"
    positional_constraint = "CONTAINS"

    field_to_match {
      type = "HEADER"
      data = "User-Agent"
    }
  }
}

# Geo match set
resource "aws_waf_geo_match_set" "main" {
  count = var.create_geo_match_set ? 1 : 0
  name  = "${local.name_base}-geomatchset"

  geo_match_constraint {
    type  = "Country"
    value = "US"
  }
}

# Regex pattern set (needed for regex match set)
resource "aws_waf_regex_pattern_set" "main" {
  count = var.create_regex_pattern_set ? 1 : 0
  name  = "${local.name_base}-regexpatternset"

  regex_pattern_strings = ["test.*"]
}

# Regex match set
resource "aws_waf_regex_match_set" "main" {
  count = var.create_regex_match_set ? 1 : 0
  name  = "${local.name_base}-regexmatchset"

  dynamic "regex_match_tuple" {
    for_each = var.create_regex_pattern_set ? [1] : []
    content {
      field_to_match {
        type = "HEADER"
        data = "User-Agent"
      }
      text_transformation   = "NONE"
      regex_pattern_set_id  = aws_waf_regex_pattern_set.main[0].id
    }
  }
}

# Size constraint set
resource "aws_waf_size_constraint_set" "main" {
  count = var.create_size_constraint_set ? 1 : 0
  name  = "${local.name_base}-sizeconstraintset"

  size_constraints {
    text_transformation = "NONE"
    comparison_operator = "EQ"
    size                = 0

    field_to_match {
      type = "HEADER"
      data = "User-Agent"
    }
  }
}

# SQL injection match set
resource "aws_waf_sql_injection_match_set" "main" {
  count = var.create_sql_injection_match_set ? 1 : 0
  name  = "${local.name_base}-sqlinjectionmatchset"

  sql_injection_match_tuples {
    text_transformation = "NONE"

    field_to_match {
      type = "HEADER"
      data = "User-Agent"
    }
  }
}

# XSS match set
resource "aws_waf_xss_match_set" "main" {
  count = var.create_xss_match_set ? 1 : 0
  name  = "${local.name_base}-xssmatchset"

  xss_match_tuples {
    text_transformation = "NONE"

    field_to_match {
      type = "HEADER"
      data = "User-Agent"
    }
  }
}

# Outputs
output "kms_key_id" {
  value = aws_kms_key.this.id
}

output "kms_key_arn" {
  value = aws_kms_key.this.arn
}

output "s3_bucket_id" {
  value = aws_s3_bucket.test.id
}

output "s3_bucket_arn" {
  value = aws_s3_bucket.test.arn
}

output "ipset_id" {
  value = var.create_ipset ? aws_waf_ipset.main[0].id : null
}

output "ipset_arn" {
  value = var.create_ipset ? aws_waf_ipset.main[0].arn : null
}

output "rate_based_rule_id" {
  value = var.create_rate_based_rule ? aws_waf_rate_based_rule.main[0].id : null
}

output "rate_based_rule_arn" {
  value = var.create_rate_based_rule ? aws_waf_rate_based_rule.main[0].arn : null
}

output "rule_id" {
  value = var.create_rule ? aws_waf_rule.main[0].id : null
}

output "rule_arn" {
  value = var.create_rule ? aws_waf_rule.main[0].arn : null
}

output "rule_group_id" {
  value = var.create_rule_group ? aws_waf_rule_group.main[0].id : null
}

output "rule_group_arn" {
  value = var.create_rule_group ? aws_waf_rule_group.main[0].arn : null
}

output "web_acl_id" {
  value = var.create_web_acl ? aws_waf_web_acl.main[0].id : null
}

output "web_acl_arn" {
  value = var.create_web_acl ? aws_waf_web_acl.main[0].arn : null
}

output "byte_match_set_id" {
  value = var.create_byte_match_set ? aws_waf_byte_match_set.main[0].id : null
}

output "byte_match_set_arn" {
  value = var.create_byte_match_set ? aws_waf_byte_match_set.main[0].arn : null
}

output "geo_match_set_id" {
  value = var.create_geo_match_set ? aws_waf_geo_match_set.main[0].id : null
}

output "geo_match_set_arn" {
  value = var.create_geo_match_set ? aws_waf_geo_match_set.main[0].arn : null
}

output "regex_pattern_set_id" {
  value = var.create_regex_pattern_set ? aws_waf_regex_pattern_set.main[0].id : null
}

output "regex_pattern_set_arn" {
  value = var.create_regex_pattern_set ? aws_waf_regex_pattern_set.main[0].arn : null
}

output "regex_match_set_id" {
  value = var.create_regex_match_set ? aws_waf_regex_match_set.main[0].id : null
}

output "regex_match_set_arn" {
  value = var.create_regex_match_set ? aws_waf_regex_match_set.main[0].arn : null
}

output "size_constraint_set_id" {
  value = var.create_size_constraint_set ? aws_waf_size_constraint_set.main[0].id : null
}

output "size_constraint_set_arn" {
  value = var.create_size_constraint_set ? aws_waf_size_constraint_set.main[0].arn : null
}

output "sql_injection_match_set_id" {
  value = var.create_sql_injection_match_set ? aws_waf_sql_injection_match_set.main[0].id : null
}

output "sql_injection_match_set_arn" {
  value = var.create_sql_injection_match_set ? aws_waf_sql_injection_match_set.main[0].arn : null
}

output "xss_match_set_id" {
  value = var.create_xss_match_set ? aws_waf_xss_match_set.main[0].id : null
}

output "xss_match_set_arn" {
  value = var.create_xss_match_set ? aws_waf_xss_match_set.main[0].arn : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "AWS_ENVIRONMENT_NAME" {
  type    = string
  default = ""
}

# Static website S3 bucket
resource "aws_s3_bucket" "s3_frontend_nft_maker_v2" {
  bucket = "s3-frontend-nft-maker-v2"

  lifecycle {
    prevent_destroy = true
  }
}

# Website configuration for static bucket
resource "aws_s3_bucket_website_configuration" "static_website_config" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

# Bucket policy for static website - OAI only access
resource "aws_s3_bucket_policy" "static_website_policy" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.oai.iam_arn
        }
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.s3_frontend_nft_maker_v2.arn,
          "${aws_s3_bucket.s3_frontend_nft_maker_v2.arn}/*"
        ]
      }
    ]
  })
}

# CORS configuration for static website
resource "aws_s3_bucket_cors_configuration" "static_website_cors" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id

  cors_rule {
    allowed_methods = ["PUT", "POST", "GET", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3600
  }
}

# Public access block for static website bucket
resource "aws_s3_bucket_public_access_block" "static_website_public_access_block" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# SSE-KMS encryption for static website bucket
resource "aws_s3_bucket_server_side_encryption_configuration" "static_website_encryption" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# CloudFront Origin Access Identity
resource "aws_cloudfront_origin_access_identity" "oai" {
  comment = "OAI for NFT Maker frontend"
}

# WAFv2 Web ACL for CloudFront protection
resource "aws_wafv2_web_acl" "cloudfront_waf" {
  name        = "nft-maker-frontend-waf"
  description = "WAF for NFT Maker CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWS-AWSManagedRulesCommonRuleSet"
    priority = 0

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = false
      metric_name                = "AWSManagedRulesCommonRuleSetMetric"
      sampled_requests_enabled   = false
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "nftMakerWafMetric"
    sampled_requests_enabled   = false
  }
}

# CloudFront distribution
resource "aws_cloudfront_distribution" "s3_distribution" {
  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"
  price_class         = "PriceClass_200"
  web_acl_id          = aws_wafv2_web_acl.cloudfront_waf.arn

  origin {
    domain_name = aws_s3_bucket.s3_frontend_nft_maker_v2.bucket_regional_domain_name
    origin_id   = "S3-${aws_s3_bucket.s3_frontend_nft_maker_v2.id}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.oai.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    target_origin_id = "S3-${aws_s3_bucket.s3_frontend_nft_maker_v2.id}"
    allowed_methods  = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods   = ["GET", "HEAD"]
    default_ttl      = 3600
    viewer_protocol_policy = "redirect-to-https"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern     = "/content/immutable/*"
    target_origin_id = "S3-${aws_s3_bucket.s3_frontend_nft_maker_v2.id}"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    default_ttl      = 3600
    max_ttl          = 31536000
    compress         = true
    viewer_protocol_policy = "redirect-to-https"

    forwarded_values {
      query_string = false
      headers      = ["Origin"]
      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern     = "/content/*"
    target_origin_id = "S3-${aws_s3_bucket.s3_frontend_nft_maker_v2.id}"
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    default_ttl      = 3600
    max_ttl          = 86400
    compress         = true
    viewer_protocol_policy = "redirect-to-https"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# KMS key for Terraform state bucket encryption
resource "aws_kms_key" "terraform_state_key" {
  description             = "This key is used to encrypt bucket objects"
  deletion_window_in_days = 10

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "terraform_state_key_alias" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.terraform_state_key.key_id
}

# Terraform state S3 bucket
resource "aws_s3_bucket" "terraform_state" {
  bucket = "near-frontend-${lower(var.AWS_ENVIRONMENT_NAME)}-terraform-state"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "terraform_state_ownership" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "terraform_state_acl" {
  depends_on = [aws_s3_bucket_ownership_controls.terraform_state_ownership]
  bucket     = aws_s3_bucket.terraform_state.id
  acl        = "private"
}

resource "aws_s3_bucket_versioning" "terraform_state_versioning" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state_encryption" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state_public_access_block" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# DynamoDB table for Terraform state locking
resource "aws_dynamodb_table" "terraform_state_lock" {
  name           = "near-frontend-terraform-state"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

variable "principal_arn" {
  type        = string
  description = "ARN of the principal (user/role) allowed to assume roles"
  default     = "arn:aws:iam::000000000000:user/placeholder"
}

variable "root_user_arn" {
  type        = string
  description = "ARN of the root user for trust policies"
  default     = "arn:aws:iam::000000000000:root"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------------------------------------------
# IAM Policies
# ------------------------------------------------------------------------------------------------------------------

# Exploitable: permits ec2:RunInstances and iam:PassRole with wildcard account ID
resource "aws_iam_policy" "privesc_ec2_passrole" {
  name        = "privesc_ec2_passrole"
  description = "Allows launching instances and passing roles (exploitable pattern)"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:RunInstances"
        Resource = "arn:aws:ec2:*:*:instance/*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = "arn:aws:iam::*:role/*"
      }
    ]
  })
}

# Non‑exploitable: Allow all except specific IAM management actions (NotAction pattern, Resource "*")
resource "aws_iam_policy" "privesc_notaction" {
  name        = "privesc_notaction"
  description = "Allows everything except specified IAM actions (non‑exploitable)"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        NotAction = [
          "iam:CreateUser",
          "iam:CreateRole",
          "iam:PutRolePolicy"
        ]
        Resource = "*"
      }
    ]
  })
}

# Single policy with both Allow and Deny statements (exploitable due to resource pattern)
resource "aws_iam_policy" "privesc_allow_deny_single" {
  name        = "privesc_allow_deny_single"
  description = "Combines Allow and Deny in one policy (exploitable)"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = "arn:aws:s3:::example-bucket"
      },
      {
        Effect   = "Deny"
        Action   = "s3:DeleteBucket"
        Resource = "arn:aws:s3:::example-bucket"
      }
    ]
  })
}

# Allow‑only policy (exploitable)
resource "aws_iam_policy" "privesc_allow_only" {
  name        = "privesc_allow_only"
  description = "Permissive allow statement (part of cross‑policy test)"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:DescribeInstances"
        Resource = "*"
      }
    ]
  })
}

# Deny‑only policy (non‑exploitable)
resource "aws_iam_policy" "privesc_deny_only" {
  name        = "privesc_deny_only"
  description = "Restrictive deny statement (part of cross‑policy test)"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Action   = "ec2:TerminateInstances"
        Resource = "*"
      }
    ]
  })
}

# Policy with date condition on TokenIssueTime (non‑exploitable)
resource "aws_iam_policy" "privesc_date_condition" {
  name        = "privesc_date_condition"
  description = "Allows action only if token issued after a fixed date"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "ec2:StartInstances"
        Resource = "*"
        Condition = {
          DateGreaterThan = {
            "aws:TokenIssueTime" = "2024-01-01T00:00:00Z"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------------------------------------------
# IAM Role with trust policy allowing both principal ARNs
# ------------------------------------------------------------------------------------------------------------------

resource "aws_iam_role" "privesc_test_role" {
  name = "privesc_test_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = [var.principal_arn, var.root_user_arn]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# ------------------------------------------------------------------------------------------------------------------
# Attach policies to role (each policy gets its own attachment for clarity)
# ------------------------------------------------------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "ec2_passrole" {
  role       = aws_iam_role.privesc_test_role.name
  policy_arn = aws_iam_policy.privesc_ec2_passrole.arn
}

resource "aws_iam_role_policy_attachment" "notaction" {
  role       = aws_iam_role.privesc_test_role.name
  policy_arn = aws_iam_policy.privesc_notaction.arn
}

resource "aws_iam_role_policy_attachment" "allow_deny_single" {
  role       = aws_iam_role.privesc_test_role.name
  policy_arn = aws_iam_policy.privesc_allow_deny_single.arn
}

resource "aws_iam_role_policy_attachment" "allow_only" {
  role       = aws_iam_role.privesc_test_role.name
  policy_arn = aws_iam_policy.privesc_allow_only.arn
}

resource "aws_iam_role_policy_attachment" "deny_only" {
  role       = aws_iam_role.privesc_test_role.name
  policy_arn = aws_iam_policy.privesc_deny_only.arn
}

resource "aws_iam_role_policy_attachment" "date_condition" {
  role       = aws_iam_role.privesc_test_role.name
  policy_arn = aws_iam_policy.privesc_date_condition.arn
}

# ------------------------------------------------------------------------------------------------------------------
# IAM User
# ------------------------------------------------------------------------------------------------------------------

resource "aws_iam_user" "privesc_test_user" {
  name = "privesc-tester"
}

# ------------------------------------------------------------------------------------------------------------------
# Attach policies to user
# ------------------------------------------------------------------------------------------------------------------

resource "aws_iam_user_policy_attachment" "ec2_passrole" {
  user       = aws_iam_user.privesc_test_user.name
  policy_arn = aws_iam_policy.privesc_ec2_passrole.arn
}

resource "aws_iam_user_policy_attachment" "notaction" {
  user       = aws_iam_user.privesc_test_user.name
  policy_arn = aws_iam_policy.privesc_notaction.arn
}

resource "aws_iam_user_policy_attachment" "allow_deny_single" {
  user       = aws_iam_user.privesc_test_user.name
  policy_arn = aws_iam_policy.privesc_allow_deny_single.arn
}

resource "aws_iam_user_policy_attachment" "allow_only" {
  user       = aws_iam_user.privesc_test_user.name
  policy_arn = aws_iam_policy.privesc_allow_only.arn
}

resource "aws_iam_user_policy_attachment" "deny_only" {
  user       = aws_iam_user.privesc_test_user.name
  policy_arn = aws_iam_policy.privesc_deny_only.arn
}

resource "aws_iam_user_policy_attachment" "date_condition" {
  user       = aws_iam_user.privesc_test_user.name
  policy_arn = aws_iam_policy.privesc_date_condition.arn
}

# ------------------------------------------------------------------------------------------------------------------
# Access Key for the test user
# ------------------------------------------------------------------------------------------------------------------

resource "aws_iam_access_key" "privesc_test_user" {
  user = aws_iam_user.privesc_test_user.name
}

# ------------------------------------------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------------------------------------------

output "access_key_id" {
  value = aws_iam_access_key.privesc_test_user.id
}

output "secret_access_key" {
  value     = aws_iam_access_key.privesc_test_user.secret
  sensitive = true
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default = {
    Environment = "production"
  }
}

# Managed IAM policies for AWS Backup
data "aws_iam_policy" "backup_service_role_policy" {
  name = "AWSBackupServiceRolePolicyForBackup"
}

data "aws_iam_policy" "restore_service_role_policy" {
  name = "AWSBackupServiceRolePolicyForRestores"
}

# KMS key for backup vault encryption
resource "aws_kms_key" "backup" {
  description             = "KMS key for AWS Backup vault encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Backup Service to use key"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow Backup Role to use key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.bronze_backup_role.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_kms_alias" "backup" {
  name          = "alias/backup-vault-key"
  target_key_id = aws_kms_key.backup.key_id
}

# IAM Role for AWS Backup
resource "aws_iam_role" "bronze_backup_role" {
  name = "Bronze_Backup_Role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "backup_service_role" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = data.aws_iam_policy.backup_service_role_policy.arn
}

resource "aws_iam_role_policy_attachment" "restore_service_role" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = data.aws_iam_policy.restore_service_role_policy.arn
}

# Backup Vaults
resource "aws_backup_vault" "bronze" {
  name        = "bronze-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn
  tags        = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "silver" {
  name        = "silver-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn
  tags        = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "gold" {
  name        = "gold-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn
  tags        = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "premium" {
  name        = "premium-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn
  tags        = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

# Bronze Backup Plan
resource "aws_backup_plan" "bronze" {
  name = "bronze-backup-plan"
  rule {
    rule_name         = "bronze_weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"
    lifecycle {
      delete_after = 10
    }
  }
  tags = var.tags
}

# Silver Backup Plan
resource "aws_backup_plan" "silver" {
  name = "silver-backup-plan"
  rule {
    rule_name         = "silver_daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"
    lifecycle {
      delete_after = 7
    }
  }
  tags = var.tags
}

# Gold Backup Plan
resource "aws_backup_plan" "gold" {
  name = "gold-backup-plan"
  rule {
    rule_name         = "gold_daily"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "gold_monthly"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 1 1 * ? *)"
    lifecycle {
      delete_after = 365
    }
  }
  rule {
    rule_name         = "gold_yearly"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 2 1 1 ? *)"
    lifecycle {
      delete_after = 2555
    }
  }
  tags = var.tags
}

# Premium Backup Plan
resource "aws_backup_plan" "premium" {
  name = "premium-backup-plan"
  rule {
    rule_name         = "premium_4hour"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "rate(4 hours)"
    lifecycle {
      delete_after = 1
    }
  }
  rule {
    rule_name         = "premium_daily"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "premium_monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 1 1 * ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }
  rule {
    rule_name         = "premium_yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 2 1 1 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
  tags = var.tags
}

# Backup Selections (tag-based)
resource "aws_backup_selection" "bronze" {
  name         = "bronze_selection"
  plan_id      = aws_backup_plan.bronze.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup-tier"
    value = "bronze"
  }
}

resource "aws_backup_selection" "silver" {
  name         = "silver_selection"
  plan_id      = aws_backup_plan.silver.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup-tier"
    value = "silver"
  }
}

resource "aws_backup_selection" "gold" {
  name         = "gold_selection"
  plan_id      = aws_backup_plan.gold.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup-tier"
    value = "gold"
  }
}

resource "aws_backup_selection" "premium" {
  name         = "premium_selection"
  plan_id      = aws_backup_plan.premium.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup-tier"
    value = "premium"
  }
}

# Data source for current account ID (used in KMS policy)
data "aws_caller_identity" "current" {}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    project     = "tf-eks-jofo"
    environment = "dev"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.14.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "tf-eks-jofo-dev-vpc"
  })
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "tf-eks-jofo-dev-public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + 3)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "tf-eks-jofo-dev-private-${count.index}"
  })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "tf-eks-jofo-dev-igw"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "tf-eks-jofo-dev-nat-eip"
  })
}

resource "aws_nat_gateway" "nat" {
  allocation_id     = aws_eip.nat.id
  subnet_id         = aws_subnet.public[0].id
  connectivity_type = "public"

  tags = merge(local.common_tags, {
    Name = "tf-eks-jofo-dev-nat"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "tf-eks-jofo-dev-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = merge(local.common_tags, {
    Name = "tf-eks-jofo-dev-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.0"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "create_organization" {
  description = "Whether to create the AWS Organization."
  type        = bool
  default     = true
}

variable "member_account_name" {
  description = "Name for the member account. Creation occurs only when both name and email are non-empty."
  type        = string
  default     = ""
}

variable "member_account_email" {
  description = "Email for the member account. Creation occurs only when both name and email are non-empty."
  type        = string
  default     = ""
}

variable "delegated_admin_service_principal" {
  description = "Service principal for the delegated administrator. Defaults to cloudtrail.amazonaws.com."
  type        = string
  default     = "cloudtrail.amazonaws.com"
}

variable "ou_name" {
  description = "Name for the organizational unit. Creation occurs only when both name and parent ID are non-empty."
  type        = string
  default     = ""
}

variable "ou_parent_id" {
  description = "Parent ID for the organizational unit. Required when ou_name is set."
  type        = string
  default     = ""
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------
locals {
  create_account = var.create_organization && var.member_account_name != "" && var.member_account_email != ""
  create_delegated_admin = var.create_organization && local.create_account && var.delegated_admin_service_principal != ""
  create_ou = var.ou_name != "" && var.ou_parent_id != ""
}

# -----------------------------------------------------------------------------
# Organization
# -----------------------------------------------------------------------------
resource "aws_organizations_organization" "org" {
  count = var.create_organization ? 1 : 0

  # Policy types intentionally omitted — LocalStack does not support EnablePolicyType.
  # Re-add SERVICE_CONTROL_POLICY, TAG_POLICY, and BACKUP_POLICY when the target environment supports them.
  feature_set = "ALL"

  aws_service_access_principals = [
    "access-analyzer.amazonaws.com",
    "backup.amazonaws.com",
    "cloudtrail.amazonaws.com",
    "config.amazonaws.com",
    "guardduty.amazonaws.com",
  ]
}

# -----------------------------------------------------------------------------
# Member Account
# -----------------------------------------------------------------------------
resource "aws_organizations_account" "member" {
  count = local.create_account ? 1 : 0

  name  = var.member_account_name
  email = var.member_account_email

  close_on_deletion            = false
  iam_user_access_to_billing   = "ALLOW"
  parent_id                    = aws_organizations_organization.org[0].roots[0].id

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Delegated Administrator
# -----------------------------------------------------------------------------
resource "aws_organizations_delegated_administrator" "delegated" {
  count = local.create_delegated_admin ? 1 : 0

  account_id        = aws_organizations_account.member[0].id
  service_principal = var.delegated_admin_service_principal
}

# -----------------------------------------------------------------------------
# Organizational Unit
# -----------------------------------------------------------------------------
resource "aws_organizations_organizational_unit" "ou" {
  count = local.create_ou ? 1 : 0

  name      = var.ou_name
  parent_id = var.ou_parent_id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "organization_id" {
  description = "The ID of the organization."
  value       = try(aws_organizations_organization.org[0].id, null)
}

output "organization_arn" {
  description = "The ARN of the organization."
  value       = try(aws_organizations_organization.org[0].arn, null)
}

output "organization_master_account_id" {
  description = "The ID of the master account (management account)."
  value       = try(aws_organizations_organization.org[0].master_account_id, null)
}

output "organization_master_account_arn" {
  description = "The ARN of the master account."
  value       = try(aws_organizations_organization.org[0].master_account_arn, null)
}

output "organization_master_account_email" {
  description = "The email address of the master account."
  value       = try(aws_organizations_organization.org[0].master_account_email, null)
}

output "organization_feature_set" {
  description = "The feature set of the organization."
  value       = try(aws_organizations_organization.org[0].feature_set, null)
}

output "member_account_id" {
  description = "The ID of the created member account."
  value       = try(aws_organizations_account.member[0].id, null)
}

output "member_account_arn" {
  description = "The ARN of the created member account."
  value       = try(aws_organizations_account.member[0].arn, null)
}

output "member_account_status" {
  description = "The status of the created member account."
  value       = try(aws_organizations_account.member[0].status, null)
}

output "delegated_admin_id" {
  description = "The ID of the delegated administrator."
  value       = try(aws_organizations_delegated_administrator.delegated[0].id, null)
}

output "delegated_admin_arn" {
  description = "The ARN of the delegated administrator."
  value       = try(aws_organizations_delegated_administrator.delegated[0].arn, null)
}

output "delegated_admin_account_id" {
  description = "The account ID delegated as administrator."
  value       = try(aws_organizations_delegated_administrator.delegated[0].account_id, null)
}

output "delegated_admin_service_principal" {
  description = "The service principal for which the account is delegated."
  value       = try(aws_organizations_delegated_administrator.delegated[0].service_principal, null)
}

output "organizational_unit_id" {
  description = "The ID of the organizational unit."
  value       = try(aws_organizations_organizational_unit.ou[0].id, null)
}

output "organizational_unit_arn" {
  description = "The ARN of the organizational unit."
  value       = try(aws_organizations_organizational_unit.ou[0].arn, null)
}

output "organizational_unit_name" {
  description = "The name of the organizational unit."
  value       = try(aws_organizations_organizational_unit.ou[0].name, null)
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "namespace" {
  description = "Namespace for the resource naming (e.g., company or project)"
  type        = string
  default     = "example"
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

variable "stage" {
  description = "Stage name (e.g., build, deploy)"
  type        = string
  default     = ""
}

variable "name" {
  description = "Resource name suffix (e.g., vpc)"
  type        = string
  default     = "vpc"
}

variable "vpc_cidr_block" {
  description = "Primary IPv4 CIDR block for the VPC"
  type        = string
  default     = "11.0.0.0/16"
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "assign_generated_ipv6_cidr_block" {
  description = "Assign an AWS-generated IPv6 CIDR block"
  type        = bool
  default     = true
}

variable "extra_ipv4_cidr_blocks" {
  description = "List of additional IPv4 CIDR blocks to associate with the VPC"
  type        = list(string)
  default     = []
}

variable "extra_ipv6_cidr_blocks" {
  description = "List of additional IPv6 CIDR blocks to associate with the VPC"
  type        = list(string)
  default     = []
}

variable "manage_default_route_table" {
  description = "Manage the default route table and remove all routes"
  type        = bool
  default     = false
}

variable "manage_default_network_acl" {
  description = "Manage the default network ACL and remove all rules"
  type        = bool
  default     = false
}

# Locals for naming and tagging
locals {
  name       = join("-", compact([var.namespace, var.environment, var.stage, var.name]))
  managed_by = "Terraform"
  tags = {
    Name        = local.name
    Namespace   = var.namespace
    Environment = var.environment
    Stage       = var.stage
    ManagedBy   = local.managed_by
  }
}

# VPC
resource "aws_vpc" "this" {
  cidr_block                       = var.vpc_cidr_block
  enable_dns_support               = var.enable_dns_support
  enable_dns_hostnames             = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = var.assign_generated_ipv6_cidr_block

  tags = local.tags
}

# Internet Gateway
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = local.tags
}

# Default Security Group - deny all traffic
resource "aws_default_security_group" "this" {
  vpc_id = aws_vpc.this.id

  ingress = []
  egress  = []

  tags = local.tags
}

# Default Route Table (optional)
resource "aws_default_route_table" "this" {
  count = var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this.default_route_table_id

  tags = local.tags
}

# Default Network ACL (optional)
resource "aws_default_network_acl" "this" {
  count = var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this.default_network_acl_id

  tags = local.tags
}

# Additional IPv4 CIDR associations
resource "aws_vpc_ipv4_cidr_block_association" "this" {
  count = length(var.extra_ipv4_cidr_blocks)

  vpc_id     = aws_vpc.this.id
  cidr_block = var.extra_ipv4_cidr_blocks[count.index]
}

# Additional IPv6 CIDR associations
resource "aws_vpc_ipv6_cidr_block_association" "this" {
  count = length(var.extra_ipv6_cidr_blocks)

  vpc_id          = aws_vpc.this.id
  ipv6_cidr_block = var.extra_ipv6_cidr_blocks[count.index]
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.this.id
}

output "vpc_cidr_block" {
  description = "The primary IPv4 CIDR block of the VPC"
  value       = aws_vpc.this.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "The IPv6 CIDR block of the VPC (if assigned)"
  value       = aws_vpc.this.ipv6_cidr_block
}

output "default_security_group_id" {
  description = "The ID of the default security group"
  value       = aws_default_security_group.this.id
}

output "default_route_table_id" {
  description = "The ID of the default route table"
  value       = var.manage_default_route_table ? aws_default_route_table.this[0].id : aws_vpc.this.default_route_table_id
}

output "default_network_acl_id" {
  description = "The ID of the default network ACL"
  value       = var.manage_default_network_acl ? aws_default_network_acl.this[0].id : aws_vpc.this.default_network_acl_id
}

output "internet_gateway_id" {
  description = "The ID of the internet gateway"
  value       = aws_internet_gateway.this.id
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "enabled" {
  description = "Master switch to enable/disable creation of all resources."
  type        = bool
  default     = true
}

variable "create_sg" {
  description = "When true, create a new security group. When false, use existing_sg_id."
  type        = bool
  default     = true
}

variable "existing_sg_id" {
  description = "ID of an existing security group to use when create_sg is false."
  type        = string
  default     = null
  validation {
    condition     = var.create_sg ? true : (var.existing_sg_id != null)
    error_message = "When create_sg is false, existing_sg_id must be provided."
  }
}

variable "name_prefix" {
  description = "Prefix used for naming resources."
  type        = string
  default     = "sgm"
}

variable "tags" {
  description = "A map of tags to apply to all created resources."
  type        = map(string)
  default     = {}
}

variable "prefix_list_entries" {
  description = "Entries for a managed prefix list. Each entry must have cidr and optional description."
  type = map(object({
    cidr        = string
    description = optional(string, "")
  }))
  default = {}
}

variable "prefix_list_ids" {
  description = "Map of friendly names to existing prefix list IDs. Used in rule definitions."
  type        = map(string)
  default     = {}
}

variable "ingress_rules" {
  description = "Map of ingress rules. Each key is a rule label."
  type = map(object({
    description         = optional(string, "")
    from_port           = number
    to_port             = number
    protocol            = string
    cidr_blocks         = optional(list(string), [])
    self                = optional(bool, false)
    source_security_group_id = optional(string, null)
    prefix_list_ids     = optional(list(string), [])
  }))
  default = {}
}

variable "egress_rules" {
  description = "Map of egress rules. Same structure as ingress_rules."
  type = map(object({
    description         = optional(string, "")
    from_port           = number
    to_port             = number
    protocol            = string
    cidr_blocks         = optional(list(string), [])
    self                = optional(bool, false)
    source_security_group_id = optional(string, null)
    prefix_list_ids     = optional(list(string), [])
  }))
  default = {}
}

# Locals
locals {
  sg_name = "${var.name_prefix}-sg"
  vpc_name = "${var.name_prefix}-vpc"
  tags    = merge(var.tags, { Name = local.sg_name })
  vpc_tags = merge(var.tags, { Name = local.vpc_name })

  # Resolve security group ID
  sg_id = var.enabled ? (
    var.create_sg ? aws_security_group.this[0].id : var.existing_sg_id
  ) : null

  # Resolve VPC ID (always created when enabled)
  vpc_id = var.enabled ? aws_vpc.main[0].id : null

  # Managed prefix list ID (if created)
  managed_prefix_list_id = try(aws_ec2_managed_prefix_list.this[0].id, null)

  # Combined prefix list ID lookup
  prefix_list_lookup = merge(var.prefix_list_ids, (
    local.managed_prefix_list_id != null ? { managed = local.managed_prefix_list_id } : {}
  ))

  # Flatten ingress rules into individual rule resources
  _ingress_rules_flat = flatten([
    for rk, rv in var.ingress_rules : concat(
      # Rules from CIDR blocks
      [for cidr in rv.cidr_blocks : {
        key             = "${rk}-cidr-${cidr}"
        sg_id           = local.sg_id
        description     = rv.description
        from_port       = rv.from_port
        to_port         = rv.to_port
        protocol        = rv.protocol
        cidr_ipv4       = cidr
        ref_sg_id       = null
        prefix_list_id  = null
      }],
      # Rules from prefix list IDs
      [for pl_key in rv.prefix_list_ids : {
        key             = "${rk}-pl-${pl_key}"
        sg_id           = local.sg_id
        description     = rv.description
        from_port       = rv.from_port
        to_port         = rv.to_port
        protocol        = rv.protocol
        cidr_ipv4       = null
        ref_sg_id       = null
        prefix_list_id  = try(local.prefix_list_lookup[pl_key], null)
      }],
      # Rule from self
      rv.self ? [{
        key             = "${rk}-self"
        sg_id           = local.sg_id
        description     = rv.description
        from_port       = rv.from_port
        to_port         = rv.to_port
        protocol        = rv.protocol
        cidr_ipv4       = null
        ref_sg_id       = local.sg_id
        prefix_list_id  = null
      }] : [],
      # Rule from source security group ID
      rv.source_security_group_id != null ? [{
        key             = "${rk}-srcsg"
        sg_id           = local.sg_id
        description     = rv.description
        from_port       = rv.from_port
        to_port         = rv.to_port
        protocol        = rv.protocol
        cidr_ipv4       = null
        ref_sg_id       = rv.source_security_group_id
        prefix_list_id  = null
      }] : []
    )
  ])

  ingress_flat = var.enabled ? {
    for item in local._ingress_rules_flat : item.key => item
  } : {}

  # Flatten egress rules (same logic)
  _egress_rules_flat = flatten([
    for rk, rv in var.egress_rules : concat(
      [for cidr in rv.cidr_blocks : {
        key             = "${rk}-cidr-${cidr}"
        sg_id           = local.sg_id
        description     = rv.description
        from_port       = rv.from_port
        to_port         = rv.to_port
        protocol        = rv.protocol
        cidr_ipv4       = cidr
        ref_sg_id       = null
        prefix_list_id  = null
      }],
      [for pl_key in rv.prefix_list_ids : {
        key             = "${rk}-pl-${pl_key}"
        sg_id           = local.sg_id
        description     = rv.description
        from_port       = rv.from_port
        to_port         = rv.to_port
        protocol        = rv.protocol
        cidr_ipv4       = null
        ref_sg_id       = null
        prefix_list_id  = try(local.prefix_list_lookup[pl_key], null)
      }],
      rv.self ? [{
        key             = "${rk}-self"
        sg_id           = local.sg_id
        description     = rv.description
        from_port       = rv.from_port
        to_port         = rv.to_port
        protocol        = rv.protocol
        cidr_ipv4       = null
        ref_sg_id       = local.sg_id
        prefix_list_id  = null
      }] : [],
      rv.source_security_group_id != null ? [{
        key             = "${rk}-srcsg"
        sg_id           = local.sg_id
        description     = rv.description
        from_port       = rv.from_port
        to_port         = rv.to_port
        protocol        = rv.protocol
        cidr_ipv4       = null
        ref_sg_id       = rv.source_security_group_id
        prefix_list_id  = null
      }] : []
    )
  ])

  egress_flat = var.enabled ? {
    for item in local._egress_rules_flat : item.key => item
  } : {}
}

# VPC resource (conditional on enabled)
resource "aws_vpc" "main" {
  count      = var.enabled ? 1 : 0
  cidr_block = "10.0.0.0/16"
  tags       = local.vpc_tags
}

# Security group resource (conditional)
resource "aws_security_group" "this" {
  count       = var.enabled && var.create_sg ? 1 : 0
  name        = local.sg_name
  description = "Security group managed by Terraform"
  vpc_id      = local.vpc_id
  tags        = local.tags
  lifecycle {
    create_before_destroy = true
  }
}

# Managed prefix list (conditional)
resource "aws_ec2_managed_prefix_list" "this" {
  count = var.enabled && var.create_sg && length(var.prefix_list_entries) > 0 ? 1 : 0
  name           = "${var.name_prefix}-pl"
  address_family = "IPv4"
  max_entries    = 20
  tags           = var.tags
  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }
}

# Ingress rules (one resource per flattened rule)
resource "aws_vpc_security_group_ingress_rule" "this" {
  for_each = local.ingress_flat

  security_group_id = each.value.sg_id
  cidr_ipv4         = each.value.cidr_ipv4
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  referenced_security_group_id = each.value.ref_sg_id
  prefix_list_id    = each.value.prefix_list_id
  description       = each.value.description

  tags = merge(var.tags, {
    Name = "${var.name_prefix}-ingress-${each.key}"
  })
}

# Egress rules (one resource per flattened rule)
resource "aws_vpc_security_group_egress_rule" "this" {
  for_each = local.egress_flat

  security_group_id = each.value.sg_id
  cidr_ipv4         = each.value.cidr_ipv4
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.protocol
  referenced_security_group_id = each.value.ref_sg_id
  prefix_list_id    = each.value.prefix_list_id
  description       = each.value.description

  tags = merge(var.tags, {
    Name = "${var.name_prefix}-egress-${each.key}"
  })
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "project" {
  description = "Project name"
  type        = string
  default     = "devops-poc"
}

variable "app" {
  description = "Application name"
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Deployment environment"
  type        = string
  default     = "dev"

  validation {
    condition     = contains(["dev", "prod", "stag", "qa"], var.environment)
    error_message = "Environment must be one of: dev, prod, stag, qa."
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_kms_key" "this" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = false
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "${var.project}-${var.app}-${var.environment}-kms"
    Project     = var.project
    App         = var.app
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "this" {
  bucket = "${var.project}-${var.app}-${var.environment}-terraform-${data.aws_region.current.name}"
  force_destroy = true

  tags = {
    Project     = var.project
    App         = var.app
    Environment = var.environment
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  status = "Enabled"
}

resource "aws_s3_bucket_website_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "error.html"
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "AllowSameAccountGetPutObject"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = [
          "${aws_s3_bucket.this.arn}/*"
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    http = {
      source  = "hashicorp/http"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "terraform-eks-demo"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "http" "my_ip" {
  url = "https://checkip.amazonaws.com"
}

locals {
  current_cidr = "${trimspace(data.http.my_ip.response_body)}/32"
}

# KMS key for EKS secret encryption
resource "aws_kms_key" "eks" {
  description             = "EKS Secret Encryption Key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EKS Cluster Role to use key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eks_cluster.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = "${var.cluster_name}-eks-key"
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

# Public Subnets (no automatic public IP)
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = false
  tags = {
    Name = "${var.cluster_name}-public-subnet-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.cluster_name}-igw"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "${var.cluster_name}-public-rt"
  }
}

# Route Table Associations
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Group for EKS Cluster
resource "aws_security_group" "eks_cluster" {
  name        = "${var.cluster_name}-cluster-sg"
  description = "Security group for EKS cluster control plane"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.current_cidr]
    description = "Allow HTTPS from local workstation"
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "Allow HTTPS from within VPC for private endpoint"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
    description = "Allow outbound traffic within VPC only"
  }

  tags = {
    Name = "${var.cluster_name}-cluster-sg"
  }
}

# IAM Role for EKS Cluster
data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "${var.cluster_name}-cluster-role"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

# IAM Role for Worker Nodes
data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = "${var.cluster_name}-node-role"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_worker_node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "eks_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "ecr_readonly" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "${var.cluster_name}-node-profile"
  role = aws_iam_role.eks_node.name
}

# EKS Cluster with encryption enabled and public access disabled
resource "aws_eks_cluster" "main" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  vpc_config {
    subnet_ids              = aws_subnet.public[*].id
    security_group_ids      = [aws_security_group.eks_cluster.id]
    endpoint_public_access  = false
    endpoint_private_access = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy
  ]
}

# Managed Node Group
resource "aws_eks_node_group" "main" {
  cluster_name    = aws_eks_cluster.main.name
  node_role_arn   = aws_iam_role.eks_node.arn
  subnet_ids      = aws_subnet.public[*].id
  disk_size       = 20
  instance_types  = ["t3.medium"]

  scaling_config {
    desired_size = 1
    min_size     = 1
    max_size     = 1
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_worker_node_policy,
    aws_iam_role_policy_attachment.eks_cni_policy,
    aws_iam_role_policy_attachment.ecr_readonly,
    aws_iam_role_policy_attachment.ssm_managed_instance
  ]
}

# Kubeconfig
resource "local_file" "kubeconfig" {
  filename = "${path.module}/kubeconfig"
  content  = <<-EOT
apiVersion: v1
clusters:
- cluster:
    server: ${aws_eks_cluster.main.endpoint}
    certificate-authority-data: ${aws_eks_cluster.main.certificate_authority[0].data}
  name: ${var.cluster_name}
contexts:
- context:
    cluster: ${var.cluster_name}
    user: aws
  name: ${var.cluster_name}
current-context: ${var.cluster_name}
kind: Config
preferences: {}
users:
- name: aws
  user:
    exec:
      apiVersion: client.authentication.k8s.io/v1beta1
      command: aws
      args:
      - eks
      - get-token
      - --cluster-name
      - ${var.cluster_name}
EOT
}

# aws-auth ConfigMap
resource "local_file" "aws_auth_configmap" {
  filename = "${path.module}/aws-auth-configmap.yaml"
  content  = <<-EOT
apiVersion: v1
kind: ConfigMap
metadata:
  name: aws-auth
  namespace: kube-system
data:
  mapRoles: |
    - rolearn: ${aws_iam_role.eks_node.arn}
      username: system:node:{{EC2PrivateDNSName}}
      groups:
        - system:bootstrappers
        - system:nodes
EOT
}

# Outputs
output "cluster_endpoint" {
  description = "Endpoint for EKS cluster"
  value       = aws_eks_cluster.main.endpoint
}

output "cluster_name" {
  description = "Name of the EKS cluster"
  value       = aws_eks_cluster.main.name
}

output "node_group_status" {
  description = "Status of the node group"
  value       = aws_eks_node_group.main.status
}

output "kubeconfig" {
  description = "Kubeconfig file path"
  value       = local_file.kubeconfig.filename
}

output "aws_auth_configmap" {
  description = "aws-auth ConfigMap file path"
  value       = local_file.aws_auth_configmap.filename
}

variable "admin_cidr" {
  description = "CIDR block for admin access"
  default     = "0.0.0.0/0"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "172.20.0.0/23"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "main-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-igw"
  }
}

# Availability Zones
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)
  subnet_types = ["public", "bastion", "private", "tgw"]
  subnet_list = flatten([
    for az_idx, az in local.azs : [
      for type_idx, type in local.subnet_types : {
        key    = "${az}-${type}"
        az     = az
        type   = type
        netnum = az_idx * length(local.subnet_types) + type_idx
      }
    ]
  ])
  subnet_configs = { for s in local.subnet_list : s.key => s }
}

# Subnets
resource "aws_subnet" "main" {
  for_each          = local.subnet_configs
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 3, each.value.netnum)
  availability_zone = each.value.az
  map_public_ip_on_launch = contains(["public", "bastion"], each.value.type) ? true : false
  tags = {
    Name = "${each.value.type}-${each.value.az}"
    Type = each.value.type
  }
}

# Route Tables
resource "aws_route_table" "main" {
  for_each = local.subnet_configs
  vpc_id   = aws_vpc.main.id
  tags = {
    Name = "rt-${each.value.type}-${each.value.az}"
  }
}

# Route Table Associations
resource "aws_route_table_association" "main" {
  for_each       = local.subnet_configs
  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.main[each.key].id
}

# Internet routes for public subnets only
resource "aws_route" "internet" {
  for_each = {
    for key, config in local.subnet_configs : key => config
    if contains(["public", "bastion"], config.type)
  }
  route_table_id         = aws_route_table.main[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

variable "create_ecr" {
  description = "Whether to create the ECR repository for container images"
  type        = bool
  default     = true
}

variable "zenml_version" {
  description = "ZenML version to use in the stack configuration"
  type        = string
  default     = "0.45.0"
}

locals {
  common_tags = {
    Environment = "test"
    Project     = "demo"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_kms_key" "demo_s3_kms_key" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_s3_bucket" "demo_artifact_store" {
  bucket        = "demo-artifact-store"
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "demo_artifact_store" {
  bucket = aws_s3_bucket.demo_artifact_store.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "demo_artifact_store" {
  bucket = aws_s3_bucket.demo_artifact_store.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.demo_s3_kms_key.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "demo_artifact_store" {
  bucket = aws_s3_bucket.demo_artifact_store.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_ecr_repository" "zenml_kubernetes" {
  count = var.create_ecr ? 1 : 0

  name                 = "demo-zenml-kubernetes"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "local_file" "stack_config" {
  filename = "zenml-stack.yaml"
  content  = <<-EOT
    version: ${var.zenml_version}
    aws_account_id: ${data.aws_caller_identity.current.account_id}
    region: ${data.aws_region.current.id}
    components:
      orchestrator:
        type: local
      artifact_store:
        type: s3
        bucket: ${aws_s3_bucket.demo_artifact_store.id}
      container_registry:
        type: aws
        uri: ${try(aws_ecr_repository.zenml_kubernetes[0].repository_url, "")}
      secrets_manager:
        type: aws
    EOT
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# --------------------------------------------------------------------------
# Variables
# --------------------------------------------------------------------------
variable "create_bucket" {
  description = "Flag to control creation of the S3 bucket"
  type        = bool
  default     = true
}

variable "geopolitical_agreement" {
  description = "Prerequisite agreement that must be set to true before bucket creation"
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "Exact name of the S3 bucket (provide either this or bucket_prefix)"
  type        = string
  default     = null

  validation {
    condition     = var.bucket_name == null || var.bucket_prefix == null
    error_message = "Provide exactly one of bucket_name or bucket_prefix, not both."
  }
}

variable "bucket_prefix" {
  description = "Prefix for auto‑generated bucket name (provide either this or bucket_name)"
  type        = string
  default     = "tf-s3-bucket-"
}

variable "enable_public_access_block" {
  description = "Flag to enable the public access block configuration"
  type        = bool
  default     = true
}

variable "enable_object_ownership" {
  description = "Flag to set object ownership to BucketOwnerEnforced"
  type        = bool
  default     = false
}

variable "enable_deny_insecure_transport_policy" {
  description = "Flag to attach the deny insecure transport bucket policy"
  type        = bool
  default     = false
}

variable "enable_server_side_encryption" {
  description = "Flag to enable server-side encryption (SSE-S3 by default unless overridden). Set to true and provide a CMK via server_side_encryption_configuration for SSE-KMS compliance in production."
  type        = bool
  default     = false
}

variable "additional_bucket_policies" {
  description = "List of additional bucket policy documents (JSON strings) to attach"
  type        = list(string)
  default     = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules (each is a map with keys: id, status, filter, transitions, etc.)"
  type        = list(any)
  default     = []
}

variable "replication_configuration" {
  description = "Replication configuration (map containing role_arn and rules). Empty map disables replication."
  type        = map(any)
  default     = {}
}

variable "server_side_encryption_configuration" {
  description = "Server‑side encryption configuration (map with keys: rule). Empty map uses default SSE-S3 (AES256)."
  type        = map(any)
  default     = {}
}

variable "cors_rule" {
  description = "CORS rules (list of maps, each with allowed_headers, allowed_methods, allowed_origins, etc.)"
  type        = list(any)
  default     = []
}

variable "website" {
  description = "Website configuration (map with keys: index_document, error_document, routing_rules, etc.)"
  type        = map(any)
  default     = {}
}

variable "logging" {
  description = "Logging configuration (map with keys: target_bucket, target_prefix). Empty map disables logging."
  type        = map(string)
  default     = {}
}

variable "versioning" {
  description = "Flag to enable versioning on the bucket"
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Object lock configuration (map with keys: object_lock_enabled, rule). Empty map disables lock."
  type        = map(any)
  default     = {}
}

# --------------------------------------------------------------------------
# Locals
# --------------------------------------------------------------------------
locals {
  bucket_exists = var.create_bucket && var.geopolitical_agreement

  # use the variable directly; the validation above ensures exactly one is non-null
  bucket_name = var.bucket_name != null ? var.bucket_name : (var.bucket_prefix != null ? var.bucket_prefix : "")

  # We rely on the bucket resource being present when bucket_exists is true.
  # Using try() gracefully handles the case when the resource is not created.
  bucket_id  = try(aws_s3_bucket.this[0].id, "")
  bucket_arn = try(aws_s3_bucket.this[0].arn, "")

  # Base deny‑insecure‑transport statement
  base_statement = {
    Sid       = "DenyInsecureTransport"
    Effect    = "Deny"
    Principal = "*"
    Action    = "s3:*"
    Resource  = ["${local.bucket_arn}/*", local.bucket_arn]
    Condition = {
      Bool = {
        "aws:SecureTransport" = "false"
      }
    }
  }

  # Extract statements from each additional policy document
  additional_statements = flatten(
    [for p in var.additional_bucket_policies : try(jsondecode(p).Statement, [])]
  )

  # Merge all statements into a single policy
  all_statements = concat([local.base_statement], local.additional_statements)

  # Policy JSON string (safe to compute even when bucket doesn't exist – the ARN will be empty)
  policy_json = jsonencode({
    Version   = "2012-10-17"
    Statement = local.all_statements
  })
}

# --------------------------------------------------------------------------
# S3 Bucket (conditional on create_bucket && geopolitical_agreement)
# --------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  count         = local.bucket_exists ? 1 : 0
  bucket        = local.bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# --------------------------------------------------------------------------
# Bucket policy (only when enable_deny_insecure_transport_policy is true)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "this" {
  count  = local.bucket_exists && var.enable_deny_insecure_transport_policy ? 1 : 0
  bucket = local.bucket_id
  policy = local.policy_json
}

# --------------------------------------------------------------------------
# Public access block (default true)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  count = local.bucket_exists && var.enable_public_access_block ? 1 : 0

  bucket = local.bucket_id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# --------------------------------------------------------------------------
# Object ownership controls (optional)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.bucket_exists && var.enable_object_ownership ? 1 : 0

  bucket = local.bucket_id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# --------------------------------------------------------------------------
# Lifecycle configuration (optional)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.bucket_exists && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = local.bucket_id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status
      # Only a subset of attributes shown; in production you'd expand as needed.
      filter {
        prefix = try(rule.value.filter.prefix, null)
        tag {
          key   = try(rule.value.filter.tag.key, null)
          value = try(rule.value.filter.tag.value, null)
        }
      }
      expiration {
        days = try(rule.value.expiration.days, null)
      }
      transition {
        days          = try(rule.value.transition.days, null)
        storage_class = try(rule.value.transition.storage_class, null)
      }
    }
  }
}

# --------------------------------------------------------------------------
# Replication configuration (optional)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.bucket_exists && length(var.replication_configuration) > 0 ? 1 : 0

  bucket = local.bucket_id

  role = try(var.replication_configuration.role_arn, "")

  dynamic "rule" {
    for_each = try(var.replication_configuration.rules, [])
    content {
      id     = rule.value.id
      status = rule.value.status

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
      }

      filter {
        prefix = try(rule.value.filter.prefix, null)
      }

      # Additional rule details (delete_marker_replication, etc.) omitted for brevity
    }
  }
}

# --------------------------------------------------------------------------
# Server‑side encryption (optional, default false)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.bucket_exists && var.enable_server_side_encryption ? 1 : 0

  bucket = local.bucket_id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = length(var.server_side_encryption_configuration) > 0 ? try(var.server_side_encryption_configuration.rule.sse_algorithm, "aws:kms") : "AES256"
      kms_master_key_id = length(var.server_side_encryption_configuration) > 0 ? try(var.server_side_encryption_configuration.rule.kms_master_key_id, null) : null
    }
  }
}

# --------------------------------------------------------------------------
# CORS configuration (optional)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.bucket_exists && length(var.cors_rule) > 0 ? 1 : 0

  bucket = local.bucket_id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, [])
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, [])
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# --------------------------------------------------------------------------
# Website configuration (optional)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "this" {
  count = local.bucket_exists && length(var.website) > 0 ? 1 : 0

  bucket = local.bucket_id

  index_document {
    suffix = var.website.index_document
  }

  error_document {
    key = try(var.website.error_document, null)
  }

  dynamic "routing_rule" {
    for_each = try(var.website.routing_rules, [])
    content {
      condition {
        key_prefix_equals = try(routing_rule.value.condition.key_prefix_equals, null)
        http_error_code_returned_equals = try(routing_rule.value.condition.http_error_code_returned_equals, null)
      }
      redirect {
        protocol         = try(routing_rule.value.redirect.protocol, null)
        host_name        = try(routing_rule.value.redirect.host_name, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with = try(routing_rule.value.redirect.replace_key_with, null)
        http_redirect_code = try(routing_rule.value.redirect.http_redirect_code, null)
      }
    }
  }
}

# --------------------------------------------------------------------------
# Logging configuration (optional)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "this" {
  count = local.bucket_exists && length(var.logging) > 0 ? 1 : 0

  bucket = local.bucket_id

  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

# --------------------------------------------------------------------------
# Versioning (optional)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  count = local.bucket_exists && var.versioning ? 1 : 0

  bucket = local.bucket_id

  versioning_configuration {
    status = "Enabled"
  }
}

# --------------------------------------------------------------------------
# Object lock configuration (optional)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.bucket_exists && length(var.object_lock_configuration) > 0 ? 1 : 0

  bucket = local.bucket_id

  rule {
    default_retention {
      mode  = try(var.object_lock_configuration.rule.default_retention.mode, "GOVERNANCE")
      days  = try(var.object_lock_configuration.rule.default_retention.days, null)
      years = try(var.object_lock_configuration.rule.default_retention.years, null)
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for availability zones – only for default fallback
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------- Variables ----------

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name (e.g., STAGE, PROD)"
  type        = string
  default     = "STAGE"
}

variable "elb_internal" {
  description = "If true, the ELB will be internal (private). If false, it will be public."
  type        = bool
  default     = true
}

variable "subnets" {
  description = "List of subnet IDs to associate with the ELB. If empty, uses availability_zones."
  type        = list(string)
  default     = []
}

variable "availability_zones" {
  description = "List of AZ names to use when subnets is empty. Falls back to all available AZs."
  type        = list(string)
  default     = []
}

variable "elb_listeners" {
  description = "List of listener maps. Each map must include instance_port, instance_protocol, lb_port, lb_protocol, and optionally ssl_certificate_id."
  type = list(object({
    instance_port     = number
    instance_protocol = string
    lb_port           = number
    lb_protocol       = string
    ssl_certificate_id = optional(string)
  }))
  default = [
    {
      instance_port     = 80
      instance_protocol = "HTTP"
      lb_port           = 80
      lb_protocol       = "HTTP"
    }
  ]
}

variable "health_check" {
  description = "Health check configuration for the ELB."
  type = object({
    target              = string
    interval            = number
    timeout             = number
    healthy_threshold   = number
    unhealthy_threshold = number
  })
  default = {
    target              = "HTTP:80/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }
}

variable "access_logs_enable" {
  description = "Flag to enable ELB access logging"
  type        = bool
  default     = false
}

variable "access_logs_bucket" {
  description = "Name of the S3 bucket for access logs (must be globally unique)"
  type        = string
  default     = null
}

variable "access_logs_bucket_prefix" {
  description = "Prefix for access log keys"
  type        = string
  default     = "elb-logs"
}

# Security Group Rules
variable "elb_sg_ingress_rules" {
  description = "List of ingress rules for the ELB security group."
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = [
    { from_port = 80, to_port = 80, protocol = "tcp", cidr_blocks = ["0.0.0.0/0"] },
    { from_port = 443, to_port = 443, protocol = "tcp", cidr_blocks = ["0.0.0.0/0"] }
  ]
}

variable "elb_sg_egress_rules" {
  description = "List of egress rules for the ELB security group."
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = [
    { from_port = 0, to_port = 0, protocol = "-1", cidr_blocks = ["10.0.0.0/8"] }
  ]
}

# Instance attachment
variable "enable_instance_attachment" {
  description = "If true, attach provided instance IDs to the ELB."
  type        = bool
  default     = false
}

variable "instance_ids" {
  description = "List of EC2 instance IDs to attach when enable_instance_attachment is true."
  type        = list(string)
  default     = []
}

# App cookie stickiness
variable "enable_app_cookie_stickiness" {
  description = "If true, create an application-controlled cookie stickiness policy."
  type        = bool
  default     = false
}

variable "app_cookie_name" {
  description = "Cookie name for the app cookie stickiness policy."
  type        = string
  default     = "myAppCookie"
}

variable "app_cookie_stickiness_listener_ports" {
  description = "List of ELB listener ports to apply the app cookie stickiness policy."
  type        = list(number)
  default     = [80]
}

# LB cookie stickiness
variable "enable_lb_cookie_stickiness" {
  description = "If true, create a load balancer generated cookie stickiness policy."
  type        = bool
  default     = false
}

variable "lb_cookie_expiration_period" {
  description = "Expiration period (in seconds) for the LB cookie."
  type        = number
  default     = 86400
}

variable "lb_cookie_stickiness_listener_ports" {
  description = "List of ELB listener ports to apply the LB cookie stickiness policy."
  type        = list(number)
  default     = [80]
}

# SSL negotiation policy
variable "enable_ssl_negotiation_policy" {
  description = "If true, create an SSL negotiation policy."
  type        = bool
  default     = false
}

variable "ssl_negotiation_policy_attributes" {
  description = "List of policy attributes for the SSL negotiation policy (name and value pairs)."
  type = list(object({
    name  = string
    value = string
  }))
  default = [
    { name = "Protocol-TLSv1.2", value = "true" }
  ]
}

variable "ssl_negotiation_policy_listener_ports" {
  description = "List of ELB listener ports to apply the SSL negotiation policy."
  type        = list(number)
  default     = [443]
}

# Proxy protocol policy
variable "enable_proxy_protocol" {
  description = "If true, enable proxy protocol on specified instance ports."
  type        = bool
  default     = false
}

variable "proxy_protocol_instance_ports" {
  description = "List of instance ports to enable proxy protocol."
  type        = list(number)
  default     = [80, 443]
}

# Custom load balancer policy
variable "enable_custom_load_balancer_policy" {
  description = "If true, create a custom load balancer policy."
  type        = bool
  default     = false
}

variable "custom_policy_type_name" {
  description = "Policy type name for the custom policy (e.g., 'OtherPolicyType')."
  type        = string
  default     = "OtherPolicyType"
}

variable "custom_policy_attributes" {
  description = "List of attributes for the custom policy."
  type = list(object({
    name  = string
    value = string
  }))
  default = []
}

variable "custom_policy_application_type" {
  description = "Whether to apply the custom policy to 'listener' or 'backend' ports."
  type        = string
  default     = "listener"
  validation {
    condition     = contains(["listener", "backend"], var.custom_policy_application_type)
    error_message = "custom_policy_application_type must be 'listener' or 'backend'."
  }
}

variable "custom_policy_ports" {
  description = "List of ports (listener or instance ports) to apply the custom policy."
  type        = list(number)
  default     = [80]
}

# ---------- Local values ----------

locals {
  elb_name = "${var.name_prefix}-${var.environment}-elb"

  # Determine the source for subnets/AZs
  elb_subnets            = length(var.subnets) > 0 ? var.subnets : []
  elb_availability_zones = length(var.subnets) > 0 ? [] : (length(var.availability_zones) > 0 ? var.availability_zones : data.aws_availability_zones.available.names)
}

# ---------- Security Group ----------

resource "aws_security_group" "elb_sg" {
  name        = "${local.elb_name}-sg"
  description = "Security group for ${local.elb_name}"

  dynamic "ingress" {
    for_each = var.elb_sg_ingress_rules
    content {
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  dynamic "egress" {
    for_each = var.elb_sg_egress_rules
    content {
      from_port   = egress.value.from_port
      to_port     = egress.value.to_port
      protocol    = egress.value.protocol
      cidr_blocks = egress.value.cidr_blocks
    }
  }

  tags = {
    Name = "${local.elb_name}-sg"
  }
}

# ---------- Access Logs S3 Bucket ----------

resource "aws_s3_bucket" "elb_logs" {
  count  = var.access_logs_enable ? 1 : 0
  bucket = var.access_logs_bucket

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "elb_logs" {
  count  = var.access_logs_enable ? 1 : 0
  bucket = aws_s3_bucket.elb_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "elb_logs" {
  count  = var.access_logs_enable ? 1 : 0
  bucket = aws_s3_bucket.elb_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "elb_logs" {
  count  = var.access_logs_enable ? 1 : 0
  bucket = aws_s3_bucket.elb_logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------- Classic ELB ----------

resource "aws_elb" "main" {
  name = local.elb_name

  internal = var.elb_internal

  # Subnets or availability zones
  subnets            = local.elb_subnets
  availability_zones = local.elb_availability_zones

  security_groups = [aws_security_group.elb_sg.id]

  dynamic "listener" {
    for_each = var.elb_listeners
    content {
      instance_port      = listener.value.instance_port
      instance_protocol  = listener.value.instance_protocol
      lb_port            = listener.value.lb_port
      lb_protocol        = listener.value.lb_protocol
      ssl_certificate_id = try(listener.value.ssl_certificate_id, null)
    }
  }

  health_check {
    target              = var.health_check.target
    interval            = var.health_check.interval
    timeout             = var.health_check.timeout
    healthy_threshold   = var.health_check.healthy_threshold
    unhealthy_threshold = var.health_check.unhealthy_threshold
  }

  dynamic "access_logs" {
    for_each = var.access_logs_enable ? [1] : []
    content {
      bucket        = aws_s3_bucket.elb_logs[0].id
      bucket_prefix = var.access_logs_bucket_prefix
      enabled       = true
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = local.elb_name
    Environment = var.environment
  }
}

# ---------- Instance Attachment ----------

resource "aws_elb_attachment" "main" {
  for_each = var.enable_instance_attachment ? toset(var.instance_ids) : toset([])
  elb      = aws_elb.main.id
  instance = each.value
}

# ---------- Policy Resources ----------

# App Cookie Stickiness Policy
resource "aws_load_balancer_policy" "app_cookie" {
  count              = var.enable_app_cookie_stickiness ? 1 : 0
  load_balancer_name = aws_elb.main.name
  policy_name        = "${local.elb_name}-app-cookie-stickiness"
  policy_type_name   = "AppCookieStickinessPolicyType"

  policy_attribute {
    name  = "CookieName"
    value = var.app_cookie_name
  }
}

# LB Cookie Stickiness Policy
resource "aws_load_balancer_policy" "lb_cookie" {
  count              = var.enable_lb_cookie_stickiness ? 1 : 0
  load_balancer_name = aws_elb.main.name
  policy_name        = "${local.elb_name}-lb-cookie-stickiness"
  policy_type_name   = "LBCookieStickinessPolicyType"

  policy_attribute {
    name  = "CookieExpirationPeriod"
    value = tostring(var.lb_cookie_expiration_period)
  }
}

# SSL Negotiation Policy
resource "aws_load_balancer_policy" "ssl_negotiation" {
  count              = var.enable_ssl_negotiation_policy ? 1 : 0
  load_balancer_name = aws_elb.main.name
  policy_name        = "${local.elb_name}-ssl-negotiation"
  policy_type_name   = "SSLNegotiationPolicyType"

  dynamic "policy_attribute" {
    for_each = var.ssl_negotiation_policy_attributes
    content {
      name  = policy_attribute.value.name
      value = policy_attribute.value.value
    }
  }
}

# Proxy Protocol Policy
resource "aws_proxy_protocol_policy" "main" {
  count          = var.enable_proxy_protocol ? 1 : 0
  load_balancer  = aws_elb.main.name
  instance_ports = var.proxy_protocol_instance_ports
}

# Custom Load Balancer Policy
resource "aws_load_balancer_policy" "custom" {
  count              = var.enable_custom_load_balancer_policy ? 1 : 0
  load_balancer_name = aws_elb.main.name
  policy_name        = "${local.elb_name}-custom-policy"
  policy_type_name   = var.custom_policy_type_name

  dynamic "policy_attribute" {
    for_each = var.custom_policy_attributes
    content {
      name  = policy_attribute.value.name
      value = policy_attribute.value.value
    }
  }
}

# ---------- Apply Policies to Listeners and Backend Servers ----------

locals {
  # For each listener port in app_cookie_stickiness_listener_ports, create a map with port and policy name
  app_cookie_listener_policies = var.enable_app_cookie_stickiness ? [
    for port in var.app_cookie_stickiness_listener_ports : {
      port        = port
      policy_name = aws_load_balancer_policy.app_cookie[0].policy_name
    }
  ] : []

  lb_cookie_listener_policies = var.enable_lb_cookie_stickiness ? [
    for port in var.lb_cookie_stickiness_listener_ports : {
      port        = port
      policy_name = aws_load_balancer_policy.lb_cookie[0].policy_name
    }
  ] : []

  ssl_listener_policies = var.enable_ssl_negotiation_policy ? [
    for port in var.ssl_negotiation_policy_listener_ports : {
      port        = port
      policy_name = aws_load_balancer_policy.ssl_negotiation[0].policy_name
    }
  ] : []

  custom_listener_policies = (var.enable_custom_load_balancer_policy && var.custom_policy_application_type == "listener") ? [
    for port in var.custom_policy_ports : {
      port        = port
      policy_name = aws_load_balancer_policy.custom[0].policy_name
    }
  ] : []

  # Combine all listener policy attachments (unique by port and policy name)
  listener_policy_attachments = concat(
    local.app_cookie_listener_policies,
    local.lb_cookie_listener_policies,
    local.ssl_listener_policies,
    local.custom_listener_policies
  )

  # For backend server policies (proxy protocol, custom on backend)
  custom_backend_policies = (var.enable_custom_load_balancer_policy && var.custom_policy_application_type == "backend") ? [
    for port in var.custom_policy_ports : {
      port        = port
      policy_name = aws_load_balancer_policy.custom[0].policy_name
    }
  ] : []

  backend_policy_attachments = local.custom_backend_policies
}

# Listener policy attachments
resource "aws_load_balancer_listener_policy" "main" {
  for_each = { for idx, att in local.listener_policy_attachments : "${att.port}-${att.policy_name}" => att }

  load_balancer_name = aws_elb.main.name
  load_balancer_port = each.value.port

  policy_names = [each.value.policy_name]
}

# Backend server policy attachments (custom policy only)
resource "aws_load_balancer_backend_server_policy" "main" {
  for_each = { for idx, att in local.backend_policy_attachments : "${att.port}-${att.policy_name}" => att }

  load_balancer_name = aws_elb.main.name
  instance_port      = each.value.port

  policy_names = [each.value.policy_name]
}

terraform {
  required_version = "~> 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "account_type" {
  description = "Type of account; only 'workload' creates backup plan, IAM role, and selections"
  type        = string
  default     = "workload"
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN for server-side encryption of the backup vault"
  type        = string
  default     = null
}

variable "backup_plan_name" {
  description = "Name of the backup plan"
  type        = string
  default     = "default-backup-plan"
}

variable "rule_name" {
  description = "Name of the first backup rule inside the plan"
  type        = string
  default     = "daily-backup"
}

variable "schedule" {
  description = "CRON expression for backup schedule (e.g., 'cron(0 5 * * ? *)'). Set to null for no schedule."
  type        = string
  default     = null
}

variable "start_window_minutes" {
  description = "Start window in minutes"
  type        = number
  default     = 60
}

variable "completion_window_minutes" {
  description = "Completion window in minutes"
  type        = number
  default     = 180
}

variable "cold_storage_after_days" {
  description = "Number of days after which to move backup to cold storage. Set to null to skip."
  type        = number
  default     = 30
}

variable "delete_after_days" {
  description = "Number of days after which to delete backup. Set to null to skip."
  type        = number
  default     = 90
}

variable "copy_actions" {
  description = "List of cross-region copy actions. Each entry supports destination_region and optionally lifecycle (cold_storage_after and delete_after days)."
  type = list(object({
    destination_region    = string
    cold_storage_after    = optional(number)
    delete_after          = optional(number)
  }))
  default = []
}

variable "selection_tag_key" {
  description = "Tag key for automatic backup selection"
  type        = string
  default     = "Backup"
}

variable "selection_tag_value" {
  description = "Tag value for automatic backup selection"
  type        = string
  default     = "true"
}

variable "resource_arn_list" {
  description = "List of explicit resource ARNs to back up"
  type        = list(string)
  default     = []
}

variable "iam_role_name" {
  description = "Name of the IAM role for AWS Backup"
  type        = string
  default     = "aws-backup-role"
}

variable "vault_name" {
  description = "Name of the backup vault"
  type        = string
  default     = "default-backup-vault"
}

variable "vault_lock_min_retention_days" {
  description = "Minimum retention days for vault lock (set both min and max to enable lock)"
  type        = number
  default     = null
}

variable "vault_lock_max_retention_days" {
  description = "Maximum retention days for vault lock (set both min and max to enable lock)"
  type        = number
  default     = null
}

variable "vault_access_policy_json" {
  description = "Optional JSON policy document for vault access policy"
  type        = string
  default     = null
}

variable "vault_notification_topic_arn" {
  description = "ARN of an existing SNS topic for vault notifications. If set, vault notifications are enabled."
  type        = string
  default     = null
}

variable "vault_notification_events" {
  description = "List of events for which to send vault notifications"
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

# Backup Vault (always created)
resource "aws_backup_vault" "this" {
  name = var.vault_name
  kms_key_arn = var.kms_key_arn

  lifecycle {
    prevent_destroy = true
  }
}

# Vault Lock (optional)
resource "aws_backup_vault_lock_configuration" "this" {
  count = (var.vault_lock_min_retention_days != null && var.vault_lock_max_retention_days != null) ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  min_retention_days = var.vault_lock_min_retention_days
  max_retention_days = var.vault_lock_max_retention_days
}

# Vault Access Policy (optional)
resource "aws_backup_vault_policy" "this" {
  count = var.vault_access_policy_json != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_access_policy_json
}

# Vault Notifications (optional)
resource "aws_backup_vault_notifications" "this" {
  count = var.vault_notification_topic_arn != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  sns_topic_arn     = var.vault_notification_topic_arn
  backup_vault_events = var.vault_notification_events
}

# Conditional creation only for workload accounts
locals {
  is_workload = var.account_type == "workload"
}

# IAM role for AWS Backup
resource "aws_iam_role" "backup" {
  count = local.is_workload ? 1 : 0
  name  = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  count = local.is_workload ? 1 : 0
  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Backup plan
resource "aws_backup_plan" "this" {
  count = local.is_workload ? 1 : 0
  name  = var.backup_plan_name

  rule {
    rule_name                = var.rule_name
    target_vault_name        = aws_backup_vault.this.name
    schedule                 = var.schedule
    start_window             = var.start_window_minutes   # FIXED: renamed from start_window_minutes to start_window
    completion_window        = var.completion_window_minutes # FIXED: renamed from completion_window_minutes to completion_window

    dynamic "lifecycle" {
      for_each = (var.cold_storage_after_days != null || var.delete_after_days != null) ? [1] : []
      content {
        cold_storage_after = var.cold_storage_after_days
        delete_after       = var.delete_after_days
      }
    }

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = "arn:aws:backup:${copy_action.value.destination_region}:${data.aws_caller_identity.current.account_id}:backup-vault:${var.vault_name}"
        dynamic "lifecycle" {
          for_each = (copy_action.value.cold_storage_after != null || copy_action.value.delete_after != null) ? [1] : []
          content {
            cold_storage_after = copy_action.value.cold_storage_after
            delete_after       = copy_action.value.delete_after
          }
        }
      }
    }
  }
}

# Tag-based backup selection
resource "aws_backup_selection" "by_tags" {
  count = local.is_workload ? 1 : 0
  name         = "tag-based-selection"
  iam_role_arn = aws_iam_role.backup[0].arn
  plan_id      = aws_backup_plan.this[0].id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }
}

# Explicit resource ARN backup selection
resource "aws_backup_selection" "by_arns" {
  count = local.is_workload && length(var.resource_arn_list) > 0 ? 1 : 0
  name         = "arn-based-selection"
  iam_role_arn = aws_iam_role.backup[0].arn
  plan_id      = aws_backup_plan.this[0].id
  resources    = var.resource_arn_list
}

data "aws_caller_identity" "current" {}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  name_prefix = "${var.prefix}-${var.environment}"
  # Determine if S3 buckets are needed
  artifacts_s3  = var.artifacts.type == "S3" ? true : false
  cache_s3      = var.cache.type == "S3" ? true : false
  report_export = var.create_report_group && var.report_group_config.export_config != null ? true : false
  vpc_enabled   = var.create_vpc ? true : false
}

# S3 bucket for artifacts
resource "aws_s3_bucket" "artifacts" {
  count  = local.artifacts_s3 ? 1 : 0
  bucket = "${local.name_prefix}-artifacts"
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  count  = local.artifacts_s3 ? 1 : 0
  bucket = aws_s3_bucket.artifacts[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  count  = local.artifacts_s3 ? 1 : 0
  bucket = aws_s3_bucket.artifacts[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "artifacts" {
  count  = local.artifacts_s3 ? 1 : 0
  bucket = aws_s3_bucket.artifacts[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# S3 bucket for cache
resource "aws_s3_bucket" "cache" {
  count  = local.cache_s3 ? 1 : 0
  bucket = "${local.name_prefix}-cache"
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cache" {
  count  = local.cache_s3 ? 1 : 0
  bucket = aws_s3_bucket.cache[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "cache" {
  count  = local.cache_s3 ? 1 : 0
  bucket = aws_s3_bucket.cache[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cache" {
  count  = local.cache_s3 ? 1 : 0
  bucket = aws_s3_bucket.cache[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# S3 bucket for report group export
resource "aws_s3_bucket" "report_group_export" {
  count  = local.report_export ? 1 : 0
  bucket = "${local.name_prefix}-report-export"
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "report_group_export" {
  count  = local.report_export ? 1 : 0
  bucket = aws_s3_bucket.report_group_export[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "report_group_export" {
  count  = local.report_export ? 1 : 0
  bucket = aws_s3_bucket.report_group_export[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "report_group_export" {
  count  = local.report_export ? 1 : 0
  bucket = aws_s3_bucket.report_group_export[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# CloudWatch log group
resource "aws_cloudwatch_log_group" "codebuild" {
  name              = "/aws/codebuild/${local.name_prefix}"
  retention_in_days = 30
}

# IAM role for CodeBuild
resource "aws_iam_role" "codebuild" {
  name               = "${local.name_prefix}-codebuild-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for CodeBuild
resource "aws_iam_role_policy" "codebuild_policy" {
  name   = "${local.name_prefix}-codebuild-policy"
  role   = aws_iam_role.codebuild.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      # S3 permissions for artifacts
      local.artifacts_s3 ? [
        {
          Effect   = "Allow"
          Action   = [
            "s3:PutObject",
            "s3:GetObject",
            "s3:GetObjectVersion",
            "s3:ListBucket",
            "s3:GetBucketLocation"
          ]
          Resource = [
            aws_s3_bucket.artifacts[0].arn,
            "${aws_s3_bucket.artifacts[0].arn}/*"
          ]
        }
      ] : [],
      # S3 permissions for cache
      local.cache_s3 ? [
        {
          Effect   = "Allow"
          Action   = [
            "s3:PutObject",
            "s3:GetObject",
            "s3:GetObjectVersion",
            "s3:ListBucket",
            "s3:GetBucketLocation"
          ]
          Resource = [
            aws_s3_bucket.cache[0].arn,
            "${aws_s3_bucket.cache[0].arn}/*"
          ]
        }
      ] : [],
      # CloudWatch Logs permissions
      [
        {
          Effect   = "Allow"
          Action   = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Resource = "${aws_cloudwatch_log_group.codebuild.arn}:*"
        }
      ],
      # VPC permissions (if VPC is enabled)
      local.vpc_enabled ? tolist([
        {
          Effect   = "Allow"
          Action   = [
            "ec2:CreateNetworkInterface",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DeleteNetworkInterface",
            "ec2:DescribeSubnets",
            "ec2:DescribeSecurityGroups",
            "ec2:DescribeDhcpOptions",
            "ec2:DescribeVpcs"
          ]
          Resource = "*"
        },
        {
          Effect   = "Allow"
          Action   = [
            "ec2:CreateNetworkInterfacePermission"
          ]
          Resource = "arn:aws:ec2:*:*:network-interface/*"
          Condition = {
            StringEquals = {
              "ec2:Subnet" = [
                for subnet in aws_subnet.public : subnet.arn
              ]
            }
          }
        }
      ]) : tolist([]),
      # Report group export S3 permissions
      local.report_export ? [
        {
          Effect   = "Allow"
          Action   = [
            "s3:PutObject"
          ]
          Resource = [
            aws_s3_bucket.report_group_export[0].arn,
            "${aws_s3_bucket.report_group_export[0].arn}/*"
          ]
        }
      ] : []
    )
  })
}

# VPC resources (conditional)
data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "codebuild" {
  count                = local.vpc_enabled ? 1 : 0
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = local.vpc_enabled ? length(data.aws_availability_zones.available.names) : 0
  vpc_id            = aws_vpc.codebuild[0].id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}-subnet-public-${count.index}"
  }
}

resource "aws_security_group" "codebuild" {
  count       = local.vpc_enabled ? 1 : 0
  name        = "${local.name_prefix}-sg"
  description = "Security group for CodeBuild project"
  vpc_id      = aws_vpc.codebuild[0].id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}-sg"
  }
}

# CodeBuild project
resource "aws_codebuild_project" "main" {
  count        = var.create_codebuild_project ? 1 : 0
  name         = "${local.name_prefix}-project"
  description  = "CodeBuild project for ${local.name_prefix}"
  service_role = aws_iam_role.codebuild.arn

  artifacts {
    type = var.artifacts.type
    location = var.artifacts.type == "S3" ? try(aws_s3_bucket.artifacts[0].id, null) : var.artifacts.location
    path     = var.artifacts.path
    namespace_type = var.artifacts.namespace_type
    name     = var.artifacts.name
  }

  environment {
    compute_type    = var.build_environment.compute_type
    image           = var.build_environment.image
    type            = var.build_environment.type
    privileged_mode = var.build_environment.privileged_mode
  }

  source {
    type      = var.build_source.type
    location  = var.build_source.type != "NO_SOURCE" ? var.build_source.location : null
    buildspec = var.build_source.type == "NO_SOURCE" ? "version: 0.2\nphases:\n  build:\n    commands:\n      - echo \"Build\"\n" : var.build_source.buildspec
  }

  dynamic "cache" {
    for_each = var.cache.type != "NO_CACHE" ? [var.cache] : []
    content {
      type     = cache.value.type
      location = cache.value.type == "S3" ? try(aws_s3_bucket.cache[0].id, null) : cache.value.location
    }
  }

  dynamic "logs_config" {
    for_each = var.logs_config != null ? [var.logs_config] : []
    content {
      cloudwatch_logs {
        group_name  = var.logs_config.group_name
        stream_name = var.logs_config.stream_name
      }
    }
  }

  dynamic "vpc_config" {
    for_each = local.vpc_enabled ? [1] : []
    content {
      vpc_id             = aws_vpc.codebuild[0].id
      subnets            = aws_subnet.public[*].id
      security_group_ids = [aws_security_group.codebuild[0].id]
    }
  }

  dynamic "secondary_sources" {
    for_each = var.secondary_sources
    content {
      type              = secondary_sources.value.type
      location          = secondary_sources.value.location
      source_identifier = secondary_sources.value.source_identifier
    }
  }

  dynamic "secondary_artifacts" {
    for_each = var.secondary_artifacts
    content {
      type                = secondary_artifacts.value.type
      location            = secondary_artifacts.value.location
      path                = secondary_artifacts.value.path
      namespace_type      = secondary_artifacts.value.namespace_type
      name                = secondary_artifacts.value.name
      artifact_identifier = secondary_artifacts.value.artifact_identifier
    }
  }

  tags = {
    Environment = var.environment
    Project     = var.prefix
  }
}

# Source credential (conditional)
resource "aws_codebuild_source_credential" "token" {
  count    = var.create_source_credentials ? 1 : 0
  server_type = var.source_credential_server_type
  auth_type   = "PERSONAL_ACCESS_TOKEN"
  token       = var.github_token
}

# Webhook (conditional)
resource "aws_codebuild_webhook" "main" {
  count        = var.create_webhook ? 1 : 0
  project_name = aws_codebuild_project.main[0].name

  dynamic "filter_group" {
    for_each = var.webhook_filter_groups
    content {
      dynamic "filter" {
        for_each = filter_group.value
        content {
          type    = filter.value.type
          pattern = filter.value.pattern
          exclude_matched_pattern = filter.value.exclude_matched_pattern
        }
      }
    }
  }
}

# Report group (conditional)
resource "aws_codebuild_report_group" "main" {
  count = var.create_report_group ? 1 : 0
  name  = "${local.name_prefix}-report-group"
  type  = var.report_group_config.type

  dynamic "export_config" {
    for_each = var.report_group_config.export_config != null ? [var.report_group_config.export_config] : []
    content {
      type = export_config.value.type
      s3_destination {
        bucket              = export_config.value.s3_destination.bucket
        encryption_key      = export_config.value.s3_destination.encryption_key
        encryption_disabled = export_config.value.s3_destination.encryption_disabled
        packaging           = export_config.value.s3_destination.packaging
        path                = export_config.value.s3_destination.path
      }
    }
  }
}

# Variables
variable "prefix" {
  description = "Prefix for naming resources"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

variable "create_codebuild_project" {
  description = "Flag to create the CodeBuild project"
  type        = bool
  default     = true
}

variable "create_source_credentials" {
  description = "Flag to create source credentials"
  type        = bool
  default     = false
}

variable "create_webhook" {
  description = "Flag to create webhook"
  type        = bool
  default     = false
}

variable "create_report_group" {
  description = "Flag to create report group"
  type        = bool
  default     = false
}

variable "create_vpc" {
  description = "Flag to create VPC for CodeBuild"
  type        = bool
  default     = false
}

variable "vpc_cidr" {
  description = "CIDR block for VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "github_token" {
  description = "GitHub personal access token for source credentials"
  type        = string
  sensitive   = true
  default     = ""
}

variable "source_credential_server_type" {
  description = "Server type for source credentials"
  type        = string
  default     = "GITHUB"
}

variable "build_source" {
  description = "CodeBuild project source configuration"
  type = object({
    type      = string
    location  = optional(string)
    buildspec = optional(string)
  })
  default = {
    type = "NO_SOURCE"
  }
}

variable "build_environment" {
  description = "CodeBuild environment configuration"
  type = object({
    compute_type    = string
    image           = string
    type            = string
    privileged_mode = bool
  })
  default = {
    compute_type    = "BUILD_GENERAL1_SMALL"
    image           = "aws/codebuild/standard:7.0"
    type            = "LINUX_CONTAINER"
    privileged_mode = false
  }
}

variable "artifacts" {
  description = "CodeBuild artifacts configuration"
  type = object({
    type           = string
    location       = optional(string)
    path           = optional(string)
    namespace_type = optional(string)
    name           = optional(string)
  })
  default = {
    type = "NO_ARTIFACTS"
  }
}

variable "cache" {
  description = "CodeBuild cache configuration"
  type = object({
    type     = string
    location = optional(string)
  })
  default = {
    type = "NO_CACHE"
  }
}

variable "logs_config" {
  description = "CloudWatch logs configuration for CodeBuild"
  type = object({
    group_name  = string
    stream_name = string
  })
  default = null
}

variable "secondary_sources" {
  description = "List of secondary source objects"
  type = list(object({
    type              = string
    location          = string
    source_identifier = string
  }))
  default = []
}

variable "secondary_artifacts" {
  description = "List of secondary artifact objects"
  type = list(object({
    type                = string
    location            = optional(string)
    path                = optional(string)
    namespace_type      = optional(string)
    name                = optional(string)
    artifact_identifier = string
  }))
  default = []
}

variable "report_group_config" {
  description = "Report group configuration"
  type = object({
    type = string
    export_config = optional(object({
      type = string
      s3_destination = object({
        bucket              = string
        encryption_key      = optional(string)
        encryption_disabled = optional(bool)
        packaging           = optional(string)
        path                = optional(string)
      })
    }))
  })
  default = {
    type = "TEST"
  }
}

variable "webhook_filter_groups" {
  description = "List of webhook filter groups"
  type = list(list(object({
    type    = string
    pattern = string
    exclude_matched_pattern = optional(bool)
  })))
  default = []
}

terraform {
  required_version = ">= 1.5, < 2.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "project" {
  type    = string
  default = "frontend"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name   = "${var.project}-vpc"
    Region = var.region
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.project}-private-subnet-${count.index + 1}"
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${var.project}-cluster"
}

resource "aws_ecr_repository" "main" {
  name                 = var.project
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  ecr_image_uri = "${aws_ecr_repository.main.repository_url}:latest"
}

data "aws_iam_policy_document" "ecs_task_execution_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution" {
  name               = "ecs_task_execution_role"
  assume_role_policy = data.aws_iam_policy_document.ecs_task_execution_trust.json
}

resource "aws_iam_policy" "ecs_task_execution" {
  name        = "ecs-task-execution-policy"
  description = "Policy for ECS task execution role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = aws_iam_policy.ecs_task_execution.arn
}

resource "aws_ecs_task_definition" "main" {
  family                   = "task-aplicativos"
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  container_definitions = jsonencode([
    {
      name      = "frontend"
      image     = local.ecr_image_uri
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
    }
  ])
}

resource "aws_security_group" "alb" {
  name        = "alb-sg"
  description = "Security group for internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.project}-alb-sg"
  }
}

resource "aws_lb" "main" {
  name                       = "${var.project}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.private[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "${var.project}-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name        = var.project
  port        = 80
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    path              = "/"
    healthy_threshold = 2
  }

  tags = {
    Name = "${var.project}-tg"
  }
}

resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  private_key_pem = tls_private_key.self_signed.private_key_pem

  subject {
    common_name = "${var.project}-alb"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  private_key      = tls_private_key.self_signed.private_key_pem
  certificate_body = tls_self_signed_cert.self_signed.cert_pem
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      protocol    = "HTTPS"
      port        = "443"
      host        = "#{host}"
      path        = "/#{path}"
      query       = "#{query}"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.self_signed.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_ecs_service" "main" {
  name            = "service-aplicativos"
  cluster         = aws_ecs_cluster.main.arn
  task_definition = "${aws_ecs_task_definition.main.family}:${aws_ecs_task_definition.main.revision}"
  desired_count   = 2
  launch_type     = "FARGATE"

  network_configuration {
    assign_public_ip = false
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.alb.id]
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = "frontend"
    container_port   = 80
  }

  depends_on = [
    aws_lb_listener.http,
    aws_lb_listener.https,
  ]
}

resource "aws_kms_key" "main" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "main" {
  bucket = "${var.project}-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket                  = aws_s3_bucket.main.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# CloudTrail Setup – Single main.tf

variable "trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "default-trail"
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name (random suffix appended)"
  type        = string
  default     = "cloudtrail-logs-"
}

variable "enable_kms_encryption" {
  description = "Enable customer-managed KMS key for CloudTrail log encryption"
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an AWS Organization trail"
  type        = bool
  default     = false
}

variable "retention_in_days" {
  description = "Retention period for CloudWatch Log Group (days)"
  type        = number
  default     = 365
}

variable "tags" {
  description = "Common tags to apply to all resources"
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}

# Random suffix for unique S3 bucket name
resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  bucket_name = "${var.bucket_name_prefix}${random_id.suffix.hex}"
  log_group_name = "/aws/cloudtrail/${var.trail_name}"
}

# S3 Bucket for CloudTrail logs
resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = false
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Server-side encryption: AES256 or KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms_encryption ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null
    }
  }
}

# Enable versioning for log integrity
resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Bucket policy granting CloudTrail permissions
resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json
}

data "aws_iam_policy_document" "cloudtrail_bucket" {
  # Allow CloudTrail to write and get bucket ACL
  statement {
    sid    = "CloudTrailBucketAccess"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl", "s3:PutObject"]
    resources = [
      aws_s3_bucket.cloudtrail.arn,
      "${aws_s3_bucket.cloudtrail.arn}/*"
    ]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"]
    }
  }

  # Additional permission to read objects when KMS encryption is enabled
  dynamic "statement" {
    for_each = var.enable_kms_encryption ? [1] : []
    content {
      sid    = "CloudTrailKMSGetObject"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["cloudtrail.amazonaws.com"]
      }
      actions   = ["s3:GetObject"]
      resources = ["${aws_s3_bucket.cloudtrail.arn}/*"]
      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = ["arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"]
      }
    }
  }
}

data "aws_region" "current" {}
data "aws_partition" "current" {}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = var.retention_in_days
  tags              = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# IAM Role for CloudTrail to write to CloudWatch Logs
resource "aws_iam_role" "cloudtrail" {
  name = "${var.trail_name}-cloudtrail-logs"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"
          }
        }
      }
    ]
  })
  tags = var.tags
}

# IAM Role Policy to allow CloudTrail to write to CloudWatch Log Group
resource "aws_iam_role_policy" "cloudtrail" {
  name = "${var.trail_name}-cloudtrail-logs-policy"
  role = aws_iam_role.cloudtrail.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

# Customer-managed KMS Key (conditional)
resource "aws_kms_key" "cloudtrail" {
  count = var.enable_kms_encryption ? 1 : 0
  description             = "CloudTrail encryption key for trail ${var.trail_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = data.aws_iam_policy_document.cloudtrail_kms_key_policy[0].json
  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  count = var.enable_kms_encryption ? 1 : 0
  name          = "alias/cloudtrail-${var.trail_name}"
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

# KMS Key Policy allowing CloudTrail service to use the key
data "aws_iam_policy_document" "cloudtrail_kms_key_policy" {
  count = var.enable_kms_encryption ? 1 : 0
  # Allow the AWS account to administer the key
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Allow CloudTrail service to use the key
  statement {
    sid    = "Allow CloudTrail to use KMS key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values = [var.is_organization_trail ? "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}" : "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"]
    }
    # For organization trails, also allow member accounts via organization ID condition
    dynamic "condition" {
      for_each = var.is_organization_trail ? [1] : []
      content {
        test     = "StringEquals"
        variable = "kms:CallerAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }
}

# CloudTrail Trail
resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  enable_logging                = true
  is_organization_trail         = var.is_organization_trail
  cloud_watch_logs_group_arn    = aws_cloudwatch_log_group.cloudtrail.arn
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail.arn
  kms_key_id                    = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }

  tags = var.tags
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "enable_athena" {
  type    = bool
  default = true
}

variable "athena_workgroups" {
  type = map(object({
    name                     = string
    description              = string
    engine_version           = string
    enforce_workgroup_config = bool
    output_location          = string
    encryption_option        = string
    kms_key_arn              = optional(string)
    tags                     = map(string)
  }))
  default = {}
}

variable "athena_databases" {
  type = map(object({
    name          = string
    description   = string
    location_uri  = optional(string)
    parameters    = optional(map(string))
  }))
  default = {}
}

variable "athena_named_queries" {
  type = map(object({
    name          = string
    description   = string
    database_name = string
    query_string  = string
  }))
  default = {}
}

variable "athena_data_catalogs" {
  type = map(object({
    name        = string
    description = string
    type        = string
    parameters  = map(string)
  }))
  default = {}
}

locals {
  workgroups_filtered    = var.enable_athena ? var.athena_workgroups : {}
  databases_filtered     = var.enable_athena ? var.athena_databases : {}
  named_queries_filtered = var.enable_athena ? var.athena_named_queries : {}
  data_catalogs_filtered = var.enable_athena ? var.athena_data_catalogs : {}
}

resource "random_pet" "bucket" {
  length = 2
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

data "aws_iam_policy_document" "kms_key" {
  statement {
    effect    = "Allow"
    principals {
      type        = "Service"
      identifiers = ["athena.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt"
    ]
    resources = ["*"]
  }

  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "athena" {
  description             = "KMS CMK for encrypting Athena query results in S3"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key.json
}

resource "aws_s3_bucket" "athena_output" {
  bucket = "athena-query-results-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-${random_pet.bucket.id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "athena_output" {
  bucket                  = aws_s3_bucket.athena_output.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "athena_output" {
  bucket = aws_s3_bucket.athena_output.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.athena.arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "athena_output" {
  statement {
    effect    = "Allow"
    principals {
      type        = "Service"
      identifiers = ["athena.amazonaws.com"]
    }
    actions = [
      "s3:PutObject",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.athena_output.arn,
      "${aws_s3_bucket.athena_output.arn}/*"
    ]
  }
}

resource "aws_s3_bucket_policy" "athena_output" {
  bucket = aws_s3_bucket.athena_output.id
  policy = data.aws_iam_policy_document.athena_output.json
}

resource "aws_athena_workgroup" "this" {
  for_each = local.workgroups_filtered

  name         = each.value.name
  description  = each.value.description
  force_destroy = true
  tags         = each.value.tags

  configuration {
    enforce_workgroup_configuration = each.value.enforce_workgroup_config
    engine_version {
      selected_engine_version = each.value.engine_version
    }
    result_configuration {
      output_location = each.value.output_location
      encryption_configuration {
        encryption_option = each.value.encryption_option
        kms_key_arn       = each.value.encryption_option == "SSE_KMS" ? each.value.kms_key_arn : null
      }
    }
  }
}

resource "aws_glue_catalog_database" "this" {
  for_each = local.databases_filtered

  name          = each.value.name
  description   = each.value.description
  location_uri  = each.value.location_uri
  parameters    = each.value.parameters

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_athena_named_query" "this" {
  for_each = local.named_queries_filtered

  name        = each.value.name
  description = each.value.description
  database    = each.value.database_name
  query       = each.value.query_string
  workgroup   = null
}

resource "aws_athena_data_catalog" "this" {
  for_each = local.data_catalogs_filtered

  name        = each.value.name
  description = each.value.description
  type        = each.value.type
  parameters  = each.value.parameters
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Random suffix for bucket names (when no explicit name is provided)
# ------------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "bucket_name" {
  description = "Name of the S3 bucket. If not set, a unique name is auto-generated."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Public access block
variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket"
  type        = bool
  default     = true
}
variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket"
  type        = bool
  default     = true
}
variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket"
  type        = bool
  default     = true
}
variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket"
  type        = bool
  default     = true
}

# Encryption
variable "encryption_type" {
  description = "Server-side encryption algorithm to use: 'AES256' or 'aws:kms'"
  type        = string
  default     = "AES256"
  validation {
    condition     = contains(["AES256", "aws:kms"], var.encryption_type)
    error_message = "Encryption type must be either 'AES256' or 'aws:kms'."
  }
}
variable "kms_master_key_id" {
  description = "KMS master key ID (only used when encryption_type='aws:kms')"
  type        = string
  default     = null
}

# Versioning
variable "enable_versioning" {
  description = "Enable S3 bucket versioning"
  type        = bool
  default     = false
}

# Lifecycle rules
variable "lifecycle_rules" {
  description = <<-EOT
    List of lifecycle rule objects. Each object can contain:
    - id (string, optional)
    - status (string, optional, default "Enabled")
    - filter (optional map, default {})
    - expiration (optional map, e.g., { days = 90 })
    - transition (optional list of maps, each with days and storage_class)
    - noncurrent_version_expiration (optional map)
    - noncurrent_version_transition (optional list)
    - abort_incomplete_multipart_upload (optional map, e.g., { days_after_initiation = 7 })
    - See terraform-aws-provider docs for full structure.
  EOT
  type = list(object({
    id                                     = optional(string)
    status                                 = optional(string, "Enabled")
    filter                                 = optional(map(string), {})
    expiration                             = optional(map(string))
    transition                             = optional(list(map(string)))
    noncurrent_version_expiration          = optional(map(string))
    noncurrent_version_transition          = optional(list(map(string)))
    abort_incomplete_multipart_upload      = optional(map(string))
  }))
  default = []
}

# Static website hosting
variable "enable_website" {
  description = "Enable static website hosting"
  type        = bool
  default     = false
}
variable "website_index_document" {
  description = "Index document for website hosting (e.g., 'index.html')"
  type        = string
  default     = "index.html"
}
variable "website_error_document" {
  description = "Error document for website hosting (e.g., 'error.html')"
  type        = string
  default     = null
}
variable "website_routing_rules" {
  description = "Routing rules for website hosting"
  type        = list(any)
  default     = []
}

# CORS
variable "cors_rules" {
  description = <<-EOT
    List of CORS rule objects. Each object can contain:
    - allowed_headers (list(string), optional)
    - allowed_methods (list(string), required)
    - allowed_origins (list(string), required)
    - expose_headers (list(string), optional)
    - max_age_seconds (number, optional)
  EOT
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

# Logging
variable "enable_logging" {
  description = "Enable access logging to a separate S3 bucket"
  type        = bool
  default     = false
}
variable "log_bucket_name" {
  description = "Name of the logging bucket (must be globally unique). Auto-generated if not set."
  type        = string
  default     = null
}
variable "log_prefix" {
  description = "Prefix for log objects in the logging bucket"
  type        = string
  default     = "logs/"
}

# Replication
variable "enable_replication" {
  description = "Enable cross-region or same-region replication"
  type        = bool
  default     = false
}
variable "replication_destination_bucket_name" {
  description = "Name of the destination bucket for replication (must be globally unique). Auto-generated if not set."
  type        = string
  default     = null
}
variable "replication_rules" {
  description = <<-EOT
    List of replication rule objects. Each object can contain:
    - id (string, optional)
    - status (string, optional, default "Enabled")
    - priority (number, optional)
    - filter (optional map)
    - delete_marker_replication (optional string, default "Disabled")
    - destination (required map with bucket, storage_class, etc.
          Also supports replica_kms_key_id inside encryption_configuration,
          and access_control_translation.owner)
    - source_selection_criteria (optional map)
    - existing_object_replication (optional map)
  EOT
  type = any
  default = []
}

# Object Lock
variable "enable_object_lock" {
  description = "Enable S3 Object Lock (requires versioning enabled)"
  type        = bool
  default     = false
}
variable "object_lock_mode" {
  description = "Default retention mode: 'GOVERNANCE' or 'COMPLIANCE'"
  type        = string
  default     = "GOVERNANCE"
  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "Object lock mode must be 'GOVERNANCE' or 'COMPLIANCE'."
  }
}
variable "object_lock_days" {
  description = "Number of days for default retention period"
  type        = number
  default     = 365
}

# Bucket policy: deny insecure transport
variable "deny_insecure_transport" {
  description = "Add a bucket policy statement that denies requests without SecureTransport"
  type        = bool
  default     = true
}
variable "allow_elb_log_delivery" {
  description = "Add a bucket policy statement that allows ELB/ALB to deliver logs"
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  bucket_name          = coalesce(var.bucket_name, "s3-bucket-${random_id.bucket_suffix.hex}")
  log_bucket_name      = coalesce(var.log_bucket_name, "logs-${random_id.bucket_suffix.hex}")
  replication_dest_bucket = coalesce(var.replication_destination_bucket_name, "replication-${random_id.bucket_suffix.hex}")
  common_tags          = merge(var.tags, { ManagedBy = "Terraform" })

  # Encryption configuration for the bucket
  use_kms = var.encryption_type == "aws:kms"
}

# ------------------------------------------------------------------------------
# Data sources (static metadata only)
# ------------------------------------------------------------------------------
data "aws_elb_service_account" "main" {}

# ------------------------------------------------------------------------------
# Main bucket resource
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  bucket = local.bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Public Access Block
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# ------------------------------------------------------------------------------
# Server-side encryption configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption_type
      kms_master_key_id = local.use_kms ? var.kms_master_key_id : null
    }
  }
}

# ------------------------------------------------------------------------------
# Versioning configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  count  = var.enable_versioning ? 1 : 0
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# Lifecycle configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status
      filter {
        prefix = try(rule.value.filter.prefix, null)
      }
      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }
      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }
      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
        }
      }
      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }
      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Static website hosting
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.enable_website ? 1 : 0
  bucket = aws_s3_bucket.this.id

  index_document {
    suffix = var.website_index_document
  }
  error_document {
    key = var.website_error_document
  }
  dynamic "routing_rule" {
    for_each = var.website_routing_rules
    content {
      condition {
        http_error_code_returned_equals = try(routing_rule.value.condition.http_error_code_returned_equals, null)
        key_prefix_equals               = try(routing_rule.value.condition.key_prefix_equals, null)
      }
      redirect {
        host_name               = try(routing_rule.value.redirect.host_name, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
        protocol                = try(routing_rule.value.redirect.protocol, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
      }
    }
  }
}

# ------------------------------------------------------------------------------
# CORS configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ------------------------------------------------------------------------------
# Bucket Policy
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "bucket_policy" {
  # Deny insecure transport
  dynamic "statement" {
    for_each = var.deny_insecure_transport ? [1] : []
    content {
      sid       = "DenyInsecureTransport"
      effect    = "Deny"
      principals {
        type        = "AWS"
        identifiers = ["*"]
      }
      actions   = ["s3:*"]
      resources = [
        aws_s3_bucket.this.arn,
        "${aws_s3_bucket.this.arn}/*",
      ]
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  # Allow ELB/ALB log delivery
  dynamic "statement" {
    for_each = var.allow_elb_log_delivery ? [1] : []
    content {
      sid       = "AllowELBLogDelivery"
      effect    = "Allow"
      principals {
        type        = "AWS"
        identifiers = [data.aws_elb_service_account.main.arn]
      }
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this.arn}/*"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

# ------------------------------------------------------------------------------
# Logging (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "log_bucket" {
  count  = var.enable_logging ? 1 : 0
  bucket = local.log_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  count  = var.enable_logging ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  count  = var.enable_logging ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_logging" "this" {
  count  = var.enable_logging ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = aws_s3_bucket.log_bucket[0].id
  target_prefix = var.log_prefix
}

# ------------------------------------------------------------------------------
# Replication (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "replication_destination" {
  count  = var.enable_replication ? 1 : 0
  bucket = local.replication_dest_bucket
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replication_destination" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.replication_destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replication_destination" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.replication_destination[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.replication_destination[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# IAM role for replication
resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${local.bucket_name}-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

data "aws_iam_policy_document" "replication" {
  count = var.enable_replication ? 1 : 0

  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.this.arn]
  }
  statement {
    sid    = "SourceObjectPermissions"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["${aws_s3_bucket.this.arn}/*"]
  }
  statement {
    sid    = "DestinationBucketPermissions"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]
    resources = ["${aws_s3_bucket.replication_destination[0].arn}/*"]
  }
}

resource "aws_iam_policy" "replication" {
  count  = var.enable_replication ? 1 : 0
  name   = "${local.bucket_name}-replication-policy"
  policy = data.aws_iam_policy_document.replication[0].json
  tags   = local.common_tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = var.enable_replication ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id     = rule.value.id
      status = rule.value.status
      priority = rule.value.priority
      filter {
        prefix = try(rule.value.filter.prefix, null)
      }
      delete_marker_replication {
        status = try(rule.value.delete_marker_replication, "Disabled")
      }
      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.replica_kms_key_id, null) != null ? [1] : []
          content {
            replica_kms_key_id = rule.value.destination.replica_kms_key_id
          }
        }
        dynamic "access_control_translation" {
          for_each = try(rule.value.destination.access_control_translation.owner, null) != null ? [1] : []
          content {
            owner = rule.value.destination.access_control_translation.owner
          }
        }
        account = try(rule.value.destination.account, null)
      }
      source_selection_criteria {
        sse_kms_encrypted_objects {
          status = try(rule.value.source_selection_criteria.sse_kms_encrypted_objects, "Disabled")
        }
        replica_modifications {
          status = try(rule.value.source_selection_criteria.replica_modifications, "Disabled")
        }
      }
      existing_object_replication {
        status = try(rule.value.existing_object_replication, "Disabled")
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# ------------------------------------------------------------------------------
# Object Lock (optional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.enable_object_lock ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_days
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "bucket_id" {
  description = "The ID (name) of the S3 bucket"
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket"
  value       = aws_s3_bucket.this.arn
}

output "website_endpoint" {
  description = "The website endpoint (only if website hosting is enabled)"
  value       = var.enable_website ? one(aws_s3_bucket_website_configuration.this[*].website_endpoint) : null
}

# Required providers and version
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "server_name" {
  description = "Optional name for the Transfer server. If not provided, a random name will be generated."
  type        = string
  default     = ""
}

variable "endpoint_type" {
  description = "Type of endpoint: PUBLIC or VPC"
  type        = string
  default     = "PUBLIC"
}

variable "security_policy_name" {
  description = "Security policy name for the Transfer server."
  type        = string
  default     = "TransferSecurityPolicy-2020-06"
}

variable "protocols" {
  description = "List of protocols to use (e.g., SFTP, FTPS, AS2)."
  type        = list(string)
  default     = ["SFTP"]
}

variable "identity_provider_type" {
  description = "Identity provider type: SERVICE_MANAGED, API_GATEWAY, DIRECTORY_SERVICE, LAMBDA."
  type        = string
  default     = "SERVICE_MANAGED"
}

variable "logging_role_arn" {
  description = "ARN of an existing IAM role for logging. If not provided, a new role will be created."
  type        = string
  default     = ""
}

variable "api_gateway_auth_enabled" {
  description = "Set to true to create API Gateway REST API and associated IAM role for identity provider."
  type        = bool
  default     = false
}

variable "certificate_arn" {
  description = "ARN of an ACM certificate for FTPS protocol."
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Force destroy users on deletion."
  type        = bool
  default     = true
}

variable "pre_authentication_login_banner" {
  description = "Banner displayed before authentication."
  type        = string
  default     = ""
}

variable "post_authentication_login_banner" {
  description = "Banner displayed after authentication."
  type        = string
  default     = ""
}

variable "as2_transports" {
  description = "List of AS2 transports (e.g., HTTP, HTTPS)."
  type        = list(string)
  default     = []
}

variable "passive_ip" {
  description = "Passive IP for FTPS."
  type        = string
  default     = ""
}

variable "set_stat_option" {
  description = "Enable SETSTAT option on S3 objects."
  type        = bool
  default     = false
}

variable "tls_session_resumption_mode" {
  description = "TLS session resumption mode: ENABLED, DISABLED, or ENFORCED."
  type        = string
  default     = "DISABLED"
}

variable "cloudwatch_log_group_arn" {
  description = "ARN of a CloudWatch log group for structured logs."
  type        = string
  default     = ""
}

# VPC endpoint variables (used when endpoint_type = "VPC")
variable "vpc_cidr" {
  description = "CIDR block for the VPC (auto-created when endpoint_type = VPC)."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "List of subnet CIDRs (auto-created when endpoint_type = VPC). Should match the number of subnets needed."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "security_group_ids" {
  description = "List of security group IDs for the VPC endpoint. If empty, a new security group will be created."
  type        = list(string)
  default     = []
}

# Route53 custom subdomain
variable "custom_subdomain" {
  description = "Custom subdomain for a Route53 CNAME record (e.g., 'sftp.example.com')"
  type        = string
  default     = ""
}

variable "hosted_zone_name" {
  description = "Name of the Route53 hosted zone to use for the custom subdomain."
  type        = string
  default     = ""
}

# Storage type
variable "storage_type" {
  description = "Type of storage: S3 or EFS"
  type        = string
  default     = "S3"
}

# EFS filesystem ID (if using existing EFS, but we auto-create)
variable "efs_filesystem_id" {
  description = "Existing EFS filesystem ID. If empty, a new EFS will be created when storage_type = EFS."
  type        = string
  default     = ""
}

variable "sftp_users" {
  description = <<-EOT
    Map of SFTP users. Each key is the username, and value is an object with:
    - home_directory_prefix: prefix path (e.g., "/bucket/prefix")
    - public_ssh_keys: list of SSH public keys (strings)
  EOT
  type = map(object({
    home_directory_prefix = string
    public_ssh_keys       = list(string)
  }))
  default = {}
}

# Random server name
resource "random_pet" "server_name" {
  count = var.server_name == "" ? 1 : 0
  length = 2
}

locals {
  server_name = var.server_name != "" ? var.server_name : random_pet.server_name[0].id
  create_logging_role = var.logging_role_arn == "" ? true : false
  logging_role_arn    = var.logging_role_arn != "" ? var.logging_role_arn : aws_iam_role.transfer_logging[0].arn
  create_vpc_resources = var.endpoint_type == "VPC" ? true : false
  create_api_gateway   = var.api_gateway_auth_enabled ? true : false
  create_default_sg    = var.endpoint_type == "VPC" && length(var.security_group_ids) == 0 ? true : false
  storage_s3           = var.storage_type == "S3" ? true : false
  storage_efs          = var.storage_type == "EFS" ? true : false
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

# Route53 hosted zone lookup
data "aws_route53_zone" "selected" {
  count = var.custom_subdomain != "" && var.hosted_zone_name != "" ? 1 : 0
  name  = var.hosted_zone_name
  private_zone = false
}

# IAM role for logging (if not provided)
resource "aws_iam_role" "transfer_logging" {
  count = local.create_logging_role ? 1 : 0
  name  = "${local.server_name}-logging-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count      = local.create_logging_role ? 1 : 0
  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

# Additional CloudWatch permissions if log group ARN provided
resource "aws_iam_role_policy" "cloudwatch_logging" {
  count  = var.cloudwatch_log_group_arn != "" && local.create_logging_role ? 1 : 0
  name   = "${local.server_name}-cw-logging"
  role   = aws_iam_role.transfer_logging[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = var.cloudwatch_log_group_arn
      }
    ]
  })
}

# VPC resources (auto-created when endpoint_type = VPC)
resource "aws_vpc" "transfer" {
  count                = local.create_vpc_resources ? 1 : 0
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${local.server_name}-vpc"
  }
}

resource "aws_internet_gateway" "transfer" {
  count  = local.create_vpc_resources ? 1 : 0
  vpc_id = aws_vpc.transfer[0].id
  tags = {
    Name = "${local.server_name}-igw"
  }
}

resource "aws_subnet" "transfer" {
  count                   = local.create_vpc_resources ? length(var.subnet_cidrs) : 0
  vpc_id                  = aws_vpc.transfer[0].id
  cidr_block              = var.subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = true
  tags = {
    Name = "${local.server_name}-subnet-${count.index}"
  }
}

resource "aws_route_table" "transfer" {
  count  = local.create_vpc_resources ? 1 : 0
  vpc_id = aws_vpc.transfer[0].id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.transfer[0].id
  }
  tags = {
    Name = "${local.server_name}-rt"
  }
}

resource "aws_route_table_association" "transfer" {
  count          = local.create_vpc_resources ? length(var.subnet_cidrs) : 0
  subnet_id      = aws_subnet.transfer[count.index].id
  route_table_id = aws_route_table.transfer[0].id
}

# Elastic IPs for each subnet (VPC endpoint)
resource "aws_eip" "transfer" {
  count = local.create_vpc_resources ? length(var.subnet_cidrs) : 0
  domain = "vpc"
  tags = {
    Name = "${local.server_name}-eip-${count.index}"
  }
}

# Security group (auto-created if not provided)
resource "aws_security_group" "transfer" {
  count       = local.create_default_sg ? 1 : 0
  name        = "${local.server_name}-sg"
  description = "Security group for Transfer server VPC endpoint"
  vpc_id      = aws_vpc.transfer[0].id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "${local.server_name}-sg"
  }
}

# Transfer server
resource "aws_transfer_server" "main" {
  tags                      = { Name = local.server_name }
  endpoint_type             = var.endpoint_type
  security_policy_name      = var.security_policy_name
  protocols                 = var.protocols
  identity_provider_type    = var.identity_provider_type
  logging_role              = local.logging_role_arn
  certificate               = var.certificate_arn != "" ? var.certificate_arn : null
  force_destroy             = var.force_destroy
  pre_authentication_login_banner = var.pre_authentication_login_banner != "" ? var.pre_authentication_login_banner : null
  post_authentication_login_banner = var.post_authentication_login_banner != "" ? var.post_authentication_login_banner : null
  protocol_details {
    as2_transports              = length(var.as2_transports) > 0 ? var.as2_transports : null
    passive_ip                  = var.passive_ip != "" ? var.passive_ip : null
    set_stat_option             = var.set_stat_option ? "ENABLED" : null
    tls_session_resumption_mode = var.tls_session_resumption_mode
  }

  dynamic "endpoint_details" {
    for_each = local.create_vpc_resources ? [1] : []
    content {
      vpc_id               = aws_vpc.transfer[0].id
      subnet_ids           = aws_subnet.transfer[*].id
      security_group_ids   = length(var.security_group_ids) > 0 ? var.security_group_ids : [aws_security_group.transfer[0].id]
      address_allocation_ids = aws_eip.transfer[*].id
    }
  }

  depends_on = [
    aws_iam_role.transfer_logging,
    aws_iam_role_policy_attachment.transfer_logging,
    aws_iam_role_policy.cloudwatch_logging
  ]
}

# API Gateway (if API_GATEWAY identity provider)
resource "aws_api_gateway_rest_api" "transfer_auth" {
  count       = local.create_api_gateway ? 1 : 0
  name        = "${local.server_name}-auth-api"
  description = "API Gateway for Transfer Server authentication"
}

resource "aws_iam_role" "api_gateway_auth" {
  count = local.create_api_gateway ? 1 : 0
  name  = "${local.server_name}-api-gw-auth-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "api_gateway_auth" {
  count       = local.create_api_gateway ? 1 : 0
  name        = "${local.server_name}-api-gw-auth-policy"
  description = "Policy for API Gateway to invoke Lambda (if needed)"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "api_gateway_auth" {
  count      = local.create_api_gateway ? 1 : 0
  role       = aws_iam_role.api_gateway_auth[0].name
  policy_arn = aws_iam_policy.api_gateway_auth[0].arn
}

# Route53 CNAME record
resource "aws_route53_record" "transfer" {
  count   = var.custom_subdomain != "" && var.hosted_zone_name != "" ? 1 : 0
  zone_id = data.aws_route53_zone.selected[0].zone_id
  name    = var.custom_subdomain
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.main.endpoint]
}

# KMS key for S3 bucket encryption
resource "aws_kms_key" "transfer" {
  count               = local.storage_s3 ? 1 : 0
  description         = "KMS key for Transfer S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# S3 bucket for storage (if storage_type = S3)
resource "aws_s3_bucket" "transfer" {
  count  = local.storage_s3 ? 1 : 0
  bucket = "${local.server_name}-transfer-bucket"
  force_destroy = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "transfer" {
  count  = local.storage_s3 ? 1 : 0
  bucket = aws_s3_bucket.transfer[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.transfer[0].arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "transfer" {
  count  = local.storage_s3 ? 1 : 0
  bucket = aws_s3_bucket.transfer[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "transfer" {
  count  = local.storage_s3 ? 1 : 0
  bucket = aws_s3_bucket.transfer[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# EFS filesystem (if storage_type = EFS)
resource "aws_efs_file_system" "transfer" {
  count        = local.storage_efs && var.efs_filesystem_id == "" ? 1 : 0
  creation_token = "${local.server_name}-efs"
  lifecycle {
    prevent_destroy = true
  }
  tags = {
    Name = "${local.server_name}-efs"
  }
}

# EFS Access Point for Transfer server
resource "aws_efs_access_point" "transfer" {
  count          = local.storage_efs ? 1 : 0
  file_system_id = var.efs_filesystem_id != "" ? var.efs_filesystem_id : aws_efs_file_system.transfer[0].id
  posix_user {
    uid = 1000
    gid = 1000
  }
  root_directory {
    path = "/transfer"
    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "0755"
    }
  }
}

# IAM role for each user
resource "aws_iam_role" "transfer_user" {
  for_each = var.sftp_users
  name     = "${local.server_name}-user-${each.key}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })
}

# IAM policy for each user to restrict S3 access to their prefix
resource "aws_iam_policy" "transfer_user" {
  for_each = var.sftp_users
  name     = "${local.server_name}-user-${each.key}-policy"
  policy = local.storage_s3 ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.transfer[0].id}"
        Condition = {
          StringLike = {
            "s3:prefix" = [each.value.home_directory_prefix]
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.transfer[0].id}${each.value.home_directory_prefix}*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.transfer[0].arn
      }
    ]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Resource = var.efs_filesystem_id != "" ? var.efs_filesystem_id : aws_efs_file_system.transfer[0].id
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "transfer_user" {
  for_each   = var.sftp_users
  role       = aws_iam_role.transfer_user[each.key].name
  policy_arn = aws_iam_policy.transfer_user[each.key].arn
}

# Transfer user resources
resource "aws_transfer_user" "user" {
  for_each           = var.sftp_users
  server_id          = aws_transfer_server.main.id
  user_name          = each.key
  role               = aws_iam_role.transfer_user[each.key].arn
  home_directory_type = "LOGICAL"
  home_directory_mappings {
    entry  = "/"
    target = local.storage_s3 ? "/${aws_s3_bucket.transfer[0].id}${each.value.home_directory_prefix}" : "/fsx"
  }
}

# SSH keys for each user
resource "aws_transfer_ssh_key" "user" {
  for_each = {
    for u, cfg in var.sftp_users : u => cfg
    if length(cfg.public_ssh_keys) > 0
  }
  server_id = aws_transfer_server.main.id
  user_name = each.key
  body      = each.value.public_ssh_keys[0]  # attach first key; for multiple keys, create additional resources
}

# Outputs
output "server_arn" {
  value = aws_transfer_server.main.arn
}

output "server_id" {
  value = aws_transfer_server.main.id
}

output "endpoint" {
  value = aws_transfer_server.main.endpoint
}

output "custom_domain_name" {
  value = var.custom_subdomain != "" && var.hosted_zone_name != "" ? aws_route53_record.transfer[0].fqdn : null
}

output "security_group_id" {
  value = local.create_vpc_resources ? (length(var.security_group_ids) > 0 ? var.security_group_ids[0] : aws_security_group.transfer[0].id) : null
}

output "elastic_ips" {
  value = local.create_vpc_resources ? aws_eip.transfer[*].public_ip : null
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "two-tier-vpc"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = count.index == 0 ? "10.0.1.0/24" : "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = count.index == 0 ? "10.0.3.0/24" : "10.0.4.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "two-tier-igw"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "two-tier-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "private-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "alb" {
  name        = "alb-sg"
  description = "Security group for Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "alb-sg"
  }
}

resource "aws_security_group" "asg" {
  name        = "asg-sg"
  description = "Security group for Auto Scaling Group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "asg-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Security group for RDS database"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "rds-sg"
  }
}

resource "aws_security_group_rule" "alb_ingress_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.alb.id
}

resource "aws_security_group_rule" "asg_ingress_http_from_alb" {
  type                     = "ingress"
  from_port                = 80
  to_port                  = 80
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.alb.id
  security_group_id        = aws_security_group.asg.id

  depends_on = [aws_security_group.alb]
}

resource "aws_security_group_rule" "asg_ingress_ssh" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = ["10.0.0.0/16"]
  security_group_id = aws_security_group.asg.id
}

resource "aws_security_group_rule" "rds_ingress_mysql_from_asg" {
  type                     = "ingress"
  from_port                = 3306
  to_port                  = 3306
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.asg.id
  security_group_id        = aws_security_group.rds.id

  depends_on = [aws_security_group.asg]
}

resource "aws_security_group_rule" "rds_ingress_ssh_from_asg" {
  type                     = "ingress"
  from_port                = 22
  to_port                  = 22
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.asg.id
  security_group_id        = aws_security_group.rds.id

  depends_on = [aws_security_group.asg]
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  value = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  value = aws_route_table.public.id
}

output "private_route_table_id" {
  value = aws_route_table.private.id
}

output "alb_security_group_id" {
  value = aws_security_group.alb.id
}

output "asg_security_group_id" {
  value = aws_security_group.asg.id
}

output "rds_security_group_id" {
  value = aws_security_group.rds.id
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

locals {
  cluster_name = "my-cluster"
  vpc_cidr     = "10.0.0.0/16"
  azs          = data.aws_availability_zones.available.names
  tags = {
    Environment = "production"
    Owner       = "karpenter"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------
# VPC
# -----------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = merge(local.tags, {
    Name                              = "${local.cluster_name}-public-${local.azs[count.index]}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/elb"          = "1"
  })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 2)
  availability_zone = local.azs[count.index]
  tags = merge(local.tags, {
    Name                              = "${local.cluster_name}-private-${local.azs[count.index]}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-igw"
  })
}

resource "aws_eip" "nat" {
  count  = 2
  domain = "vpc"
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-nat-${count.index}"
  })
}

resource "aws_nat_gateway" "main" {
  count         = 2
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-nat-${count.index}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = 2
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-private-rt-${count.index}"
  })
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# -----------------------------------------------------------
# EKS Cluster Security Group
# -----------------------------------------------------------
resource "aws_security_group" "cluster" {
  name        = "${local.cluster_name}-cluster-sg"
  description = "Security group for EKS cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "All outbound traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.tags, {
    Name = "${local.cluster_name}-cluster-sg"
  })
}

# -----------------------------------------------------------
# EKS Cluster IAM Role
# -----------------------------------------------------------
resource "aws_iam_role" "cluster" {
  name = "${local.cluster_name}-cluster-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "cluster" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster.name
}

# -----------------------------------------------------------
# EKS Cluster KMS Key for Secret Encryption
# -----------------------------------------------------------
resource "aws_kms_key" "eks" {
  description             = "EKS Secret Encryption Key"
  deletion_window_in_days = 7
  tags = local.tags
}

# -----------------------------------------------------------
# EKS Cluster
# -----------------------------------------------------------
resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.cluster.arn

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    security_group_ids      = [aws_security_group.cluster.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  timeouts {
    create = "30m"
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster,
    aws_subnet.private
  ]

  tags = local.tags
}

# -----------------------------------------------------------
# OIDC Provider
# -----------------------------------------------------------
resource "aws_iam_openid_connect_provider" "eks" {
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["9F3B7B0A5C6C3B7A1F2D8E4A5C6B7A1F2D8E4A5"]
  url             = aws_eks_cluster.main.identity[0].oidc[0].issuer
  tags            = local.tags
}

# -----------------------------------------------------------
# Karpenter IRSA Role
# -----------------------------------------------------------
resource "aws_iam_role" "karpenter_irsa" {
  name = "${local.cluster_name}-karpenter-irsa"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.eks.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(aws_iam_openid_connect_provider.eks.url, "https://", "")}:sub" = "system:serviceaccount:karpenter:karpenter"
          }
        }
      }
    ]
  })
  tags = local.tags
}

resource "aws_iam_policy" "karpenter" {
  name        = "${local.cluster_name}-karpenter-policy"
  description = "Policy for Karpenter IRSA"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeImages",
          "ec2:DescribeLaunchTemplateVersions",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeInstanceTypeOfferings",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeSpotPriceHistory",
          "ec2:CreateFleet",
          "ec2:CreateLaunchTemplate",
          "ec2:CreateTags",
          "ec2:DeleteLaunchTemplate",
          "ec2:RunInstances",
          "ec2:TerminateInstances"
        ]
        Resource = "*"
      },
      {
        Sid    = "SSM"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.region}:*:parameter/aws/service/eks/optimized-ami/*"
      },
      {
        Sid    = "EKS"
        Effect = "Allow"
        Action = [
          "eks:DescribeCluster"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:eks:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:cluster/${local.cluster_name}"
      },
      {
        Sid    = "IAM"
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = aws_iam_role.node.arn
      },
      {
        Sid    = "SQS"
        Effect = "Allow"
        Action = [
          "sqs:ReceiveMessage",
          "sqs:DeleteMessage",
          "sqs:GetQueueAttributes",
          "sqs:GetQueueUrl"
        ]
        Resource = aws_sqs_queue.karpenter.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "karpenter" {
  policy_arn = aws_iam_policy.karpenter.arn
  role       = aws_iam_role.karpenter_irsa.name
}

# -----------------------------------------------------------
# Node IAM Role and Instance Profile
# -----------------------------------------------------------
resource "aws_iam_role" "node" {
  name = "${local.cluster_name}-node-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_ecr" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_instance_profile" "node" {
  name = "${local.cluster_name}-node-profile"
  role = aws_iam_role.node.name
  tags = local.tags
}

# -----------------------------------------------------------
# SQS Queue KMS Key (Customer Managed)
# -----------------------------------------------------------
resource "aws_kms_key" "sqs" {
  description             = "KMS key for Karpenter SQS queue encryption"
  deletion_window_in_days = 7
  tags = local.tags
}

# -----------------------------------------------------------
# SQS Queue
# -----------------------------------------------------------
resource "aws_sqs_queue" "karpenter" {
  name                       = "Karpenter-${local.cluster_name}"
  message_retention_seconds  = 300
  kms_master_key_id          = aws_kms_key.sqs.arn

  timeouts {
    create = "5m"
  }

  depends_on = [
    aws_kms_key.sqs
  ]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudWatchEvents"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sqs:SendMessage"
        Resource = "arn:${data.aws_partition.current.partition}:sqs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:Karpenter-${local.cluster_name}"
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "Karpenter-${local.cluster_name}"
  })
}

# -----------------------------------------------------------
# CloudWatch Event Rules
# -----------------------------------------------------------
resource "aws_cloudwatch_event_rule" "health" {
  name        = "${local.cluster_name}-karpenter-health"
  description = "EC2 health events for Karpenter"
  event_pattern = jsonencode({
    source      = ["aws.health"]
    detail-type = ["AWS Health Event"]
  })
  tags = { "cluster" = local.cluster_name }
}

resource "aws_cloudwatch_event_rule" "spot" {
  name        = "${local.cluster_name}-karpenter-spot"
  description = "EC2 spot instance interruptions for Karpenter"
  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Spot Instance Interruption Warning"]
  })
  tags = { "cluster" = local.cluster_name }
}

resource "aws_cloudwatch_event_rule" "rebalance" {
  name        = "${local.cluster_name}-karpenter-rebalance"
  description = "EC2 instance rebalance recommendations for Karpenter"
  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Instance Rebalance Recommendation"]
  })
  tags = { "cluster" = local.cluster_name }
}

resource "aws_cloudwatch_event_rule" "state_change" {
  name        = "${local.cluster_name}-karpenter-state-change"
  description = "EC2 instance state change notifications for Karpenter"
  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Instance State-change Notification"]
  })
  tags = { "cluster" = local.cluster_name }
}

resource "aws_cloudwatch_event_target" "health" {
  rule      = aws_cloudwatch_event_rule.health.name
  arn       = aws_sqs_queue.karpenter.arn
  target_id = "SendToSQS"
}

resource "aws_cloudwatch_event_target" "spot" {
  rule      = aws_cloudwatch_event_rule.spot.name
  arn       = aws_sqs_queue.karpenter.arn
  target_id = "SendToSQS"
}

resource "aws_cloudwatch_event_target" "rebalance" {
  rule      = aws_cloudwatch_event_rule.rebalance.name
  arn       = aws_sqs_queue.karpenter.arn
  target_id = "SendToSQS"
}

resource "aws_cloudwatch_event_target" "state_change" {
  rule      = aws_cloudwatch_event_rule.state_change.name
  arn       = aws_sqs_queue.karpenter.arn
  target_id = "SendToSQS"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Passing cases: no environment variables
# ------------------------------------------------------------------------------
resource "aws_ecs_task_definition" "passing_no_env" {
  family = "foo"
  container_definitions = jsonencode([
    {
      name      = "bar"
      image     = "foobar"
      cpu       = 10
      memory    = 512
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
    }
  ])
}

# ------------------------------------------------------------------------------
# Passing case: non-sensitive environment variable "bar"
# ------------------------------------------------------------------------------
resource "aws_ecs_task_definition" "passing_non_sensitive_bar" {
  family = "foo"
