locals {
  project     = "demo"
  environment = "poc"
  vpc_cidr    = "10.0.0.0/16"
  public_subnet_cidrs = ["10.0.0.0/24", "10.0.2.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block = local.vpc_cidr
  tags = {
    Name        = "main"
    project     = local.project
    environment = local.environment
  }
}

resource "aws_subnet" "public" {
  count             = length(local.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name        = "public-${count.index}"
    project     = local.project
    environment = local.environment
  }
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name        = "demogwInternet"
    project     = local.project
    environment = local.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name        = "public"
    project     = local.project
    environment = local.environment
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.gw.id
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "vpc_cidr_block" {
  value = aws_vpc.main.cidr_block
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# Provider for primary region
provider "aws" {
  region = "us-east-1"
}

# Provider for destination (cross-region) resources
provider "aws" {
  alias  = "destination"
  region = var.destination_region
}

# Variables
variable "destination_region" {
  description = "The AWS region for the destination backup vault"
  type        = string
  default     = "us-east-2"
}

variable "cross_account_vault_arn" {
  description = "Optional ARN of a backup vault in another AWS account for cross-account replication. If null, no cross-account copy is configured."
  type        = string
  default     = null
}

variable "excluded_db_arns" {
  description = "List of RDS database ARNs to exclude from the backup selection"
  type        = list(string)
  default     = []
}

# Primary KMS key for backup vault encryption
resource "aws_kms_key" "primary" {
  description             = "KMS key for primary backup vault"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "primary" {
  name          = "alias/backup-primary-vault-key"
  target_key_id = aws_kms_key.primary.key_id
}

# Destination KMS key for cross-region backup vault encryption
resource "aws_kms_key" "destination" {
  provider                = aws.destination
  description             = "KMS key for destination backup vault"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "destination" {
  provider      = aws.destination
  name          = "alias/backup-destination-vault-key"
  target_key_id = aws_kms_key.destination.key_id
}

# Primary backup vault
resource "aws_backup_vault" "primary" {
  name        = "primary-backup-vault"
  kms_key_arn = aws_kms_key.primary.arn
}

# Destination backup vault (cross-region)
resource "aws_backup_vault" "destination" {
  provider    = aws.destination
  name        = "destination-backup-vault"
  kms_key_arn = aws_kms_key.destination.arn
}

# IAM role and policy attachment for AWS Backup
resource "aws_iam_role" "backup" {
  name               = "AWSBackupServiceRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.backup.name
}

# Backup plan with four rules
resource "aws_backup_plan" "rds" {
  name = "rds-backup-plan"

  rule {
    rule_name         = "daily"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 5 * * ? *)"
    lifecycle {
      delete_after = 7
    }

    dynamic "copy_action" {
      for_each = [1]
      content {
        destination_vault_arn = aws_backup_vault.destination.arn
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_vault_arn != null ? [1] : []
      content {
        destination_vault_arn = var.cross_account_vault_arn
      }
    }
  }

  rule {
    rule_name         = "weekly"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 5 ? * SUN *)"
    lifecycle {
      delete_after = 30
    }

    dynamic "copy_action" {
      for_each = [1]
      content {
        destination_vault_arn = aws_backup_vault.destination.arn
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_vault_arn != null ? [1] : []
      content {
        destination_vault_arn = var.cross_account_vault_arn
      }
    }
  }

  rule {
    rule_name         = "monthly"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 5 1 * ? *)"
    lifecycle {
      delete_after = 365
    }

    dynamic "copy_action" {
      for_each = [1]
      content {
        destination_vault_arn = aws_backup_vault.destination.arn
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_vault_arn != null ? [1] : []
      content {
        destination_vault_arn = var.cross_account_vault_arn
      }
    }
  }

  rule {
    rule_name         = "yearly"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 5 1 1 ? *)"
    lifecycle {
      delete_after = 2555
    }

    dynamic "copy_action" {
      for_each = [1]
      content {
        destination_vault_arn = aws_backup_vault.destination.arn
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_vault_arn != null ? [1] : []
      content {
        destination_vault_arn = var.cross_account_vault_arn
      }
    }
  }
}

# Backup selection: all RDS instances with tag filter, excluding specified ARNs
resource "aws_backup_selection" "rds" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "rds-backup-selection"
  plan_id      = aws_backup_plan.rds.id

  resources = [
    "arn:aws:rds:*:*:db:*"
  ]

  not_resources = var.excluded_db_arns

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "BackupType"
    value = "RDS"
  }
}

# ------------------------------------------------------------------------------
# TERRAFORM AND PROVIDER REQUIREMENTS
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "my-eks-cluster"
}

variable "oidc_provider_arn" {
  description = "ARN of the OIDC provider for the EKS cluster"
  type        = string
  default     = "arn:aws:iam::000000000000:oidc-provider/placeholder"
}

variable "namespace_service_accounts" {
  description = "List of namespace/service account pairs for the Karpenter service account"
  type = list(object({
    namespace      = string
    service_account = string
  }))
  default = [
    {
      namespace      = "karpenter"
      service_account = "karpenter"
    }
  ]
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "enable_karpenter_service_role" {
  description = "Enable creation of the Karpenter IAM service role"
  type        = bool
  default     = true
}

variable "enable_sqs_queue" {
  description = "Enable creation of the SQS queue for spot termination"
  type        = bool
  default     = true
}

variable "enable_event_rules" {
  description = "Enable creation of CloudWatch event rules"
  type        = bool
  default     = true
}

variable "enable_node_role" {
  description = "Enable creation of the node IAM role and instance profile"
  type        = bool
  default     = true
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  name_prefix = var.cluster_name
}

# ------------------------------------------------------------------------------
# DATA SOURCES (only permitted static lookups)
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# KARPENTER SERVICE ROLE (IAM role for the Karpenter service account)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "karpenter" {
  count = var.enable_karpenter_service_role ? 1 : 0

  name = "Karpenter-${local.name_prefix}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = var.oidc_provider_arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            for pair in var.namespace_service_accounts :
            "${replace(var.oidc_provider_arn, "/^.*oidc-provider\\//", "")}:sub" => "system:serviceaccount:${pair.namespace}:${pair.service_account}"
          }
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = "Karpenter-${local.name_prefix}" })
}

resource "aws_iam_policy" "karpenter" {
  count = var.enable_karpenter_service_role ? 1 : 0

  name        = "Karpenter-${local.name_prefix}"
  description = "Least privilege policy for Karpenter"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeLaunchTemplateVersions",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeSpotPriceHistory",
          "ec2:DescribeImages",
          "ec2:CreateTags",
          "ec2:RunInstances",
          "ec2:TerminateInstances",
          "ec2:DeleteLaunchTemplate"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "ssm:DescribeInstanceInformation"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "eks:DescribeCluster"
        Resource = "arn:${data.aws_partition.current.partition}:eks:us-east-1:${data.aws_caller_identity.current.account_id}:cluster/${var.cluster_name}"
      },
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = var.enable_node_role ? aws_iam_instance_profile.node[0].arn : "arn:aws:iam::*:role/Karpenter-Node-*"
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "ec2.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = "Karpenter-${local.name_prefix}" })
}

resource "aws_iam_role_policy_attachment" "karpenter" {
  count = var.enable_karpenter_service_role ? 1 : 0

  role       = aws_iam_role.karpenter[0].name
  policy_arn = aws_iam_policy.karpenter[0].arn
}

# ------------------------------------------------------------------------------
# SQS QUEUE (spot termination queue with DLQ)
# ------------------------------------------------------------------------------
resource "aws_sqs_queue" "spot_termination_dlq" {
  count = var.enable_sqs_queue ? 1 : 0

  name = "Karpenter-${local.name_prefix}-spot-termination-dlq"
  lifecycle {
    prevent_destroy = true
  }

  sqs_managed_sse_enabled = true

  tags = merge(var.tags, { Name = "Karpenter-${local.name_prefix}-spot-termination-dlq" })
}

resource "aws_sqs_queue" "spot_termination" {
  count = var.enable_sqs_queue ? 1 : 0

  name = "Karpenter-${local.name_prefix}-spot-termination"
  lifecycle {
    prevent_destroy = true
  }

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.spot_termination_dlq[0].arn
    maxReceiveCount     = 5
  })

  sqs_managed_sse_enabled = true

  tags = merge(var.tags, { Name = "Karpenter-${local.name_prefix}-spot-termination" })
}

resource "aws_sqs_queue_policy" "spot_termination" {
  count = var.enable_sqs_queue ? 1 : 0

  queue_url = aws_sqs_queue.spot_termination[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.spot_termination[0].arn
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.spot_termination[0].arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_sqs_queue.spot_termination[0].arn
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CLOUDWATCH EVENT RULES
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_event_rule" "ec2_health" {
  count = var.enable_event_rules ? 1 : 0

  name        = "Karpenter-${local.name_prefix}-EC2-Instance-Health"
  description = "Capture EC2 instance health events"

  event_pattern = jsonencode({
    source      = ["aws.health"]
    detail-type = ["AWS Health Event"]
    resources   = ["arn:${data.aws_partition.current.partition}:ec2:us-east-1:*:instance/*"]
  })

  tags = merge(var.tags, { Name = "Karpenter-${local.name_prefix}-EC2-Instance-Health" })
}

resource "aws_cloudwatch_event_rule" "spot_interruption" {
  count = var.enable_event_rules ? 1 : 0

  name        = "Karpenter-${local.name_prefix}-EC2-Spot-Instance-Interruption"
  description = "Capture EC2 spot instance interruption warnings"

  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Spot Instance Interruption Warning"]
  })

  tags = merge(var.tags, { Name = "Karpenter-${local.name_prefix}-EC2-Spot-Instance-Interruption" })
}

resource "aws_cloudwatch_event_rule" "instance_rebalance" {
  count = var.enable_event_rules ? 1 : 0

  name        = "Karpenter-${local.name_prefix}-EC2-Instance-Rebalance"
  description = "Capture EC2 instance rebalance recommendations"

  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Instance Rebalance Recommendation"]
  })

  tags = merge(var.tags, { Name = "Karpenter-${local.name_prefix}-EC2-Instance-Rebalance" })
}

resource "aws_cloudwatch_event_rule" "instance_state_change" {
  count = var.enable_event_rules ? 1 : 0

  name        = "Karpenter-${local.name_prefix}-EC2-InstanceState-Change"
  description = "Capture EC2 instance state changes"

  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Instance State-change Notification"]
    detail = {
      state = ["running"]
    }
  })

  tags = merge(var.tags, { Name = "Karpenter-${local.name_prefix}-EC2-InstanceState-Change" })
}

resource "aws_cloudwatch_event_target" "ec2_health" {
  count = var.enable_event_rules ? 1 : 0

  rule     = aws_cloudwatch_event_rule.ec2_health[0].name
  arn      = aws_sqs_queue.spot_termination[0].arn
  target_id = "Karpenter-SQS"
}

resource "aws_cloudwatch_event_target" "spot_interruption" {
  count = var.enable_event_rules ? 1 : 0

  rule     = aws_cloudwatch_event_rule.spot_interruption[0].name
  arn      = aws_sqs_queue.spot_termination[0].arn
  target_id = "Karpenter-SQS"
}

resource "aws_cloudwatch_event_target" "instance_rebalance" {
  count = var.enable_event_rules ? 1 : 0

  rule     = aws_cloudwatch_event_rule.instance_rebalance[0].name
  arn      = aws_sqs_queue.spot_termination[0].arn
  target_id = "Karpenter-SQS"
}

resource "aws_cloudwatch_event_target" "instance_state_change" {
  count = var.enable_event_rules ? 1 : 0

  rule     = aws_cloudwatch_event_rule.instance_state_change[0].name
  arn      = aws_sqs_queue.spot_termination[0].arn
  target_id = "Karpenter-SQS"
}

# ------------------------------------------------------------------------------
# NODE ROLE (IAM role for Karpenter node instances)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "node" {
  count = var.enable_node_role ? 1 : 0

  name = "Karpenter-Node-${local.name_prefix}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.tags, { Name = "Karpenter-Node-${local.name_prefix}" })
}

resource "aws_iam_role_policy_attachment" "node_eks_worker" {
  count = var.enable_node_role ? 1 : 0

  role       = aws_iam_role.node[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  count = var.enable_node_role ? 1 : 0

  role       = aws_iam_role.node[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr_readonly" {
  count = var.enable_node_role ? 1 : 0

  role       = aws_iam_role.node[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_instance_profile" "node" {
  count = var.enable_node_role ? 1 : 0

  name = "Karpenter-Node-${local.name_prefix}"
  role = aws_iam_role.node[0].name

  tags = merge(var.tags, { Name = "Karpenter-Node-${local.name_prefix}" })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "environment_name" {
  description = "Name used as a prefix for resource tags"
  type        = string
  default     = "dev"
}

variable "vpc_id" {
  description = "Optional existing VPC ID. If provided, the template will use this VPC instead of creating a new one."
  type        = string
  default     = null
}

variable "create_private_subnets" {
  description = "Boolean to control creation of private subnets, NAT Gateway, and associated route table."
  type        = bool
  default     = false
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC (used only when creating a new VPC)"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

locals {
  vpc_id = var.vpc_id != null ? var.vpc_id : (
    var.vpc_id == null ? aws_vpc.main[0].id : null
  )
}

# VPC creation (only when vpc_id is not provided)
resource "aws_vpc" "main" {
  count = var.vpc_id == null ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment_name}-vpc"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = 2

  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = var.public_subnet_cidrs[count.index]
  vpc_id            = local.vpc_id

  tags = {
    Name = "${var.environment_name}-public-${count.index + 1}"
  }
}

# Private subnets (conditional)
resource "aws_subnet" "private" {
  count = var.create_private_subnets ? 2 : 0

  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = var.private_subnet_cidrs[count.index]
  vpc_id            = local.vpc_id

  tags = {
    Name = "${var.environment_name}-private-${count.index + 1}"
  }
}

# Internet Gateway (only when VPC is created)
resource "aws_internet_gateway" "main" {
  count = var.vpc_id == null ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = "${var.environment_name}-igw"
  }
}

# Public route table (always created)
resource "aws_route_table" "public" {
  count = 1

  vpc_id = local.vpc_id

  tags = {
    Name = "${var.environment_name}-public-rt"
  }
}

# Default route to internet via IGW (only when IGW is created)
resource "aws_route" "public_internet" {
  count = var.vpc_id == null ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

# Associate public subnets to public route table
resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Elastic IP and NAT Gateway (only when private subnets are created)
resource "aws_eip" "nat" {
  count = var.create_private_subnets ? 1 : 0

  domain = "vpc"

  tags = {
    Name = "${var.environment_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  count = var.create_private_subnets ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.environment_name}-nat"
  }

  depends_on = [aws_eip.nat]
}

# Private route table (conditional)
resource "aws_route_table" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = local.vpc_id

  tags = {
    Name = "${var.environment_name}-private-rt"
  }
}

# Default route from private subnets to NAT Gateway
resource "aws_route" "private_nat" {
  count = var.create_private_subnets ? 1 : 0

  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[0].id
}

# Associate private subnets to private route table
resource "aws_route_table_association" "private" {
  count = var.create_private_subnets ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = local.vpc_id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets (empty list if not created)"
  value       = try(aws_subnet.private[*].id, [])
}

output "public_subnet_list" {
  description = "List of public subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_list" {
  description = "List of private subnet IDs (empty list if not created)"
  value       = try(aws_subnet.private[*].id, [])
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_profile" {
  description = "AWS CLI profile name"
  type        = string
  default     = "default"
}

variable "aws_shared_credentials_file" {
  description = "Path to AWS shared credentials file"
  type        = string
  default     = "~/.aws/credentials"
}

variable "assume_role_principal_arn" {
  description = "ARN of principal allowed to assume roles for demo roles"
  type        = string
  default     = ""
}

variable "root_user_arn" {
  description = "ARN of root user for no-policy role trust"
  type        = string
  default     = ""
}

data "aws_caller_identity" "current" {}

locals {
  assume_role_principal = var.assume_role_principal_arn != "" ? var.assume_role_principal_arn : "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
  root_user_principal   = var.root_user_arn != "" ? var.root_user_arn : "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
}

data "aws_iam_policy_document" "assume_role_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = [local.assume_role_principal]
    }
  }
}

data "aws_iam_policy_document" "root_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = [local.root_user_principal]
    }
  }
}

# ------------------------------------------------------------------------------
# Policy 1: ec2:DescribeInstances and ec2:RunInstances
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_describe_run" {
  statement {
    actions   = ["ec2:DescribeInstances", "ec2:RunInstances"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ec2_describe_run" {
  name        = "demo-ec2-describe-run"
  description = "Policy allowing ec2:DescribeInstances and ec2:RunInstances"
  policy      = data.aws_iam_policy_document.ec2_describe_run.json
}

resource "aws_iam_user" "ec2_describe_run" {
  name = "user-ec2-describe-run"
}

resource "aws_iam_user_policy_attachment" "ec2_describe_run" {
  user       = aws_iam_user.ec2_describe_run.name
  policy_arn = aws_iam_policy.ec2_describe_run.arn
}

resource "aws_iam_role" "ec2_describe_run" {
  name               = "role-ec2-describe-run"
  assume_role_policy = data.aws_iam_policy_document.assume_role_trust.json
}

resource "aws_iam_role_policy_attachment" "ec2_describe_run" {
  role       = aws_iam_role.ec2_describe_run.name
  policy_arn = aws_iam_policy.ec2_describe_run.arn
}

resource "aws_iam_access_key" "ec2_describe_run" {
  user = aws_iam_user.ec2_describe_run.name
}

