  statement {
    actions   = ["iam:CreatePolicyVersion"]
    resources = ["arn:aws:iam::*:policy/fn2-*"]
  }
}

resource "aws_iam_policy" "create_policy_version_fn2" {
  name        = "demo-create-policy-version-fn2"
