# ------------------------------------------------------------------------------
# Policy 4: iam:CreatePolicyVersion with DateGreaterThan condition
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "create_policy_version_dategreater" {
  statement {
    actions   = ["iam:CreatePolicyVersion"]
    resources = ["*"]
    condition {
      test     = "DateGreaterThan"
      variable = "aws:TokenIssueTime"
      values   = ["2020-01-01T00:00:00Z"]
    }
  }
}

resource "aws_iam_policy" "create_policy_version_dategreater" {
  name        = "demo-create-policy-version-dategreater"
  description = "Policy allowing iam:CreatePolicyVersion on all resources with DateGreaterThan condition"
  policy      = data.aws_iam_policy_document.create_policy_version_dategreater.json
}

resource "aws_iam_user" "create_policy_version_dategreater" {
  name = "user-create-policy-version-dategreater"
}

resource "aws_iam_user_policy_attachment" "create_policy_version_dategreater" {
  user       = aws_iam_user.create_policy_version_dategreater.name
  policy_arn = aws_iam_policy.create_policy_version_dategreater.arn
}

resource "aws_iam_role" "create_policy_version_dategreater" {
  name               = "role-create-policy-version-dategreater"
  assume_role_policy = data.aws_iam_policy_document.assume_role_trust.json
}

resource "aws_iam_role_policy_attachment" "create_policy_version_dategreater" {
  role       = aws_iam_role.create_policy_version_dategreater.name
  policy_arn = aws_iam_policy.create_policy_version_dategreater.arn
}

resource "aws_iam_access_key" "create_policy_version_dategreater" {
  user = aws_iam_user.create_policy_version_dategreater.name
}

# ------------------------------------------------------------------------------
# Policy 5: NotAction – allow everything except iam:Update*, iam:Create*, iam:Attach*
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "notaction_iam" {
  statement {
    effect    = "Allow"
    not_actions = [
      "iam:Update*",
      "iam:Create*",
      "iam:Attach*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "notaction_iam" {
  name        = "demo-notaction-iam"
  description = "Policy allowing all except iam:Update*, iam:Create*, iam:Attach*"
