resource "aws_iam_role_policy_attachment" "create_policy_version_dateless" {
  role       = aws_iam_role.create_policy_version_dateless.name
  policy_arn = aws_iam_policy.create_policy_version_dateless.arn
}

resource "aws_iam_access_key" "create_policy_version_dateless" {
  user = aws_iam_user.create_policy_version_dateless.name
}

# ------------------------------------------------------------------------------
# Additional role with no attached policies, trusting root user
# ------------------------------------------------------------------------------
resource "aws_iam_role" "no_policy_role" {
  name               = "role-no-policy"
  assume_role_policy = data.aws_iam_policy_document.root_trust.json
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "web_subnet_cidrs" {
  description = "CIDR blocks for web (public) subnets"
  type        = list(string)
  default     = ["10.16.1.0/24", "10.16.2.0/24", "10.16.3.0/24"]
}

variable "app_subnet_cidrs" {
  description = "CIDR blocks for app (private) subnets"
  type        = list(string)
  default     = ["10.16.10.0/24", "10.16.11.0/24", "10.16.12.0/24"]
}

variable "db_subnet_cidrs" {
  description = "CIDR blocks for db (private) subnets"
  type        = list(string)
  default     = ["10.16.20.0/24", "10.16.21.0/24", "10.16.22.0/24"]
}

variable "reserved_subnet_cidrs" {
  description = "CIDR blocks for reserved (private) subnets"
  type        = list(string)
  default     = ["10.16.30.0/24", "10.16.31.0/24", "10.16.32.0/24"]
}

variable "interface_endpoint_services" {
  description = "List of AWS service names for Interface VPC Endpoints (e.g., com.amazonaws.region.ec2)"
  type        = list(string)
  default     = []
}

variable "gateway_endpoint_service" {
  description = "Service name for the Gateway VPC Endpoint (e.g., com.amazonaws.region.s3)"
  type        = string
  default     = null
}

# Data sources for static provider metadata
data "aws_availability_zones" "available" {
  state = "available"
}

# Random suffix for VPC name
resource "random_integer" "vpc_suffix" {
  min = 1
  max = 99999
}

# Shuffle AZs to distribute subnets randomly
resource "random_shuffle" "azs" {
  input        = data.aws_availability_zones.available.names
  keepers = {
    vpc_id = random_integer.vpc_suffix.id
  }
}

locals {
  shuffled_azs = random_shuffle.azs.result
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "tf-project-${random_integer.vpc_suffix.result}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Web (public) subnets
resource "aws_subnet" "web" {
  count = length(var.web_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.web_subnet_cidrs[count.index]
  availability_zone = local.shuffled_azs[count.index % length(local.shuffled_azs)]
  map_public_ip_on_launch = false

  tags = {
    Name = "web-${count.index + 1}-${element(split("-", local.shuffled_azs[count.index % length(local.shuffled_azs)]), 1)}"
  }
}

# App (private) subnets
resource "aws_subnet" "app" {
  count = length(var.app_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.app_subnet_cidrs[count.index]
  availability_zone = local.shuffled_azs[count.index % length(local.shuffled_azs)]
  map_public_ip_on_launch = false

  tags = {
    Name = "app-${count.index + 1}-${element(split("-", local.shuffled_azs[count.index % length(local.shuffled_azs)]), 1)}"
  }
}

# DB (private) subnets
resource "aws_subnet" "db" {
  count = length(var.db_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.db_subnet_cidrs[count.index]
  availability_zone = local.shuffled_azs[count.index % length(local.shuffled_azs)]
  map_public_ip_on_launch = false

  tags = {
    Name = "db-${count.index + 1}-${element(split("-", local.shuffled_azs[count.index % length(local.shuffled_azs)]), 1)}"
  }
}

# Reserved (private) subnets
resource "aws_subnet" "reserved" {
  count = length(var.reserved_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.reserved_subnet_cidrs[count.index]
  availability_zone = local.shuffled_azs[count.index % length(local.shuffled_azs)]
  map_public_ip_on_launch = false

  tags = {
    Name = "reserved-${count.index + 1}-${element(split("-", local.shuffled_azs[count.index % length(local.shuffled_azs)]), 1)}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "tf-project-igw"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "tf-project-public"
  }
}

# Public route table associations with web subnets
resource "aws_route_table_association" "public" {
  count = length(var.web_subnet_cidrs)

  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Route Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "tf-project-private"
  }
}

# Private route table associations with app, db, reserved subnets
resource "aws_route_table_association" "private" {
  count = length(var.app_subnet_cidrs) + length(var.db_subnet_cidrs) + length(var.reserved_subnet_cidrs)

  subnet_id = element(
    concat(aws_subnet.app[*].id, aws_subnet.db[*].id, aws_subnet.reserved[*].id),
    count.index
  )
  route_table_id = aws_route_table.private.id
}

# Security group for VPC Endpoints
resource "aws_security_group" "endpoint" {
  name        = "vpc-endpoint-sg"
  description = "Security group for VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "vpc-endpoint-sg"
  }
}

# Locals for private subnet IDs (used for interface endpoints)
locals {
  private_subnet_ids = concat(aws_subnet.app[*].id, aws_subnet.db[*].id, aws_subnet.reserved[*].id)
}

# Interface VPC Endpoints
resource "aws_vpc_endpoint" "interface" {
  count = length(var.interface_endpoint_services)

  vpc_id              = aws_vpc.main.id
  service_name        = var.interface_endpoint_services[count.index]
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = local.private_subnet_ids
  security_group_ids  = [aws_security_group.endpoint.id]

  tags = {
    Name = "vpc-endpoint-interface-${count.index + 1}"
  }
}

# Gateway VPC Endpoint
resource "aws_vpc_endpoint" "gateway" {
  count = var.gateway_endpoint_service != null ? 1 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = var.gateway_endpoint_service
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = {
    Name = "vpc-endpoint-gateway"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  prefix = var.prefix
  azs    = slice(data.aws_availability_zones.available.names, 0, 3)
}

variable "prefix" {
  description = "Prefix for resource names and tags"
  type        = string
  default     = "n8n"
}

variable "container_image" {
  description = "Container image for the n8n application"
  type        = string
  default     = "n8nio/n8n:stable"
}

variable "webhook_url" {
  description = "WEBHOOK_URL environment variable for n8n"
  type        = string
  default     = ""
}

variable "certificate_arn" {
  description = "ARN of an ACM certificate for HTTPS listener; if empty, a self‑signed certificate is used"
  type        = string
  default     = ""
}

# ------------------------------------------------------------------------------
# Self‑signed certificate (fallback when certificate_arn is empty)
# ------------------------------------------------------------------------------
resource "tls_private_key" "self_signed" {
  count     = var.certificate_arn == "" ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count                 = var.certificate_arn == "" ? 1 : 0
  private_key_pem       = tls_private_key.self_signed[0].private_key_pem
  validity_period_hours = 87600

  subject {
    common_name = "self-signed.${local.prefix}.internal"
  }

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count            = var.certificate_arn == "" ? 1 : 0
  private_key      = tls_private_key.self_signed[0].private_key_pem
  certificate_body = tls_self_signed_cert.self_signed[0].cert_pem
}

locals {
  self_signed_cert_arn = one(aws_acm_certificate.self_signed[*].arn)
  lb_certificate_arn   = var.certificate_arn != "" ? var.certificate_arn : local.self_signed_cert_arn
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = local.prefix
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = local.prefix
  }
}

# ------------------------------------------------------------------------------
# Subnets
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count             = length(local.azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = local.azs[count.index]
  map_public_ip_on_launch = false   # ECS service assigns public IPs explicitly
  tags = {
    Name = "${local.prefix}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = length(local.azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 3)
  availability_zone = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${local.prefix}-private-${count.index}"
  }
}

# ------------------------------------------------------------------------------
# Route Tables
# ------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${local.prefix}-public"
  }
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${local.prefix}-private"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# Security Groups
# ------------------------------------------------------------------------------
resource "aws_security_group" "alb" {
  name        = "${local.prefix}-alb-sg"
  description = "Security group for the ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.prefix}-alb-sg"
  }
}

resource "aws_security_group" "ecs_tasks" {
  name        = "${local.prefix}-ecs-tasks-sg"
  description = "Security group for ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Allow traffic from ALB to n8n"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.prefix}-ecs-tasks-sg"
  }
}

resource "aws_security_group" "efs" {
  name        = "${local.prefix}-efs-sg"
  description = "Security group for EFS mount targets"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "NFS from ECS tasks"
    from_port       = 2049
    to_port         = 2049
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_tasks.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.prefix}-efs-sg"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.prefix}-vpc-endpoints-sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTPS from ECS tasks"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_tasks.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.prefix}-vpc-endpoints-sg"
  }
}

# ------------------------------------------------------------------------------
# VPC Endpoints
# ------------------------------------------------------------------------------
resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.prefix}-ecr-dkr-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.prefix}-ecr-api-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.prefix}-logs-endpoint"
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]
  tags = {
    Name = "${local.prefix}-s3-endpoint"
  }
}

# ------------------------------------------------------------------------------
# Load Balancer
# ------------------------------------------------------------------------------
resource "aws_lb" "main" {
  name                       = "${local.prefix}-alb"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  idle_timeout               = 60
  drop_invalid_header_fields = true
  tags = {
    Name = "${local.prefix}-alb"
  }
}

resource "aws_lb_target_group" "n8n" {
  name        = "${local.prefix}-tg"
  port        = 5678
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    path                = "/healthz"
    port                = "traffic-port"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 5
    interval            = 30
    matcher             = "200-399"
  }

  tags = {
    Name = "${local.prefix}-tg"
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = "443"
  protocol          = "HTTPS"
  certificate_arn   = local.lb_certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.n8n.arn
  }
}

# ------------------------------------------------------------------------------
# ECS Cluster
# ------------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = local.prefix
  tags = {
    Name = local.prefix
  }
}

# ------------------------------------------------------------------------------
# IAM Roles for ECS
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_task_execution_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution" {
  name               = "${local.prefix}-ecs-task-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_task_execution_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_policy" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_policy" "ecs_task_execution_custom" {
  name        = "${local.prefix}-ecs-task-execution-custom-policy"
  description = "Additional permissions for ECS task execution role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_custom" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = aws_iam_policy.ecs_task_execution_custom.arn
}

data "aws_iam_policy_document" "ecs_task_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task" {
  name               = "${local.prefix}-ecs-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_task_assume_role.json
}

resource "aws_iam_policy" "ecs_task" {
  name        = "${local.prefix}-ecs-task-policy"
  description = "Minimal policy for ECS task role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "logs:DescribeLogGroups"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = aws_iam_policy.ecs_task.arn
}

# ------------------------------------------------------------------------------
# CloudWatch Log Group
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/${local.prefix}/ecs"
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
  tags = {
    Name = "${local.prefix}-ecs-logs"
  }
}

# ------------------------------------------------------------------------------
# EFS
# ------------------------------------------------------------------------------
resource "aws_efs_file_system" "n8n" {
  creation_token   = "${local.prefix}-efs"
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"
  lifecycle {
    prevent_destroy = true
  }
  tags = {
    Name = "${local.prefix}-efs"
  }
}

resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.n8n.id
  posix_user {
    gid = 1000
    uid = 1000
  }
  root_directory {
    path = "/"
    creation_info {
      owner_gid   = 1000
      owner_uid   = 1000
      permissions = "0755"
    }
  }
  lifecycle {
    prevent_destroy = true
  }
  tags = {
    Name = "${local.prefix}-efs-ap"
  }
}

resource "aws_efs_mount_target" "n8n" {
  count          = length(local.azs)
  file_system_id = aws_efs_file_system.n8n.id
  subnet_id      = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# ECS Task Definition
# ------------------------------------------------------------------------------
resource "aws_ecs_task_definition" "n8n" {
  family                   = local.prefix
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name  = local.prefix
      image = var.container_image
      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "WEBHOOK_URL"
          value = var.webhook_url
        },
        {
          name  = "N8N_PORT"
          value = "5678"
        }
      ]
      mountPoints = [
        {
          sourceVolume  = "n8n_data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = "ecs"
        }
      }
      essential = true
    }
  ])

  volume {
    name = "n8n_data"
    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.n8n.id
      root_directory     = "/"
      transit_encryption = "ENABLED"
      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
      }
    }
  }

  tags = {
    Name = local.prefix
  }
}

# ------------------------------------------------------------------------------
# ECS Service
# ------------------------------------------------------------------------------
resource "aws_ecs_service" "n8n" {
  name            = local.prefix
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.n8n.arn
  desired_count   = 1
  launch_type     = "FARGATE"
  platform_version = "LATEST"

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 1
    base              = 0
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs_tasks.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.n8n.arn
    container_name   = local.prefix
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.http,
    aws_lb_listener.https,
    aws_efs_mount_target.n8n
  ]

  lifecycle {
    ignore_changes = [
      desired_count,
      task_definition
    ]
  }

  tags = {
    Name = local.prefix
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "alb_dns_name" {
  description = "DNS name of the Application Load Balancer"
  value       = aws_lb.main.dns_name
}

# Terraform configuration
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources for static provider metadata
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# Local values for naming and reusability
locals {
  name_prefix = "${var.name}-efs-${var.environment}"
  vpc_cidr    = "10.0.0.0/16"
}

# VPC
resource "aws_vpc" "this" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

# Public subnets (two)
resource "aws_subnet" "public" {
  count = 2

  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}-subnet-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

# Route Table
resource "aws_route_table" "this" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "${local.name_prefix}-rt"
  }
}

# Route Table Association
resource "aws_route_table_association" "this" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.this.id
}

# Security Group for NFS
resource "aws_security_group" "efs" {
  name        = "${local.name_prefix}-sg"
  description = "Allow NFS (port 2049) from VPC CIDR"
  vpc_id      = aws_vpc.this.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.name_prefix}-sg"
  }
}

# KMS Key for EFS encryption
resource "aws_kms_key" "this" {
  description             = "KMS key for EFS encryption - ${local.name_prefix}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableFullAccessForAccount"
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-kms"
  }
}

resource "aws_kms_alias" "this" {
  name          = "alias/efs-${var.name}-${var.environment}"
  target_key_id = aws_kms_key.this.key_id
}

# EFS File System
resource "aws_efs_file_system" "this" {
  count = var.create_efs ? 1 : 0

  creation_token   = local.name_prefix
  encrypted        = true
  kms_key_id       = aws_kms_key.this.arn
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode
  provisioned_throughput_in_mibps = var.throughput_mode == "provisioned" ? var.provisioned_throughput_in_mibps : null

  dynamic "lifecycle_policy" {
    for_each = var.lifecycle_policies
    content {
      transition_to_ia                    = lifecycle_policy.value.transition_to_ia
      transition_to_primary_storage_class = lookup(lifecycle_policy.value, "transition_to_primary_storage_class", null)
    }
  }

  tags = {
    Name = "${var.name}-efs-${var.environment}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Mount Targets
resource "aws_efs_mount_target" "this" {
  count = var.create_efs && var.create_mount_targets ? length(local.mount_subnet_ids) : 0

  file_system_id  = aws_efs_file_system.this[0].id
  subnet_id       = local.mount_subnet_ids[count.index]
  security_groups = local.mount_security_group_ids

  depends_on = [aws_efs_file_system.this]
}

locals {
  # If subnet_ids variable is non-empty, use it; otherwise fall back to created public subnets
  mount_subnet_ids        = length(var.subnet_ids) > 0 ? var.subnet_ids : aws_subnet.public[*].id
  # If security_group_ids variable is non-empty, use it; otherwise fall back to created security group
  mount_security_group_ids = length(var.security_group_ids) > 0 ? var.security_group_ids : [aws_security_group.efs.id]
}

# File System Policy
resource "aws_efs_file_system_policy" "this" {
  count = var.create_efs && var.create_efs_policy ? 1 : 0

  file_system_id = aws_efs_file_system.this[0].id
  policy         = var.efs_policy_json
}

# Backup Policy
resource "aws_efs_backup_policy" "this" {
  count = var.create_efs && var.enable_backup ? 1 : 0

  file_system_id = aws_efs_file_system.this[0].id

  backup_policy {
    status = "ENABLED"
  }
}

# Access Point
resource "aws_efs_access_point" "this" {
  count = var.create_efs && var.create_access_point ? 1 : 0

  file_system_id = aws_efs_file_system.this[0].id

  posix_user {
    uid             = var.posix_user.uid
    gid             = var.posix_user.gid
    secondary_gids  = lookup(var.posix_user, "secondary_gids", null)
  }

  root_directory {
    path = var.root_directory.path
    dynamic "creation_info" {
      for_each = lookup(var.root_directory, "creation_info", null) != null ? [1] : []
      content {
        owner_uid   = var.root_directory.creation_info.owner_uid
        owner_gid   = var.root_directory.creation_info.owner_gid
        permissions = var.root_directory.creation_info.permissions
      }
    }
  }

  tags = {
    Name = "${var.name}-efs-ap-${var.environment}"
  }
}

# Outputs
output "efs_file_system_id" {
  description = "ID of the EFS file system"
  value       = try(aws_efs_file_system.this[0].id, null)
}

output "efs_file_system_arn" {
  description = "ARN of the EFS file system"
  value = var.create_efs ? "arn:aws:elasticfilesystem:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:file-system/${aws_efs_file_system.this[0].id}" : null
}

output "efs_file_system_dns_name" {
  description = "DNS name of the EFS file system"
  value       = try(aws_efs_file_system.this[0].dns_name, null)
}

output "mount_target_ids" {
  description = "List of mount target IDs"
  value       = var.create_efs && var.create_mount_targets ? aws_efs_mount_target.this[*].id : []
}

output "mount_target_arns" {
  description = "List of file system ARNs associated with mount targets"
  value       = var.create_efs && var.create_mount_targets ? aws_efs_mount_target.this[*].file_system_arn : []
}

output "mount_target_dns_names" {
  description = "List of mount target DNS names (same as file system DNS name)"
  value       = var.create_efs && var.create_mount_targets ? [for mt in aws_efs_mount_target.this : aws_efs_file_system.this[0].dns_name] : []
}

output "file_system_policy_id" {
  description = "ID of the EFS file system policy"
  value       = try(aws_efs_file_system_policy.this[0].id, null)
}

output "access_point_id" {
  description = "ID of the EFS access point"
  value       = try(aws_efs_access_point.this[0].id, null)
}

output "access_point_arn" {
  description = "ARN of the EFS access point"
  value       = try(aws_efs_access_point.this[0].arn, null)
}

output "access_point_dns_name" {
  description = "DNS name of the EFS access point (same as file system DNS name)"
  value       = try(aws_efs_file_system.this[0].dns_name, null)
}

# Variables
variable "name" {
  description = "Base name for resources"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name (e.g., STAGE)"
  type        = string
  default     = "STAGE"
}

variable "create_efs" {
  description = "Flag to create the EFS file system"
  type        = bool
  default     = true
}

variable "create_mount_targets" {
  description = "Flag to create mount targets"
  type        = bool
  default     = true
}

variable "create_efs_policy" {
  description = "Flag to create the EFS file system policy"
  type        = bool
  default     = true
}

variable "create_access_point" {
  description = "Flag to create the EFS access point"
  type        = bool
  default     = true
}

variable "performance_mode" {
  description = "Performance mode for the EFS file system"
  type        = string
  default     = "generalPurpose"
}

variable "throughput_mode" {
  description = "Throughput mode for the EFS file system"
  type        = string
  default     = "bursting"
}

variable "provisioned_throughput_in_mibps" {
  description = "Provisioned throughput in MiB/s (only when throughput_mode is 'provisioned')"
  type        = number
  default     = null
}

variable "lifecycle_policies" {
  description = "List of lifecycle policy configurations"
  type = list(object({
    transition_to_ia                    = string
    transition_to_primary_storage_class = optional(string)
  }))
  default = [
    {
      transition_to_ia = "AFTER_30_DAYS"
    }
  ]
}

variable "subnet_ids" {
  description = "List of subnet IDs for mount targets. If empty, uses created subnets."
  type        = list(string)
  default     = []
}

variable "security_group_ids" {
  description = "List of security group IDs for mount targets. If empty, uses the created security group."
  type        = list(string)
  default     = []
}

variable "posix_user" {
  description = "POSIX user configuration for the access point"
  type = object({
    uid            = number
    gid            = number
    secondary_gids = optional(list(number))
  })
  default = {
    uid = 1000
    gid = 1000
  }
}

variable "root_directory" {
  description = "Root directory configuration for the access point"
  type = object({
    path = string
    creation_info = optional(object({
      owner_uid   = number
      owner_gid   = number
      permissions = string
    }))
  })
  default = {
    path = "/"
  }
}

variable "efs_policy_json" {
  description = "JSON policy for the EFS file system policy"
  type        = string
  default     = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowTestAccess",
      "Effect": "Allow",
      "Principal": {
        "AWS": "*"
      },
      "Action": [
        "elasticfilesystem:ClientRootAccess",
        "elasticfilesystem:ClientWrite",
        "elasticfilesystem:ClientRead"
      ],
      "Resource": "*"
    }
  ]
}
EOF
}

variable "enable_backup" {
  description = "Flag to enable automatic backups via backup policy"
  type        = bool
  default     = false
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  bucket_name     = "cloudtrail-logs-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.region}"
  trail_name      = "multi-region-cloudtrail"
  log_group_name  = "/aws/cloudtrail/management"
  retention_days  = 14
  kms_key_alias   = "alias/cloudtrail-logs-key"
}

# KMS key for CloudTrail, S3, and SNS encryption
resource "aws_kms_key" "trail" {
  description             = "CMK for CloudTrail, S3, and SNS encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to encrypt/decrypt logs"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to encrypt/decrypt logs"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow SNS to encrypt/decrypt notifications"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "trail" {
  name          = local.kms_key_alias
  target_key_id = aws_kms_key.trail.key_id
}

# S3 bucket for CloudTrail logs
resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.bucket_name
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.trail.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket                  = aws_s3_bucket.cloudtrail_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket policy allowing CloudTrail to write
resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail_logs.arn
        Condition = {
          StringEquals = {
            "aws:SourceArn" = aws_cloudtrail.main.arn
          }
        }
      },
      {
        Sid    = "AWSCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail_logs.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl"  = "bucket-owner-full-control"
            "aws:SourceArn" = aws_cloudtrail.main.arn
          }
        }
      }
    ]
  })
}

# CloudWatch Logs group for CloudTrail
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = local.retention_days
  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for CloudTrail to deliver logs
resource "aws_iam_role" "cloudtrail" {
  name = "cloudtrail-log-delivery-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Policy for S3 access
resource "aws_iam_role_policy" "cloudtrail_s3" {
  name = "cloudtrail-s3-policy"
  role = aws_iam_role.cloudtrail.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl"
        ]
        Resource = [
          aws_s3_bucket.cloudtrail_logs.arn,
          "${aws_s3_bucket.cloudtrail_logs.arn}/*"
        ]
      }
    ]
  })
}

# Policy for CloudWatch Logs access
resource "aws_iam_role_policy" "cloudtrail_logs" {
  name = "cloudtrail-logs-policy"
  role = aws_iam_role.cloudtrail.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = aws_cloudwatch_log_group.cloudtrail.arn
      }
    ]
  })
}

# Multi-region CloudTrail trail
resource "aws_cloudtrail" "main" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  s3_key_prefix                 = "cloudtrail"
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_logging                = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.trail.arn
  cloud_watch_logs_group_arn    = aws_cloudwatch_log_group.cloudtrail.arn
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail.arn
  advanced_event_selector {
    name = "Management events"
    field_selector {
      field  = "eventCategory"
      equals = ["Management"]
    }
    field_selector {
      field      = "eventSource"
      not_equals = ["kms.amazonaws.com", "rdsdata.amazonaws.com"]
    }
  }
}

# SNS topic for alarms
resource "aws_sns_topic" "cloudtrail_alarms" {
  name              = "cloudtrail-alarms-topic"
  kms_master_key_id = aws_kms_key.trail.arn
}

# Variable for email endpoints
variable "alarm_email_endpoints" {
  description = "List of email addresses to subscribe to the SNS topic for CloudTrail alarms"
  type        = list(string)
  default     = []
}

# SNS topic subscriptions for each email
resource "aws_sns_topic_subscription" "cloudtrail_alarms" {
  for_each  = toset(var.alarm_email_endpoints)
  topic_arn = aws_sns_topic.cloudtrail_alarms.arn
  protocol  = "email"
  endpoint  = each.value
}

# -------------------------------------------------------------------------
# Metric Filters and Alarms
# -------------------------------------------------------------------------

# 1. Security Group Ingress/Egress Authorization and Revocation
resource "aws_cloudwatch_log_metric_filter" "security_group_authorization" {
  name           = "SecurityGroupAuthorization"
  pattern        = "{ ($.eventName = \"AuthorizeSecurityGroupIngress\") || ($.eventName = \"AuthorizeSecurityGroupEgress\") || ($.eventName = \"RevokeSecurityGroupIngress\") || ($.eventName = \"RevokeSecurityGroupEgress\") }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name
  metric_transformation {
    name      = "SecurityGroupAuthorization"
    namespace = "CloudTrailMetrics"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "security_group_authorization" {
  alarm_name                = "SecurityGroupAuthorizationAlarm"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = 1
  metric_name               = "SecurityGroupAuthorization"
  namespace                 = "CloudTrailMetrics"
  period                    = 60
  statistic                 = "Sum"
  threshold                 = 1
  alarm_description         = "Alarm when security group authorization events occur within 60 seconds"
  treat_missing_data        = "notBreaching"
  alarm_actions             = [aws_sns_topic.cloudtrail_alarms.arn]
}

# 2. Security Group Creation and Deletion
resource "aws_cloudwatch_log_metric_filter" "security_group_creation_deletion" {
  name           = "SecurityGroupCreationDeletion"
  pattern        = "{ ($.eventName = \"CreateSecurityGroup\") || ($.eventName = \"DeleteSecurityGroup\") }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name
  metric_transformation {
    name      = "SecurityGroupCreationDeletion"
    namespace = "CloudTrailMetrics"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "security_group_creation_deletion" {
  alarm_name                = "SecurityGroupCreationDeletionAlarm"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = 1
  metric_name               = "SecurityGroupCreationDeletion"
  namespace                 = "CloudTrailMetrics"
  period                    = 60
  statistic                 = "Sum"
  threshold                 = 1
  alarm_description         = "Alarm when security group creation/deletion events occur within 60 seconds"
  treat_missing_data        = "notBreaching"
  alarm_actions             = [aws_sns_topic.cloudtrail_alarms.arn]
}

# 3. IAM User Creation and Deletion
resource "aws_cloudwatch_log_metric_filter" "iam_user_creation_deletion" {
  name           = "IAMUserCreationDeletion"
  pattern        = "{ ($.eventName = \"CreateUser\") || ($.eventName = \"DeleteUser\") }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name
  metric_transformation {
    name      = "IAMUserCreationDeletion"
    namespace = "CloudTrailMetrics"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_user_creation_deletion" {
  alarm_name                = "IAMUserCreationDeletionAlarm"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = 1
  metric_name               = "IAMUserCreationDeletion"
  namespace                 = "CloudTrailMetrics"
  period                    = 60
  statistic                 = "Sum"
  threshold                 = 1
  alarm_description         = "Alarm when IAM user creation/deletion events occur within 60 seconds"
  treat_missing_data        = "notBreaching"
  alarm_actions             = [aws_sns_topic.cloudtrail_alarms.arn]
}

# 4. Failed Console Login
resource "aws_cloudwatch_log_metric_filter" "failed_console_login" {
  name           = "FailedConsoleLogin"
  pattern        = "{ ($.eventName = \"ConsoleLogin\") && ($.responseElements.ConsoleLogin = \"Failure\") }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name
  metric_transformation {
    name      = "FailedConsoleLogin"
    namespace = "CloudTrailMetrics"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "failed_console_login" {
  alarm_name                = "FailedConsoleLoginAlarm"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = 1
  metric_name               = "FailedConsoleLogin"
  namespace                 = "CloudTrailMetrics"
  period                    = 60
  statistic                 = "Sum"
  threshold                 = 1
  alarm_description         = "Alarm when a failed console login occurs within 60 seconds"
  treat_missing_data        = "notBreaching"
  alarm_actions             = [aws_sns_topic.cloudtrail_alarms.arn]
}

# 5. IAM Group/Role/User Policy Changes (inline policies)
resource "aws_cloudwatch_log_metric_filter" "iam_group_role_user_policy_changes" {
  name           = "IAMGroupRoleUserPolicyChanges"
  pattern        = "{ ($.eventName = \"PutGroupPolicy\") || ($.eventName = \"PutRolePolicy\") || ($.eventName = \"PutUserPolicy\") || ($.eventName = \"DeleteGroupPolicy\") || ($.eventName = \"DeleteRolePolicy\") || ($.eventName = \"DeleteUserPolicy\") }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name
  metric_transformation {
    name      = "IAMGroupRoleUserPolicyChanges"
    namespace = "CloudTrailMetrics"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_group_role_user_policy_changes" {
  alarm_name                = "IAMGroupRoleUserPolicyChangesAlarm"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = 1
  metric_name               = "IAMGroupRoleUserPolicyChanges"
  namespace                 = "CloudTrailMetrics"
  period                    = 60
  statistic                 = "Sum"
  threshold                 = 1
  alarm_description         = "Alarm when IAM group/role/user policy changes occur within 60 seconds"
  treat_missing_data        = "notBreaching"
  alarm_actions             = [aws_sns_topic.cloudtrail_alarms.arn]
}

# 6. IAM Policy Changes (managed policies)
resource "aws_cloudwatch_log_metric_filter" "iam_policy_changes" {
  name           = "IAMPolicyChanges"
  pattern        = "{ ($.eventName = \"CreatePolicy\") || ($.eventName = \"DeletePolicy\") || ($.eventName = \"CreatePolicyVersion\") || ($.eventName = \"DeletePolicyVersion\") || ($.eventName = \"AttachGroupPolicy\") || ($.eventName = \"DetachGroupPolicy\") || ($.eventName = \"AttachRolePolicy\") || ($.eventName = \"DetachRolePolicy\") || ($.eventName = \"AttachUserPolicy\") || ($.eventName = \"DetachUserPolicy\") }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name
  metric_transformation {
    name      = "IAMPolicyChanges"
    namespace = "CloudTrailMetrics"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_policy_changes" {
  alarm_name                = "IAMPolicyChangesAlarm"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = 1
  metric_name               = "IAMPolicyChanges"
  namespace                 = "CloudTrailMetrics"
  period                    = 60
  statistic                 = "Sum"
  threshold                 = 1
  alarm_description         = "Alarm when IAM policy changes occur within 60 seconds"
  treat_missing_data        = "notBreaching"
  alarm_actions             = [aws_sns_topic.cloudtrail_alarms.arn]
}

# 7. User Added to Group
resource "aws_cloudwatch_log_metric_filter" "user_added_to_group" {
  name           = "UserAddedToGroup"
  pattern        = "{ ($.eventName = \"AddUserToGroup\") }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name
  metric_transformation {
