  alarm_description         = "Alarm when a user is added to a group within 60 seconds"
  treat_missing_data        = "notBreaching"
  alarm_actions             = [aws_sns_topic.cloudtrail_alarms.arn]
}

# 8. IAM Role Creation and Deletion
resource "aws_cloudwatch_log_metric_filter" "iam_role_creation_deletion" {
  name           = "IAMRoleCreationDeletion"
  pattern        = "{ ($.eventName = \"CreateRole\") || ($.eventName = \"DeleteRole\") }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name
  metric_transformation {
    name      = "IAMRoleCreationDeletion"
