}

output "ipset_arn" {
  description = "ARN of the WAFv2 IP set (if created)."
  value       = try(aws_wafv2_ip_set.this[0].arn, "")
}

output "regex_pattern_set_id" {
  description = "ID of the WAFv2 regex pattern set (if created)."
  value       = try(aws_wafv2_regex_pattern_set.this[0].id, "")
}

output "regex_pattern_set_arn" {
  description = "ARN of the WAFv2 regex pattern set (if created)."
  value       = try(aws_wafv2_regex_pattern_set.this[0].arn, "")
}

output "rule_group_id" {
  description = "ID of the WAFv2 rule group (if created)."
  value       = try(aws_wafv2_rule_group.this[0].id, "")
}

output "rule_group_arn" {
  description = "ARN of the WAFv2 rule group (if created)."
  value       = try(aws_wafv2_rule_group.this[0].arn, "")
}

output "web_acl_id" {
  description = "ID of the WAFv2 web ACL (if created)."
  value       = try(aws_wafv2_web_acl.this[0].id, "")
}

output "web_acl_arn" {
  description = "ARN of the WAFv2 web ACL (if created)."
  value       = try(aws_wafv2_web_acl.this[0].arn, "")
}

output "waf_log_bucket_id" {
  description = "ID of the S3 bucket for WAF logs (if created)."
  value       = try(aws_s3_bucket.waf_logs[0].id, "")
}

output "waf_log_bucket_

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

variable "event_bus_name" {
  description = "Name of the custom event bus. Leave empty to use the default bus."
  type        = string
  default     = ""
}

variable "schedule_expression" {
  description = "Schedule expression for the event rule (e.g., rate(5 minutes)). Provide either this or event_pattern."
  type        = string
  default     = "rate(5 minutes)"
  validation {
    condition     = var.schedule_expression != null || var.event_pattern != null
    error_message = "At least one of schedule_expression or event_pattern must be specified."
  }
}

variable "event_pattern" {
  description = "JSON event pattern for the rule. Provide either this or schedule_expression."
  type        = string
  default     = null
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  type        = string
  default     = "my-function"
}

variable "state_machine_name" {
  description = "Name of the Step Functions state machine."
  type        = string
  default     = "my-state-machine"
}

variable "common_tags" {
  description = "Common tags to apply to all resources."
  type        = map(string)
  default     = {}
}

locals {
  event_bus_name = length(var.event_bus_name) > 0 ? aws_cloudwatch_event_bus.this[0].name : "default"
}

resource "aws_cloudwatch_event_bus" "this" {
  count = length(var.event_bus_name) > 0 ? 1 : 0
  name  = var.event_bus_name
  tags  = var.common_tags
}

resource "local_file" "lambda_code" {
  filename = "${path.module}/lambda_function.py"
  content  = <<-EOF
def lambda_handler(event, context):
    return {"statusCode": 200, "body": "Hello from Lambda"}
EOF
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  source_file = local_file.lambda_code.filename
  output_path = "${path.module}/lambda_function.zip"
}

resource "aws_iam_role" "lambda_execution" {
  name = "${var.lambda_function_name}-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      }
    ]
  })
  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "this" {
  filename         = data.archive_file.lambda_zip.output_path
  function_name    = var.lambda_function_name
  role             = aws_iam_role.lambda_execution.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.12"
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  tags             = var.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "sfn_execution" {
  name = "${var.state_machine_name}-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "states.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      }
    ]
  })
  tags = var.common_tags
}

resource "aws_sfn_state_machine" "this" {
  name     = var.state_machine_name
  role_arn = aws_iam_role.sfn_execution.arn
  type     = "STANDARD"
  definition = jsonencode({
    Comment = "A minimal state machine"
    StartAt = "PassState"
    States = {
      PassState = {
        Type = "Pass"
        End  = true
      }
    }
  })
  tags = var.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_event_rule" "this" {
  name                = "main-event-rule"
  event_bus_name      = local.event_bus_name
  schedule_expression = var.schedule_expression
  event_pattern       = var.event_pattern
  tags                = var.common_tags
}

resource "aws_cloudwatch_event_target" "lambda" {
  rule           = aws_cloudwatch_event_rule.this.name
  event_bus_name = local.event_bus_name
  target_id      = "LambdaTarget"
  arn            = aws_lambda_function.this.arn
}

resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.this.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.this.arn
}

resource "aws_iam_role" "eventbridge_invoke_sfn" {
  name = "eventbridge-invoke-sfn-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      }
    ]
  })
  tags = var.common_tags
}

resource "aws_iam_role_policy" "eventbridge_invoke_sfn_policy" {
  role = aws_iam_role.eventbridge_invoke_sfn.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "states:StartExecution"
        Effect   = "Allow"
        Resource = aws_sfn_state_machine.this.arn
      }
    ]
  })
}

resource "aws_cloudwatch_event_target" "step_functions" {
  rule           = aws_cloudwatch_event_rule.this.name
  event_bus_name = local.event_bus_name
  target_id      = "StepFunctionsTarget"
  arn            = aws_sfn_state_machine.this.arn
  role_arn       = aws_iam_role.eventbridge_invoke_sfn.arn
}

# ------------------------------------------------------------------------------
# Terraform configuration
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "my-eks-cluster"
}

variable "oidc_provider_arn" {
  description = "ARN of the EKS cluster's OIDC provider"
  type        = string
  default     = "arn:aws:iam::000000000000:oidc-provider/placeholder"
}

variable "karpenter_namespace" {
  description = "Kubernetes namespace for Karpenter"
  type        = string
  default     = "karpenter"
}

variable "karpenter_service_account" {
  description = "Kubernetes service account name for Karpenter"
  type        = string
  default     = "karpenter"
}

variable "include_eks_cni_policy" {
  description = "Whether to attach AmazonEKS_CNI_Policy to the node role"
  type        = bool
  default     = true
}

# ------------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  queue_name = "karpenter-${var.cluster_name}"

  # Standard AWS managed policy ARNs
  worker_node_policy_arn     = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  ec2_readonly_policy_arn    = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  eks_cni_policy_arn         = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"

  # Construct the full OIDC provider URL for use in conditions
  oidc_provider_url = replace(var.oidc_provider_arn, "/^arn:aws:iam::\\d{12}:oidc-provider\\//", "")
}

# ------------------------------------------------------------------------------
# Karpenter IAM Role (service account)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "karpenter" {
  name               = "Karpenter-${var.cluster_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = var.oidc_provider_arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${local.oidc_provider_url}:sub" = "system:serviceaccount:${var.karpenter_namespace}:${var.karpenter_service_account}"
            "${local.oidc_provider_url}:aud" = "sts.amazonaws.com"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Karpenter Node IAM Role (used by EC2 instances provisioned by Karpenter)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "karpenter_node" {
  name               = "KarpenterNode-${var.cluster_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach AmazonEKSWorkerNodePolicy
resource "aws_iam_role_policy_attachment" "worker_node" {
  role       = aws_iam_role.karpenter_node.name
  policy_arn = local.worker_node_policy_arn
}

# Attach AmazonEC2ContainerRegistryReadOnly
resource "aws_iam_role_policy_attachment" "ecr_readonly" {
  role       = aws_iam_role.karpenter_node.name
  policy_arn = local.ec2_readonly_policy_arn
}

# Conditionally attach AmazonEKS_CNI_Policy
resource "aws_iam_role_policy_attachment" "cni" {
  count      = var.include_eks_cni_policy ? 1 : 0
  role       = aws_iam_role.karpenter_node.name
  policy_arn = local.eks_cni_policy_arn
}

# Instance profile for the node role
resource "aws_iam_instance_profile" "karpenter_node" {
  name = aws_iam_role.karpenter_node.name
  role = aws_iam_role.karpenter_node.name
}

# ------------------------------------------------------------------------------
# SQS Queue for native spot termination handling
# ------------------------------------------------------------------------------
resource "aws_sqs_queue" "karpenter" {
  name                      = local.queue_name
  sqs_managed_sse_enabled   = true

  lifecycle {
    prevent_destroy = true
  }
}

# Queue policy to allow CloudWatch Events to send messages
data "aws_iam_policy_document" "karpenter_queue" {
  statement {
    sid    = "AllowCloudWatchEvents"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.karpenter.arn]

    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values = [
        "arn:aws:events:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:rule/Karpenter-${var.cluster_name}-*"
      ]
    }
  }
}

resource "aws_sqs_queue_policy" "karpenter" {
  queue_url = aws_sqs_queue.karpenter.id
  policy    = data.aws_iam_policy_document.karpenter_queue.json
}

# ------------------------------------------------------------------------------
# CloudWatch Event Rules and Targets
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_event_rule" "instance_state_change" {
  name          = "Karpenter-${var.cluster_name}-InstanceStateChange"
  description   = "Capture EC2 instance state changes for Karpenter"
  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Instance State-change Notification"]
  })
}

resource "aws_cloudwatch_event_rule" "spot_interruption" {
  name          = "Karpenter-${var.cluster_name}-SpotInterruption"
  description   = "Capture EC2 spot instance interruption warnings for Karpenter"
  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Spot Instance Interruption Warning"]
  })
}

resource "aws_cloudwatch_event_rule" "rebalance_recommendation" {
  name          = "Karpenter-${var.cluster_name}-RebalanceRecommendation"
  description   = "Capture EC2 instance rebalance recommendations for Karpenter"
  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Instance Rebalance Recommendation"]
  })
}

resource "aws_cloudwatch_event_rule" "health_event" {
  name          = "Karpenter-${var.cluster_name}-HealthEvent"
  description   = "Capture AWS Health events for Karpenter"
  event_pattern = jsonencode({
    source      = ["aws.health"]
    detail-type = ["AWS Health Event"]
  })
}

# Targets for each rule
resource "aws_cloudwatch_event_target" "instance_state_change" {
  rule      = aws_cloudwatch_event_rule.instance_state_change.name
  target_id = "KarpenterQueue"
  arn       = aws_sqs_queue.karpenter.arn
}

resource "aws_cloudwatch_event_target" "spot_interruption" {
  rule      = aws_cloudwatch_event_rule.spot_interruption.name
  target_id = "KarpenterQueue"
  arn       = aws_sqs_queue.karpenter.arn
}

resource "aws_cloudwatch_event_target" "rebalance_recommendation" {
  rule      = aws_cloudwatch_event_rule.rebalance_recommendation.name
  target_id = "KarpenterQueue"
  arn       = aws_sqs_queue.karpenter.arn
}

resource "aws_cloudwatch_event_target" "health_event" {
  rule      = aws_cloudwatch_event_rule.health_event.name
  target_id = "KarpenterQueue"
  arn       = aws_sqs_queue.karpenter.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

# Variables
variable "bucket_primary" {
  description = "Name of the primary S3 bucket (us-east-1)"
  type        = string
  default     = "example1"
}

variable "bucket_secondary" {
  description = "Name of the secondary S3 bucket"
  type        = string
  default     = "example2"
}

variable "secondary_region" {
  description = "Region for the secondary S3 bucket and provider alias"
  type        = string
  default     = "us-west-2"
}

# Data sources
data "aws_caller_identity" "current" {}

# KMS key for S3 bucket encryption
resource "aws_kms_key" "s3_cmk" {
  description             = "CMK for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# Primary bucket (us-east-1 via default provider)
resource "aws_s3_bucket" "primary" {
  bucket = var.bucket_primary

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_cmk.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Secondary bucket (secondary region via provider alias)
resource "aws_s3_bucket" "secondary" {
  provider = aws.secondary
  bucket   = var.bucket_secondary

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_cmk.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# IAM role and policy for replication
resource "aws_iam_role" "replication" {
  name = "s3-cross-region-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Policy for S3 cross-region replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary.arn
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          "${aws_s3_bucket.primary.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          "${aws_s3_bucket.secondary.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# Replication configuration on primary bucket
resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [aws_s3_bucket_versioning.primary, aws_s3_bucket_versioning.secondary]

  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }
}

# Multi-Region Access Point
resource "aws_s3control_multi_region_access_point" "mrap" {
  details {
    name = "example-mrap"

    region {
      bucket = aws_s3_bucket.primary.bucket
    }

    region {
      bucket = aws_s3_bucket.secondary.bucket
    }
  }
}

# Brief sleep to allow MRAP propagation
resource "time_sleep" "wait_for_mrap" {
  depends_on      = [aws_s3control_multi_region_access_point.mrap]
  create_duration = "15s"
}

# Policy for the MRAP
resource "aws_s3control_multi_region_access_point_policy" "mrap_policy" {
  depends_on = [aws_s3control_multi_region_access_point.mrap, time_sleep.wait_for_mrap]

  details {
    name = "example-mrap"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Principal = {
            AWS = "*"
          }
          Action = [
            "s3:GetObject",
            "s3:PutObject"
          ]
          Resource = [
            "${aws_s3control_multi_region_access_point.mrap.arn}/object/*"
          ]
          Condition = {
            StringEquals = {
              "aws:SourceAccount" = data.aws_caller_identity.current.account_id
            }
          }
        }
      ]
    })
  }
}

# Outputs
output "mrap_status" {
  description = "Status of the Multi-Region Access Point"
  value       = aws_s3control_multi_region_access_point.mrap.status
}

output "mrap_alias" {
  description = "Alias of the Multi-Region Access Point"
  value       = aws_s3control_multi_region_access_point.mrap.alias
}

output "mrap_domain_name" {
  description = "Domain name of the Multi-Region Access Point"
  value       = aws_s3control_multi_region_access_point.mrap.domain_name
}

output "mrap_arn" {
  description = "ARN of the Multi-Region Access Point"
  value       = aws_s3control_multi_region_access_point.mrap.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources for dynamic ARN construction
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# Variables
variable "oidc_provider_urls" {
  type        = list(string)
  default     = []
  description = "List of OIDC provider URLs (e.g. https://oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE)"
}

variable "namespace_service_accounts" {
  type = list(object({
    namespace      = string
    service_account = string
  }))
  default     = []
  description = "List of Kubernetes namespace/service account pairs for IRSA"
}

variable "cluster_ids" {
  type        = list(string)
  default     = []
  description = "List of EKS cluster IDs (names) used for tag conditions"
}

variable "external_dns_hosted_zone_arns" {
  type        = list(string)
  default     = []
  description = "ARNs of Route53 hosted zones for External DNS"
}

variable "ebs_csi_kms_cmk_arn" {
  type        = string
  default     = ""
  description = "ARN of KMS CMK for EBS CSI (optional)"
}

variable "nth_sqs_queue_arns" {
  type        = list(string)
  default     = []
  description = "ARNs of SQS queues for Node Termination Handler"
}

variable "karpenter_node_role_arn" {
  type        = string
  default     = ""
  description = "ARN of IAM role for Karpenter nodes (PassRole)"
}

variable "karpenter_discovery_tag_key" {
  type        = string
  default     = "karpenter.sh/discovery"
  description = "Tag key for Karpenter discovery"
}

variable "karpenter_discovery_tag_value" {
  type        = string
  default     = ""
  description = "Tag value for Karpenter discovery (cluster name)"
}

variable "ssm_parameter_path" {
  type        = string
  default     = "/aws/service/eks/optimized-ami/amazon-linux-2/recommended/image_id"
  description = "SSM parameter path prefix for node AMI lookup"
}

variable "lb_controller_cluster_name" {
  type        = string
  default     = ""
  description = "Cluster name used in the elbv2.k8s.aws/cluster tag condition for Load Balancer Controller"
}

variable "enable_cluster_autoscaler" {
  type    = bool
  default = false
}

variable "enable_external_dns" {
  type    = bool
  default = false
}

variable "enable_ebs_csi" {
  type    = bool
  default = false
}

variable "enable_vpc_cni" {
  type    = bool
  default = false
}

variable "enable_node_termination_handler" {
  type    = bool
  default = false
}

variable "enable_karpenter" {
  type    = bool
  default = false
}

variable "enable_lb_controller" {
  type    = bool
  default = false
}

# TLS certificate data for each OIDC provider
data "tls_certificate" "oidc" {
  for_each = toset(var.oidc_provider_urls)
  url      = each.value
}

# OIDC providers
resource "aws_iam_openid_connect_provider" "oidc" {
  for_each         = toset(var.oidc_provider_urls)
  url              = each.value
  client_id_list   = ["sts.amazonaws.com"]
  thumbprint_list  = [data.tls_certificate.oidc[each.key].certificates[0].sha1_fingerprint]
}

# IRSA role
resource "aws_iam_role" "irsa_role" {
  name        = "eks-irsa"
  description = "IRSA role for EKS service accounts"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      for oidc_url in var.oidc_provider_urls : {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.oidc[oidc_url].arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${oidc_url}:aud" = "sts.amazonaws.com"
            "${oidc_url}:sub" = [
              for nsa in var.namespace_service_accounts :
                "system:serviceaccount:${nsa.namespace}:${nsa.service_account}"
            ]
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# 1. Cluster Autoscaler Policy
# ----------------------------------------------------------------------
resource "aws_iam_policy" "cluster_autoscaler" {
  count  = var.enable_cluster_autoscaler ? 1 : 0
  name   = "EKSIRSA-ClusterAutoscaler"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeAutoScalingGroupInstances",
          "autoscaling:DescribeLaunchConfigurations",
          "autoscaling:DescribeTags",
          "autoscaling:DescribeNotificationConfigurations",
          "autoscaling:DescribeScalingActivities"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "autoscaling:SetDesiredCapacity",
          "autoscaling:UpdateAutoScalingGroup",
          "autoscaling:TerminateInstanceInAutoScalingGroup"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            for cid in var.cluster_ids :
              "autoscaling:ResourceTag/kubernetes.io/cluster/${cid}" => "owned"
          }
        }
      }
    ]
  })
}

# ----------------------------------------------------------------------
# 2. External DNS Policy
# ----------------------------------------------------------------------
resource "aws_iam_policy" "external_dns" {
  count  = var.enable_external_dns ? 1 : 0
  name   = "EKSIRSA-ExternalDNS"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "route53:ChangeResourceRecordSets"
        Resource = var.external_dns_hosted_zone_arns
      },
      {
        Effect   = "Allow"
        Action   = [
          "route53:ListHostedZones",
          "route53:ListResourceRecordSets",
          "route53:GetChange"
        ]
        Resource = "*"
      }
    ]
  })
}

# ----------------------------------------------------------------------
# 3. EBS CSI Policy
# ----------------------------------------------------------------------
resource "aws_iam_policy" "ebs_csi" {
  count  = var.enable_ebs_csi ? 1 : 0
  name   = "EKSIRSA-EBSCSI"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateVolume",
          "ec2:DeleteVolume",
          "ec2:AttachVolume",
          "ec2:DetachVolume",
          "ec2:DescribeVolumes",
          "ec2:DescribeVolumeStatus",
          "ec2:DescribeSnapshots",
          "ec2:CreateSnapshot",
          "ec2:DeleteSnapshot",
          "ec2:ModifyVolume"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:volume/*",
          "arn:${data.aws_partition.current.partition}:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:snapshot/*"
        ]
      }
    ]
  })
}

# Optional KMS CMK statement for EBS CSI (attached via separate policy)
resource "aws_iam_policy" "ebs_csi_kms" {
  count  = var.enable_ebs_csi && var.ebs_csi_kms_cmk_arn != "" ? 1 : 0
  name   = "EKSIRSA-EBSCSI-KMS"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
        Resource = var.ebs_csi_kms_cmk_arn
      }
    ]
  })
}

# ----------------------------------------------------------------------
# 4. VPC CNI Policy
# ----------------------------------------------------------------------
resource "aws_iam_policy" "vpc_cni" {
  count  = var.enable_vpc_cni ? 1 : 0
  name   = "EKSIRSA-VPCCNI"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses",
          "ec2:CreateNetworkInterface",
          "ec2:AttachNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeInstances",
          "ec2:AssignIpv6Addresses",
          "ec2:UnassignIpv6Addresses"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:network-interface/*",
          "arn:${data.aws_partition.current.partition}:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:instance/*"
        ]
      }
    ]
  })
}

# ----------------------------------------------------------------------
# 5. Node Termination Handler Policy
# ----------------------------------------------------------------------
resource "aws_iam_policy" "node_termination_handler" {
  count  = var.enable_node_termination_handler ? 1 : 0
  name   = "EKSIRSA-NodeTerminationHandler"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "sqs:GetQueueUrl",
          "sqs:ListQueues",
          "sqs:ReceiveMessage",
          "sqs:DeleteMessage"
        ]
        Resource = var.nth_sqs_queue_arns
      },
      {
        Effect   = "Allow"
        Action   = "autoscaling:CompleteLifecycleAction"
        Resource = "*"
        Condition = {
          StringEquals = {
            for cid in var.cluster_ids :
              "autoscaling:ResourceTag/kubernetes.io/cluster/${cid}" => "owned"
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = "ec2:DescribeInstances"
        Resource = "*"
      }
    ]
  })
}

# ----------------------------------------------------------------------
# 6. Karpenter Controller Policy
# ----------------------------------------------------------------------
resource "aws_iam_policy" "karpenter" {
  count  = var.enable_karpenter ? 1 : 0
  name   = "EKSIRSA-Karpenter"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "ec2:RunInstances",
          "ec2:TerminateInstances",
          "ec2:CreateTags",
          "ec2:DeleteTags"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:RequestTag/${var.karpenter_discovery_tag_key}" = var.karpenter_discovery_tag_value
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = [
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeImages",
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceTypeOfferings",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeLaunchTemplates",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSpotPriceHistory",
          "ec2:DescribeSubnets"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "ssm:GetParameter",
          "ssm:GetParametersByPath"
        ]
        Resource = "${var.ssm_parameter_path}*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = var.karpenter_node_role_arn
      }
    ]
  })
}

# ----------------------------------------------------------------------
# 7. AWS Load Balancer Controller Policy
# ----------------------------------------------------------------------
resource "aws_iam_policy" "lb_controller" {
  count  = var.enable_lb_controller ? 1 : 0
  name   = "EKSIRSA-LoadBalancerController"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "elasticloadbalancing:*"
        Resource = "*"
        Condition = {
          StringEquals = {
            "elbv2.k8s.aws/cluster" = var.lb_controller_cluster_name
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = [
          "ec2:DescribeAccountAttributes",
          "ec2:DescribeAddresses",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeVpcPeeringConnections",
          "ec2:DescribeTags",
          "ec2:DescribeInstances",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeManagedPrefixLists"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:RevokeSecurityGroupIngress",
          "ec2:CreateSecurityGroup",
          "ec2:DeleteSecurityGroup",
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "acm:DescribeCertificate"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "acm:ListCertificates"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "waf:GetWebACL",
          "waf:GetWebACLForResource",
          "waf:AssociateWebACL",
          "waf:DisassociateWebACL",
          "waf:ListWebACLs",
          "wafv2:GetWebACL",
          "wafv2:GetWebACLForResource",
          "wafv2:AssociateWebACL",
          "wafv2:DisassociateWebACL",
          "wafv2:ListWebACLs"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "shield:DescribeProtection",
          "shield:GetSubscriptionState",
          "shield:ListProtections",
          "shield:CreateProtection",
          "shield:DeleteProtection"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:CreateServiceLinkedRole"
        Resource = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/elasticloadbalancing.amazonaws.com/AWSServiceRoleForElasticLoadBalancing"
        Condition = {
          StringEquals = {
            "iam:AWSServiceName" = "elasticloadbalancing.amazonaws.com"
          }
        }
      }
    ]
  })
}

# ----------------------------------------------------------------------
# Attach all policies to the IRSA role
# ----------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "cluster_autoscaler" {
  count      = var.enable_cluster_autoscaler ? 1 : 0
  role       = aws_iam_role.irsa_role.name
  policy_arn = aws_iam_policy.cluster_autoscaler[count.index].arn
}

resource "aws_iam_role_policy_attachment" "external_dns" {
  count      = var.enable_external_dns ? 1 : 0
  role       = aws_iam_role.irsa_role.name
  policy_arn = aws_iam_policy.external_dns[count.index].arn
}

resource "aws_iam_role_policy_attachment" "ebs_csi" {
  count      = var.enable_ebs_csi ? 1 : 0
  role       = aws_iam_role.irsa_role.name
  policy_arn = aws_iam_policy.ebs_csi[count.index].arn
}

resource "aws_iam_role_policy_attachment" "ebs_csi_kms" {
  count      = var.enable_ebs_csi && var.ebs_csi_kms_cmk_arn != "" ? 1 : 0
  role       = aws_iam_role.irsa_role.name
  policy_arn = aws_iam_policy.ebs_csi_kms[count.index].arn
}

resource "aws_iam_role_policy_attachment" "vpc_cni" {
  count      = var.enable_vpc_cni ? 1 : 0
  role       = aws_iam_role.irsa_role.name
  policy_arn = aws_iam_policy.vpc_cni[count.index].arn
}

resource "aws_iam_role_policy_attachment" "node_termination_handler" {
  count      = var.enable_node_termination_handler ? 1 : 0
  role       = aws_iam_role.irsa_role.name
  policy_arn = aws_iam_policy.node_termination_handler[count.index].arn
}

resource "aws_iam_role_policy_attachment" "karpenter" {
  count      = var.enable_karpenter ? 1 : 0
  role       = aws_iam_role.irsa_role.name
  policy_arn = aws_iam_policy.karpenter[count.index].arn
}

resource "aws_iam_role_policy_attachment" "lb_controller" {
  count      = var.enable_lb_controller ? 1 : 0
  role       = aws_iam_role.irsa_role.name
  policy_arn = aws_iam_policy.lb_controller[count.index].arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]
}

resource "aws_route_table" "private_a" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "private_b" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private_a.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private_b.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.us-east-1.s3"
  route_table_ids = [
    aws_route_table.private_a.id,
    aws_route_table.private_b.id,
  ]
}

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]
}

resource "aws_network_acl_rule" "allow_all_tcp_ingress" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  egress         = false
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "allow_all_tcp_egress" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  egress         = true
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "allow_all_udp_ingress" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 110
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  egress         = false
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "allow_all_udp_egress" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 110
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  egress         = true
  from_port      = 0
  to_port        = 65535
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "name_prefix" {
  description = "Prefix used for resource names"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment label"
  type        = string
  default     = "STAGE"
}

variable "enable_ses_template" {
  description = "Enable SES template resource"
  type        = bool
  default     = true
}

variable "enable_receipt_rule" {
  description = "Enable SES receipt rule"
  type        = bool
  default     = false
}

variable "enable_receipt_rule_set" {
  description = "Enable SES receipt rule set"
  type        = bool
  default     = true
}

variable "enable_active_receipt_rule_set" {
  description = "Enable SES active receipt rule set"
  type        = bool
  default     = true
}

variable "enable_receipt_filter" {
  description = "Enable SES receipt filters"
  type        = bool
  default     = false
}

variable "enable_configuration_set" {
  description = "Enable SES configuration set"
  type        = bool
  default     = true
}

variable "enable_domain_identity" {
  description = "Enable SES domain identity"
  type        = bool
  default     = false
}

variable "enable_email_identity" {
  description = "Enable SES email identity"
  type        = bool
  default     = false
}

variable "enable_identity_policy" {
  description = "Enable SES identity policy"
  type        = bool
  default     = false
}

variable "enable_identity_notification_topic" {
  description = "Enable SES identity notification topics"
  type        = bool
  default     = false
}

variable "enable_domain_mail_from" {
  description = "Enable SES domain mail from"
  type        = bool
  default     = false
}

variable "enable_domain_identity_verification" {
  description = "Enable SES domain identity verification"
  type        = bool
  default     = false
}

variable "enable_domain_dkim" {
  description = "Enable SES domain DKIM"
  type        = bool
  default     = false
}

variable "enable_event_destination" {
  description = "Enable SES event destination"
  type        = bool
  default     = false
}

variable "domains" {
  description = "List of domains for SES domain identity and related features"
  type        = list(string)
  default     = []
}

variable "emails" {
  description = "List of email addresses for SES email identity"
  type        = list(string)
  default     = []
}

variable "receipt_filters" {
  description = "List of receipt filters with name, CIDR, and policy"
  type = list(object({
    name   = string
    cidr   = string
    policy = string
  }))
  default = []
}

variable "event_destinations" {
  description = "List of event destinations for SES configuration set"
  type = list(object({
    name             = string
    type             = string
    log_group_name   = optional(string)
    stream_name      = optional(string)
    topic_name       = optional(string)
    matching_types   = optional(list(string), ["send", "reject", "bounce", "complaint", "delivery"])
  }))
  default = []
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------

locals {
  name_prefix_lower = lower(var.name_prefix)
  environment_lower = lower(var.environment)

  # Common naming pattern: "<prefix>-<resource>-<environment>"
  # Used with lowercase prefix and environment.
  # e.g., "test-ses-template-stage"

  template_name               = "${local.name_prefix_lower}-ses-template-${local.environment_lower}"
  receipt_rule_name           = "${local.name_prefix_lower}-ses-receipt-rule-${local.environment_lower}"
  receipt_rule_set_name       = "${local.name_prefix_lower}-ses-receipt-rule-set-${local.environment_lower}"
  configuration_set_name      = "${local.name_prefix_lower}-ses-configuration-set-${local.environment_lower}"
  receipt_bucket_name         = "${local.name_prefix_lower}-ses-receipt-${local.environment_lower}"

  # Maps from event_destinations for for_each usage
  cloudwatch_destinations = var.enable_event_destination ? {
    for d in var.event_destinations : d.name => d if d.type == "cloudwatch"
  } : {}
  kinesis_destinations = var.enable_event_destination ? {
    for d in var.event_destinations : d.name => d if d.type == "kinesis"
  } : {}
  sns_destinations = var.enable_event_destination ? {
    for d in var.event_destinations : d.name => d if d.type == "sns"
  } : {}
}

# ------------------------------------------------------------------------------
# S3 RECEIPT BUCKET (Conditional)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "receipt_bucket" {
  count  = var.enable_receipt_rule ? 1 : 0
  bucket = local.receipt_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "receipt_bucket" {
  count  = var.enable_receipt_rule ? 1 : 0
  bucket = aws_s3_bucket.receipt_bucket[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "receipt_bucket" {
  count  = var.enable_receipt_rule ? 1 : 0
  bucket = aws_s3_bucket.receipt_bucket[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "receipt_bucket" {
  count  = var.enable_receipt_rule ? 1 : 0
  bucket = aws_s3_bucket.receipt_bucket[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# SES TEMPLATE
# ------------------------------------------------------------------------------

resource "aws_ses_template" "main" {
  count   = var.enable_ses_template ? 1 : 0
  name    = local.template_name
  subject = "Test Subject"
  html    = "<h1>Hello {{name}}</h1>"
  text    = "Hello {{name}}"
}

# ------------------------------------------------------------------------------
# SES RECEIPT RULE SET & ACTIVE RULE SET
# ------------------------------------------------------------------------------

resource "aws_ses_receipt_rule_set" "main" {
  count          = var.enable_receipt_rule_set ? 1 : 0
  rule_set_name  = local.receipt_rule_set_name
}

resource "aws_ses_active_receipt_rule_set" "main" {
  count          = var.enable_active_receipt_rule_set ? 1 : 0
  rule_set_name  = aws_ses_receipt_rule_set.main[0].rule_set_name
  depends_on     = [aws_ses_receipt_rule_set.main]
}

# ------------------------------------------------------------------------------
# SES RECEIPT RULE
# ------------------------------------------------------------------------------

resource "aws_ses_receipt_rule" "main" {
  count          = var.enable_receipt_rule ? 1 : 0
  name           = local.receipt_rule_name
  rule_set_name  = aws_ses_receipt_rule_set.main[0].rule_set_name
  recipients     = var.enable_receipt_rule ? var.emails : []
  enabled        = true
  scan_enabled   = true

  s3_action {
    bucket_name = aws_s3_bucket.receipt_bucket[0].id
    position    = 1
  }

  depends_on = [
    aws_s3_bucket.receipt_bucket,
    aws_ses_receipt_rule_set.main
  ]
}

# ------------------------------------------------------------------------------
# SES RECEIPT FILTERS
# ------------------------------------------------------------------------------

resource "aws_ses_receipt_filter" "filters" {
  for_each = var.enable_receipt_filter ? { for f in var.receipt_filters : f.name => f } : {}

  name   = each.value.name
  cidr   = each.value.cidr
  policy = each.value.policy
}

# ------------------------------------------------------------------------------
# SES CONFIGURATION SET
# ------------------------------------------------------------------------------

resource "aws_ses_configuration_set" "main" {
  count = var.enable_configuration_set ? 1 : 0
  name  = local.configuration_set_name
}

# ------------------------------------------------------------------------------
# SES DOMAIN & EMAIL IDENTITIES
# ------------------------------------------------------------------------------

resource "aws_ses_domain_identity" "domains" {
  for_each = var.enable_domain_identity ? toset(var.domains) : toset([])
  domain   = each.key
}

resource "aws_ses_email_identity" "emails" {
  for_each = var.enable_email_identity ? toset(var.emails) : toset([])
  email    = each.key
}

# ------------------------------------------------------------------------------
# SES IDENTITY POLICY (Domain)
# ------------------------------------------------------------------------------

resource "aws_ses_identity_policy" "domain_policies" {
  for_each = var.enable_identity_policy && var.enable_domain_identity ? { for d in var.domains : d => aws_ses_domain_identity.domains[d].arn } : {}

  identity = each.value
  name     = "${local.name_prefix_lower}-ses-domain-policy-${each.key}"
  policy   = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ses:SendEmail", "ses:SendRawEmail"]
        Resource = each.value
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# SES IDENTITY NOTIFICATION TOPICS (Bounce, Complaint, Delivery)
# ------------------------------------------------------------------------------

# SNS topics for notification types
resource "aws_sns_topic" "bounce" {
  count = var.enable_identity_notification_topic ? 1 : 0
  name  = "${local.name_prefix_lower}-ses-bounce-${local.environment_lower}"
}

resource "aws_sns_topic_policy" "bounce" {
  count  = var.enable_identity_notification_topic ? 1 : 0
  arn    = aws_sns_topic.bounce[0].arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowSESSendNotification"
        Effect    = "Allow"
        Principal = { Service = "ses.amazonaws.com" }
        Action    = "SNS:Publish"
        Resource  = aws_sns_topic.bounce[0].arn
      }
    ]
  })
}

resource "aws_ses_identity_notification_topic" "bounce" {
  count             = var.enable_identity_notification_topic ? 1 : 0
  identity          = var.enable_domain_identity ? var.domains[0] : ""
  notification_type = "Bounce"
  topic_arn         = aws_sns_topic.bounce[0].arn
}

resource "aws_sns_topic" "complaint" {
  count = var.enable_identity_notification_topic ? 1 : 0
  name  = "${local.name_prefix_lower}-ses-complaint-${local.environment_lower}"
}

resource "aws_sns_topic_policy" "complaint" {
  count  = var.enable_identity_notification_topic ? 1 : 0
  arn    = aws_sns_topic.complaint[0].arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowSESSendNotification"
        Effect    = "Allow"
        Principal = { Service = "ses.amazonaws.com" }
        Action    = "SNS:Publish"
        Resource  = aws_sns_topic.complaint[0].arn
      }
    ]
  })
}

resource "aws_ses_identity_notification_topic" "complaint" {
  count             = var.enable_identity_notification_topic ? 1 : 0
  identity          = var.enable_domain_identity ? var.domains[0] : ""
  notification_type = "Complaint"
  topic_arn         = aws_sns_topic.complaint[0].arn
}

resource "aws_sns_topic" "delivery" {
  count = var.enable_identity_notification_topic ? 1 : 0
  name  = "${local.name_prefix_lower}-ses-delivery-${local.environment_lower}"
}

resource "aws_sns_topic_policy" "delivery" {
  count  = var.enable_identity_notification_topic ? 1 : 0
  arn    = aws_sns_topic.delivery[0].arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowSESSendNotification"
        Effect    = "Allow"
        Principal = { Service = "ses.amazonaws.com" }
        Action    = "SNS:Publish"
        Resource  = aws_sns_topic.delivery[0].arn
      }
    ]
  })
}

resource "aws_ses_identity_notification_topic" "delivery" {
  count             = var.enable_identity_notification_topic ? 1 : 0
  identity          = var.enable_domain_identity ? var.domains[0] : ""
  notification_type = "Delivery"
  topic_arn         = aws_sns_topic.delivery[0].arn
}

# ------------------------------------------------------------------------------
# SES DOMAIN MAIL FROM
# ------------------------------------------------------------------------------

resource "aws_ses_domain_mail_from" "main" {
  count                  = var.enable_domain_mail_from ? 1 : 0
  domain                 = var.enable_domain_identity ? var.domains[0] : ""
  mail_from_domain       = "bounce.${var.domains[0]}"
  behavior_on_mx_failure = "RejectMessage"
  depends_on             = [aws_ses_domain_identity.domains]
}

# ------------------------------------------------------------------------------
# SES DOMAIN IDENTITY VERIFICATION
# ------------------------------------------------------------------------------

resource "aws_ses_domain_identity_verification" "main" {
  count      = var.enable_domain_identity_verification ? 1 : 0
  domain     = var.enable_domain_identity ? var.domains[0] : ""
  depends_on = [aws_ses_domain_identity.domains]
}

# ------------------------------------------------------------------------------
# SES DOMAIN DKIM
# ------------------------------------------------------------------------------

resource "aws_ses_domain_dkim" "main" {
  count      = var.enable_domain_dkim ? 1 : 0
  domain     = var.enable_domain_identity ? var.domains[0] : ""
  depends_on = [aws_ses_domain_identity.domains]
}

# ------------------------------------------------------------------------------
# EVENT DESTINATION SUPPORTING RESOURCES
# ------------------------------------------------------------------------------

# CloudWatch Log Groups
resource "aws_cloudwatch_log_group" "event_destinations" {
  for_each = local.cloudwatch_destinations

  name              = each.value.log_group_name != null ? each.value.log_group_name : "${local.name_prefix_lower}-ses-${each.key}-${local.environment_lower}"
  retention_in_days = var.enable_event_destination ? 7 : 0
}

# Kinesis Streams
resource "aws_kinesis_stream" "event_destinations" {
  for_each = local.kinesis_destinations

  name        = each.value.stream_name != null ? each.value.stream_name : "${local.name_prefix_lower}-ses-${each.key}-${local.environment_lower}"
  shard_count = 1

  lifecycle {
    prevent_destroy = true
  }
}

# SNS Topics for Event Destinations
resource "aws_sns_topic" "event_destinations" {
  for_each = local.sns_destinations

  name = each.value.topic_name != null ? each.value.topic_name : "${local.name_prefix_lower}-ses-${each.key}-${local.environment_lower}"
}

resource "aws_sns_topic_policy" "event_destinations" {
  for_each = local.sns_destinations
  arn      = aws_sns_topic.event_destinations[each.key].arn
  policy   = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowSESSendNotification"
        Effect    = "Allow"
        Principal = { Service = "ses.amazonaws.com" }
        Action    = "SNS:Publish"
        Resource  = aws_sns_topic.event_destinations[each.key].arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# IAM ROLE FOR EVENT DESTINATIONS
# ------------------------------------------------------------------------------

resource "aws_iam_role" "ses_event_destination_role" {
  count = var.enable_event_destination ? 1 : 0
  name  = "${local.name_prefix_lower}-ses-event-destination-role-${local.environment_lower}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ses.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

# IAM Policies for Event Destinations (Least Privilege)
resource "aws_iam_policy" "cloudwatch_logs" {
  count = length(local.cloudwatch_destinations) > 0 ? 1 : 0
  name  = "${local.name_prefix_lower}-ses-cloudwatch-logs-policy-${local.environment_lower}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = [for cw in aws_cloudwatch_log_group.event_destinations : "${cw.arn}:*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudwatch_logs" {
  count      = length(local.cloudwatch_destinations) > 0 ? 1 : 0
  role       = aws_iam_role.ses_event_destination_role[0].name
  policy_arn = aws_iam_policy.cloudwatch_logs[0].arn
}

resource "aws_iam_policy" "kinesis" {
  count = length(local.kinesis_destinations) > 0 ? 1 : 0
  name  = "${local.name_prefix_lower}-ses-kinesis-policy-${local.environment_lower}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["kinesis:PutRecord", "kinesis:PutRecords"]
        Resource = [for k in aws_kinesis_stream.event_destinations : k.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis" {
  count      = length(local.kinesis_destinations) > 0 ? 1 : 0
  role       = aws_iam_role.ses_event_destination_role[0].name
  policy_arn = aws_iam_policy.kinesis[0].arn
}

resource "aws_iam_policy" "sns" {
  count = length(local.sns_destinations) > 0 ? 1 : 0
  name  = "${local.name_prefix_lower}-ses-sns-policy-${local.environment_lower}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = [for t in aws_sns_topic.event_destinations : t.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sns" {
  count      = length(local.sns_destinations) > 0 ? 1 : 0
  role       = aws_iam_role.ses_event_destination_role[0].name
  policy_arn = aws_iam_policy.sns[0].arn
}

# ------------------------------------------------------------------------------
# SES EVENT DESTINATION
# ------------------------------------------------------------------------------

resource "aws_ses_event_destination" "main" {
  for_each = var.enable_event_destination ? { for d in var.event_destinations : d.name => d } : {}

  name                   = each.value.name
  configuration_set_name = aws_ses_configuration_set.main[0].name
  matching_types         = each.value.matching_types
  enabled                = true

  dynamic "cloudwatch_destination" {
    for_each = each.value.type == "cloudwatch" ? [1] : []
    content {
      dimension_name = "ses-event"
      value_source   = "emailHeader"
      default_value  = "none"
    }
  }

  dynamic "kinesis_destination" {
    for_each = each.value.type == "kinesis" ? [1] : []
    content {
      stream_arn = aws_kinesis_stream.event_destinations[each.key].arn
      role_arn   = aws_iam_role.ses_event_destination_role[0].arn
    }
  }

  dynamic "sns_destination" {
    for_each = each.value.type == "sns" ? [1] : []
    content {
      topic_arn = aws_sns_topic.event_destinations[each.key].arn
    }
  }

  depends_on = [
    aws_ses_configuration_set.main,
    aws_iam_role.ses_event_destination_role,
    aws_cloudwatch_log_group.event_destinations,
    aws_kinesis_stream.event_destinations,
    aws_sns_topic.event_destinations
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

locals {
  cluster_name = "demo-eks"
}

variable "eks_version" {
  description = "Kubernetes version for the EKS cluster"
  type        = string
  default     = "1.30"
}

variable "ssh_cidr_blocks" {
  description = "CIDR blocks allowed SSH access to worker nodes (internal only)"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "eks_optimized" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["amazon-eks-node-*"]
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name                                   = "demo-eks-vpc"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name                                   = "demo-eks-igw"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

# Public Subnets (3)
resource "aws_subnet" "public" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                                   = "demo-eks-public-${count.index + 1}"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

# Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name                                   = "demo-eks-public-rt"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

# Route Table Associations
resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# IAM Role for EKS Cluster
resource "aws_iam_role" "cluster" {
  name = "eksClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

resource "aws_iam_role_policy_attachment" "cluster_AmazonEKSClusterPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster.name
}

# IAM Role for Worker Nodes
resource "aws_iam_role" "node" {
  name = "eks-demo-node"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

resource "aws_iam_role_policy_attachment" "node_AmazonEKSWorkerNodePolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_AmazonEKS_CNI_Policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_AmazonEC2ContainerRegistryReadOnly" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_AmazonSSMManagedInstanceCore" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
  role       = aws_iam_role.node.name
}

# Instance profile for worker nodes
resource "aws_iam_instance_profile" "node" {
  name = "eks-demo-node-profile"
  role = aws_iam_role.node.name
}

# SSH Key Pair
resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "eks" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh

  tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

resource "local_file" "private_key" {
  content         = tls_private_key.eks.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0600"
}

# KMS Key for EKS Secret Encryption
resource "aws_kms_key" "eks" {
  description             = "EKS secret encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

# Security Group for Control Plane (no ingress rules that reference node SG)
resource "aws_security_group" "control_plane" {
  name        = "demo-eks-control-plane-sg"
  description = "Security group for EKS cluster control plane"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name                                   = "demo-eks-control-plane-sg"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

# Security Group for Worker Nodes (no ingress rules that reference control plane SG)
resource "aws_security_group" "node" {
  name        = "demo-eks-node-sg"
  description = "Security group for EKS worker nodes"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow SSH (internal)"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.ssh_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name                                   = "demo-eks-node-sg"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

# Separate ingress rule: control plane allows HTTPS from nodes
resource "aws_security_group_rule" "control_plane_ingress_from_node" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.node.id
  security_group_id        = aws_security_group.control_plane.id
}

# Separate ingress rule: nodes allow HTTPS from control plane
resource "aws_security_group_rule" "node_ingress_from_control_plane_443" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.control_plane.id
  security_group_id        = aws_security_group.node.id
}

# Separate ingress rule: nodes allow kubelet/node ports from control plane
resource "aws_security_group_rule" "node_ingress_from_control_plane_kubelet" {
  type                     = "ingress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.control_plane.id
  security_group_id        = aws_security_group.node.id
}

# VPC Endpoints for ECR and S3 (nodes need these to pull images without internet)
resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type = "Interface"
  subnet_ids        = aws_subnet.public[*].id
  security_group_ids = [aws_security_group.node.id]
  private_dns_enabled = true

  tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type = "Interface"
  subnet_ids        = aws_subnet.public[*].id
  security_group_ids = [aws_security_group.node.id]
  private_dns_enabled = true

  tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

# VPC Endpoint for EKS (needed for private cluster access)
resource "aws_vpc_endpoint" "eks" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.eks"
  vpc_endpoint_type = "Interface"
  subnet_ids        = aws_subnet.public[*].id
  security_group_ids = [aws_security_group.control_plane.id]
  private_dns_enabled = true

  tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

# Launch Template for Worker Nodes
resource "aws_launch_template" "node" {
  name_prefix   = "demo-eks-node-"
  image_id      = data.aws_ami.eks_optimized.id
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks.key_name

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size = 30
      volume_type = "gp2"
    }
  }

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  iam_instance_profile {
    arn = aws_iam_instance_profile.node.arn
  }

  vpc_security_group_ids = [aws_security_group.node.id]

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name                                   = "demo-eks-node"
      "kubernetes.io/cluster/${local.cluster_name}" = "owned"
    }
  }

  tag_specifications {
    resource_type = "volume"
    tags = {
      "kubernetes.io/cluster/${local.cluster_name}" = "owned"
    }
  }

  tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }
}

# Auto Scaling Group (Unmanaged Node Group)
resource "aws_autoscaling_group" "node" {
  name                = "demo-eks-node-asg"
  vpc_zone_identifier = aws_subnet.public[*].id
  desired_capacity    = 3
  min_size            = 1
  max_size            = 4

  launch_template {
    id      = aws_launch_template.node.id
    version = "$Latest"
  }

  tag {
    key                 = "kubernetes.io/cluster/${local.cluster_name}"
    value               = "owned"
    propagate_at_launch = true
  }

  tag {
    key                 = "Name"
    value               = "demo-eks-node"
    propagate_at_launch = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

# EKS Cluster
resource "aws_eks_cluster" "demo" {
  name     = local.cluster_name
  role_arn = aws_iam_role.cluster.arn
  version  = var.eks_version

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  vpc_config {
    subnet_ids              = aws_subnet.public[*].id
    security_group_ids      = [aws_security_group.control_plane.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_AmazonEKSClusterPolicy,
    aws_security_group.control_plane,
  ]

  tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

data "aws_iam_policy" "AmazonEC2RoleforAWSCodeDeploy" {
  name = "AmazonEC2RoleforAWSCodeDeploy"
}

data "aws_iam_policy" "AmazonEC2FullAccess" {
  name = "AmazonEC2FullAccess"
}

data "aws_iam_policy" "AWSCodeDeployRole" {
  name = "AWSCodeDeployRole"
}

data "aws_iam_policy" "CloudWatchAgentServerPolicy" {
  name = "CloudWatchAgentServerPolicy"
}

variable "project_name" {
  default = "Cv-React-App"
  type    = string
}

locals {
  account_id    = data.aws_caller_identity.current.account_id
  region        = data.aws_region.current.name
  partition     = data.aws_partition.current.partition
  codebuild_log_arn       = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/codebuild/*"
  codepipeline_s3_bucket  = "arn:${local.partition}:s3:::codepipeline-${var.project_name}*"
  codepipeline_s3_key     = "arn:${local.partition}:s3:::codepipeline-${var.project_name}/*"
  codebuild_report_arn    = "arn:${local.partition}:codebuild:${local.region}:${local.account_id}:report-group/*"
  codebuild_role_name     = "CodeBuildRole"
  codepipeline_role_name  = "CodePipelineRole"
}

resource "aws_iam_policy" "s3_cicd_minimal" {
  name        = "s3-cicd-minimal-${var.project_name}"
  description = "Minimal S3 permissions for CI/CD pipeline on codepipeline buckets"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "MinimalS3Actions"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:PutObjectAcl",
          "s3:GetObjectVersion"
        ]
        Resource = [
          local.codepipeline_s3_bucket,
          local.codepipeline_s3_key
        ]
      }
    ]
  })
}

resource "aws_iam_role" "ec2_codedeploy" {
  name = "ec2-codedeploy-${var.project_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_codedeploy" {
  name = "ec2-codedeploy-profile-${var.project_name}"
  role = aws_iam_role.ec2_codedeploy.name
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_ec2_codedeploy" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = data.aws_iam_policy.AmazonEC2RoleforAWSCodeDeploy.arn
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_ec2_full_access" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = data.aws_iam_policy.AmazonEC2FullAccess.arn
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_s3_cicd" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = aws_iam_policy.s3_cicd_minimal.arn
}

resource "aws_iam_role" "codedeploy_service" {
  name = "codedeploy-service-${var.project_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_codedeploy_role" {
  role       = aws_iam_role.codedeploy_service.name
  policy_arn = data.aws_iam_policy.AWSCodeDeployRole.arn
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_s3_cicd" {
  role       = aws_iam_role.codedeploy_service.name
  policy_arn = aws_iam_policy.s3_cicd_minimal.arn
}

resource "aws_iam_role" "codebuild" {
  name = local.codebuild_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_cicd" {
  role       = aws_iam_role.codebuild.name
  policy_arn = aws_iam_policy.s3_cicd_minimal.arn
}

resource "aws_iam_role_policy" "codebuild_inline" {
  name   = "codebuild-inline-${var.project_name}"
  role   = aws_iam_role.codebuild.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = local.codebuild_log_arn
      },
      {
        Sid    = "S3OnCodepipelineBuckets"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          local.codepipeline_s3_bucket,
          local.codepipeline_s3_key
        ]
      },
      {
        Sid    = "CodeBuildReports"
        Effect = "Allow"
        Action = [
          "codebuild:CreateReportGroup",
          "codebuild:CreateReport",
          "codebuild:UpdateReport",
          "codebuild:BatchPutTestCases"
        ]
        Resource = local.codebuild_report_arn
      }
    ]
  })
}

resource "aws_iam_role" "codepipeline" {
  name = local.codepipeline_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "codepipeline.amazonaws.com",
            "codebuild.amazonaws.com",
            "codedeploy.amazonaws.com",
            "ec2.amazonaws.com",
            "ecs-tasks.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::*:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_inline" {
  name   = "codepipeline-inline-${var.project_name}"
  role   = aws_iam_role.codepipeline.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeStarConnections"
        Effect = "Allow"
        Action = [
          "codestar-connections:UseConnection",
          "codestar-connections:PassConnection"
        ]
        Resource = "arn:${local.partition}:codestar-connections:*:*:connection/*"
      },
      {
        Sid    = "S3OnCodepipelineBuckets"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          local.codepipeline_s3_bucket,
          local.codepipeline_s3_key
        ]
      },
      {
        Sid    = "CodeCommit"
        Effect = "Allow"
        Action = [
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:GetRepository",
          "codecommit:GetUploadArchiveStatus",
          "codecommit:UploadArchive"
        ]
        Resource = "arn:${local.partition}:codecommit:${local.region}:${local.account_id}:${var.project_name}*"
      },
      {
        Sid    = "CodeDeploy"
        Effect = "Allow"
        Action = [
          "codedeploy:GetApplication",
          "codedeploy:GetDeployment",
          "codedeploy:GetDeploymentGroup",
          "codedeploy:ListApplications",
          "codedeploy:ListDeployments",
          "codedeploy:ListDeploymentGroups",
          "codedeploy:RegisterApplicationRevision",
          "codedeploy:PutLifecycleEventHookExecutionStatus"
        ]
        Resource = "arn:${local.partition}:codedeploy:${local.region}:${local.account_id}:*"
      },
      {
        Sid    = "ElasticBeanstalk"
        Effect = "Allow"
        Action = [
          "elasticbeanstalk:DescribeApplications",
          "elasticbeanstalk:DescribeEnvironments",
          "elasticbeanstalk:DescribeEvents",
          "elasticbeanstalk:DescribeConfigurationSettings"
        ]
        Resource = "*"
      },
      {
        Sid    = "EC2"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeAddresses",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeVolumes",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeTags"
        ]
        Resource = "*"
      },
      {
        Sid    = "ElasticLoadBalancing"
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeRules"
        ]
        Resource = "*"
      },
      {
        Sid    = "AutoScaling"
        Effect = "Allow"
        Action = [
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeLaunchConfigurations",
          "autoscaling:DescribeScalingActivities",
          "autoscaling:DescribePolicies"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatch"
        Effect = "Allow"
        Action = [
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics",
          "cloudwatch:DescribeAlarms"
        ]
        Resource = "*"
      },
      {
        Sid    = "SNS"
        Effect = "Allow"
        Action = [
          "sns:Publish",
          "sns:ListTopics",
          "sns:GetTopicAttributes"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudFormation"
        Effect = "Allow"
        Action = [
          "cloudformation:DescribeStacks",
          "cloudformation:DescribeStackEvents",
          "cloudformation:GetTemplate",
          "cloudformation:ValidateTemplate",
          "cloudformation:CreateStack",
          "cloudformation:UpdateStack",
          "cloudformation:DeleteStack"
        ]
        Resource = "*"
      },
      {
        Sid    = "RDS"
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances",
          "rds:DescribeDBSnapshots",
          "rds:DescribeDBClusters",
          "rds:DescribeDBSubnetGroups"
        ]
        Resource = "*"
      },
      {
        Sid    = "SQS"
        Effect = "Allow"
        Action = [
          "sqs:SendMessage",
          "sqs:ReceiveMessage",
          "sqs:DeleteMessage",
          "sqs:GetQueueAttributes",
          "sqs:GetQueueUrl"
        ]
        Resource = "*"
      },
      {
        Sid    = "ECS"
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
          "ecs:DescribeTaskDefinition",
          "ecs:DescribeTasks",
          "ecs:ListServices",
          "ecs:ListTaskDefinitions",
          "ecs:ListTasks",
          "ecs:RunTask",
          "ecs:StopTask",
          "ecs:UpdateService"
        ]
        Resource = "*"
      },
      {
        Sid    = "IAMPassRole"
        Effect = "Allow"
        Action = ["iam:PassRole"]
        Resource = [
          aws_iam_role.ec2_codedeploy.arn,
          aws_iam_role.codedeploy_service.arn,
          aws_iam_role.codebuild.arn,
          aws_iam_role.codepipeline.arn,
          aws_iam_role.cloudwatch_agent.arn
        ]
      },
      {
        Sid    = "Lambda"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "lambda:GetFunction",
          "lambda:ListFunctions",
          "lambda:UpdateFunctionCode",
          "lambda:PublishVersion"
        ]
        Resource = "*"
      },
      {
        Sid    = "OpsWorks"
        Effect = "Allow"
        Action = [
          "opsworks:DescribeStacks",
          "opsworks:DescribeApps",
          "opsworks:DescribeLayers",
          "opsworks:DescribeInstances",
          "opsworks:DescribeDeployments",
          "opsworks:CreateDeployment"
        ]
        Resource = "*"
      },
      {
        Sid    = "CodeBuild"
        Effect = "Allow"
        Action = [
          "codebuild:StartBuild",
          "codebuild:BatchGetBuilds",
          "codebuild:StopBuild",
          "codebuild:ListBuilds",
          "codebuild:BatchGetProjects"
        ]
        Resource = "arn:${local.partition}:codebuild:${local.region}:${local.account_id}:project/${var.project_name}*"
      }
    ]
  })
}

resource "aws_iam_role" "cloudwatch_agent" {
  name = "cloudwatch-agent-${var.project_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "cloudwatch_agent" {
  name = "cloudwatch-agent-profile-${var.project_name}"
  role = aws_iam_role.cloudwatch_agent.name
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_cw_agent" {
  role       = aws_iam_role.cloudwatch_agent.name
  policy_arn = data.aws_iam_policy.CloudWatchAgentServerPolicy.arn
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_s3_cicd" {
  role       = aws_iam_role.cloudwatch_agent.name
  policy_arn = aws_iam_policy.s3_cicd_minimal.arn
}

output "codedeploy_role_arn" {
  value = aws_iam_role.codedeploy_service.arn
}

output "codebuild_role_arn" {
  value = aws_iam_role.codebuild.arn
}

output "codepipeline_role_arn" {
  value = aws_iam_role.codepipeline.arn
}

output "ec2_codedeploy_instance_profile_name" {
  value = aws_iam_instance_profile.ec2_codedeploy.name
}

output "cloudwatch_agent_instance_profile_name" {
  value = aws_iam_instance_profile.cloudwatch_agent.name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "external-vpc"
  }
}

resource "aws_vpc" "internal" {
  cidr_block           = "10.40.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "internal-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 4

  vpc_id                  = aws_vpc.external.id
  cidr_block              = cidrsubnet("10.41.0.0/16", 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = 4

  vpc_id            = aws_vpc.internal.id
  cidr_block        = cidrsubnet("10.40.0.0/16", 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name = "external-igw"
  }
}

resource "aws_default_route_table" "external" {
  default_route_table_id = aws_vpc.external.default_route_table_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external.id
  }

  tags = {
    Name = "external-default-route-table"
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.internal.cidr_block]
  }

  tags = {
    Name = "external-default-sg"
  }
}

resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id

  # No ingress or egress rules

  tags = {
    Name = "internal-default-sg"
  }
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "external-default-nacl"
  }
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    icmp_type  = -1
    icmp_code  = -1
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "internal-default-nacl"
  }
}

output "external_vpc_id" {
  value = aws_vpc.external.id
}

output "internal_vpc_id" {
  value = aws_vpc.internal.id
}

output "external_default_security_group_id" {
  value = aws_default_security_group.external.id
}

output "internal_default_security_group_id" {
  value = aws_default_security_group.internal.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

locals {
  security_group_id = var.existing_security_group_id != null ? var.existing_security_group_id : (try(aws_security_group.this[0].id, ""))
  label_name        = module.labels.name
  label_tags        = module.labels.tags
}

# Labels module for consistent naming and tagging
module "labels" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = ""
  name        = var.name
  stage       = var.environment
  environment = var.environment
  attributes  = []
  tags        = {}
}

# Data source for the default VPC (used when var.vpc_id is null)
data "aws_vpc" "default" {
  default = true
}

# Security Group - created only if an existing one is not provided
resource "aws_security_group" "this" {
  count = var.existing_security_group_id == null ? 1 : 0

  name        = local.label_name
  description = "Security group managed by Terraform for ${var.name} in ${var.environment}"
  vpc_id      = var.vpc_id != null ? var.vpc_id : data.aws_vpc.default.id
  tags        = local.label_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Ingress Rules
resource "aws_security_group_rule" "ingress" {
  for_each = { for idx, rule in var.ingress_rules : idx => rule }

  security_group_id = local.security_group_id
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, "")

  cidr_blocks              = try(each.value.cidr_blocks, null)
  source_security_group_id = try(each.value.source_security_group_id, null)
  self                     = try(each.value.self, null)
  prefix_list_ids          = try(each.value.prefix_list_id, null) != null ? [try(each.value.prefix_list_id, null)] : null
}

# Egress Rules
resource "aws_security_group_rule" "egress" {
  for_each = { for idx, rule in var.egress_rules : idx => rule }

  security_group_id = local.security_group_id
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, "")

  cidr_blocks              = try(each.value.cidr_blocks, null)
  source_security_group_id = try(each.value.source_security_group_id, null)
  self                     = try(each.value.self, null)
  prefix_list_ids          = try(each.value.prefix_list_id, null) != null ? [try(each.value.prefix_list_id, null)] : null
}

# Optional Managed Prefix List
resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create_prefix_list ? 1 : 0

  name           = "prefix-list-${local.label_name}"
  address_family = "IPv4"
  max_entries    = length(var.prefix_list_entries)

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = local.label_tags
}

# Variables
variable "vpc_id" {
  description = "The ID of the VPC where the security group will reside. If not provided, the default VPC is used."
  type        = string
  default     = null
}

variable "name" {
  description = "Name of the application or component (used in labels)"
  type        = string
  default     = "my-app"
}

variable "environment" {
  description = "Environment name (e.g., dev, prod) used in labels"
  type        = string
  default     = "dev"
}

variable "existing_security_group_id" {
  description = "ID of an existing security group to attach rules to. If null, a new SG is created."
  type        = string
  default     = null
}

variable "ingress_rules" {
  description = <<-EOT
    List of ingress rules. Each rule must contain from_port, to_port, protocol, and exactly one of:
    cidr_blocks, self, source_security_group_id, or prefix_list_id.
    Optional: description.
  EOT
  type = list(object({
    description              = optional(string)
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string))
    self                     = optional(bool)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.ingress_rules :
      (rule.cidr_blocks != null ? 1 : 0) +
      (rule.self != null ? 1 : 0) +
      (rule.source_security_group_id != null ? 1 : 0) +
      (rule.prefix_list_id != null ? 1 : 0) == 1
    ])
    error_message = "Each ingress rule must specify exactly one source type: cidr_blocks, self, source_security_group_id, or prefix_list_id."
  }
}

variable "egress_rules" {
  description = <<-EOT
    List of egress rules. Same structure as ingress_rules.
  EOT
  type = list(object({
    description              = optional(string)
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string))
    self                     = optional(bool)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.egress_rules :
      (rule.cidr_blocks != null ? 1 : 0) +
      (rule.self != null ? 1 : 0) +
      (rule.source_security_group_id != null ? 1 : 0) +
      (rule.prefix_list_id != null ? 1 : 0) == 1
    ])
    error_message = "Each egress rule must specify exactly one source type: cidr_blocks, self, source_security_group_id, or prefix_list_id."
  }
}

variable "create_prefix_list" {
  description = "Whether to create a managed prefix list"
  type        = bool
  default     = false
}

variable "prefix_list_entries" {
  description = "Entries for the managed prefix list (required if create_prefix_list is true)"
  type = list(object({
    cidr        = string
    description = string
  }))
  default = []
}

# Outputs
output "security_group_id" {
  description = "ID of the security group (created or existing)"
  value       = local.security_group_id
}

output "security_group_arn" {
  description = "ARN of the security group (created only; null if existing is used)"
  value       = try(aws_security_group.this[0].arn, null)
}

output "prefix_list_id" {
  description = "ID of the created prefix list (null if not created)"
  value       = try(aws_ec2_managed_prefix_list.this[0].id, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 3.0"
    }
  }
}

# Data sources for AZs and AMI
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

# Local values for convenience
locals {
  vpc_cidr            = "192.168.0.0/16"
  public_subnet_cidrs = ["192.168.1.0/24", "192.168.2.0/24"]
  private_subnet_cidrs = ["192.168.10.0/24", "192.168.20.0/24"]
  az_count            = 2
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "terraform-vpc"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "terraform-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "terraform-nat-eip"
  }
}

# NAT Gateway in first public subnet
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "terraform-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

# Public route table associations
resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "private-rt"
  }
}

# Private route table associations
resource "aws_route_table_association" "private" {
  count = local.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security group for ALB
resource "aws_security_group" "alb" {
  name        = "alb-sg"
  description = "Allow HTTP from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-sg"
  }
}

# Security group for EC2 instances (allow HTTP only from ALB)
resource "aws_security_group" "ec2" {
  name        = "ec2-sg"
  description = "Allow HTTP from ALB only"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  tags = {
    Name = "ec2-sg"
  }
}

# Local file for user_data script
resource "local_file" "user_data" {
  content = <<-EOF
#!/bin/bash
yum install -y httpd
systemctl start httpd
systemctl enable httpd
echo "<html><body><h1>Hello from $(hostname -f)</h1></body></html>" > /var/www/html/index.html
EOF

  filename = "${path.module}/user_data.sh"
}

# TLS private key for self-signed certificate
resource "tls_private_key" "self" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

# Self-signed TLS certificate
resource "tls_self_signed_cert" "self" {
  private_key_pem = tls_private_key.self.private_key_pem

  subject {
    common_name = "terraform-alb.local"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

# Import certificate into ACM
resource "aws_acm_certificate" "self" {
  private_key      = tls_private_key.self.private_key_pem
  certificate_body = tls_self_signed_cert.self.cert_pem

  tags = {
    Name = "terraform-alb-cert"
  }
}

# Application Load Balancer (internal to satisfy security policy)
resource "aws_lb" "main" {
  name                       = "terraform-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "terraform-alb"
  }
}

# Target group
resource "aws_lb_target_group" "main" {
  name     = "terraform-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    healthy_threshold   = 2
    unhealthy_threshold = 2
    interval            = 30
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    timeout             = 5
    matcher             = "200"
  }

  tags = {
    Name = "terraform-tg"
  }
}

# Listener (HTTPS with modern SSL policy)
resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.self.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

# EC2 instances (private subnets)
resource "aws_instance" "web" {
  count = local.az_count

  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.private[count.index].id
  vpc_security_group_ids = [aws_security_group.ec2.id]
  user_data_base64       = base64encode(local_file.user_data.content)

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted  = true
    volume_size = 8
  }

  tags = {
    Name = "web-${count.index + 1}"
  }
}

# Target group attachments
resource "aws_lb_target_group_attachment" "web" {
  count = local.az_count

  target_group_arn = aws_lb_target_group.main.arn
  target_id        = aws_instance.web[count.index].id
  port             = 80
}

# KMS key for S3 bucket encryption
resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform state S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name = "terraform-state-kms"
  }
}

resource "aws_kms_alias" "state" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.state.key_id
}

# S3 bucket for Terraform state
resource "aws_s3_bucket" "terraform_state" {
  bucket = "terraform-state-bucket-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

# S3 bucket versioning
resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

# S3 bucket server-side encryption with KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

# S3 bucket public access block
resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# DynamoDB table for state locking
resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Data source for current account ID (needed for unique S3 bucket name)
data "aws_caller_identity" "current" {}

# Outputs
output "alb_dns_name" {
  description = "DNS name of the Application Load Balancer"
  value       = aws_lb.main.dns_name
}

output "state_s3_bucket_arn" {
  description = "ARN of S3 bucket for Terraform state"
  value       = aws_s3_bucket.terraform_state.arn
}

output "dynamodb_table_name" {
  description = "Name of DynamoDB table for state locking"
  value       = aws_dynamodb_table.terraform_locks.name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "enabled" {
  type    = bool
  default = true
}

variable "create_security_group" {
  type    = bool
  default = true
}

variable "existing_security_group_id" {
  type    = string
  default = null
}

variable "name" {
  type    = string
  default = "example"
}

variable "namespace" {
  type    = string
  default = "acme"
}

variable "environment" {
  type    = string
  default = "dev"
}

variable "description" {
  type    = string
  default = "Managed by Terraform"
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "ingress_cidr_blocks" {
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = {
    "0.0.0.0/0" = {
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      description = "HTTPS from anywhere"
    },
    "203.0.113.0/24" = {
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      description = "SSH from restricted CIDR"
    }
  }
  validation {
    condition = alltrue([
      for rule in values(var.ingress_cidr_blocks) : contains(["tcp", "udp", "icmp", "-1"], rule.protocol)
    ])
    error_message = "Protocol must be one of: tcp, udp, icmp, -1."
  }
}

variable "ingress_self" {
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = {}
  validation {
    condition = alltrue([
      for rule in values(var.ingress_self) : contains(["tcp", "udp", "icmp", "-1"], rule.protocol)
    ])
    error_message = "Protocol must be one of: tcp, udp, icmp, -1."
  }
}

variable "ingress_security_groups" {
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = {}
  validation {
    condition = alltrue([
      for rule in values(var.ingress_security_groups) : contains(["tcp", "udp", "icmp", "-1"], rule.protocol)
    ])
    error_message = "Protocol must be one of: tcp, udp, icmp, -1."
  }
}

variable "ingress_prefix_lists" {
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = {}
  validation {
    condition = alltrue([
      for rule in values(var.ingress_prefix_lists) : contains(["tcp", "udp", "icmp", "-1"], rule.protocol)
    ])
    error_message = "Protocol must be one of: tcp, udp, icmp, -1."
  }
}

variable "egress_cidr_blocks" {
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = {
    "10.0.0.0/16" = {
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      description = "Allow all traffic to VPC CIDR"
    }
  }
  validation {
    condition = alltrue([
      for cidr, rule in var.egress_cidr_blocks : cidr != "0.0.0.0/0" && contains(["tcp", "udp", "icmp", "-1"], rule.protocol)
    ])
    error_message = "Unrestricted egress to 0.0.0.0/0 is not allowed, and protocol must be one of: tcp, udp, icmp, -1."
  }
}

variable "egress_self" {
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = {}
  validation {
    condition = alltrue([
      for rule in values(var.egress_self) : contains(["tcp", "udp", "icmp", "-1"], rule.protocol)
    ])
    error_message = "Protocol must be one of: tcp, udp, icmp, -1."
  }
}

variable "egress_security_groups" {
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = {}
  validation {
    condition = alltrue([
      for rule in values(var.egress_security_groups) : contains(["tcp", "udp", "icmp", "-1"], rule.protocol)
    ])
    error_message = "Protocol must be one of: tcp, udp, icmp, -1."
  }
}

variable "egress_prefix_lists" {
  type = map(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  default = {}
  validation {
    condition = alltrue([
      for rule in values(var.egress_prefix_lists) : contains(["tcp", "udp", "icmp", "-1"], rule.protocol)
    ])
    error_message = "Protocol must be one of: tcp, udp, icmp, -1."
  }
}

variable "create_prefix_list" {
  type    = bool
  default = false
}

variable "address_family" {
  type    = string
  default = "IPv4"
  validation {
    condition     = contains(["IPv4", "IPv6"], var.address_family)
    error_message = "Address family must be either 'IPv4' or 'IPv6'."
  }
}

variable "max_entries" {
  type    = number
  default = 20
  validation {
    condition     = var.max_entries >= 1
    error_message = "Max entries must be a positive integer (>= 1)."
  }
}

variable "prefix_list_entries" {
  type = list(object({
    cidr        = string
    description = string
  }))
  default = []
}

locals {
  labels = {
    id   = join("-", compact([var.namespace, var.environment, var.name]))
    tags = {
      Name        = join("-", compact([var.namespace, var.environment, var.name]))
      Environment = var.environment
      Namespace   = var.namespace
    }
  }
  sg_name          = "${local.labels.id}-sg"
  prefix_list_name = "${local.labels.id}-pl"

  security_group_id = var.enabled ? (
    var.create_security_group ? aws_security_group.this[0].id : var.existing_security_group_id
  ) : null

  prefix_list_id = var.enabled && var.create_prefix_list ? aws_ec2_managed_prefix_list.this[0].id : null
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_security_group" "this" {
  count       = var.enabled && var.create_security_group ? 1 : 0
  name        = local.sg_name
  description = var.description
  vpc_id      = aws_vpc.main.id

  tags = merge(local.labels.tags, var.tags)

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_security_group_rule" "ingress_cidr" {
  for_each          = var.enabled ? var.ingress_cidr_blocks : {}
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  cidr_blocks       = [each.key]
  security_group_id = local.security_group_id
}

resource "aws_security_group_rule" "ingress_self" {
  for_each          = var.enabled ? var.ingress_self : {}
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  self              = true
  security_group_id = local.security_group_id
}

resource "aws_security_group_rule" "ingress_security_groups" {
  for_each                 = var.enabled ? var.ingress_security_groups : {}
  type                     = "ingress"
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  description              = each.value.description
  source_security_group_id = each.key
  security_group_id        = local.security_group_id
}

resource "aws_security_group_rule" "ingress_prefix_lists" {
  for_each          = var.enabled ? var.ingress_prefix_lists : {}
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  prefix_list_ids   = [local.prefix_list_id]
  security_group_id = local.security_group_id
}

resource "aws_security_group_rule" "egress_cidr" {
  for_each          = var.enabled ? var.egress_cidr_blocks : {}
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  cidr_blocks       = [each.key]
  security_group_id = local.security_group_id
}

resource "aws_security_group_rule" "egress_self" {
  for_each          = var.enabled ? var.egress_self : {}
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  self              = true
  security_group_id = local.security_group_id
}

resource "aws_security_group_rule" "egress_security_groups" {
  for_each                 = var.enabled ? var.egress_security_groups : {}
  type                     = "egress"
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  description              = each.value.description
  source_security_group_id = each.key
  security_group_id        = local.security_group_id
}

resource "aws_security_group_rule" "egress_prefix_lists" {
  for_each          = var.enabled ? var.egress_prefix_lists : {}
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  prefix_list_ids   = [local.prefix_list_id]
  security_group_id = local.security_group_id
}

resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.enabled && var.create_prefix_list ? 1 : 0
  name           = local.prefix_list_name
  address_family = var.address_family
  max_entries    = var.max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(local.labels.tags, var.tags)
}

output "security_group_id" {
  value = local.security_group_id
}

output "prefix_list_id" {
  value = local.prefix_list_id
}

output "security_group_arn" {
  value = var.enabled && var.create_security_group ? aws_security_group.this[0].arn : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  common_tags = {
    Environment = "dev"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "dev" {
  cidr_block           = "10.32.0.0/20"
  enable_dns_hostnames = true
  tags = merge(local.common_tags, {
    Name = "dev-vpc"
  })
}

# Public bastion subnet (auto-assign public IP disabled to comply with AWS-0164)
resource "aws_subnet" "bastion" {
  vpc_id                  = aws_vpc.dev.id
  cidr_block              = "10.32.15.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name = "bastion-subnet"
  })
}

# Private RDS subnets (two separate AZs)
resource "aws_subnet" "rds_db_0" {
  vpc_id            = aws_vpc.dev.id
  cidr_block        = "10.32.0.0/28"
  availability_zone = data.aws_availability_zones.available.names[0]
  tags = merge(local.common_tags, {
    Name = "rds-db-subnet-0"
  })
}

resource "aws_subnet" "rds_db_1" {
  vpc_id            = aws_vpc.dev.id
  cidr_block        = "10.32.0.16/28"
  availability_zone = data.aws_availability_zones.available.names[1]
  tags = merge(local.common_tags, {
    Name = "rds-db-subnet-1"
  })
}

# Private Lambda subnet (first AZ)
resource "aws_subnet" "lambda" {
  vpc_id            = aws_vpc.dev.id
  cidr_block        = "10.32.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  tags = merge(local.common_tags, {
    Name = "lambda-subnet"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "dev" {
  vpc_id = aws_vpc.dev.id
  tags   = merge(local.common_tags, { Name = "dev-igw" })
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.dev.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.dev.id
  }
  tags = merge(local.common_tags, { Name = "public-rt" })
}

# Association to bastion subnet only
resource "aws_route_table_association" "bastion" {
  subnet_id      = aws_subnet.bastion.id
  route_table_id = aws_route_table.public.id
}

# Security groups (no inline rules to allow cross-references via rules)
resource "aws_security_group" "bastion_sg" {
  name        = "bastion-sg"
  description = "Security group for bastion host"
  vpc_id      = aws_vpc.dev.id
  tags        = merge(local.common_tags, { Name = "bastion-sg" })
}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for RDS PostgreSQL"
  vpc_id      = aws_vpc.dev.id
  tags        = merge(local.common_tags, { Name = "db-sg" })
}

resource "aws_security_group" "lambda_sg" {
  name        = "lambda-sg"
  description = "Security group for Lambda functions"
  vpc_id      = aws_vpc.dev.id
  tags        = merge(local.common_tags, { Name = "lambda-sg" })
}

# Bastion SG: ingress SSH from restricted CIDR (non‑wildcard to comply with AWS-0107)
resource "aws_security_group_rule" "bastion_ingress_ssh" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = ["10.0.0.0/8"]
  security_group_id = aws_security_group.bastion_sg.id
}

# Bastion SG: egress to DB SG (postgres)
resource "aws_security_group_rule" "bastion_egress_db" {
  type                     = "egress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.db_sg.id
  security_group_id        = aws_security_group.bastion_sg.id
}

# DB SG: ingress postgres from bastion SG
resource "aws_security_group_rule" "db_ingress_bastion" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.bastion_sg.id
  security_group_id        = aws_security_group.db_sg.id
}

# DB SG: ingress postgres from lambda SG
resource "aws_security_group_rule" "db_ingress_lambda" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.lambda_sg.id
  security_group_id        = aws_security_group.db_sg.id
}

# DB SG: egress to VPC CIDR
resource "aws_security_group_rule" "db_egress_vpc" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = [aws_vpc.dev.cidr_block]
  security_group_id = aws_security_group.db_sg.id
}

# Lambda SG: egress to VPC CIDR
resource "aws_security_group_rule" "lambda_egress_vpc" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = [aws_vpc.dev.cidr_block]
  security_group_id = aws_security_group.lambda_sg.id
}

# Default security group: no ingress, allow all outbound
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.dev.id

  ingress = []

  egress = [
    {
      protocol    = "-1"
      from_port   = 0
      to_port     = 0
      cidr_blocks = ["0.0.0.0/0"]
      description = "Allow all outbound"
      ipv6_cidr_blocks = []
      prefix_list_ids  = []
      security_groups  = []
      self             = false
    }
  ]

  tags = merge(local.common_tags, { Name = "default-sg" })
}

# Default network ACL: allow all inbound and outbound (nested block syntax)
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.dev.default_network_acl_id

  ingress {
    rule_no    = 100
    protocol   = -1
    from_port  = 0
    to_port    = 0
    action     = "allow"
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 100
    protocol   = -1
    from_port  = 0
    to_port    = 0
    action     = "allow"
    cidr_block = "0.0.0.0/0"
  }

  tags = merge(local.common_tags, { Name = "default-nacl" })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

# ----------------------------------------------------------------------
# VARIABLES
# ----------------------------------------------------------------------

variable "name_prefix" {
  description = "Prefix for all resource names"
  type        = string
  default     = "ffc"
}

variable "enable_kms" {
  description = "Enable KMS encryption for S3 and CloudTrail"
  type        = bool
  default     = true
}

variable "log_expiration_days" {
  description = "Number of days after which log objects expire"
  type        = number
  default     = 5
}

variable "member_account_id" {
  description = "AWS account ID of member account for cross-account SNS subscription (optional)"
  type        = string
  default     = ""
}

variable "member_role_name" {
  description = "Role name in member account for cross-account SNS subscription (optional)"
  type        = string
  default     = ""
}

# ----------------------------------------------------------------------
# S3 BUCKET FOR CLOUDTRAIL LOGS
# ----------------------------------------------------------------------

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = "${var.name_prefix}-cloudtrail-logs"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms ? aws_kms_key.cloudtrail_key[0].arn : null
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    id     = "cloudtrail-log-expiration"
    status = "Enabled"

    filter {}

    expiration {
      days = var.log_expiration_days
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AWSCloudTrailAclCheck"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "s3:GetBucketAcl"
        Resource  = aws_s3_bucket.cloudtrail_logs.arn
      },
      {
        Sid       = "AWSCloudTrailWrite"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# ----------------------------------------------------------------------
# SNS TOPIC FOR CLOUDTRAIL NOTIFICATIONS
# ----------------------------------------------------------------------

resource "aws_sns_topic" "cloudtrail_notifications" {
  name              = "${var.name_prefix}-cloudtrail-notifications"
  kms_master_key_id = var.enable_kms ? aws_kms_key.cloudtrail_key[0].arn : "alias/aws/sns"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_policy" "cloudtrail_notifications" {
  arn = aws_sns_topic.cloudtrail_notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid       = "AllowCloudTrailToPublish"
          Effect    = "Allow"
          Principal = { Service = "cloudtrail.amazonaws.com" }
          Action    = "sns:Publish"
          Resource  = aws_sns_topic.cloudtrail_notifications.arn
        }
      ],
      (var.member_account_id != "" && var.member_role_name != "") ? [
        {
          Sid       = "AllowCrossAccountSubscribe"
          Effect    = "Allow"
          Principal = { AWS = "arn:aws:iam::${var.member_account_id}:role/${var.member_role_name}" }
          Action    = "sns:Subscribe"
          Resource  = aws_sns_topic.cloudtrail_notifications.arn
        }
      ] : []
    )
  })
}

# ----------------------------------------------------------------------
# KMS KEY (OPTIONAL)
# ----------------------------------------------------------------------

resource "aws_kms_key" "cloudtrail_key" {
  count                   = var.enable_kms ? 1 : 0
  description             = "KMS key for CloudTrail logs - ${var.name_prefix}"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "Enable IAM User Permissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "Allow CloudTrail to encrypt/decrypt logs"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid       = "Allow SNS to encrypt/decrypt messages"
        Effect    = "Allow"
        Principal = { Service = "sns.amazonaws.com" }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail_key_alias" {
  count         = var.enable_kms ? 1 : 0
  name          = "alias/${var.name_prefix}-cloudtrail"
  target_key_id = aws_kms_key.cloudtrail_key[0].id
}

# ----------------------------------------------------------------------
# IAM ROLE AND POLICY FOR CLOUDTRAIL
# ----------------------------------------------------------------------

resource "aws_iam_role" "cloudtrail_role" {
  name = "${var.name_prefix}-cloudtrail-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "cloudtrail_policy" {
  name = "${var.name_prefix}-cloudtrail-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3PutAndGet"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl"
        ]
        Resource = [
          aws_s3_bucket.cloudtrail_logs.arn,
          "${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/*"
        ]
      },
      {
        Sid       = "AllowSNSPublish"
        Effect    = "Allow"
        Action    = "sns:Publish"
        Resource  = aws_sns_topic.cloudtrail_notifications.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudtrail_role_attachment" {
  role       = aws_iam_role.cloudtrail_role.name
  policy_arn = aws_iam_policy.cloudtrail_policy.arn
}

# ----------------------------------------------------------------------
# CLOUDTRAIL
# ----------------------------------------------------------------------

resource "aws_cloudtrail" "main" {
  name                          = "${var.name_prefix}-trail"
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  sns_topic_name                = aws_sns_topic.cloudtrail_notifications.name
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  include_global_service_events = true
  is_organization_trail         = false
  kms_key_id                    = var.enable_kms ? aws_kms_key.cloudtrail_key[0].arn : null
}

# ----------------------------------------------------------------------
# OUTPUTS
# ----------------------------------------------------------------------

output "sns_topic_arn" {
  value = aws_sns_topic.cloudtrail_notifications.arn
}

output "s3_bucket_arn" {
  value = aws_s3_bucket.cloudtrail_logs.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Amazon side of a BGP session"
  type        = number
  default     = 65200
  validation {
    condition     = var.amazon_side_asn >= 64512 && var.amazon_side_asn <= 65533
    error_message = "The Amazon side ASN must be in the private ASN range (64512-65533)."
  }
}

variable "dns_support" {
  description = "Enable or disable DNS support in the transit gateway"
  type        = string
  default     = "enable"
  validation {
    condition     = contains(["enable", "disable"], var.dns_support)
    error_message = "Valid values for dns_support are 'enable' or 'disable'."
  }
}

variable "vpn_ecmp_support" {
  description = "Enable or disable VPN ECMP support in the transit gateway"
  type        = string
  default     = "enable"
  validation {
    condition     = contains(["enable", "disable"], var.vpn_ecmp_support)
    error_message = "Valid values for vpn_ecmp_support are 'enable' or 'disable'."
  }
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks to assign to the transit gateway"
  type        = list(string)
  default     = []
  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks :
      try(
        # IPv4: must be valid CIDR and prefix length >= 24
        can(regex("^(\\d{1,3}\\.){3}\\d{1,3}/(\\d{1,2})$", cidr)) && tonumber(regex("^(\\d{1,3}\\.){3}\\d{1,3}/(\\d{1,2})$", cidr)[1]) >= 24,
        # IPv6: must be valid CIDR and prefix length >= 64
        can(regex("^([0-9a-fA-F:]+)/(\\d{1,3})$", cidr)) && tonumber(regex("^([0-9a-fA-F:]+)/(\\d{1,3})$", cidr)[1]) >= 64
      )
    ])
    error_message = "Each transit gateway CIDR block must be a valid IPv4 (prefix >= 24) or IPv6 (prefix >= 64) CIDR."
  }
}

variable "route_tables" {
  description = "List of names for transit gateway route tables to create"
  type        = list(string)
  default     = []
}

variable "ram_share_accounts" {
  description = "List of AWS account IDs to share the transit gateway with via RAM"
  type        = list(string)
  default     = []
  validation {
    condition = alltrue([
      for a in var.ram_share_accounts : can(regex("^\\d{12}$", a))
    ])
    error_message = "Each account ID must be a 12-digit string."
  }
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default     = {}
}

locals {
  common_tags = var.tags
}

resource "aws_ec2_transit_gateway" "this" {
  amazon_side_asn                 = var.amazon_side_asn
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  tags = merge(local.common_tags, {
    Name = "transit-gateway"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = toset(var.route_tables)

  transit_gateway_id = aws_ec2_transit_gateway.this.id

  tags = merge(local.common_tags, {
    Name = each.value
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ram_resource_share" "this" {
  count = length(var.ram_share_accounts) > 0 ? 1 : 0

  name                      = "transit-gateway-share"
  allow_external_principals = false

  tags = merge(local.common_tags, {
    Name = "transit-gateway-share"
  })
}

resource "aws_ram_resource_association" "this" {
  count = length(var.ram_share_accounts) > 0 ? 1 : 0

  resource_share_arn = aws_ram_resource_share.this[0].arn
  resource_arn       = aws_ec2_transit_gateway.this.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ram_principal_association" "this" {
  count = length(var.ram_share_accounts) > 0 ? length(var.ram_share_accounts) : 0

  resource_share_arn = aws_ram_resource_share.this[0].arn
  principal          = var.ram_share_accounts[count.index]

  lifecycle {
    prevent_destroy = true
  }
}

output "transit_gateway_id" {
  description = "The ID of the created Transit Gateway"
  value       = aws_ec2_transit_gateway.this.id
}

output "route_table_ids" {
  description = "Map of route table names to their IDs"
  value       = { for k, rt in aws_ec2_transit_gateway_route_table.this : k => rt.id }
}

output "route_table_arns" {
  description = "Map of route table names to their ARNs"
  value       = { for k, rt in aws_ec2_transit_gateway_route_table.this : k => rt.arn }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default = {
    Environment = "dev"
    Project     = "ecs-codedeploy"
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# S3 bucket for granular permissions
resource "aws_s3_bucket" "ecs_data" {
  bucket = "ecs-codedeploy-data-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.region}"
  tags   = var.tags
}

resource "aws_s3_bucket_public_access_block" "ecs_data" {
  bucket                  = aws_s3_bucket.ecs_data.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "ecs_data" {
  bucket = aws_s3_bucket.ecs_data.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.ecs.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_kms_key" "ecs" {
  description             = "KMS key for ECS secrets and encryption"
  deletion_window_in_days = 7
  tags                    = var.tags
}

resource "aws_kms_alias" "ecs" {
  name          = "alias/ecs-key"
  target_key_id = aws_kms_key.ecs.key_id
}

# ------------------------------------------------------------------------------
# IAM Role: ECS Service Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ecs_service_role" {
  name        = "ecs_service_role"
  description = "IAM role for ECS service (integrations with ELB, CodeDeploy, etc.)"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy" "ecs_service_role_policy" {
  name   = "ecs_service_role_policy"
  role   = aws_iam_role.ecs_service_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "elasticloadbalancing:*"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "ec2:Describe*",
          "ec2:AuthorizeSecurityGroupIngress"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "ssm:GetParameter*"
        Resource = "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:parameter/*"
      },
      {
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = "arn:${data.aws_partition.current.partition}:secretsmanager:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:secret:*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.ecs.arn
      },
      {
        Effect   = "Allow"
        Action   = "codedeploy:*"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "cloudwatch:PutMetricData",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# IAM Role: ECS Task Execution Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_execution_role" {
  name        = "ecs_task_execution_role"
  description = "IAM role for ECS task execution (pull images, logs, secrets)"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs-tasks.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy" "ecs_task_execution_role_policy" {
  name   = "ecs_task_execution_role_policy"
  role   = aws_iam_role.ecs_task_execution_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "ecs:DescribeTasks"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = "arn:${data.aws_partition.current.partition}:secretsmanager:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:secret:*"
      },
      {
        Effect   = "Allow"
        Action   = "kms:Decrypt"
        Resource = aws_kms_key.ecs.arn
      },
      {
        Effect   = "Allow"
        Action   = "ssm:GetParameters"
        Resource = "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:parameter/*"
      },
      {
        Effect   = "Allow"
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.ecs_data.arn}/*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# IAM Role: ECS Task Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_role" {
  name        = "ecs_task_role"
  description = "IAM role for ECS tasks (service discovery, S3 operations)"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs-tasks.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy" "ecs_task_role_policy" {
  name   = "ecs_task_role_policy"
  role   = aws_iam_role.ecs_task_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "ecs:UpdateService",
          "servicediscovery:*"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.ecs_data.arn,
          "${aws_s3_bucket.ecs_data.arn}/*"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# IAM Role: Application Auto Scaling Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ecs_autoscaling_role" {
  name        = "ecs_autoscaling_role"
  description = "IAM role for Application Auto Scaling (ECS and CloudWatch)"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "application-autoscaling.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy" "ecs_autoscaling_role_policy" {
  name   = "ecs_autoscaling_role_policy"
  role   = aws_iam_role.ecs_autoscaling_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "ecs:UpdateService",
          "ecs:DescribeServices"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DeleteAlarms"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# IAM Role: CodeDeploy Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ecs_codedeploy_role" {
  name        = "ecs_codedeploy_role"
  description = "IAM role for CodeDeploy to manage ECS deployments"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_inline" {
  name   = "ecs_codedeploy_role_inline"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "codedeploy:*"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "ecs:CreateTaskSet",
          "ecs:UpdateServicePrimaryTaskSet",
          "ecs:DeleteTaskSet",
          "ecs:DescribeTaskSets"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "elasticloadbalancing:ModifyListener",
          "elasticloadbalancing:DescribeListeners"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:PutMetricAlarm"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.ecs_data.arn}/*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = [
          aws_iam_role.ecs_task_role.arn,
          aws_iam_role.ecs_task_execution_role.arn
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_id" {
  type        = string
  description = "VPC ID where the security group will be created or where the existing security group resides. If empty and new_sg is true, a VPC will be created."
  default     = ""
}

variable "name" {
  type        = string
  description = "Name component for the label."
  default     = "default"
}

variable "environment" {
  type        = string
  description = "Environment component (e.g., dev, prod)."
  default     = "dev"
}

variable "managed_by" {
  type        = string
  description = "Managed-by component for the label."
  default     = "terraform"
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes for the label."
  default     = []
}

variable "new_sg" {
  type        = bool
  description = "Whether to create a new security group or use an existing one."
  default     = true
}

variable "enabled" {
  type        = bool
  description = "Flag to enable/disable all resources."
  default     = true
}

variable "description" {
  type        = string
  description = "Description for the security group."
  default     = "Managed by Terraform"
}

variable "existing_security_group_id" {
  type        = string
  description = "ID of an existing security group to attach rules to when new_sg is false. Must be in the same VPC."
  default     = ""
}

variable "ingress_cidr_blocks" {
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
    description = string
  }))
  description = "Ingress rules using CIDR blocks."
  default     = []
}

variable "egress_cidr_blocks" {
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
    description = string
  }))
  description = "Egress rules using CIDR blocks."
  default     = []
}

variable "ingress_self" {
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  description = "Ingress rules referencing the security group itself."
  default     = []
}

variable "egress_self" {
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = string
  }))
  description = "Egress rules referencing the security group itself."
  default     = []
}

variable "ingress_security_group_id" {
  type = list(object({
    from_port               = number
    to_port                 = number
    protocol                = string
    source_security_group_id = string
    description             = string
  }))
  description = "Ingress rules referencing another security group ID."
  default     = []
}

variable "egress_security_group_id" {
  type = list(object({
    from_port               = number
    to_port                 = number
    protocol                = string
    source_security_group_id = string
    description             = string
  }))
  description = "Egress rules referencing another security group ID."
  default     = []
}

variable "ingress_prefix_list_id" {
  type = list(object({
    from_port      = number
    to_port        = number
    protocol       = string
    prefix_list_id = string
    description    = string
  }))
  description = "Ingress rules referencing a prefix list ID."
  default     = []
}

variable "egress_prefix_list_id" {
  type = list(object({
    from_port      = number
    to_port        = number
    protocol       = string
    prefix_list_id = string
    description    = string
  }))
  description = "Egress rules referencing a prefix list ID."
  default     = []
}

variable "create_prefix_list" {
  type        = bool
  description = "Whether to create a managed prefix list."
  default     = false
}

variable "address_family" {
  type        = string
  description = "Address family for the prefix list (IPv4 or IPv6)."
  default     = "IPv4"
}

variable "max_entries" {
  type        = number
  description = "Maximum number of entries for the prefix list."
  default     = 50
}

variable "prefix_list_entries" {
  type = list(object({
    cidr        = string
    description = string
  }))
  description = "List of entries for the prefix list."
  default     = []
}

module "label" {
  source      = "cloudposse/label/null"
  version     = "0.25.0"
  name        = var.name
  environment = var.environment
  attributes  = concat(var.attributes, [var.managed_by])
  tags        = { managed_by = var.managed_by }
}

locals {
  sg_id = var.new_sg ? aws_security_group.this[0].id : var.existing_security_group_id
  create_rules = var.enabled && (var.new_sg || var.existing_security_group_id != "")
  prefix_list_id = var.create_prefix_list ? aws_ec2_managed_prefix_list.this[0].id : ""
}

resource "aws_vpc" "this" {
  count      = var.new_sg && var.vpc_id == "" ? 1 : 0
  cidr_block = "10.0.0.0/16"
  tags       = module.label.tags
}

resource "aws_security_group" "this" {
  count       = var.enabled && var.new_sg ? 1 : 0
  name        = module.label.id
  description = var.description
  vpc_id      = coalesce(var.vpc_id, aws_vpc.this[0].id)
  tags        = module.label.tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "ingress_cidr" {
  for_each          = local.create_rules && length(var.ingress_cidr_blocks) > 0 ? { for idx, rule in var.ingress_cidr_blocks : idx => rule } : {}
  type              = "ingress"
  security_group_id = local.sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = each.value.cidr_blocks
  description       = each.value.description
}

resource "aws_security_group_rule" "egress_cidr" {
  for_each          = local.create_rules && length(var.egress_cidr_blocks) > 0 ? { for idx, rule in var.egress_cidr_blocks : idx => rule } : {}
  type              = "egress"
  security_group_id = local.sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = each.value.cidr_blocks
  description       = each.value.description
}

resource "aws_security_group_rule" "ingress_self" {
  for_each          = local.create_rules && length(var.ingress_self) > 0 ? { for idx, rule in var.ingress_self : idx => rule } : {}
  type              = "ingress"
  security_group_id = local.sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  self              = true
  description       = each.value.description
}

resource "aws_security_group_rule" "egress_self" {
  for_each          = local.create_rules && length(var.egress_self) > 0 ? { for idx, rule in var.egress_self : idx => rule } : {}
  type              = "egress"
  security_group_id = local.sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  self              = true
  description       = each.value.description
}

resource "aws_security_group_rule" "ingress_security_group_id" {
  for_each                  = local.create_rules && length(var.ingress_security_group_id) > 0 ? { for idx, rule in var.ingress_security_group_id : idx => rule } : {}
  type                      = "ingress"
  security_group_id         = local.sg_id
  from_port                 = each.value.from_port
  to_port                   = each.value.to_port
  protocol                  = each.value.protocol
  source_security_group_id  = each.value.source_security_group_id
  description               = each.value.description
}

resource "aws_security_group_rule" "egress_security_group_id" {
  for_each                  = local.create_rules && length(var.egress_security_group_id) > 0 ? { for idx, rule in var.egress_security_group_id : idx => rule } : {}
  type                      = "egress"
  security_group_id         = local.sg_id
  from_port                 = each.value.from_port
  to_port                   = each.value.to_port
  protocol                  = each.value.protocol
  source_security_group_id  = each.value.source_security_group_id
  description               = each.value.description
}

resource "aws_security_group_rule" "ingress_prefix_list" {
  for_each          = local.create_rules && length(var.ingress_prefix_list_id) > 0 ? { for idx, rule in var.ingress_prefix_list_id : idx => rule } : {}
  type              = "ingress"
  security_group_id = local.sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  prefix_list_ids   = [local.prefix_list_id != "" ? local.prefix_list_id : each.value.prefix_list_id]
  description       = each.value.description
}

resource "aws_security_group_rule" "egress_prefix_list" {
  for_each          = local.create_rules && length(var.egress_prefix_list_id) > 0 ? { for idx, rule in var.egress_prefix_list_id : idx => rule } : {}
  type              = "egress"
  security_group_id = local.sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  prefix_list_ids   = [local.prefix_list_id != "" ? local.prefix_list_id : each.value.prefix_list_id]
  description       = each.value.description
}

resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.enabled && var.create_prefix_list ? 1 : 0
  name           = module.label.id
  address_family = var.address_family
  max_entries    = var.max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = module.label.tags
}

output "security_group_id" {
  description = "ID of the security group (created or existing)."
  value       = local.sg_id
}

output "security_group_arn" {
  description = "ARN of the security group if newly created, otherwise empty."
  value       = var.new_sg ? aws_security_group.this[0].arn : ""
}

output "security_group_tags" {
  description = "Tags from the label module."
  value       = module.label.tags
}

output "prefix_list_id" {
  description = "ID of the created prefix list, if any."
  value       = local.prefix_list_id
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "namespace" {
  type        = string
  default     = ""
  description = "Optional namespace prefix for the repository name."
}

variable "name" {
  type        = string
  default     = "ecr"
  description = "Base name for the repository."
}

variable "use_random_name" {
  type        = bool
  default     = true
  description = "Append a random hex suffix to the repository name."
}

variable "image_tag_mutability" {
  type        = string
  default     = "IMMUTABLE"
  description = "The tag mutability setting for the repository. Defaults to 'IMMUTABLE' for security. Must be 'MUTABLE' or 'IMMUTABLE'."

  validation {
    condition     = contains(["MUTABLE", "IMMUTABLE"], var.image_tag_mutability)
    error_message = "image_tag_mutability must be either 'MUTABLE' or 'IMMUTABLE'."
  }
}

variable "scan_on_push" {
  type        = bool
  default     = true
  description = "Enable image scanning on push."
}

variable "trusted_account_ids" {
  type        = list(string)
  default     = []
  description = "List of AWS account IDs allowed to pull images from the repository."
}

data "aws_partition" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  base_name = join("-", compact([var.namespace, var.name]))
  repo_name = var.use_random_name ? "${local.base_name}-${random_id.suffix.hex}" : local.base_name
}

resource "aws_ecr_repository" "repo" {
  name                 = local.repo_name
  image_tag_mutability = var.image_tag_mutability
  force_delete         = false

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "expire_old" {
  repository = aws_ecr_repository.repo.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire images when count exceeds 2"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 2
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "ecr_read" {
  name        = "${local.repo_name}-read"
  description = "Read access to ECR repository ${local.repo_name}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadRepository"
        Effect = "Allow"
        Action = [
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:BatchCheckLayerAvailability",
          "ecr:DescribeRepositories",
          "ecr:ListImages"
        ]
        Resource = aws_ecr_repository.repo.arn
      },
      {
        Sid    = "GetAuthToken"
        Effect = "Allow"
        Action = ["ecr:GetAuthorizationToken"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "ecr_write" {
  name        = "${local.repo_name}-write"
  description = "Write access to ECR repository ${local.repo_name}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteRepository"
        Effect = "Allow"
        Action = [
          "ecr:PutImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload",
          "ecr:BatchCheckLayerAvailability"
        ]
        Resource = aws_ecr_repository.repo.arn
      }
    ]
  })
}

data "aws_iam_policy_document" "cross_account" {
  count = length(var.trusted_account_ids) > 0 ? 1 : 0

  statement {
    sid    = "CrossAccountPull"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [for account in var.trusted_account_ids : "arn:${data.aws_partition.current.partition}:iam::${account}:root"]
    }

    actions = [
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:BatchCheckLayerAvailability"
    ]

    resources = [aws_ecr_repository.repo.arn]
  }
}

resource "aws_ecr_repository_policy" "cross_account" {
  count      = length(var.trusted_account_ids) > 0 ? 1 : 0
  repository = aws_ecr_repository.repo.name
  policy     = data.aws_iam_policy_document.cross_account[0].json
}

output "repository_name" {
  value = aws_ecr_repository.repo.name
}

output "repository_arn" {
  value = aws_ecr_repository.repo.arn
}

output "read_policy_arn" {
  value = aws_iam_policy.ecr_read.arn
}

output "write_policy_arn" {
  value = aws_iam_policy.ecr_write.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "prefix" {
  description = "Resource name prefix"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

variable "domain_name" {
  description = "Certificate domain name. Derived from prefix and environment if not provided."
  type        = string
  default     = null
}

variable "subject_alternative_names" {
  description = "Additional domain names for the certificate"
  type        = list(string)
  default     = []
}

variable "certificate_acquisition_mode" {
  description = "How the certificate is acquired. One of: request, import, issue."
  type        = string
  default     = "request"

  validation {
    condition     = contains(["request", "import", "issue"], var.certificate_acquisition_mode)
    error_message = "certificate_acquisition_mode must be one of: 'request', 'import', 'issue'."
  }
}

variable "validation_method" {
  description = "Validation method for requested certificates: DNS or EMAIL"
  type        = string
  default     = "DNS"
}

variable "route53_zone_id" {
  description = "Route53 hosted zone ID for DNS validation records (required if validation_method=DNS)"
  type        = string
  default     = null
}

variable "private_key" {
  description = "PEM‑encoded private key for certificate import"
  type        = string
  default     = null
  sensitive   = true
}

variable "certificate_body" {
  description = "PEM‑encoded certificate body for import"
  type        = string
  default     = null
  sensitive   = true
}

variable "certificate_chain" {
  description = "PEM‑encoded certificate chain for import"
  type        = string
  default     = null
  sensitive   = true
}

variable "create_ca" {
  description = "Create a new AWS Private CA authority for issuing certificates"
  type        = bool
  default     = false
}

variable "acmpca_certificate_authority_arn" {
  description = "ARN of an existing ACMPCA to issue certificates from (ignored if create_ca is true)"
  type        = string
  default     = null
}

variable "ca_key_algorithm" {
  description = "Key algorithm for the CA (e.g., RSA_2048, EC_prime256v1)"
  type        = string
  default     = "RSA_2048"
}

variable "ca_signing_algorithm" {
  description = "Signing algorithm for the CA (e.g., SHA256WITHRSA)"
  type        = string
  default     = "SHA256WITHRSA"
}

variable "ca_subject" {
  description = "Subject details for the CA. Must include common_name, organization, etc."
  type = object({
    common_name         = string
    organization        = string
    organizational_unit = optional(string)
    country             = optional(string)
    state               = optional(string)
    locality            = optional(string)
  })
  default = {
    common_name  = "Test CA"
    organization = "Example Org"
  }
}

variable "ca_revocation_enabled" {
  description = "Enable CRL revocation for the CA"
  type        = bool
  default     = false
}

variable "ca_crl_bucket_name" {
  description = "S3 bucket name for CRL distribution (required if ca_revocation_enabled is true)"
  type        = string
  default     = null
}

variable "permanent_deletion_time_in_days" {
  description = "Number of days before permanent deletion of the CA"
  type        = number
  default     = 7
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  domain = var.domain_name != null ? var.domain_name : "${var.prefix}.${var.environment}.local"

  ca_arn = var.create_ca ? aws_acmpca_certificate_authority.this[0].arn : var.acmpca_certificate_authority_arn
}

# ------------------------------------------------------------------------------
# ACM Certificate Resources
# ------------------------------------------------------------------------------

# Request mode
resource "aws_acm_certificate" "requested" {
  count = var.certificate_acquisition_mode == "request" ? 1 : 0

  domain_name       = local.domain
  validation_method = var.validation_method
  subject_alternative_names = length(var.subject_alternative_names) > 0 ? var.subject_alternative_names : null

  lifecycle {
    create_before_destroy = true
  }
}

# Import mode
resource "aws_acm_certificate" "imported" {
  count = var.certificate_acquisition_mode == "import" ? 1 : 0

  private_key       = var.private_key
  certificate_body  = var.certificate_body
  certificate_chain = var.certificate_chain

  lifecycle {
    create_before_destroy = true
  }
}

# Issue mode
resource "aws_acm_certificate" "issued" {
  count = var.certificate_acquisition_mode == "issue" ? 1 : 0

  domain_name       = local.domain
  certificate_authority_arn = local.ca_arn
  subject_alternative_names = length(var.subject_alternative_names) > 0 ? var.subject_alternative_names : null

  lifecycle {
    create_before_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Optional Private CA
# ------------------------------------------------------------------------------

locals {
  create_crl_bucket = var.create_ca && var.ca_revocation_enabled && var.ca_crl_bucket_name != null
}

# S3 bucket for CRLs (if enabled)
resource "aws_s3_bucket" "ca_crl" {
  count = local.create_crl_bucket ? 1 : 0

  bucket        = var.ca_crl_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "ca_crl" {
  count = local.create_crl_bucket ? 1 : 0

  bucket = aws_s3_bucket.ca_crl[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "ca_crl" {
  count = local.create_crl_bucket ? 1 : 0

  bucket = aws_s3_bucket.ca_crl[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Private CA
resource "aws_acmpca_certificate_authority" "this" {
  count = var.create_ca ? 1 : 0

  permanent_deletion_time_in_days = var.permanent_deletion_time_in_days

  certificate_authority_configuration {
    key_algorithm     = var.ca_key_algorithm
    signing_algorithm = var.ca_signing_algorithm

    subject {
      common_name         = var.ca_subject.common_name
      organization        = var.ca_subject.organization
      organizational_unit = var.ca_subject.organizational_unit
      country             = var.ca_subject.country
      state               = var.ca_subject.state
      locality            = var.ca_subject.locality
    }
  }

  dynamic "revocation_configuration" {
    for_each = var.ca_revocation_enabled ? [1] : []
    content {
      crl_configuration {
        enabled = true
        s3_bucket_name = var.ca_crl_bucket_name
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# DNS Validation Record (for request mode with DNS validation)
# ------------------------------------------------------------------------------

resource "aws_route53_record" "acm_validation" {
  count = var.certificate_acquisition_mode == "request" && var.validation_method == "DNS" && var.route53_zone_id != null ? 1 : 0

  zone_id = var.route53_zone_id
  name    = one(aws_acm_certificate.requested[0].domain_validation_options).resource_record_name
  type    = one(aws_acm_certificate.requested[0].domain_validation_options).resource_record_type
  records = [one(aws_acm_certificate.requested[0].domain_validation_options).resource_record_value]
  ttl     = 60
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "certificate_arn" {
  description = "ARN of the ACM certificate"
  value = one(concat(
    aws_acm_certificate.requested[*].arn,
    aws_acm_certificate.imported[*].arn,
    aws_acm_certificate.issued[*].arn
  ))
}

output "certificate_id" {
  description = "ID of the ACM certificate"
  value = one(concat(
    aws_acm_certificate.requested[*].id,
    aws_acm_certificate.imported[*].id,
    aws_acm_certificate.issued[*].id
  ))
}

output "domain_validation_options" {
  description = "Domain validation options (only for request mode with DNS)"
  value = var.certificate_acquisition_mode == "request" && var.validation_method == "DNS" && length(aws_acm_certificate.requested) > 0 ? [
    for dvo in aws_acm_certificate.requested[0].domain_validation_options : {
      domain_name           = dvo.domain_name
      resource_record_name  = dvo.resource_record_name
      resource_record_type  = dvo.resource_record_type
      resource_record_value = dvo.resource_record_value
    }
  ] : []
}

output "ca_arn" {
  description = "ARN of the Private CA (if created)"
  value = try(aws_acmpca_certificate_authority.this[0].arn, null)
}

output "ca_serial" {
  description = "Serial number of the Private CA (if created)"
  value = try(aws_acmpca_certificate_authority.this[0].serial, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "CIDR blocks for the subnets (must be two for Multi-AZ)"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "instance_type" {
  description = "ElastiCache node instance type"
  type        = string
  default     = "cache.t3.micro"
}

variable "engine_version" {
  description = "Redis engine version"
  type        = string
  default     = "7.1"
}

variable "num_cache_clusters" {
  description = "Number of cache clusters (minimum 2 for Multi-AZ)"
  type        = number
  default     = 2
}

variable "parameter_group_family" {
  description = "Parameter group family (e.g., redis7)"
  type        = string
  default     = "redis7"
}

variable "maintenance_window" {
  description = "Maintenance window (e.g., sun:05:00-sun:06:00)"
  type        = string
  default     = "sun:05:00-sun:06:00"
}

variable "enable_global_datastore" {
  description = "Whether to create a Global Datastore from the primary replication group"
  type        = bool
  default     = false
}

variable "alarm_cpu_threshold" {
  description = "CPU utilization alarm threshold (percent)"
  type        = number
  default     = 80
}

variable "alarm_memory_threshold" {
  description = "DatabaseMemoryUsagePercentage alarm threshold (percent)"
  type        = number
  default     = 80
}

variable "alarm_evaluation_periods" {
  description = "Number of evaluation periods for alarms"
  type        = number
  default     = 3
}

variable "alarm_period" {
  description = "Period for alarms (seconds)"
  type        = number
  default     = 300
}

locals {
  name_prefix = "redis-demo"
  common_tags = {
    Environment = "demo"
    Terraform   = "true"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "cache" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags              = merge(local.common_tags, { Name = "${local.name_prefix}-subnet-${count.index}" })
}

resource "aws_elasticache_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group for Redis ElastiCache"
  subnet_ids  = aws_subnet.cache[*].id
  tags        = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elasticache_parameter_group" "main" {
  name        = "${local.name_prefix}-params"
  family      = var.parameter_group_family
  description = "Custom parameter group for Redis ${var.engine_version}"
  tags        = local.common_tags
}

resource "aws_security_group" "redis" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for Redis ElastiCache"
  vpc_id      = aws_vpc.main.id
  tags        = merge(local.common_tags, { Name = "${local.name_prefix}-sg" })
}

resource "aws_security_group_rule" "ingress_redis" {
  type              = "ingress"
  from_port         = 6379
  to_port           = 6379
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.redis.id
  description       = "Allow inbound Redis traffic"
}

resource "aws_security_group_rule" "egress_all" {
  type              = "egress"
  from_port         = 6379
  to_port           = 6379
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.redis.id
  description       = "Allow outbound Redis traffic within VPC"
}

resource "aws_elasticache_replication_group" "redis" {
  replication_group_id          = "${local.name_prefix}-rg"
  description                   = "Highly available Redis replication group"
  engine                        = "redis"
  engine_version                = var.engine_version
  node_type                     = var.instance_type
  num_cache_clusters            = var.num_cache_clusters
  parameter_group_name          = aws_elasticache_parameter_group.main.name
  subnet_group_name             = aws_elasticache_subnet_group.main.name
  security_group_ids            = [aws_security_group.redis.id]
  automatic_failover_enabled    = true
  multi_az_enabled              = var.num_cache_clusters >= 2 ? true : false
  at_rest_encryption_enabled    = true
  transit_encryption_enabled    = true
  maintenance_window            = var.maintenance_window
  tags                          = local.common_tags

  lifecycle {
    prevent_destroy = true
    ignore_changes  = [global_replication_group_id]
  }
}

resource "aws_kms_key" "sns" {
  description             = "KMS key for SNS topic encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_sns_topic" "alarms" {
  name              = "${local.name_prefix}-alarms"
  kms_master_key_id = aws_kms_key.sns.arn
  tags              = local.common_tags
}

resource "aws_cloudwatch_metric_alarm" "cpu_utilization" {
  alarm_name          = "${local.name_prefix}-cpu-utilization"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = var.alarm_evaluation_periods
  metric_name         = "CPUUtilization"
  namespace           = "AWS/ElastiCache"
  period              = var.alarm_period
  statistic           = "Average"
  threshold           = var.alarm_cpu_threshold
  alarm_description   = "CPU utilization alarm for Redis replication group"
  alarm_actions       = [aws_sns_topic.alarms.arn]

  dimensions = {
    ReplicationGroupId = aws_elasticache_replication_group.redis.replication_group_id
  }

  tags = local.common_tags
}

resource "aws_cloudwatch_metric_alarm" "memory_usage" {
  alarm_name          = "${local.name_prefix}-memory-usage"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = var.alarm_evaluation_periods
  metric_name         = "DatabaseMemoryUsagePercentage"
  namespace           = "AWS/ElastiCache"
  period              = var.alarm_period
  statistic           = "Average"
  threshold           = var.alarm_memory_threshold
  alarm_description   = "Memory usage alarm for Redis replication group"
  alarm_actions       = [aws_sns_topic.alarms.arn]

  dimensions = {
    ReplicationGroupId = aws_elasticache_replication_group.redis.replication_group_id
  }

  tags = local.common_tags
}

resource "aws_elasticache_global_replication_group" "global" {
  count                             = var.enable_global_datastore ? 1 : 0
  global_replication_group_id_suffix = "${local.name_prefix}-global"
  primary_replication_group_id      = aws_elasticache_replication_group.redis.id
  global_replication_group_description = "Global datastore for Redis"
  engine_version                    = var.engine_version
  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "config_file_path" {
  description = "Path to the YAML configuration file for Lambda functions"
  type        = string
  default     = "config.yaml"
}

variable "raw_yaml_config" {
  description = "Inline raw YAML configuration that overrides the file when non-empty"
  type        = string
  default     = ""
}

variable "shared_tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Decode YAML from raw variable if provided; otherwise, read from file if it exists.
  # If neither source provides content, fall back to an empty functions map.
  yaml_content = var.raw_yaml_config != "" ? yamldecode(var.raw_yaml_config) : (
    fileexists(var.config_file_path) ? yamldecode(file(var.config_file_path)) : { functions = {} }
  )

  # Safely extract the functions list; default to empty map if missing or unexpected type.
  functions = try(local.yaml_content["functions"], {})

  # VPC subnet CIDRs derived from VPC CIDR
  vpc_cidr = "10.0.0.0/16"
  public_subnet_cidrs  = [for i, az in data.aws_availability_zones.available.names : cidrsubnet(local.vpc_cidr, 8, i)]
  private_subnet_cidrs = [for i, az in data.aws_availability_zones.available.names : cidrsubnet(local.vpc_cidr, 8, i + 10)]
}

# ------------------------------------------------------------------------------
# VPC Resources
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "public" {
  count = length(data.aws_availability_zones.available.names)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  map_public_ip_on_launch = false

  tags = merge(var.shared_tags, {
    Terraformed = "true"
    Name        = "public-${count.index}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private" {
  count = length(data.aws_availability_zones.available.names)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(var.shared_tags, {
    Terraformed = "true"
    Name        = "private-${count.index}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "lambda_vpc" {
  name_prefix = "lambda-vpc-"
  description = "Security group for Lambda functions in VPC"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Lambda Function Resources (iterated from YAML)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "lambda" {
  for_each = local.functions

  name = each.key
  path = lookup(each.value, "role_path", "/terrabits/lambda/")

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "lambda_logging" {
  for_each = local.functions

  name        = "${each.key}-logging"
  description = "Allow Lambda to write logs to CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:/aws/lambda/${each.key}"
      }
    ]
  })

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "lambda_logging" {
  for_each = local.functions

  role       = aws_iam_role.lambda[each.key].name
  policy_arn = aws_iam_policy.lambda_logging[each.key].arn
}

resource "aws_iam_role_policy" "custom" {
  for_each = {
    for k, v in local.functions : k => v
    if try(v.custom_policy, null) != null && v.custom_policy != ""
  }

  name   = each.key
  role   = aws_iam_role.lambda[each.key].name
  policy = each.value.custom_policy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "lambda" {
  for_each = local.functions

  name              = "/aws/lambda/${each.key}"
  retention_in_days = 7

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lambda_function" "lambda" {
  for_each = local.functions

  function_name = each.key
  runtime       = each.value.runtime
  handler       = each.value.handler
  filename      = each.value.filename
  memory_size   = try(each.value.memory_size, 128)
  timeout       = try(each.value.timeout, 3)
  architectures = [try(each.value.architecture, "x86_64")]

  role = aws_iam_role.lambda[each.key].arn

  environment {
    variables = try(each.value.environment, {})
  }

  dynamic "vpc_config" {
    for_each = try(each.value.vpc_config, null) != null ? [1] : []
    content {
      subnet_ids         = each.value.vpc_config.subnet_ids
      security_group_ids = each.value.vpc_config.security_group_ids
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.lambda_logging,
    aws_cloudwatch_log_group.lambda
  ]

  tags = merge(var.shared_tags, {
    Terraformed = "true"
  })
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "lambda_function_arns" {
  description = "Map of function names to their ARNs"
  value       = { for k, v in aws_lambda_function.lambda : k => v.arn }
}

output "lambda_invoke_arns" {
  description = "Map of function names to their invoke ARNs"
  value       = { for k, v in aws_lambda_function.lambda : k => v.invoke_arn }
}

output "lambda_function_names" {
  description = "Map of function names to their function names (identity)"
  value       = { for k, v in aws_lambda_function.lambda : k => v.function_name }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "roles_config" {
  description = "Configuration map for IAM roles"
  type = map(object({
    enable                  = optional(bool, true)
    trusted_principals      = list(string)
    mfa_enabled             = optional(bool, false)
    mfa_max_age             = optional(number, 86400)
    custom_policy_arns      = optional(list(string), [])
    permissions_boundary_arn = optional(string, "")
    session_duration        = optional(number, 3600)
    force_detach_policies   = optional(bool, true)
    tags                    = optional(map(string), {})
  }))
  default = {
    admin = {
      trusted_principals = []
    }
    poweruser = {
      trusted_principals = []
    }
    readonly = {
      trusted_principals = []
    }
  }
}

data "aws_iam_policy" "admin" {
  name = "AdministratorAccess"
}

data "aws_iam_policy" "poweruser" {
  name = "PowerUserAccess"
}

data "aws_iam_policy" "readonly" {
  name = "ReadOnlyAccess"
}

locals {
  enabled_roles = { for k, v in var.roles_config : k => v if v.enable }
  standard_policy_arns = {
    admin     = data.aws_iam_policy.admin.arn
    poweruser = data.aws_iam_policy.poweruser.arn
    readonly  = data.aws_iam_policy.readonly.arn
  }
}

data "aws_iam_policy_document" "trust" {
  for_each = local.enabled_roles

  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [for p in each.value.trusted_principals : p if can(regex("^arn:aws:iam::", p))]
    }
    principals {
      type        = "Service"
      identifiers = [for p in each.value.trusted_principals : p if !can(regex("^arn:aws:iam::", p))]
    }
    actions = ["sts:AssumeRole"]

    dynamic "condition" {
      for_each = each.value.mfa_enabled ? [1] : []
      content {
        test     = "Bool"
        variable = "aws:MultiFactorAuthPresent"
        values   = ["true"]
      }
    }

    dynamic "condition" {
      for_each = each.value.mfa_enabled ? [1] : []
      content {
        test     = "NumericLessThan"
        variable = "aws:MultiFactorAuthAge"
        values   = [tostring(each.value.mfa_max_age)]
      }
    }
  }
}

resource "aws_iam_role" "role" {
  for_each = local.enabled_roles

  name               = each.key
  assume_role_policy = data.aws_iam_policy_document.trust[each.key].json
  max_session_duration = each.value.session_duration
  force_detach_policies = each.value.force_detach_policies
  permissions_boundary   = each.value.permissions_boundary_arn != "" ? each.value.permissions_boundary_arn : null
  tags = each.value.tags
}

# Attach standard managed policy when no custom policies are provided
resource "aws_iam_role_policy_attachment" "standard" {
  for_each = { for k, v in local.enabled_roles : k => v if length(v.custom_policy_arns) == 0 }

  role       = aws_iam_role.role[each.key].name
  policy_arn = local.standard_policy_arns[each.key]
}

# Attach custom policies when provided
resource "aws_iam_role_policy_attachment" "custom" {
  for_each = { for pair in flatten(
    [for k, v in local.enabled_roles : [
      for arn in v.custom_policy_arns : { key = k, arn = arn }
    ] if length(v.custom_policy_arns) > 0]
  ) : "${pair.key}-${pair.arn}" => pair }

  role       = aws_iam_role.role[each.value.key].name
  policy_arn = each.value.arn
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "md-k8s"
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "persistent_deployment" {
  description = "Flag for persistent deployment (enables managed node group)"
  type        = bool
  default     = false
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# Locals
locals {
  azs = slice(data.aws_availability_zones.available.names, 0, min(3, length(data.aws_availability_zones.available.names)))
  vpc_cidr = "192.168.0.0/16"
  public_subnet_cidrs  = [for i in range(3) : cidrsubnet(local.vpc_cidr, 8, i)]
  private_subnet_cidrs = [for i in range(3) : cidrsubnet(local.vpc_cidr, 8, i + 4)]
  cluster_name = var.cluster_name
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name                                                     = local.cluster_name
    Region                                                   = var.region
    "kubernetes.io/cluster/${local.cluster_name}"            = "shared"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                                                     = "${local.cluster_name}-public-${count.index}"
    Region                                                   = var.region
    "kubernetes.io/cluster/${local.cluster_name}"            = "shared"
    "kubernetes.io/role/elb"                                 = "1"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]

  tags = {
    Name                                                     = "${local.cluster_name}-private-${count.index}"
    Region                                                   = var.region
    "kubernetes.io/cluster/${local.cluster_name}"            = "shared"
    "kubernetes.io/role/internal-elb"                        = "1"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.cluster_name}-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.cluster_name}-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${local.cluster_name}-nat"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = length(local.azs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.cluster_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = length(local.azs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# IAM roles
resource "aws_iam_role" "eks_cluster" {
  name = "${local.cluster_name}-eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role" "fargate_pod" {
  name = "${local.cluster_name}-fargate-pod-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks-fargate-pods.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "fargate_pod_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSFargatePodExecutionRolePolicy"
  role       = aws_iam_role.fargate_pod.name
}

resource "aws_iam_role" "worker_node" {
  count = var.persistent_deployment ? 1 : 0

  name = "${local.cluster_name}-worker-node-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "worker_node_policies" {
  count = var.persistent_deployment ? 3 : 0

  role = aws_iam_role.worker_node[0].name
  policy_arn = element([
    "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
    "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy",
    "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  ], count.index)
}

# Custom policy for load balancing (attached to node group role)
resource "aws_iam_policy" "lb_controller" {
  count = var.persistent_deployment ? 1 : 0

  name        = "${local.cluster_name}-lb-controller-policy"
  description = "Policy for AWS Load Balancer Controller"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:Describe*",
          "elasticloadbalancing:CreateLoadBalancer",
          "elasticloadbalancing:DeleteLoadBalancer",
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:ModifyLoadBalancerAttributes",
          "elasticloadbalancing:CreateTargetGroup",
          "elasticloadbalancing:DeleteTargetGroup",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:RegisterTargets",
          "elasticloadbalancing:DeregisterTargets",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:CreateListener",
          "elasticloadbalancing:DeleteListener",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:ModifyListener",
          "iam:CreateServiceLinkedRole",
          "waf-regional:GetWebACLForResource",
          "waf-regional:AssociateWebACL",
          "waf-regional:DisassociateWebACL",
          "tag:GetResources",
          "tag:TagResources",
          "tag:UntagResources"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lb_controller_attachment" {
  count = var.persistent_deployment ? 1 : 0

  role       = aws_iam_role.worker_node[0].name
  policy_arn = aws_iam_policy.lb_controller[0].arn
}

resource "aws_iam_policy" "cloudwatch_metrics" {
  count = var.persistent_deployment ? 1 : 0

  name        = "${local.cluster_name}-cloudwatch-metrics-policy"
  description = "Policy for CloudWatch metrics from EKS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricData",
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics",
          "ec2:DescribeTags"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudwatch_metrics_attachment" {
  count = var.persistent_deployment ? 1 : 0

  role       = aws_iam_role.worker_node[0].name
  policy_arn = aws_iam_policy.cloudwatch_metrics[0].arn
}

# KMS key for EKS secrets encryption
resource "aws_kms_key" "eks" {
  description             = "EKS secrets encryption key"
  enable_key_rotation    = true
  deletion_window_in_days = 7
}

# EKS Cluster (version omitted to use platform default)
resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids = concat(
      aws_subnet.public[*].id,
      aws_subnet.private[*].id
    )
    endpoint_public_access  = false
    endpoint_private_access = true
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_kms_key.eks
  ]

  tags = {
    Name   = local.cluster_name
    Region = var.region
  }
}

# Fargate Profile
resource "aws_eks_fargate_profile" "main" {
  cluster_name           = aws_eks_cluster.main.name
  fargate_profile_name   = var.persistent_deployment ? "fp-${local.cluster_name}" : local.cluster_name
  pod_execution_role_arn = aws_iam_role.fargate_pod.arn
  subnet_ids             = aws_subnet.private[*].id

  selector {
    namespace = "default"
    labels = {
      name = local.cluster_name
    }
  }
}

# Data source for EKS optimized AMI (wildcard version-agnostic)
data "aws_ami" "eks_worker" {
  count = var.persistent_deployment ? 1 : 0

  filter {
    name   = "name"
    values = ["amazon-eks-node-*"]
  }
  most_recent = true
  owners      = ["602401143452"]
}

# Resources for persistent deployment
resource "aws_launch_template" "eks_nodes" {
  count = var.persistent_deployment ? 1 : 0

  name          = "${local.cluster_name}-lt"
  image_id      = data.aws_ami.eks_worker[0].id
  instance_type = "c5.2xlarge"
  key_name      = "${local.cluster_name}-ssh-key"

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size           = 50
      volume_type           = "gp3"
      delete_on_termination = true
    }
  }

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name = "${local.cluster_name}-node"
    }
  }

  user_data = base64encode(<<-EOF
#!/bin/bash
/etc/eks/bootstrap.sh ${local.cluster_name}
EOF
  )

  lifecycle {
    create_before_destroy = true
  }

  provisioner "local-exec" {
    command = <<EOT
      if [ ! -f /tmp/${local.cluster_name}-ssh-key ]; then
        ssh-keygen -t rsa -b 4096 -f /tmp/${local.cluster_name}-ssh-key -N "" -q
      fi
      aws ec2 import-key-pair --key-name "${local.cluster_name}-ssh-key" --public-key-material fileb:///tmp/${local.cluster_name}-ssh-key.pub --region ${var.region}
    EOT
    interpreter = ["sh", "-c"]
  }
}

resource "aws_eks_node_group" "main" {
  count = var.persistent_deployment ? 1 : 0

  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "${local.cluster_name}-node-group"
  node_role_arn   = aws_iam_role.worker_node[0].arn
  subnet_ids      = aws_subnet.private[*].id
  instance_types  = ["c5.2xlarge"]

  launch_template {
    id      = aws_launch_template.eks_nodes[0].id
    version = "$Latest"
  }

  scaling_config {
    desired_size = 2
    min_size     = 2
    max_size     = 5
  }

  tags = {
    Name = "${local.cluster_name}-node-group"
  }

  depends_on = [
    aws_iam_role_policy_attachment.worker_node_policies
  ]
}

# RDS subnet group (from private subnets)
resource "aws_db_subnet_group" "private" {
  name       = "${local.cluster_name}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${local.cluster_name}-db-subnet-group"
  }
}

# Outputs
output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "db_subnet_group_id" {
  description = "Identifier of the DB subnet group"
  value       = aws_db_subnet_group.private.id
}

output "oidc_issuer_url" {
  description = "The OIDC issuer URL of the EKS cluster"
  value       = aws_eks_cluster.main.identity[0].oidc[0].issuer
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# Variables
variable "trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "cloudtrail-trail"
}

variable "key_prefix" {
  description = "S3 key prefix for CloudTrail logs"
  type        = string
  default     = "cloudtrail"
}

variable "log_group_name" {
  description = "Name of the CloudWatch Logs log group"
  type        = string
  default     = "/aws/cloudtrail/cloudtrail-logs"
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Locals
locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.region
  bucket_name = "${var.trail_name}-logs-${local.account_id}-${local.region}"
  kms_key_alias = "alias/${var.trail_name}-key"
  glue_db_name = "${var.trail_name}_db"
  glue_table_name = "${local.account_id}_${replace(var.key_prefix, "/", "_")}_cloudtrail"
  log_group_name = var.log_group_name
  cloudtrail_logs_path = "AWSLogs/${local.account_id}/CloudTrail/"
}

# KMS Key
resource "aws_kms_key" "this" {
  description             = "KMS key for CloudTrail encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to use the key for S3 encryption"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key for log group encryption"
        Effect = "Allow"
        Principal = {
          Service = "logs.${local.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow SNS to use the key for topic encryption"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "this" {
  name          = local.kms_key_alias
  target_key_id = aws_kms_key.this.key_id
}

# S3 Bucket
resource "aws_s3_bucket" "this" {
  bucket = local.bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    id     = "expire-current-objects"
    status = "Enabled"

    expiration {
      days = 30
    }

    filter {
      prefix = ""
    }
  }

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    noncurrent_version_expiration {
      noncurrent_days = 31
    }

    filter {
      prefix = ""
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow CloudTrail to write logs"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl"
        ]
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/${var.key_prefix}/${local.cloudtrail_logs_path}*"
        ]
        Condition = {
          StringEquals = {
            "s3:x-amz-server-side-encryption-aws-kms-key-id" = aws_kms_key.this.arn
            "s3:x-amz-acl"                                   = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# IAM Role for CloudTrail CloudWatch Logs delivery
resource "aws_iam_role" "cloudtrail_cloudwatch_role" {
  name = "${var.trail_name}-cloudwatch-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch_policy" {
  name = "${var.trail_name}-cloudwatch-policy"
  role = aws_iam_role.cloudtrail_cloudwatch_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.this.arn}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl"
        ]
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/${var.key_prefix}/${local.cloudtrail_logs_path}*"
        ]
      }
    ]
  })
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "this" {
  name              = local.log_group_name
  retention_in_days = 90
  kms_key_id        = aws_kms_key.this.arn

  lifecycle {
    prevent_destroy = true
  }
}

# SNS Topic
resource "aws_sns_topic" "this" {
  name              = "${var.trail_name}-notifications"
  kms_master_key_id = aws_kms_key.this.arn
}

# CloudTrail Trail
resource "aws_cloudtrail" "this" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.this.id
  s3_key_prefix                 = var.key_prefix
  cloud_watch_logs_group_arn    = aws_cloudwatch_log_group.this.arn
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch_role.arn
  include_global_service_events = false
  is_multi_region_trail         = true
  is_organization_trail         = false
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.this.arn
  sns_topic_name                = aws_sns_topic.this.name

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }

  depends_on = [
    aws_s3_bucket_policy.this,
    aws_iam_role_policy.cloudtrail_cloudwatch_policy
  ]
}

# Glue Catalog Database
resource "aws_glue_catalog_database" "this" {
  name = local.glue_db_name
}

# Glue Catalog Table
resource "aws_glue_catalog_table" "this" {
  name          = local.glue_table_name
  database_name = aws_glue_catalog_database.this.name

  table_type = "EXTERNAL_TABLE"

  parameters = {
    EXTERNAL = "TRUE"
  }

  partition_keys {
    name = "region"
    type = "string"
  }
  partition_keys {
    name = "year"
    type = "string"
  }
  partition_keys {
    name = "month"
    type = "string"
  }
  partition_keys {
    name = "day"
    type = "string"
  }

  storage_descriptor {
    location      = "s3://${aws_s3_bucket.this.bucket}/${var.key_prefix}/${local.cloudtrail_logs_path}"
    input_format  = "com.amazon.emr.cloudtrail.CloudTrailInputFormat"
    output_format = "org.apache.hadoop.hive.ql.io.HiveIgnoreKeyTextOutputFormat"

    ser_de_info {
      serialization_library = "com.amazon.emr.hive.serde.CloudTrailSerde"
    }

    columns {
      name = "eventversion"
      type = "string"
    }
    columns {
      name = "useridentity"
      type = "struct<type:string,principalid:string,arn:string,accountid:string,invokedby:string,accesskeyid:string,username:string,sessioncontext:struct<attributes:struct<mfaauthenticated:string,creationdate:string>,sessionissuer:struct<type:string,principalid:string,arn:string,accountid:string,username:string>>>"
    }
    columns {
      name = "eventtime"
      type = "string"
    }
    columns {
      name = "eventsource"
      type = "string"
    }
    columns {
      name = "eventname"
      type = "string"
    }
    columns {
      name = "awsregion"
      type = "string"
    }
    columns {
      name = "sourceipaddress"
      type = "string"
    }
    columns {
      name = "useragent"
      type = "string"
    }
    columns {
      name = "errorcode"
      type = "string"
    }
    columns {
      name = "errormessage"
      type = "string"
    }
    columns {
      name = "requestparameters"
      type = "string"
    }
    columns {
      name = "responseelements"
      type = "string"
    }
    columns {
      name = "additionaleventdata"
      type = "string"
    }
    columns {
      name = "requestid"
      type = "string"
    }
    columns {
      name = "eventid"
      type = "string"
    }
    columns {
      name = "resources"
      type = "array<struct<arn:string,accountid:string,type:string>>"
    }
    columns {
      name = "eventtype"
      type = "string"
    }
    columns {
      name = "apiversion"
      type = "string"
    }
    columns {
      name = "readonly"
      type = "string"
    }
    columns {
      name = "recipientaccountid"
      type = "string"
    }
    columns {
      name = "serviceeventdetails"
      type = "string"
    }
    columns {
      name = "sharedeventid"
      type = "string"
    }
    columns {
      name = "vpcendpointid"
      type = "string"
    }
  }

  depends_on = [
    aws_cloudtrail.this
  ]
}

# Outputs
output "cloudtrail_trail_name" {
  value = aws_cloudtrail.this.name
}

output "s3_bucket_name" {
  value = aws_s3_bucket.this.bucket
}

output "cloudwatch_log_group_name" {
  value = aws_cloudwatch_log_group.this.name
}

output "kms_key_id" {
  value = aws_kms_key.this.key_id
}

output "glue_database_name" {
  value = aws_glue_catalog_database.this.name
}

output "glue_table_name" {
  value = aws_glue_catalog_table.this.name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

locals {
  bucket_suffix   = random_id.suffix.hex
  main_bucket     = "my-app-bucket-${local.bucket_suffix}"
  logs_bucket     = "my-app-logs-bucket-${local.bucket_suffix}"
  log_prefix      = "logs/"
}

resource "random_id" "suffix" {
  byte_length = 8
}

# Customer managed KMS key for main bucket encryption
resource "aws_kms_key" "main" {
  description             = "KMS key for S3 main bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

# Main bucket
resource "aws_s3_bucket" "main" {
  bucket = local.main_bucket

  lifecycle {
    prevent_destroy = true
  }
}

# Logs bucket
resource "aws_s3_bucket" "logs" {
  bucket = local.logs_bucket

  lifecycle {
    prevent_destroy = true
  }
}

# Encryption - main bucket (CMK)
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

# Encryption - logs bucket (SSE-S3)
resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Versioning - main bucket
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Versioning - logs bucket
resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Logging - main bucket to logs bucket
resource "aws_s3_bucket_logging" "main" {
  bucket = aws_s3_bucket.main.id

  target_bucket = aws_s3_bucket.logs.id
  target_prefix = local.log_prefix
}

# Lifecycle rule - main bucket
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    id     = "expire-and-glacier"
    status = "Enabled"

    filter {}

    transition {
      days          = 30
      storage_class = "GLACIER"
    }

    expiration {
      days = 365
    }
  }
}

# Bucket policy - main bucket: deny non-SSL and require TLS >= 1.2
data "aws_iam_policy_document" "main" {
  statement {
    sid    = "DenyNonSSLTransport"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = [
      "s3:*"
    ]
    resources = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "RequireTLS12"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = [
      "s3:*"
    ]
    resources = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*"
    ]
    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }
}

resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = data.aws_iam_policy_document.main.json
}

# Public access block - main bucket
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Public access block - logs bucket
resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Object ownership - main bucket: BucketOwnerEnforced
resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# Static website hosting - main bucket
resource "aws_s3_bucket_website_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "error.html"
  }
}

# CORS configuration - main bucket
resource "aws_s3_bucket_cors_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  cors_rule {
    allowed_methods = ["GET", "HEAD"]
    allowed_origins = ["*"]
    max_age_seconds = 3000
  }
}

# ACL on logs bucket to grant log delivery write access
resource "aws_s3_bucket_acl" "logs" {
  bucket = aws_s3_bucket.logs.id
  acl    = "log-delivery-write"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}

##### Variables #####
variable "topic_name" {
  description = "Exact name for the SNS topic. If provided, name_prefix is ignored."
  type        = string
  default     = "my-topic"
}

variable "name_prefix" {
  description = "Prefix for the SNS topic name; a random suffix will be appended."
  type        = string
  default     = null
}

variable "is_fifo" {
  description = "Whether the SNS topic is FIFO."
  type        = bool
  default     = false
}

variable "encryption_enabled" {
  description = "Enable server-side encryption using KMS."
  type        = bool
  default     = true
}

variable "custom_kms_key_arn" {
  description = "ARN of a custom KMS key to use for encryption. If not provided and encryption_enabled is true, a new key is created."
  type        = string
  default     = null
}

variable "subscriptions" {
  description = "List of subscriptions to create on the topic."
  type = list(object({
    endpoint = string
    protocol = string
  }))
  default = []
}

variable "delivery_policy" {
  description = "JSON string for the delivery policy."
  type        = string
  default     = null
}

variable "custom_policy_statements" {
  description = "List of IAM policy statements to merge into the topic policy."
  type = list(object({
    Effect    = string
    Action    = list(string)
    Resource  = list(string)
    Principal = any
    Condition = optional(map(any))
  }))
  default = []
}

variable "data_protection_policy" {
  description = "JSON string for the data protection policy (only for non-FIFO topics)."
  type        = string
  default     = null
}

variable "feedback_role_arn" {
  description = "ARN of an existing IAM role for delivery status feedback. If not provided, a new role will be created."
  type        = string
  default     = null
}

variable "log_retention_days" {
  description = "Retention in days for the CloudWatch log group."
  type        = number
  default     = 14
}

##### Locals #####
locals {
  suffix = join("", random_id.sns_name_suffix[*].hex)

  topic_name_final = var.topic_name != null ? (
    var.is_fifo ? "${var.topic_name}.fifo" : var.topic_name
  ) : (
    var.is_fifo ? "${var.name_prefix}-${local.suffix}.fifo" : "${var.name_prefix}-${local.suffix}"
  )

  kms_key_arn = var.custom_kms_key_arn != null ? var.custom_kms_key_arn : (
    var.encryption_enabled ? try(aws_kms_key.sns[0].arn, null) : null
  )

  feedback_role_arn = coalesce(var.feedback_role_arn, one(aws_iam_role.sns_delivery_status[*].arn))

  custom_policy_json = [
    for stmt in var.custom_policy_statements :
    jsonencode({
      Version   = "2012-10-17"
      Statement = [stmt]
    })
  ]
}

##### Random suffix #####
resource "random_id" "sns_name_suffix" {
  count       = var.name_prefix != null ? 1 : 0
  byte_length = 4
}

##### KMS Key (if encryption enabled and no custom key) #####
resource "aws_kms_key" "sns" {
  count               = var.encryption_enabled && var.custom_kms_key_arn == null ? 1 : 0
  description         = "KMS key for SNS topic encryption"
  enable_key_rotation = true
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sns" {
  count        = var.encryption_enabled && var.custom_kms_key_arn == null ? 1 : 0
  name         = "alias/sns-topic-key"
  target_key_id = aws_kms_key.sns[0].key_id
}

##### Default Topic Policy Document #####
data "aws_iam_policy_document" "default_topic_policy" {
  statement {
    sid    = "AllowSameAccountActions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.account_id]
    }
    actions   = ["SNS:Publish", "SNS:Subscribe"]
    resources = [aws_sns_topic.main.arn]
  }

  source_policy_documents = local.custom_policy_json
}

##### SNS Topic #####
resource "aws_sns_topic" "main" {
  name          = local.topic_name_final
  fifo_topic    = var.is_fifo
  delivery_policy = var.delivery_policy

  kms_master_key_id = local.kms_key_arn

  application_success_feedback_role_arn = local.feedback_role_arn
  lambda_success_feedback_role_arn      = local.feedback_role_arn
  http_success_feedback_role_arn        = local.feedback_role_arn
  sqs_success_feedback_role_arn         = local.feedback_role_arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_policy" "default" {
  arn    = aws_sns_topic.main.arn
  policy = data.aws_iam_policy_document.default_topic_policy.json
}

##### Subscriptions #####
resource "aws_sns_topic_subscription" "subscriptions" {
  for_each = { for idx, sub in var.subscriptions : idx => sub }

  topic_arn = aws_sns_topic.main.arn
  protocol  = each.value.protocol
  endpoint  = each.value.endpoint
}

##### Delivery Status Infrastructure (only if no external feedback role) #####
resource "aws_iam_role" "sns_delivery_status" {
  count = var.feedback_role_arn == null ? 1 : 0
  name  = "sns-delivery-status-${local.topic_name_final}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sns_delivery_status" {
  count      = var.feedback_role_arn == null ? 1 : 0
  role       = aws_iam_role.sns_delivery_status[0].name
  policy_arn = aws_iam_policy.sns_delivery_logging[0].arn
}

resource "aws_iam_policy" "sns_delivery_logging" {
  count       = var.feedback_role_arn == null ? 1 : 0
  name        = "sns-delivery-logging-${local.topic_name_final}"
  description = "Allow SNS to write delivery status logs to CloudWatch"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.sns_delivery[0].arn}:*"
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "sns_delivery" {
  count             = var.feedback_role_arn == null ? 1 : 0
  name              = "/aws/sns/${aws_sns_topic.main.name}"
  retention_in_days = var.log_retention_days
  lifecycle {
    prevent_destroy = true
  }
}

##### Data Protection Policy (only for non-FIFO topics) #####
resource "aws_sns_topic_data_protection_policy" "main" {
  count  = var.is_fifo == false && var.data_protection_policy != null ? 1 : 0
  arn    = aws_sns_topic.main.arn
  policy = var.data_protection_policy
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

variable "name_prefix" {
  description = "Prefix to prepend to all IAM resource names"
  type        = string
  default     = ""
}

variable "users" {
  description = "List of users with group assignments"
  type = list(object({
    username = string
    groups   = list(string)
  }))
  default = []
}

variable "password_policy" {
  description = "Password policy configuration"
  type = object({
    minimum_password_length        = optional(number, 14)
    require_lowercase              = optional(bool, true)
    require_uppercase              = optional(bool, true)
    require_numbers                = optional(bool, true)
    require_symbols                = optional(bool, true)
    password_reuse_prevention      = optional(number, 24)
    allow_users_to_change_password = optional(bool, true)
  })
  default = {}
}

locals {
  prefix = var.name_prefix
}

resource "aws_iam_group" "admins" {
  name = "${local.prefix}admins"
}

resource "aws_iam_group" "users" {
  name = "${local.prefix}users"
}

resource "aws_iam_group" "read-only" {
  name = "${local.prefix}read-only"
}

resource "aws_iam_group" "billing" {
  name = "${local.prefix}billing"
}

resource "aws_iam_group" "billing-ro" {
  name = "${local.prefix}billing-ro"
}

resource "aws_iam_group_policy_attachment" "admins_administrator_access" {
  group      = aws_iam_group.admins.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "readonly_read_only_access" {
  group      = aws_iam_group.read-only.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "billing_billing" {
  group      = aws_iam_group.billing.name
  policy_arn = "arn:aws:iam::aws:policy/job-function/Billing"
}

resource "aws_iam_group_policy_attachment" "billing_ro_billing_read_only_access" {
  group      = aws_iam_group.billing-ro.name
  policy_arn = "arn:aws:iam::aws:policy/AWSBillingReadOnlyAccess"
}

resource "aws_iam_policy" "users_self_management" {
  name        = "${local.prefix}users-self-management"
  description = "Policy for users group that allows self-management of IAM resources with MFA requirement"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBootstrapActionsWithoutMFA"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListMFADevices",
          "iam:GetUser",
          "iam:GetAccountPasswordPolicy",
          "iam:GetAccountSummary",
          "iam:ListAccessKeys",
          "iam:ListAccountAliases",
          "iam:ListGroupsForUser",
          "iam:ListSigningCertificates",
          "iam:ListUserPolicies",
          "iam:ListVirtualMFADevices",
          "iam:ListSSHPublicKeys"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowSelfManagementWithMFA"
        Effect = "Allow"
        Action = [
          "iam:CreateAccessKey",
          "iam:CreateLoginProfile",
          "iam:DeactivateMFADevice",
          "iam:DeleteAccessKey",
          "iam:DeleteLoginProfile",
          "iam:DeleteSigningCertificate",
          "iam:DeleteVirtualMFADevice",
          "iam:GetLoginProfile",
          "iam:PutUserPolicy",
          "iam:UpdateAccessKey",
          "iam:UpdateLoginProfile",
          "iam:UpdateSigningCertificate",
          "iam:UpdateUser",
          "iam:UploadSigningCertificate",
          "iam:UploadSSHPublicKey",
          "iam:GetSSHPublicKey",
          "iam:UpdateSSHPublicKey",
          "iam:DeleteSSHPublicKey"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "DenyOtherIAMActionsWithoutMFA"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListMFADevices",
          "iam:GetUser",
          "iam:GetAccountPasswordPolicy",
          "iam:GetAccountSummary",
          "iam:ListAccessKeys",
          "iam:ListAccountAliases",
          "iam:ListGroupsForUser",
          "iam:ListSigningCertificates",
          "iam:ListUserPolicies",
          "iam:ListVirtualMFADevices",
          "iam:ListSSHPublicKeys",
          "iam:CreateAccessKey",
          "iam:CreateLoginProfile",
          "iam:DeactivateMFADevice",
          "iam:DeleteAccessKey",
          "iam:DeleteLoginProfile",
          "iam:DeleteSigningCertificate",
          "iam:DeleteVirtualMFADevice",
          "iam:GetLoginProfile",
          "iam:PutUserPolicy",
          "iam:UpdateAccessKey",
          "iam:UpdateLoginProfile",
          "iam:UpdateSigningCertificate",
          "iam:UpdateUser",
          "iam:UploadSigningCertificate",
          "iam:UploadSSHPublicKey",
          "iam:GetSSHPublicKey",
          "iam:UpdateSSHPublicKey",
          "iam:DeleteSSHPublicKey"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "users_self_management" {
  group      = aws_iam_group.users.name
  policy_arn = aws_iam_policy.users_self_management.arn
}

resource "aws_iam_role" "admin" {
  name = "${local.prefix}admin-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:MultiFactorAuthPresent" = "true"
            "aws:PrincipalGroup"         = aws_iam_group.admins.arn
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_role" "readonly" {
  name = "${local.prefix}readonly-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:MultiFactorAuthPresent" = "true"
            "aws:PrincipalGroup"         = aws_iam_group.read-only.arn
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "readonly_read_only_access" {
  role       = aws_iam_role.readonly.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_user" "user" {
  for_each = { for u in var.users : u.username => u }
  name     = each.value.username
}

resource "aws_iam_user_group_membership" "user" {
  for_each = { for pair in flatten([
    for u in var.users : [
      for g in u.groups : {
        key      = "${u.username}-${g}"
        username = u.username
        group    = g
      }
    ]
  ]) : pair.key => pair }

  user     = each.value.username
  groups   = [each.value.group]
  depends_on = [aws_iam_user.user]
}

resource "aws_iam_account_password_policy" "this" {
  minimum_password_length        = var.password_policy.minimum_password_length
  require_lowercase_characters   = var.password_policy.require_lowercase
  require_uppercase_characters   = var.password_policy.require_uppercase
  require_numbers                = var.password_policy.require_numbers
  require_symbols                = var.password_policy.require_symbols
  password_reuse_prevention       = var.password_policy.password_reuse_prevention
  allow_users_to_change_password = var.password_policy.allow_users_to_change_password
}

# Terraform configuration for foundational EKS networking and IAM

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment_name" {
  description = "Environment name tag for all resources"
  type        = string
  default     = "capstone-project-terraform"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "az_names" {
  description = "List of availability zone names to use. If empty, uses the first two from the region."
  type        = list(string)
  default     = []
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  selected_az_names = length(var.az_names) > 0 ? var.az_names : slice(data.aws_availability_zones.available.names, 0, 2)
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Environment = var.environment_name
  }
}

# ------------------------------------------------------------------------------
# Public subnets
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = count.index == 0 ? "10.0.0.0/24" : "10.0.1.0/24"
  availability_zone       = local.selected_az_names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "public-subnet-${count.index + 1}"
    Environment = var.environment_name
  }
}

# ------------------------------------------------------------------------------
# Internet Gateway
# ------------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Environment = var.environment_name
  }
}

# ------------------------------------------------------------------------------
# Elastic IPs for NAT Gateways
# ------------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count  = 2
  domain = "vpc"

  tags = {
    Name        = "nat-eip-${count.index + 1}"
    Environment = var.environment_name
  }
}

# ------------------------------------------------------------------------------
# NAT Gateways
# ------------------------------------------------------------------------------
resource "aws_nat_gateway" "main" {
  count         = 2
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name        = "nat-gw-${count.index + 1}"
    Environment = var.environment_name
  }

  depends_on = [aws_internet_gateway.main]
}

# ------------------------------------------------------------------------------
# Public route table
# ------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "public-rt"
    Environment = var.environment_name
  }
}

# ------------------------------------------------------------------------------
# Route table associations for public subnets
# ------------------------------------------------------------------------------
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# IAM role for EKS cluster
# ------------------------------------------------------------------------------
resource "aws_iam_role" "eks_cluster" {
  name               = "eks-cluster-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Environment = var.environment_name
  }
}

# Custom policy for cluster role: eks:* on all resources
resource "aws_iam_policy" "eks_cluster" {
  name        = "eks-cluster-policy"
  description = "Custom policy granting eks:* actions to the cluster role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "eks:*"
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })

  tags = {
    Environment = var.environment_name
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = aws_iam_policy.eks_cluster.arn
}

# ------------------------------------------------------------------------------
# IAM role for worker nodes
# ------------------------------------------------------------------------------
resource "aws_iam_role" "worker_node" {
  name               = "eks-worker-node-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Environment = var.environment_name
  }
}

# Attach required managed policies to worker node role
resource "aws_iam_role_policy_attachment" "worker_node_eks_worker" {
  role       = aws_iam_role.worker_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "worker_node_eks_cni" {
  role       = aws_iam_role.worker_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "worker_node_ecr_read" {
  role       = aws_iam_role.worker_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

# Custom policy for worker node: eks:DescribeCluster and ssm:GetParameter
resource "aws_iam_policy" "worker_node_custom" {
  name        = "eks-worker-node-custom-policy"
  description = "Custom policy for worker node allowing EKS DescribeCluster and SSM GetParameter"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "eks:DescribeCluster",
          "ssm:GetParameter"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })

  tags = {
    Environment = var.environment_name
  }
}

resource "aws_iam_role_policy_attachment" "worker_node_custom" {
  role       = aws_iam_role.worker_node.name
  policy_arn = aws_iam_policy.worker_node_custom.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.0"
}

variable "name" {
  type        = string
  description = "Base name for the SNS module resources"
  default     = "sns-topic"
}

variable "environment" {
  type        = string
  description = "Environment name (e.g., dev, prod)"
  default     = "dev"
}

variable "tags" {
  type        = map(string)
  description = "Additional tags to apply to all resources"
  default     = {}
}

variable "create_topic" {
  type        = bool
  description = "Whether to create an SNS topic"
  default     = true
}

variable "create_subscriptions" {
  type        = bool
  description = "Whether to create SNS topic subscriptions"
  default     = false
}

variable "create_topic_policy" {
  type        = bool
  description = "Whether to attach a policy to the SNS topic"
  default     = false
}

variable "create_sms_preferences" {
  type        = bool
  description = "Whether to set SMS preferences for the account"
  default     = false
}

variable "create_platform_application" {
  type        = bool
  description = "Whether to create a platform application"
  default     = false
}

variable "topic_arn" {
  type        = string
  description = "External SNS topic ARN to use when create_topic is false"
  default     = null
}

variable "subscription_protocol" {
  type        = string
  description = "Protocol for the subscription (e.g., email, sqs, lambda)"
  default     = null
}

variable "subscription_endpoints" {
  type        = list(string)
  description = "List of endpoints for subscriptions"
  default     = []
}

variable "topic_policy_json" {
  type        = string
  description = "JSON policy document to attach to the topic"
  default     = null
}

variable "platform_application_name" {
  type        = string
  description = "Name for the platform application"
  default     = null
}

variable "platform_credential" {
  type        = string
  description = "Platform credential (e.g., API key) for the application"
  sensitive   = true
  default     = null
}

variable "platform_principal" {
  type        = string
  description = "Platform principal (optional, e.g., platform ID)"
  default     = null
}

variable "platform" {
  type        = string
  description = "Platform type for SNS platform application (e.g., GCM, APNS, APNS_SANDBOX)"
  default     = "GCM"
}

variable "sms_default_sender_id" {
  type        = string
  description = "Default sender ID for SMS messages"
  default     = null
}

variable "sms_default_sms_type" {
  type        = string
  description = "Default SMS type (Promotional or Transactional)"
  default     = null
}

variable "kms_master_key_id" {
  type        = string
  description = "KMS master key ID (key ID, ARN, or alias) to use for SNS topic encryption. Defaults to a module-created CMK if not specified."
  default     = null
}

locals {
  topic_name = "sns-${var.name}-${var.environment}"
  # If we create a topic, use its ARN; otherwise use the externally provided topic_arn.
  # When using var.topic_arn, the caller must ensure it is non-null if create_topic is false.
  topic_arn = var.create_topic ? aws_sns_topic.this[0].arn : var.topic_arn
}

# Conditionally create a customer-managed KMS key for SNS topic encryption
resource "aws_kms_key" "sns" {
  count = var.create_topic ? 1 : 0

  description             = "CMK for SNS topic ${local.topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(
    var.tags,
    { Name = "${local.topic_name}-key" }
  )
}

# Conditionally create the SNS topic
resource "aws_sns_topic" "this" {
  count = var.create_topic ? 1 : 0

  name = local.topic_name

  # Use user-provided KMS key if given, otherwise use the module-created CMK
  kms_master_key_id = var.kms_master_key_id != null ? var.kms_master_key_id : aws_kms_key.sns[0].arn

  tags = merge(
    var.tags,
    { Name = local.topic_name }
  )
}

# Conditionally create SNS topic subscriptions
resource "aws_sns_topic_subscription" "this" {
  for_each = var.create_subscriptions ? toset(var.subscription_endpoints) : toset([])

  topic_arn = local.topic_arn
  protocol  = var.subscription_protocol
  endpoint  = each.key
}

# Conditionally create SNS topic policy
resource "aws_sns_topic_policy" "this" {
  count = var.create_topic_policy ? 1 : 0

  arn    = local.topic_arn
  policy = var.topic_policy_json
}

# Conditionally set SMS preferences
resource "aws_sns_sms_preferences" "this" {
  count = var.create_sms_preferences ? 1 : 0

  default_sender_id = var.sms_default_sender_id
  default_sms_type  = var.sms_default_sms_type
}

# Conditionally create platform application
resource "aws_sns_platform_application" "this" {
  count = var.create_platform_application ? 1 : 0

  name                = var.platform_application_name
  platform            = var.platform
  platform_credential = var.platform_credential
  platform_principal  = var.platform_principal
}

# Output the topic ARN for external consumers
output "sns_topic_arn" {
  description = "ARN of the SNS topic (created or provided)"
  value       = local.topic_arn
}

# Terraform configuration for SQS queues with optional DLQ and policy management

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

# Overall stack control
variable "create" {
  description = "Controls whether the entire SQS stack (main queue, DLQ, policies) is created"
  type        = bool
  default     = true
}

variable "fifo_queue" {
  description = "Set to true for FIFO queue; false for standard queue"
  type        = bool
  default     = false
}

variable "queue_name" {
  description = "Base name for the main queue (without .fifo suffix)"
  type        = string
  default     = "my-queue"
}

# Main queue configuration
variable "delay_seconds" {
  description = "Delay seconds for the main queue"
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "Maximum message size (bytes) for the main queue"
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "Message retention period (seconds) for the main queue"
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "Receive wait time (seconds) for the main queue"
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout (seconds) for the main queue"
  type        = number
  default     = 30
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS managed SSE for the main queue"
  type        = bool
  default     = true
}

variable "kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse period (seconds) for the main queue (only used if sqs_managed_sse_enabled is false)"
  type        = number
  default     = 300
}

variable "fifo_throughput_limit" {
  description = "Throughput limit for FIFO queues (per queue or per message group)"
  type        = string
  default     = "perQueue"
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO queues"
  type        = bool
  default     = false
}

variable "max_receive_count" {
  description = "Maximum receive count before message is sent to DLQ"
  type        = number
  default     = 5
}

# DLQ configuration variables (all optional with null defaults)
variable "create_dlq" {
  description = "Set to true to create a dead letter queue"
  type        = bool
  default     = false
}

variable "dlq_queue_name" {
  description = "Name for the DLQ. Defaults to main queue name with '-dlq' suffix"
  type        = string
  default     = null
}

variable "dlq_delay_seconds" {
  description = "Delay seconds for the DLQ (defaults to main queue value if null)"
  type        = number
  default     = null
}

variable "dlq_max_message_size" {
  description = "Max message size for the DLQ (defaults to main queue value if null)"
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "Message retention for the DLQ (defaults to main queue value if null)"
  type        = number
  default     = null
}

variable "dlq_receive_wait_time_seconds" {
  description = "Receive wait time for the DLQ (defaults to main queue value if null)"
  type        = number
  default     = null
}

variable "dlq_visibility_timeout_seconds" {
  description = "Visibility timeout for the DLQ (defaults to main queue value if null)"
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "SSE for DLQ (defaults to main queue setting if null)"
  type        = bool
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse for DLQ (defaults to main queue if null)"
  type        = number
  default     = null
}

variable "dlq_fifo_throughput_limit" {
  description = "Throughput limit for DLQ if FIFO"
  type        = string
  default     = null
}

variable "dlq_content_based_deduplication" {
  description = "Content-based deduplication for DLQ if FIFO"
  type        = bool
  default     = null
}

variable "dlq_redrive_allow_policy" {
  description = "Redrive allow policy for DLQ (default: byQueue with source ARN = main queue)"
  type        = string
  default     = null
}

# Policy variables
variable "main_policy_json_strings" {
  description = "List of JSON policy strings to be merged for the main queue"
  type        = list(string)
  default     = []
}

variable "main_policy_statements" {
  description = "Map of structured policy statements for the main queue. Key is arbitrary, each value contains SID, actions, not_actions, effect, resources, not_resources, principals, not_principals, conditions"
  type = map(object({
    sid           = string
    actions       = optional(list(string))
    not_actions   = optional(list(string))
    effect        = string
    resources     = optional(list(string))
    not_resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    not_principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = {}
}

variable "main_create_policy" {
  description = "Set to true to attach the constructed policy to the main queue"
  type        = bool
  default     = false
}

variable "dlq_policy_json_strings" {
  description = "List of JSON policy strings to be merged for the DLQ"
  type        = list(string)
  default     = []
}

variable "dlq_policy_statements" {
  description = "Map of structured policy statements for the DLQ"
  type = map(object({
    sid           = string
    actions       = optional(list(string))
    not_actions   = optional(list(string))
    effect        = string
    resources     = optional(list(string))
    not_resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    not_principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = {}
}

variable "dlq_create_policy" {
  description = "Set to true to attach the constructed policy to the DLQ"
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  # Main queue name: strip or append .fifo
  base_name = var.queue_name
  main_name = var.fifo_queue ? (
    endswith(local.base_name, ".fifo") ? local.base_name : "${local.base_name}.fifo"
  ) : (
    replace(local.base_name, "/\\.fifo$/", "")
  )

  # DLQ name – default to main name + "-dlq"
  dlq_name_raw = var.dlq_queue_name != null ? var.dlq_queue_name : "${local.main_name}-dlq"
  dlq_name     = var.fifo_queue ? (
    endswith(local.dlq_name_raw, ".fifo") ? local.dlq_name_raw : "${local.dlq_name_raw}.fifo"
  ) : (
    replace(local.dlq_name_raw, "/\\.fifo$/", "")
  )

  # Resolve DLQ configuration: coalesce with main queue values
  dlq_delay_seconds                    = coalesce(var.dlq_delay_seconds, var.delay_seconds)
  dlq_max_message_size                 = coalesce(var.dlq_max_message_size, var.max_message_size)
  dlq_message_retention_seconds        = coalesce(var.dlq_message_retention_seconds, var.message_retention_seconds)
  dlq_receive_wait_time_seconds        = coalesce(var.dlq_receive_wait_time_seconds, var.receive_wait_time_seconds)
  dlq_visibility_timeout_seconds       = coalesce(var.dlq_visibility_timeout_seconds, var.visibility_timeout_seconds)
  dlq_sqs_managed_sse_enabled          = coalesce(var.dlq_sqs_managed_sse_enabled, var.sqs_managed_sse_enabled)
  dlq_kms_data_key_reuse_period_seconds = coalesce(var.dlq_kms_data_key_reuse_period_seconds, var.kms_data_key_reuse_period_seconds)
  dlq_fifo_throughput_limit            = coalesce(var.dlq_fifo_throughput_limit, var.fifo_throughput_limit, "perQueue")
  dlq_content_based_deduplication      = coalesce(var.dlq_content_based_deduplication, var.content_based_deduplication)
}

# ------------------------------------------------------------------------------
# Resources
# ------------------------------------------------------------------------------

# Main SQS queue
resource "aws_sqs_queue" "main" {
  count = var.create ? 1 : 0

  name                              = local.main_name
  delay_seconds                     = var.delay_seconds
  max_message_size                  = var.max_message_size
  message_retention_seconds         = var.message_retention_seconds
  receive_wait_time_seconds         = var.receive_wait_time_seconds
  visibility_timeout_seconds        = var.visibility_timeout_seconds
  sqs_managed_sse_enabled           = var.sqs_managed_sse_enabled
  kms_data_key_reuse_period_seconds = var.sqs_managed_sse_enabled ? null : var.kms_data_key_reuse_period_seconds
  fifo_queue                        = var.fifo_queue
  content_based_deduplication       = var.fifo_queue ? var.content_based_deduplication : null
  fifo_throughput_limit             = var.fifo_queue ? var.fifo_throughput_limit : null

  # Attach redrive policy if DLQ is created
  redrive_policy = var.create && var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = {
    Name = local.main_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Dead letter queue
resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name                              = local.dlq_name
  delay_seconds                     = local.dlq_delay_seconds
  max_message_size                  = local.dlq_max_message_size
  message_retention_seconds         = local.dlq_message_retention_seconds
  receive_wait_time_seconds         = local.dlq_receive_wait_time_seconds
  visibility_timeout_seconds        = local.dlq_visibility_timeout_seconds
  sqs_managed_sse_enabled           = local.dlq_sqs_managed_sse_enabled
  kms_data_key_reuse_period_seconds = local.dlq_sqs_managed_sse_enabled ? null : local.dlq_kms_data_key_reuse_period_seconds
  fifo_queue                        = var.fifo_queue
  content_based_deduplication       = var.fifo_queue ? local.dlq_content_based_deduplication : null
  fifo_throughput_limit             = var.fifo_queue ? local.dlq_fifo_throughput_limit : null

  tags = {
    Name = local.dlq_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Redrive allow policy for DLQ (separate resource to break cycle)
resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id

  redrive_allow_policy = var.dlq_redrive_allow_policy != null ? var.dlq_redrive_allow_policy : jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.main[0].arn]
  })
}

# IAM policy documents
data "aws_iam_policy_document" "main_policy" {
  count = var.create ? 1 : 0

  source_policy_documents = var.main_policy_json_strings

  dynamic "statement" {
    for_each = var.main_policy_statements
    content {
      sid           = statement.value.sid
      effect        = statement.value.effect
      actions       = statement.value.actions
      not_actions   = statement.value.not_actions
      resources     = statement.value.resources
      not_resources = statement.value.not_resources

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals != null ? statement.value.not_principals : []
        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "main_policy" {
  count = var.create && var.main_create_policy ? 1 : 0

  queue_url = aws_sqs_queue.main[0].id
  policy    = data.aws_iam_policy_document.main_policy[0].json
}

data "aws_iam_policy_document" "dlq_policy" {
  count = var.create && var.create_dlq ? 1 : 0

  source_policy_documents = var.dlq_policy_json_strings

  dynamic "statement" {
    for_each = var.dlq_policy_statements
    content {
      sid           = statement.value.sid
      effect        = statement.value.effect
      actions       = statement.value.actions
      not_actions   = statement.value.not_actions
      resources     = statement.value.resources
      not_resources = statement.value.not_resources

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals != null ? statement.value.not_principals : []
        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "dlq_policy" {
  count = var.create && var.create_dlq && var.dlq_create_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id
  policy    = data.aws_iam_policy_document.dlq_policy[0].json
}

# Outputs
output "main_queue_arn" {
  description = "ARN of the main SQS queue"
  value       = try(aws_sqs_queue.main[0].arn, null)
}

output "main_queue_url" {
  description = "URL of the main SQS queue"
  value       = try(aws_sqs_queue.main[0].id, null)
}

output "dlq_arn" {
  description = "ARN of the DLQ (if created)"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_url" {
  description = "URL of the DLQ (if created)"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

# Terraform configuration block
terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "project_prefix" {
  description = "Prefix for resource naming and tagging"
  type        = string
  default     = "myproject"
}

variable "owner" {
  description = "Owner tag value"
  type        = string
  default     = "user"
}

variable "build_suffix" {
  description = "Suffix for build identification"
  type        = string
  default     = "001"
}

# Local common tags
locals {
  common_tags = {
    Project = var.project_prefix
    Owner   = var.owner
    Build   = var.build_suffix
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.1.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    {
      Name = "${var.project_prefix}-vpc"
    },
    local.common_tags
  )
}

# Public subnets (with automatic public IP assignment disabled)
resource "aws_subnet" "public1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.1.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    {
      Name = "${var.project_prefix}-public-${data.aws_availability_zones.available.names[0]}"
    },
    local.common_tags
  )
}

resource "aws_subnet" "public2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.1.110.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    {
      Name = "${var.project_prefix}-public-${data.aws_availability_zones.available.names[1]}"
    },
    local.common_tags
  )
}

# Management subnets
resource "aws_subnet" "mgmt1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.1.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]

  tags = merge(
    {
      Name = "${var.project_prefix}-management-${data.aws_availability_zones.available.names[0]}"
    },
    local.common_tags
  )
}

resource "aws_subnet" "mgmt2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.1.101.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]

  tags = merge(
    {
      Name = "${var.project_prefix}-management-${data.aws_availability_zones.available.names[1]}"
    },
    local.common_tags
  )
}

# Private subnets
resource "aws_subnet" "private1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.1.20.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(
    {
      Name = "${var.project_prefix}-private-${data.aws_availability_zones.available.names[0]}"
    },
    local.common_tags
  )
}

resource "aws_subnet" "private2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.1.120.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(
    {
      Name = "${var.project_prefix}-private-${data.aws_availability_zones.available.names[1]}"
    },
    local.common_tags
  )
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.project_prefix}-igw"
    },
    local.common_tags
  )
}

# Route Table
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    {
      Name = "${var.project_prefix}-rt"
    },
    local.common_tags
  )
}

# Associate custom route table as main route table
resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

# Outputs
output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "subnet_ids_by_az_and_type" {
  description = "Map of subnet IDs grouped by availability zone and subnet type"
  value = {
    (data.aws_availability_zones.available.names[0]) = {
      public     = aws_subnet.public1.id
      management = aws_subnet.mgmt1.id
      private    = aws_subnet.private1.id
    }
    (data.aws_availability_zones.available.names[1]) = {
      public     = aws_subnet.public2.id
      management = aws_subnet.mgmt2.id
      private    = aws_subnet.private2.id
    }
  }
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = aws_internet_gateway.main.id
}

output "route_table_id" {
  description = "ID of the custom route table"
  value       = aws_route_table.main.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "user_name" {
  type        = string
  default     = "terraform-user"
  description = "Name of the IAM user to create"
}

variable "group_name" {
  type        = string
  default     = "terraform-admins"
  description = "Name of the IAM group"
}

variable "project_tag" {
  type        = string
  default     = "default-project"
  description = "Value for the Project tag on all taggable resources"
}

variable "policies_path" {
  type        = string
  default     = "/"
  description = "Path for IAM policies"
}

resource "random_id" "suffix" {
  byte_length = 4
}

# IAM User
resource "aws_iam_user" "this" {
  name          = var.user_name
  force_destroy = true
  path          = "/"
  tags = {
    Project = var.project_tag
  }
}

# IAM Group (no tags supported)
resource "aws_iam_group" "this" {
  name = var.group_name
  path = "/"
}

# IAM User Group Membership
resource "aws_iam_user_group_membership" "this" {
  user   = aws_iam_user.this.name
  groups = [aws_iam_group.this.name]
}

# IAM Access Key
resource "aws_iam_access_key" "this" {
  user = aws_iam_user.this.name
}

# EC2 Full Management Policy Document
data "aws_iam_policy_document" "ec2_full_management" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:AllocateAddress",
      "ec2:AssociateAddress",
      "ec2:AssociateDhcpOptions",
      "ec2:AssociateRouteTable",
      "ec2:AttachInternetGateway",
      "ec2:AttachNetworkInterface",
      "ec2:AttachVolume",
      "ec2:AuthorizeSecurityGroupEgress",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:CreateCustomerGateway",
      "ec2:CreateDhcpOptions",
      "ec2:CreateInternetGateway",
      "ec2:CreateKeyPair",
      "ec2:CreateNetworkAcl",
      "ec2:CreateNetworkAclEntry",
      "ec2:CreateNetworkInterface",
      "ec2:CreateRoute",
      "ec2:CreateRouteTable",
      "ec2:CreateSecurityGroup",
      "ec2:CreateSubnet",
      "ec2:CreateTags",
      "ec2:CreateVolume",
      "ec2:CreateVpc",
      "ec2:CreateVpcEndpoint",
      "ec2:CreateVpcPeeringConnection",
      "ec2:DeleteCustomerGateway",
      "ec2:DeleteDhcpOptions",
      "ec2:DeleteInternetGateway",
      "ec2:DeleteKeyPair",
      "ec2:DeleteNetworkAcl",
      "ec2:DeleteNetworkAclEntry",
      "ec2:DeleteNetworkInterface",
      "ec2:DeleteRoute",
      "ec2:DeleteRouteTable",
      "ec2:DeleteSecurityGroup",
      "ec2:DeleteSubnet",
      "ec2:DeleteTags",
      "ec2:DeleteVolume",
      "ec2:DeleteVpc",
      "ec2:DeleteVpcEndpoints",
      "ec2:DeleteVpcPeeringConnection",
      "ec2:DescribeAccountAttributes",
      "ec2:DescribeAddresses",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeCustomerGateways",
      "ec2:DescribeDhcpOptions",
      "ec2:DescribeImages",
      "ec2:DescribeInstanceAttribute",
      "ec2:DescribeInstanceCreditSpecifications",
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeInternetGateways",
      "ec2:DescribeKeyPairs",
      "ec2:DescribeNetworkAcls",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeRegions",
      "ec2:DescribeRouteTables",
      "ec2:DescribeSecurityGroupReferences",
      "ec2:DescribeSecurityGroupRules",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSnapshots",
      "ec2:DescribeSubnets",
      "ec2:DescribeTags",
      "ec2:DescribeVolumes",
      "ec2:DescribeVpcAttribute",
      "ec2:DescribeVpcClassicLink",
      "ec2:DescribeVpcClassicLinkDnsSupport",
      "ec2:DescribeVpcEndpoints",
      "ec2:DescribeVpcEndpointServices",
      "ec2:DescribeVpcPeeringConnections",
      "ec2:DescribeVpcs",
      "ec2:DetachInternetGateway",
      "ec2:DetachNetworkInterface",
      "ec2:DetachVolume",
      "ec2:DisassociateAddress",
      "ec2:DisassociateRouteTable",
      "ec2:ImportKeyPair",
      "ec2:ModifyInstanceAttribute",
      "ec2:ModifyNetworkInterfaceAttribute",
      "ec2:ModifySubnetAttribute",
      "ec2:ModifyVpcAttribute",
      "ec2:ModifyVpcEndpoint",
      "ec2:MonitorInstances",
      "ec2:RebootInstances",
      "ec2:ReleaseAddress",
      "ec2:RevokeSecurityGroupEgress",
      "ec2:RevokeSecurityGroupIngress",
      "ec2:RunInstances",
      "ec2:StartInstances",
      "ec2:StopInstances",
      "ec2:TerminateInstances",
      "ec2:UnmonitorInstances",
      "ec2:UpdateSecurityGroupRuleDescriptionsEgress",
      "ec2:UpdateSecurityGroupRuleDescriptionsIngress"
    ]
    resources = ["*"]
  }
}

# EC2 Full Management Policy
resource "aws_iam_policy" "ec2_full_management" {
  name        = "EC2FullManagement"
  path        = var.policies_path
  description = "Policy to allow full management of EC2 resources"
  policy      = data.aws_iam_policy_document.ec2_full_management.json
  tags = {
    Project = var.project_tag
  }
}

# KMS Customer Managed Key for S3 state bucket encryption
resource "aws_kms_key" "terraform_state" {
  description             = "Terraform state encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = false
  tags = {
    Project = var.project_tag
  }
}

# S3 Bucket for Terraform state
resource "aws_s3_bucket" "terraform_state" {
  bucket = "terraform-state-${var.project_tag}-${random_id.suffix.hex}"
  tags = {
    Project = var.project_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.terraform_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.terraform_state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.terraform_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# DynamoDB table for state locking
resource "aws_dynamodb_table" "terraform_lock" {
  name         = "terraform-state-lock-${var.project_tag}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
  tags = {
    Project = var.project_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Terraform State Access Policy Document
data "aws_iam_policy_document" "terraform_state_access" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.terraform_state.arn,
      "${aws_s3_bucket.terraform_state.arn}/*"
    ]
  }
  statement {
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [aws_kms_key.terraform_state.arn]
  }
  statement {
    effect = "Allow"
    actions = [
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:DeleteItem",
      "dynamodb:Scan",
      "dynamodb:Query",
      "dynamodb:UpdateItem"
    ]
    resources = [aws_dynamodb_table.terraform_lock.arn]
  }
}

# Terraform State Access Policy
resource "aws_iam_policy" "terraform_state_access" {
  name        = "TerraformStateAccess"
  path        = var.policies_path
  description = "Policy to allow Terraform state storage and locking"
  policy      = data.aws_iam_policy_document.terraform_state_access.json
  tags = {
    Project = var.project_tag
  }
}

# Attach EC2 Full Management Policy to Group
resource "aws_iam_group_policy_attachment" "ec2_full_management" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.ec2_full_management.arn
}

# Attach Terraform State Access Policy to Group
resource "aws_iam_group_policy_attachment" "terraform_state_access" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.terraform_state_access.arn
}

# Outputs
output "access_key_id" {
  value = aws_iam_access_key.this.id
}

output "secret_access_key" {
  value     = aws_iam_access_key.this.secret
  sensitive = true
}
